-- LOCAL STANDALONE TEST COPY. This Maintenance build intentionally does not use
-- the KeySystem/runtime-capability gate. Re-executing it is supported: the
-- existing CloverHub instance is unloaded below before this copy takes ownership.

-- [[ PLACE GUARD ]] --
local EXPECTED_PLACE_ID = "107778070777162"
if tostring(game.PlaceId) ~= EXPECTED_PLACE_ID then
    print("[CloverHub-SAE] Not Steal An Egg (PlaceId " .. tostring(game.PlaceId) .. "). Aborting.")
    return
end

-- Production payloads still require the private loader capability. Only this
-- local Maintenance copy skips that requirement for direct executor testing.

-- Potassium and several other executors scan both the autoexec root and nested
-- folders. If the identical build is already ready, the second copy must not
-- unload/restart it (which also caused duplicated Anti-AFK failure toasts).
if getgenv().__CHSAE_BuildId == "2026-09-10-v2.1-rift-handoff-v214"
    and getgenv().__CHSAE_PayloadReady == true then
    return
end

getgenv().__CHSAE_PayloadReady = nil

-- This is the maintained autoexec copy. Potassium currently contains several
-- archived CloverHub(StealAnEgg) files under other autoexec folders; mark this
-- session so those older files can return before replacing the fixed engine.
getgenv().__CHSAE_CanonicalLoaded = true

-- CloverHub is now the only Auto-Steal owner. Retire any standalone AutoStealEgg
-- script that autoexec loaded earlier so two CFrame loops can never fight.
if type(_G.AutoStealCtl) == "table" and type(_G.AutoStealCtl.panic) == "function" then
    pcall(_G.AutoStealCtl.panic)
elseif type(_G.AutoStealCtl) == "table" and type(_G.AutoStealCtl.stop) == "function" then
    pcall(_G.AutoStealCtl.stop)
end
_G.AutoSteal = false
_G.AutoStealCtl = nil

-- Dev-friendly reload: unload the previous instance instead of stacking UIs.
-- Older v0.2 sessions synchronously fired this event from their unload handler;
-- if an awakened status consumer re-entered the event, even loading the fixed
-- build could deadlock before it took ownership. Retire the stale event first so
-- the legacy unload closure observes nil and skips that unsafe Fire.
do
    local staleStatusWake = getgenv().__CHSAE_StatusWake
    getgenv().__CHSAE_StatusWake = nil
    if staleStatusWake then pcall(function() staleStatusWake:Destroy() end) end
end
do
local previousBuild = getgenv().__CHSAE_BuildId
local previousCharacter = game:GetService("Players").LocalPlayer.Character
if getgenv().__CloverHubSAE_Unload or getgenv().__VoidHubSAE_Unload then
    pcall(getgenv().__CloverHubSAE_Unload or getgenv().__VoidHubSAE_Unload)
    getgenv().__CloverHubSAE_Unload = nil
    getgenv().__VoidHubSAE_Unload = nil -- one-release compatibility cleanup
    task.wait(0.15)
end
-- v175 used Physics for flight, which the native Ragdoll module interprets
-- as ragdoll. Its cleanup then refused to stand up. Repair only that build's
-- same inactive rig after unloading; never interrupt a live native ragdoll.
if previousBuild == "2026-09-08-v1.7-arena-sell-v175"
    or previousBuild == "2026-09-08-v1.7-arena-sell-v175-key-r1" then
    local player = game:GetService("Players").LocalPlayer
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if character == previousCharacter and humanoid and humanoid.Health > 0
        and root and not root.Anchored and not humanoid.PlatformStand and not humanoid.Sit
        and humanoid:GetState() == Enum.HumanoidStateType.Physics
        and (tonumber(player:GetAttribute("RagdollEndTime")) or 0) <= workspace:GetServerTimeNow()
        and #character:QueryDescendants("BallSocketConstraint") == 0 then
        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
    end
end
end
-- Belt-and-suspenders: destroy any leftover CloverHub UI (a failed prior unload
-- can strand a duplicate). The former title is accepted once for migration.
-- title, so other Obsidian-based scripts are left alone.
do
    local guiRoots = { game:GetService("CoreGui") }
    pcall(function() if gethui then guiRoots[#guiRoots + 1] = gethui() end end)
    pcall(function() guiRoots[#guiRoots + 1] = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui") end)
    for _, root in ipairs(guiRoots) do
        if root then
            -- GetDescendants: the Obsidian ScreenGui is nested (e.g. under RobloxGui),
            -- so GetChildren misses it — that left stale duplicates on reload.
            for _, g in ipairs(root:GetDescendants()) do
                if g:IsA("ScreenGui") and g.Name == "Obsidian" then
                    for _, d in ipairs(g:GetDescendants()) do
                        if (d:IsA("TextLabel") or d:IsA("TextButton"))
                            and (tostring(d.Text):find("CloverHub", 1, true)
                                or tostring(d.Text):find("VoidHub", 1, true)) then
                            pcall(function() g:Destroy() end)
                            break
                        end
                    end
                end
            end
        end
    end
end

-- Session token: background loops check this and exit when a newer script
-- instance takes over (Library:Unload doesn't kill task.spawn loops).
local SESSION = { Marker = {} }
getgenv().__CloverHubSAE_Session = SESSION.Marker
getgenv().__CHSAE_ConfigControllers = {}
local RELEASE_VERSION = "v2.1"
local BUILD_ID = "2026-09-10-v2.1-rift-handoff-v214"
getgenv().__CHSAE_ReleaseVersion = RELEASE_VERSION
getgenv().__CHSAE_BuildId = BUILD_ID
local function sessionAlive()
    return getgenv().__CloverHubSAE_Session == SESSION.Marker
end

-- Disabled feature workers share one rare wake signal instead of polling forever.
-- Fire it deferred so a UI callback never runs resumed gameplay work inline.
SESSION.IdleWorkerWake = Instance.new("BindableEvent")
SESSION.IdleWorkerWakeQueued = false
function SESSION.WakeIdleWorkers(reason)
    if not sessionAlive() or SESSION.IdleWorkerWakeQueued then return end
    SESSION.IdleWorkerWakeQueued = true
    task.defer(function()
        SESSION.IdleWorkerWakeQueued = false
        if sessionAlive() then
            pcall(function() SESSION.IdleWorkerWake:Fire(reason or "setting") end)
        end
    end)
end

