-- ══════════════════════════════════════════
-- 💾 CONFIG PERSISTENCE — every setting, one JSON file
-- ══════════════════════════════════════════
-- The whole `Settings` table IS the private automatic config — no per-control
-- save code, so any setting added later persists automatically. Named/shared
-- profiles use a redacted snapshot below and never receive WebhookURL.
-- Loaded HERE, before a single control is built, so every dropdown/toggle/
-- slider comes up with your saved value on a fresh server (rejoin, server hop,
-- or a plain re-execute).
--
-- FILE LAYOUT (CloverHub keeps a separate Steal an Egg profile):
-- can never read each other's config):
--   CloverHub/universalToggle(SAG).json  → { "UseUniversalConfig": true|false }
--   CloverHub/universalConfig(SAG).json  → shared by every account on this PC
--   CloverHub/config(SAG)_<UserId>.json  → DEFAULT: per-user, so two accounts
--                                        don't overwrite each other's setup
--
-- Auto-save checks scalar/selection values against the last saved snapshot every
-- 3 s. Unchanged checks do not copy Settings, sort keys, build strings or encode
-- JSON. Keep direct Settings writes and picker table references compatible.
--
local ConfigMeta = {
    loaded = false, lastSave = 0, note = "never saved",
    migrated = false,
    legacyPath = "VoidHub/config(SAG)_" .. tostring(LocalPlayer.UserId) .. ".json",
}
local CONFIG_DIR    = "CloverHub"
local CONFIG_TOGGLE = CONFIG_DIR .. "/universalToggle(SAG).json"
local CONFIG_PATH   = CONFIG_DIR .. "/config(SAG)_" .. tostring(LocalPlayer.UserId) .. ".json"
do -- flip to the shared file only if the toggle file says so
    local ok, universal = pcall(function()
        local togglePath = isfile and isfile(CONFIG_TOGGLE) and CONFIG_TOGGLE
            or (isfile and isfile("VoidHub/universalToggle(SAG).json")
                and "VoidHub/universalToggle(SAG).json")
        if togglePath then
            local d = HttpService:JSONDecode(readfile(togglePath))
            return type(d) == "table" and d.UseUniversalConfig == true
        end
        return false
    end)
    if ok and universal then
        CONFIG_PATH = CONFIG_DIR .. "/universalConfig(SAG).json"
        ConfigMeta.legacyPath = "VoidHub/universalConfig(SAG).json"
    end
end

local function configSig(t, depth)
    local keys = {}
    for k in pairs(t) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        local v = t[k]
        if type(v) == "table" then
            parts[#parts + 1] = tostring(k) .. "={" .. (((depth or 0) < 3) and configSig(v, (depth or 0) + 1) or "…") .. "}"
        else
            parts[#parts + 1] = tostring(k) .. "=" .. tostring(v)
        end
    end
    return table.concat(parts, ",")
end

-- [[ DELIVERY SPEED PROFILE ]] --
function ConfigMeta.normalizeDeliverySpeeds(profile)
    profile = type(profile) == "table" and profile or {}
    local mode = Settings.StealMovementType == "Tween" and "Tween" or "TP"
    for _, name in ipairs({ "TP", "Tween" }) do
        local key = name .. "ReturnSpeed"
        local value = tonumber(profile[key])
        if value == nil and name == mode then value = tonumber(profile.StealSpeed or profile.HopSpeed or profile.TweenSpeed) end
        if not value or value ~= value or value == math.huge or value == -math.huge then
            value = name == "Tween" and 500 or 1000
        end
        Settings[key] = math.clamp(math.floor(value + 0.5), 100, 1000)
    end
    Settings.StealSpeed = Settings[mode .. "ReturnSpeed"]
end
-- [[ END DELIVERY SPEED PROFILE ]] --

local function configLoad()
    if not (isfile and readfile) then ConfigMeta.note = "no file API"; return false end
    local sourcePath = isfile(CONFIG_PATH) and CONFIG_PATH
        or (isfile(ConfigMeta.legacyPath) and ConfigMeta.legacyPath)
    local ok, raw = pcall(function() return sourcePath and readfile(sourcePath) or nil end)
    if not (ok and type(raw) == "string" and #raw > 2) then ConfigMeta.note = "no saved config"; return false end
    local ok2, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not (ok2 and type(data) == "table") then ConfigMeta.note = "⚠️ corrupt file — using defaults"; return false end

    for k, def in pairs(Settings) do
        local v = data[k]
        if v ~= nil then
            if type(def) == "table" and type(v) == "table" then
                -- MERGE IN PLACE: the overlay pickers hold a reference to this exact
                -- table, so replacing it would silently orphan their store.
                for kk in pairs(def) do def[kk] = nil end
                for kk, vv in pairs(v) do if vv == true then def[kk] = true end end
            elseif type(def) == type(v) then
                Settings[k] = v
            end
        end
    end
    -- Seller thresholds are irreversible safety inputs. Type-mismatched or
    -- missing values must not be skipped while a saved Auto-Sell flag is kept.
    local function savedSellerFloorValid(key)
        local value = data[key]
        return type(value) == "number" and value == value
            and value >= 0 and value < math.huge
    end
    if not savedSellerFloorValid("FuseMinimumValue")
        or not savedSellerFloorValid("FuseKGThreshold")
        or (data.FuseKGMode ~= "Any" and data.FuseKGMode ~= "Above" and data.FuseKGMode ~= "Below") then
        Settings.AutoFuse = false
        Settings.FuseMinimumValue, Settings.FuseKGThreshold, Settings.FuseKGMode = 0, 0, "Any"
    end
    if not savedSellerFloorValid("SellPetValueThreshold") then
        Settings.SellPetValueThreshold = 0
        Settings.AutoSell = false
        Settings.SellPetsWhenFull = false
        ConfigMeta.migrated = true
    end
    if not savedSellerFloorValid("SellEggValueThreshold") then
        Settings.SellEggValueThreshold = 0
        Settings.AutoSellEggs = false
        Settings.SellEggsWhenFull = false
        ConfigMeta.migrated = true
    end
    -- Public v0.1 changes the safe default from distance/value-first to rarity-first.
    -- Migrate old profiles once; later user changes continue to save normally.
    if (tonumber(data.ConfigRevision) or 0) < 1 then
        Settings.TargetPriority = "Rarity"
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 2 then
        -- v0.2 efficiency profile: preserve explicit Straight/Default choices,
        -- but upgrade the previous safe default into the requested hybrid route.
        if Settings.StealRoute == "Wall to Wall" then Settings.StealRoute = "Turbo Hybrid" end
        if Settings.StealRoute == "Y Level" then Settings.StealRoute = "Fly" end
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 3 then
        -- The status overlay used to default ON, which also persisted that
        -- accidental default into existing profiles. Hide it once; users can
        -- still explicitly enable Show Status afterward.
        Settings.ShowStatusOverlay = false
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 4 then
        -- v0.4 cleanup: retire the removed one-shot mutation experiment safely.
        -- Its old transaction keys are not part of Settings and the rewritten
        -- config drops them; Auto Mutate is disarmed once in case it was coupled.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 5 then
        -- v0.6 adds explicit full-inventory sellers and refreshes the config schema.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 6 then
        -- Sideways facing is now part of registered movement instead of a setting.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 7 then
        -- Guard protection is now an explicit opt-in control.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 8 then
        -- Ordinary runtime controls resume as saved. WebhookURL is private to
        -- the local automatic profile and is redacted only when a named/shared
        -- config is serialized later in this file. Irreversible sellers are now
        -- the deliberate exception and require fresh session approval.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 9 then
        -- v1.0 retires Great Bloom/Incubator automation and introduces the
        -- previous event flow and its protected-egg filters.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 10 then
        -- v1.3 adds compact native-income filters to Steal and both sellers.
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 11 then
        -- v77 changes seller Value into a strict keep floor and repairs mobile
        -- blur commits. Disarm irreversible sellers once so every upgraded user
        -- reviews the new Minimum Value before the first batch can run.
        Settings.AutoSell = false
        Settings.SellPetsWhenFull = false
        Settings.AutoSellEggs = false
        Settings.SellEggsWhenFull = false
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 12 then
        -- v82 adds an explicit irreversible-sale review. Existing persisted
        -- seller toggles are disarmed once so the first activation must pass
        -- through the new live match preview.
        Settings.AutoSell = false
        Settings.SellPetsWhenFull = false
        Settings.AutoSellEggs = false
        Settings.SellEggsWhenFull = false
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 14 then
        -- Retired movement engines migrate to the single maintained Glide engine.
        ConfigMeta.migrated = true
    end
    -- Seller consent is session-only. A saved ON flag must never start an
    -- irreversible worker during autoexecute before the user can see the live
    -- match preview in this Roblox session.
    Settings.AutoSell = false
    Settings.SellPetsWhenFull = false
    Settings.AutoSellEggs = false
    Settings.SellEggsWhenFull = false
    if (tonumber(data.ConfigRevision) or 0) < 15 then
        Settings.AutoRift, Settings.PriorityEvent, Settings.RiftMinimumValue = false, false, 0
        ConfigMeta.migrated = true
    elseif not savedSellerFloorValid("RiftMinimumValue") then
        Settings.AutoRift, Settings.RiftMinimumValue = false, 0
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 16 then
        -- User deferred the collection flow while movement is investigated.
        Settings.AutoRift = false
        ConfigMeta.migrated = true
    end
    if (tonumber(data.ConfigRevision) or 0) < 17 then
        ConfigMeta.migrated = true
    end
    if Settings.StealRoute == "Chicken TP" then Settings.StealRoute = "Straight" end
    Settings.ConfigRevision = 17
    -- v3 migration: keep the user's prior Hop/Tween speed, but retire both old
    -- movement modes and the separate step-size setting.
    if data.StealSpeed == nil then
        Settings.StealSpeed = tonumber(data.HopSpeed or data.TweenSpeed) or 800
    end
    Settings.StealSpeed = math.clamp(tonumber(Settings.StealSpeed) or 800, 100, 1000)
    if Settings.StealRoute == "Wall to Wall" then Settings.StealRoute = "Turbo Hybrid" end
    if Settings.StealRoute == "Y Level" then Settings.StealRoute = "Fly" end
    if Settings.StealRoute ~= "Straight" and Settings.StealRoute ~= "Default"
        and Settings.StealRoute ~= "Turbo Hybrid" and Settings.StealRoute ~= "Fly" then
        Settings.StealRoute = "Straight"
    end
    Settings.StealMovementBackend = "Glide"
    Settings.StealMovementType = Settings.StealMovementType == "Tween" and "Tween" or "TP"
    ConfigMeta.normalizeDeliverySpeeds(data)
    Settings.HoverRunSpeed = nil -- discard the retired saved setting
    Settings.StealWallSpacing = "Wide Wall"
    -- v4.5 migration: the old switch meant move when true. The new user-facing
    -- Prevent Snap switch means wait for range when true.
    if data.PlaceInRangeOnly == nil and type(data.PlaceMoveToPen) == "boolean" then
        Settings.PlaceInRangeOnly = not data.PlaceMoveToPen
    end
    -- v4.6 migration: the old master Enabled switch is gone. Preserve its
    -- effective state once, so an old disabled profile cannot start sending.
    if data.WebhookMutations == nil and data.WebhookHatches == nil then
        Settings.WebhookSteals = data.WebhookEnabled == true and data.WebhookSteals ~= false
    end


    ConfigMeta.loaded = true
    ConfigMeta.note   = sourcePath == ConfigMeta.legacyPath and "loaded legacy profile" or "loaded"
    return true
end

-- Private automatic persistence and shareable configs deliberately use two
-- views of the same Settings table. The default is fail-closed for callers:
-- only an explicit true may include the Discord webhook token.
local function configSnapshot(includeWebhookURL)
    local snapshot = {}
    for key, value in pairs(Settings) do
        if includeWebhookURL == true or key ~= "WebhookURL" then
            if type(value) == "table" then
                local copy = {}
                for item, enabled in pairs(value) do copy[item] = enabled end
                snapshot[key] = copy
            else
                snapshot[key] = value
            end
        end
    end
    -- Consent to an irreversible seller is intentionally session-ephemeral;
    -- persist its filters, never an armed worker.
    snapshot.AutoSell = false
    snapshot.SellPetsWhenFull = false
    snapshot.AutoSellEggs = false
    snapshot.SellEggsWhenFull = false
    return snapshot
end

-- [[ AUTOMATIC CONFIG PERSISTENCE CONTROLLER ]] --
function ConfigMeta.CreatePersistence(deps)
    local controller = {}
    local lastSnapshot, saving, retry = nil, false, false
    -- These flags are session consent, not persistent settings. Keep the same
    -- normalization as configSnapshot without allocating a snapshot on each tick.
    local ephemeral = { AutoSell = true, SellPetsWhenFull = true,
        AutoSellEggs = true, SellEggsWhenFull = true }
    local function unchanged()
        if not lastSnapshot then return false end
        for key, value in pairs(deps.settings) do
            if ephemeral[key] then value = false end
            local saved = lastSnapshot[key]
            if type(value) == "table" then
                if type(saved) ~= "table" then return false end
                -- Settings tables are flat boolean selection stores. Compare
                -- both directions so in-place removals and false entries count.
                for item, enabled in pairs(value) do
                    if saved[item] ~= enabled then return false end
                end
                for item, enabled in pairs(saved) do
                    if value[item] ~= enabled then return false end
                end
            elseif value ~= saved then return false end
        end
        for key in pairs(lastSnapshot) do
            if not ephemeral[key] and deps.settings[key] == nil then return false end
        end
        return true
    end
    function controller:Prime()
        -- Only a non-migrated load is the baseline. A failed migration save must
        -- remain dirty, not be marked saved by startup initialization.
        if saving or not deps.alive() then return false end
        lastSnapshot = deps.snapshot()
        return true
    end
    function controller:Save(force)
        if not deps.alive() or deps.blocked() then return false end
        if saving then
            if force then retry = true end -- coalesce force requests until next tick
            return false
        end
        if not force and not retry and unchanged() then return false end
        saving, retry = true, false
        local ok, written = pcall(function()
            local snapshot = deps.snapshot()
            local encodedOk, encoded = pcall(deps.encode, snapshot)
            if not encodedOk then deps.meta.note = "⚠️ encode failed"; return false end
            -- Encoding/file APIs may yield on some executors. Never begin a
            -- write from a superseded session or after NoSave became enabled.
            if not deps.alive() or deps.blocked() then return false end
            if not pcall(deps.write, encoded) then
                deps.meta.note = "⚠️ write failed"
                return false
            end
            lastSnapshot = snapshot -- commit only the snapshot actually written
            deps.meta.lastSave, deps.meta.note = deps.time(), "saved"
            return true
        end)
        saving = false
        if not ok then deps.meta.note = "⚠️ save failed" end
        if not ok or not written then retry = true end
        return ok and written == true
    end
    return controller
end
-- [[ AUTOMATIC CONFIG FILE ADAPTER ]] --
ConfigMeta.persistence = ConfigMeta.CreatePersistence({
    settings = Settings, meta = ConfigMeta, alive = sessionAlive,
    blocked = function() return getgenv().__CloverHubSAE_NoSave or getgenv().__VoidHubSAE_NoSave end,
    snapshot = function() return configSnapshot(true) end,
    encode = function(snapshot) return HttpService:JSONEncode(snapshot) end,
    write = function(encoded)
        pcall(function()
            if makefolder and isfolder and not isfolder(CONFIG_DIR) then makefolder(CONFIG_DIR) end
        end)
        if not sessionAlive() or getgenv().__CloverHubSAE_NoSave or getgenv().__VoidHubSAE_NoSave then
            error("config save cancelled", 0)
        end
        writefile(CONFIG_PATH, encoded)
    end,
    time = os.time,
})
local function configSave(force)
    if SESSION.InventoryWake then SESSION.InventoryWake("config") end
    if not writefile then ConfigMeta.note = "no file API"; return false end
    return ConfigMeta.persistence:Save(force)
end

configLoad()
do
    -- Flat scalar keys are deliberate: configLoad treats table defaults as
    -- boolean selection stores. Invalid/legacy values fail safely to disabled.
    for _, keys in ipairs({
        { "TargetKGMode", "TargetKGThreshold" },
        { "SellPetKGMode", "SellPetKGThreshold" },
        { "SellEggKGMode", "SellEggKGThreshold" },
        { "FuseKGMode", "FuseKGThreshold" },
    }) do
        local modeKey, thresholdKey = keys[1], keys[2]
        local mode = Settings[modeKey]
        if mode ~= "Below" and mode ~= "Above" and mode ~= "Any" then
            Settings[modeKey] = "Any"
            ConfigMeta.migrated = true
        end
        local threshold = math.max(tonumber(Settings[thresholdKey]) or 0, 0)
        if Settings[thresholdKey] ~= threshold then
            Settings[thresholdKey] = threshold
            ConfigMeta.migrated = true
        end
    end
    for _, thresholdKey in ipairs({
        "TargetValueThreshold", "SellPetValueThreshold", "SellEggValueThreshold", "RiftMinimumValue", "FuseMinimumValue",
    }) do
        local threshold = tonumber(Settings[thresholdKey])
        local valid = type(threshold) == "number" and threshold == threshold
            and threshold >= 0 and threshold < math.huge
        if not valid then
            threshold = 0
            if thresholdKey == "SellPetValueThreshold" then
                Settings.AutoSell = false
                Settings.SellPetsWhenFull = false
            elseif thresholdKey == "SellEggValueThreshold" then
                Settings.AutoSellEggs = false
                Settings.SellEggsWhenFull = false
            end
        end
        if Settings[thresholdKey] ~= threshold then
            Settings[thresholdKey] = threshold
            ConfigMeta.migrated = true
        end
    end
end
if Settings.AutoRift ~= true then Settings.AutoRift = false end
if Settings.PriorityEvent ~= true then Settings.PriorityEvent = false end
if ConfigMeta.migrated then configSave(true)
else ConfigMeta.persistence:Prime() end -- loading itself is not a change

-- Always on: whatever you change in the hub is on disk within ~3s.
task.spawn(function()
    while sessionAlive() do
        task.wait(3)
        if not sessionAlive() then break end
        pcall(configSave)
    end
end)

