-- [[ RIFT PLANNER ]] --
-- Pure rules; native decoding and eligibility are supplied by the adapter.
RuntimeStatus.RiftPlanner = {}
function RuntimeStatus.RiftPlanner.Signature(state)
    if type(state) ~= "table" or type(state.Requirements) ~= "table"
        or #state.Requirements ~= 3 then return nil end
    local parts = { tostring(state.BannerId or "") }
    for i = 1, 3 do
        local category = state.Requirements[i]
        if type(category) ~= "string" or category == "" then return nil end
        parts[#parts + 1] = category
    end
    return table.concat(parts, "\31")
end
function RuntimeStatus.RiftPlanner.ValueAllowed(value, known, minimum)
    if type(minimum) ~= "number" or minimum ~= minimum
        or minimum < 0 or minimum >= math.huge then return false end
    if known ~= true or type(value) ~= "number" or value ~= value
        or value < 0 or value >= math.huge then return false end
    return minimum == 0 or value < minimum
end
function RuntimeStatus.RiftPlanner.Plan(state, pets, eggs)
    local signature = RuntimeStatus.RiftPlanner.Signature(state)
    if not signature then return nil end
    local plan = { signature = signature, slots = {}, pets = {}, eggs = {}, missing = {}, ready = true }
    local function cheapest(list, category, used)
        local best
        for _, entry in ipairs(list) do
            if entry.category == category and not used[entry.uid]
                and (not best or entry.value < best.value
                    or (entry.value == best.value and entry.uid < best.uid)) then best = entry end
        end
        return best
    end
    for i, category in ipairs(state.Requirements) do
        local pet = cheapest(pets, category, plan.pets)
        local slot = { category = category }
        if pet then
            plan.pets[pet.uid] = true
            slot.petUid, slot.waiting = pet.uid, pet.waiting == true
            if slot.waiting then plan.ready = false end
        else
            plan.ready = false
            local egg = cheapest(eggs, category, plan.eggs)
            if egg then
                plan.eggs[egg.uid] = true
                slot.eggUid, slot.placed = egg.uid, egg.placed == true
            else
                plan.missing[category] = (plan.missing[category] or 0) + 1
            end
        end
        plan.slots[i] = slot
    end
    return plan
end
function RuntimeStatus.RiftPlanner.Action(enabled, protected, normalAvailable, priority, pending, plan)
    if not enabled then return "off" end
    if protected then return "transaction" end
    if normalAvailable then return "normal" end
    if pending then return "claim" end
    if not plan then return "state" end
    if plan.ready then return "trade" end
    for _, slot in ipairs(plan.slots) do
        if slot.eggUid and not slot.placed then return "place" end
    end
    if next(plan.missing) ~= nil then return "collect" end
    return "hatch"
end
