RuntimeStatus.getSafetySummary = function()
    return "🛡️ Guard loading", 0
end

-- Status cards are written by several workers. Avoid invalidating the same UI
-- hierarchy every polling pass, and provide one lightweight wake signal for the
-- overlay so it can react to real state changes instead of formatting at 4 Hz.
RuntimeStatus.statusWake = Instance.new("BindableEvent")
getgenv().__CHSAE_StatusWake = RuntimeStatus.statusWake
RuntimeStatus.statusLabelCache = setmetatable({}, { __mode = "k" })
RuntimeStatus.statusWakeBusy = false
RuntimeStatus.statusWakePending = nil
RuntimeStatus.presentationInterval = function()
    return (RuntimeStatus.clientFPS or 60) < 35 and 0.25 or 0.1
end
function RuntimeStatus.wakeOverlay(reason)
    if not sessionAlive() then return end
    RuntimeStatus.statusWakePending = reason or "status"
    if RuntimeStatus.statusWakeBusy then return end
    RuntimeStatus.statusWakeBusy = true
    -- BindableEvent:Fire resumes Event:Wait listeners synchronously. One resumed
    -- arbiter worker can set another status before returning to Wait, recursively
    -- firing the same event and hanging the entire producer (observed for 30 s in
    -- setStealStatus after a claim). Isolate and coalesce the wake so status/UI
    -- listeners can never block movement, carry completion, or the loader thread.
    task.defer(function()
        while sessionAlive() and RuntimeStatus.statusWakePending ~= nil do
            local pending = RuntimeStatus.statusWakePending
            RuntimeStatus.statusWakePending = nil
            pcall(function() RuntimeStatus.statusWake:Fire(pending) end)
            task.wait(RuntimeStatus.presentationInterval())
        end
        RuntimeStatus.statusWakeBusy = false
    end)
end
function RuntimeStatus.setLabel(label, text)
    text = tostring(text)
    if not label or RuntimeStatus.statusLabelCache[label] == text then return false end
    RuntimeStatus.statusLabelCache[label] = text
    -- Obsidian's Label:SetText performs a synchronous layout refresh. During a
    -- snapshot replacement the steal worker can change status several times in
    -- one scheduler turn; the library refresh then re-enters groupbox layout and
    -- has been observed hanging the client for 30+ seconds. Update the native
    -- TextLabel directly when available so status presentation can never block
    -- movement or target reconciliation. Keep SetText only as a compatibility
    -- fallback for a future library object without an exposed TextLabel.
    local textLabel = type(label) == "table" and rawget(label, "TextLabel") or nil
    local ok
    -- Even Instance:IsA is protected for the identity-2 worker when Obsidian is
    -- parented under CoreGui, so do not touch the instance before elevating.
    if typeof(textLabel) == "Instance" then
        local originalIdentity = type(getthreadidentity) == "function" and getthreadidentity() or nil
        if type(setthreadidentity) == "function" then pcall(setthreadidentity, 8) end
        ok = pcall(function()
            textLabel.Text = text
            rawset(label, "Text", text)
        end)
        if originalIdentity ~= nil and type(setthreadidentity) == "function" then
            pcall(setthreadidentity, originalIdentity)
        end
    else
        ok = pcall(function() label:SetText(text) end)
    end
    if ok then RuntimeStatus.wakeOverlay("label") end
    return ok
end
function RuntimeStatus.set(key, value)
    value = tostring(value)
    if RuntimeStatus[key] == value then return false end
    RuntimeStatus[key] = value
    RuntimeStatus.wakeOverlay(key)
    return true
end

function RuntimeStatus.kgFilterActive(mode, threshold)
    return (mode == "Below" or mode == "Above") and (tonumber(threshold) or 0) > 0
end
