    Below = '<font color="#60A5FA"><b>Below</b></font> <font color="#9AA0AA">at or below</font>',
    Above = '<font color="#49E685"><b>Above</b></font> <font color="#9AA0AA">at or above</font>',
}

-- Reused by Steal and both sellers. Each feature gets only the two
-- requested controls and evaluates them inside its existing scan/pass.
function RuntimeStatus.addKGFilterControls(groupbox, idPrefix, modeKey, thresholdKey, onChange, protection)
    local picker = BindDropdownOverlay(groupbox, idPrefix .. "KGMode", protection and "Prevent KG" or "KG Rule",
        RuntimeStatus.kgFilterModes, {
        configKey = modeKey,
        multi = false,
        text = protection and "Prevent KG" or "KG Rule",
        tooltip = "Any = no KG filter.",
        displayMap = RuntimeStatus.kgFilterDisplayMap,
        get = function() return Settings[modeKey] or "Any" end,
        set = function(value)
            Settings[modeKey] = (value == "Below" or value == "Above") and value or "Any"
        end,
        onChange = onChange,
    })

    local input = groupbox:AddInput(idPrefix .. "KGThreshold", {
        Text = "KG Threshold",
        Default = tostring(math.max(tonumber(Settings[thresholdKey]) or 0, 0)),
        Numeric = true,
        Finished = true,
        Placeholder = "0",
        Tooltip = "Uses the KG shown in game.",
    })
    local function refreshCommittedCaption()
        if type(RuntimeStatus.setCommittedThresholdCaption) == "function" then
            RuntimeStatus.setCommittedThresholdCaption(input, "KG Threshold",
                Settings[thresholdKey])
        end
    end
    refreshCommittedCaption()
    input:OnChanged(function(value)
        Settings[thresholdKey] = math.max(tonumber(value) or 0, 0)
        refreshCommittedCaption()
        if onChange then pcall(onChange) end
    end)

    local registry = getgenv().__CHSAE_ConfigControllers
    if type(registry) == "table" then
        registry[thresholdKey] = {
            GetValue = function() return Settings[thresholdKey] end,
            SetValue = function(_, value)
                local threshold = math.max(tonumber(value) or 0, 0)
                Settings[thresholdKey] = threshold
                pcall(function() input:SetValue(tostring(threshold)) end)
                refreshCommittedCaption()
            end,
        }
    end
    return picker, input
end

-- Compact native-income thresholds shared by Steal and both sellers. The UI
-- accepts the same suffix language players see in game while Settings keeps the
-- exact numeric value for comparisons and config persistence.
do
    local multipliers = {
        [""] = 1,
        k = 1e3,
        m = 1e6,
        b = 1e9,
        t = 1e12,
    }
    local displaySuffixes = {
        { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" },
    }

    local function finiteNonnegative(value)
        return type(value) == "number" and value == value
            and value >= 0 and value < math.huge
    end

    function RuntimeStatus.parseCompactValue(raw)
        if type(raw) == "number" then
            return finiteNonnegative(raw) and raw or nil
        end
        local text = tostring(raw or ""):lower():gsub("%s+", "")
        if text == "" then return 0 end
        if text:sub(1, 1) == "$" then text = text:sub(2) end
        if text == "" then return nil end

        local amountText, suffix = text:match("^([%d,]*%.?%d+)(%a*)$")
        local multiplier = multipliers[suffix]
        if not amountText or not multiplier then return nil end

        -- Commas are optional, but malformed groups are rejected instead of
        -- silently changing an irreversible seller threshold.
        local integer = amountText:match("^([^%.]*)") or ""
        if integer == "" then integer = "0" end
        if integer:find(",", 1, true) then
            local lead, groups = integer:match("^(%d%d?%d?)(,.*)$")
            if not lead or not groups or (groups:gsub(",%d%d%d", "")) ~= "" then
                return nil
            end
        elseif not integer:match("^%d+$") then
            return nil
        end

        local amount = tonumber((amountText:gsub(",", "")))
        local value = amount and amount * multiplier or nil
        return finiteNonnegative(value) and value or nil
    end

    function RuntimeStatus.formatCompactValue(raw)
        local value = tonumber(raw) or 0
        if not finiteNonnegative(value) or value == 0 then return "0" end
        local divisor, suffix = 1, ""
        for _, row in ipairs(displaySuffixes) do
            if value >= row[1] then
                divisor, suffix = row[1], row[2]
                break
            end
        end
        local text = ("%.6f"):format(value / divisor)
        text = text:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
        return text .. suffix
    end

    -- Short display used only in the caption above a threshold textbox. The
    -- textbox and Settings retain their canonical numeric value; this compact
    -- copy prevents long KG/value numbers from running outside narrow columns.
    function RuntimeStatus.formatThresholdConfirmation(raw)
        local value = tonumber(raw) or 0
        if not finiteNonnegative(value) or value == 0 then return "0" end
        local divisor, suffix, suffixIndex = 1, "", nil
        for index, row in ipairs(displaySuffixes) do
            if value >= row[1] then
                divisor, suffix, suffixIndex = row[1], row[2], index
                break
            end
        end
        local function render(currentDivisor, currentSuffix)
            local scaled = value / currentDivisor
            local decimals = scaled >= 100 and 0 or (scaled >= 10 and 1
                or (scaled >= 1 and 2 or (currentDivisor == 1 and 6 or 2)))
            local text = (("%%.%df"):format(decimals)):format(scaled)
            text = text:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
            return text, currentSuffix
        end
        local text, renderedSuffix = render(divisor, suffix)
        if tonumber(text) and tonumber(text) >= 1000 and suffixIndex and suffixIndex > 1 then
            local nextRow = displaySuffixes[suffixIndex - 1]
            text, renderedSuffix = render(nextRow[1], nextRow[2])
        end
        return text .. renderedSuffix
    end

    function RuntimeStatus.setCommittedThresholdCaption(input, title, raw)
        if type(input) ~= "table" or type(input.SetText) ~= "function" then return false end
        local display = RuntimeStatus.formatThresholdConfirmation(raw)
        local caption = ('%s: <font color="#49E685"><b>%s</b></font>')
            :format(tostring(title), display)
        return pcall(function() input:SetText(caption) end)
    end

    function RuntimeStatus.valueFilterActive(threshold)
        return (tonumber(threshold) or 0) > 0
    end

    function RuntimeStatus.markValueFilterChanged()
        -- Irreversible sellers wait for the textbox and config callback to settle.
        -- This also closes the mobile tap-away race where visible text used to be
        -- newer than the numeric Settings value.
        RuntimeStatus.valueFilterReadyAt = os.clock() + 0.75
    end

    function RuntimeStatus.sellerValueFilterReady(settingKey)
        if RuntimeStatus.valueFilterLoadInProgress == true then return false end
        if os.clock() < (tonumber(RuntimeStatus.valueFilterReadyAt) or 0) then return false end
        local ok, focused = pcall(function()
            return game:GetService("UserInputService"):GetFocusedTextBox()
        end)
        if not (ok and focused == nil) then return false end

        -- Finished text inputs can update their visible Value before Obsidian's
        -- callback commits the parsed number. An irreversible seller must prove
        -- that the text the user sees and the number it will compare are equal.
        local state = settingKey and RuntimeStatus.valueFilterInputs
            and RuntimeStatus.valueFilterInputs[settingKey] or nil
        if state and type(state.ReadText) == "function" then
            local readOk, visible = pcall(state.ReadText)
            local parsed = readOk and RuntimeStatus.parseCompactValue(visible) or nil
            if parsed == nil or parsed ~= tonumber(Settings[settingKey]) then return false end
        end
        return true
    end

    function RuntimeStatus.addValueFilterInput(groupbox, inputId, settingKey, labelText, onChange, tooltipText)
        local normalizing = false
        -- The formatted textbox is the user's safety contract. Canonicalize the
        -- stored number to that exact round trip so readiness can use strict
        -- equality even for unusually precise imported thresholds.
        local initialText = RuntimeStatus.formatCompactValue(Settings[settingKey])
        local initialValue = RuntimeStatus.parseCompactValue(initialText)
        if initialValue ~= nil then Settings[settingKey] = initialValue end
        local input = groupbox:AddInput(inputId, {
            Text = labelText,
            Default = initialText,
            Numeric = false,
            -- Keep full-string editing for decimals; a supplemental FocusLost
            -- connection below commits ordinary PC/mobile tap-away as well.
            Finished = true,
            Placeholder = "750M / 1.25B / 2T",
            Tooltip = tooltipText or "Uses $/s. K, M, B, T work; 0 disables.",
        })

        local function refreshCommittedCaption()
            RuntimeStatus.setCommittedThresholdCaption(input, labelText, Settings[settingKey])
        end
        refreshCommittedCaption()

        local function setInputText(value)
            local text = RuntimeStatus.formatCompactValue(value)
            normalizing = true
            pcall(function() input:SetValue(text) end)
            normalizing = false
        end

        local function commitRaw(raw, source)
            if normalizing then return false end
            RuntimeStatus.markValueFilterChanged()
            local value = RuntimeStatus.parseCompactValue(raw)
            if value == nil then
                setInputText(Settings[settingKey])
                pcall(function()
                    Library:Notify("Use a value like 750M, 1.25B, or 2T.", 4)
                end)
                if onChange then pcall(onChange, "invalid") end
                return false
            end
            local display = RuntimeStatus.formatCompactValue(value)
            local canonical = RuntimeStatus.parseCompactValue(display)
            if canonical == nil then return false end
            local changed = tonumber(Settings[settingKey]) ~= canonical
            Settings[settingKey] = canonical
            setInputText(canonical)
            refreshCommittedCaption()
            if changed and onChange then pcall(onChange, source or "user") end
            return true
        end

        input:OnChanged(function(raw)
            commitRaw(raw, "user")
        end)

        -- Pinned Obsidian only commits Finished inputs when FocusLost's Enter
        -- argument is true. Its input object exposes Holder, so attach the
        -- missing ordinary-blur commit without depending on private upvalues.
        local textBox = input.Holder and input.Holder:FindFirstChildWhichIsA("TextBox", true)
        if textBox then
            local blurConnection = textBox.FocusLost:Connect(function()
                if normalizing then return end
                -- Do not compare against input.Value here: Finished inputs may
                -- already mirror the typed text even though OnChanged never ran.
                commitRaw(textBox.Text, "blur")
            end)
            if type(input.Connections) == "table" then
                table.insert(input.Connections, blurConnection)
            else
                RuntimeStatus.valueFilterInputConnections =
                    RuntimeStatus.valueFilterInputConnections or {}
                table.insert(RuntimeStatus.valueFilterInputConnections, blurConnection)
            end
        end

        RuntimeStatus.valueFilterInputs = RuntimeStatus.valueFilterInputs or {}
        RuntimeStatus.valueFilterInputs[settingKey] = {
            ReadText = function()
                return textBox and textBox.Text or input.Value
            end,
            Commit = function()
                return commitRaw(textBox and textBox.Text or input.Value, "blur")
            end,
        }

        local registry = getgenv().__CHSAE_ConfigControllers
        if type(registry) == "table" then
            registry[settingKey] = {
                GetValue = function() return Settings[settingKey] end,
                SetValue = function(_, raw)
                    RuntimeStatus.markValueFilterChanged()
                    local value = RuntimeStatus.parseCompactValue(raw)
                    if value == nil then
                        local current = tonumber(Settings[settingKey])
                        value = finiteNonnegative(current) and current or 0
                    end
                    local display = RuntimeStatus.formatCompactValue(value)
                    local canonical = RuntimeStatus.parseCompactValue(display)
                    Settings[settingKey] = canonical ~= nil and canonical or 0
                    setInputText(Settings[settingKey])
                    refreshCommittedCaption()
                    if onChange then pcall(onChange, "config") end
                end,
            }
        end
        return input
    end
end

