-- One clock per steal transaction. It updates only while a transaction is live,
-- then sleeps on the shared status event, so idle clients pay no timer polling cost.
do
    function RuntimeStatus.beginStealTimer(uid)
        local timer = RuntimeStatus.stealTimer
        timer.active = true
        timer.startedAt = os.clock()
        timer.uid = uid
        RuntimeStatus.set("stealTime", "⏱️ Time: 0.00s")
    end

    function RuntimeStatus.finishStealTimer(outTime, backTime)
        local timer = RuntimeStatus.stealTimer
        local total = math.max(0, (tonumber(outTime) or 0) + (tonumber(backTime) or 0))
        timer.active = false
        timer.last = total
        timer.outTime = tonumber(outTime) or 0
        timer.backTime = tonumber(backTime) or 0
        timer.completed = (tonumber(timer.completed) or 0) + 1
        timer.total = (tonumber(timer.total) or 0) + total
        timer.average = timer.total / timer.completed
        RuntimeStatus.set("stealTime", ("⏱️ Time: %.2fs · %.2f out / %.2f back")
            :format(total, timer.outTime, timer.backTime))
        -- Home may be rebuilding/unloading while a delivery signal finishes.
        -- Presentation must never be able to terminate the steal worker after
        -- the server has already accepted and claimed the egg.
        pcall(SessionMetrics.Set, SessionMetrics, "stealTime", ("%.2fs"):format(total))
        pcall(SessionMetrics.Set, SessionMetrics, "avgStealTime", ("%.2fs"):format(timer.average))
    end

    function RuntimeStatus.pauseStealTimer()
        local timer = RuntimeStatus.stealTimer
        if not timer.active then return false end
        timer.active = false
        -- Preserve timer.last and the Home metric as the most recent verified
        -- steal. The game-screen timer is driven only by timer.active, so armed,
        -- cooldown, resync, event, place, and treadmill activity show no timer.
        RuntimeStatus.wakeOverlay("steal-timer-paused")
        return true
    end

    task.spawn(function()
        while sessionAlive() do
            local timer = RuntimeStatus.stealTimer
            if timer.active then
                local elapsed = math.max(0, os.clock() - (tonumber(timer.startedAt) or os.clock()))
                RuntimeStatus.set("stealTime", ("⏱️ Time: %.2fs"):format(elapsed))
                pcall(SessionMetrics.Set, SessionMetrics, "stealTime", ("%.2fs"):format(elapsed))
                task.wait(RuntimeStatus.presentationInterval())
            else
                RuntimeStatus.statusWake.Event:Wait()
            end
        end
    end)
end

