-- A successful same-server rejoin deliberately removes ClientReplicator and can
-- also populate GuiService's error text during the handoff. Mark it before the
-- TeleportService call so the disconnect webhook only reports unexpected losses.
getgenv().__CHSAE_RuntimeConns = getgenv().__CHSAE_RuntimeConns or {}
function RuntimeStatus.failSameServerRejoin(detail, attempt)
    if not RuntimeStatus.sameServerRejoinPending then return end
    if attempt ~= nil and RuntimeStatus.sameServerRejoinAttempt ~= attempt then return end
    RuntimeStatus.sameServerRejoinPending = false
    RuntimeStatus.sameServerRejoinAttempt = nil
    RuntimeStatus.intentionalDisconnectUntil = 0
    RuntimeStatus.intentionalDisconnectReason = nil
    detail = tostring(detail or "Teleport failed")
    Library:Notify("⚠️ Same-server rejoin failed: " .. detail, 5)
end
function RuntimeStatus.requestSameServerRejoin(reason)
    if RuntimeStatus.sameServerRejoinPending or RuntimeStatus.serverHopPending then
        local detail = "another teleport is already pending"
        Library:Notify("⚠️ " .. detail, 4)
        return false
    end
    local placeId, jobId = game.PlaceId, game.JobId
    if type(jobId) ~= "string" or jobId == "" then
        Library:Notify("⚠️ Same-server rejoin failed: job id unavailable", 5)
        return false
    end
    RuntimeStatus.sameServerRejoinPending = true
    local attempt = {}
    RuntimeStatus.sameServerRejoinAttempt = attempt
    RuntimeStatus.intentionalDisconnectUntil = os.clock() + 45
    RuntimeStatus.intentionalDisconnectReason = tostring(reason or "Same-server rejoin")
    task.spawn(function()
        local ok, err = pcall(function()
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LocalPlayer)
        end)
        if not ok then
            RuntimeStatus.failSameServerRejoin(err, attempt)
        end
    end)
    task.delay(45, function()
        if sessionAlive() and RuntimeStatus.sameServerRejoinAttempt == attempt then
            RuntimeStatus.failSameServerRejoin("teleport timed out", attempt)
        end
    end)
    return true
end
pcall(function()
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
        = TeleportService.TeleportInitFailed:Connect(function(player, _, message)
            if player ~= LocalPlayer then return end
            if os.clock() < (tonumber(RuntimeStatus.intentionalDisconnectUntil) or 0) then
                RuntimeStatus.failSameServerRejoin(message)
            end
        end)
end)

MakeButtonPanel(ServerBox, "BtnServerPanel", {
