            .. (e.odds and string.format(' <font color="%s">%s</font>', DIM, tostring(e.odds)) or "")
    end
    if #RarityItems == 0 then
        RarityItems = { "Divine","Superior","Eternal","Limited","Secret","Exotic","Exclusive",
            "Cosmic","Rainbow","BrainrotGod","Mythical","Mythic","Legendary","Epic","Rare",
            "Celestial","SuperRare","Uncommon","Basic","Common" }
    end

    -- Area nests use a much smaller pool than the complete asset directory.
    -- Build every picker from the real area directory, including Titan Temple.
    -- Event-only Admin Abuse assets stay out of user category filters; the
    -- dedicated Admin Events flow owns them independently.
    local spawnRaritySet, spawnCategorySet = {}, {}
    local spawnAssets
    pcall(function()
        local Areas = require(ReplicatedStorage.Data.Areas)
        local Assets = require(ReplicatedStorage.Data.Assets)
        spawnAssets = Assets.Directory
        for _, area in pairs(Areas.Directory or {}) do
            for dropKey, dropEntry in pairs(area.DropTable or {}) do
                local assetCategory = type(dropEntry) == "table" and dropEntry[1] or dropKey
                local asset = Assets.Directory and Assets.Directory[assetCategory]
                if assetCategory then
                    assetCategory = tostring(assetCategory)
                    spawnCategorySet[assetCategory] = true
                end
                local rarity = asset and asset.Rarity
                local rarityId = type(rarity) == "table" and rarity._id or rarity
                if rarityId then spawnRaritySet[tostring(rarityId)] = true end
            end
        end
    end)
    if next(spawnRaritySet) == nil then
        for _, rarityId in ipairs({
            "Common", "Uncommon", "Rare", "Epic", "Legendary",
            "Mythic", "Cosmic", "Divine", "Eternal", "Secret",
        }) do
            spawnRaritySet[rarityId] = true
        end
    end
    for _, entry in ipairs(RarityEntries) do
        if spawnRaritySet[entry.id] then
            TargetRarityItems[#TargetRarityItems + 1] = entry.id
            TargetRarityDM[entry.id] = RarityDM[entry.id]
        end
    end
    -- Protect against a renamed/missing rarity module while still presenting the
    -- known live area pool in a useful order.
    if #TargetRarityItems == 0 then
        for _, rarityId in ipairs({
            "Secret", "Eternal", "Divine", "Cosmic", "Mythic",
            "Legendary", "Epic", "Rare", "Uncommon", "Common",
        }) do
            TargetRarityItems[#TargetRarityItems + 1] = rarityId
            TargetRarityDM[rarityId] = RarityDM[rarityId] or rarityId
        end
    end
    for rarityId in pairs(Settings.TargetRarities) do
        if not spawnRaritySet[rarityId] then Settings.TargetRarities[rarityId] = nil end
    end
    -- Place, Sell, Egg Sell, and Rift now expose this live
    -- spawning rarity pool. Remove stale shop-only selections that would be
    -- invisible in their shared picker after an older config is loaded.
    for _, settingsKey in ipairs({
        "PlaceRarities", "SellRarities", "SellEggRarities",
    }) do
        local selected = Settings[settingsKey]
        if type(selected) == "table" then
            for rarityId in pairs(selected) do
                if not spawnRaritySet[rarityId] then selected[rarityId] = nil end
            end
        end
    end

    -- The game calls each egg/pet species its AssetCategory. Only categories
    -- supplied by real area drop tables belong here; event/shop-only assets stay out.
    -- Sort strongest to weakest so the overlay is useful without searching.
    local categoryEntries = {}
    for category in pairs(spawnCategorySet) do
        local asset = spawnAssets and spawnAssets[category]
        local rarity = asset and asset.Rarity
        categoryEntries[#categoryEntries + 1] = {
            id = category,
            name = tostring(asset and (asset.DisplayName or asset.Name) or category),
            rarity = type(rarity) == "table" and tostring(rarity._id or rarity.DisplayName or "") or tostring(rarity or ""),
            rate = tonumber(asset and asset.EarningRate) or 0,
            color = type(rarity) == "table" and rarity.Color or nil,
        }
    end
    table.sort(categoryEntries, function(a, b)
        if a.rate ~= b.rate then return a.rate > b.rate end
        return a.name < b.name
    end)
    for _, entry in ipairs(categoryEntries) do
        TargetCategoryData.Items[#TargetCategoryData.Items + 1] = entry.id
        local hex = typeof(entry.color) == "Color3" and toHex(entry.color) or "#FFFFFF"
        TargetCategoryData.Display[entry.id] = ('<b>%s</b> <font color="%s">%s</font> <font color="#9AA0AA">$%s/s</font>')
            :format(entry.name, hex, entry.rarity, short(entry.rate))
    end
    for category in pairs(Settings.TargetCategories) do
        if not spawnCategorySet[category] then Settings.TargetCategories[category] = nil end
    end
    -- Every category filter uses the same live area-spawn pool as Steal Filter.
    -- This keeps the wording, order, colors, and available species consistent
    -- across Place, Sell, Egg Sell, and Rift protection.
    for _, settingsKey in ipairs({
        "PlaceCategories", "SellPets", "SellEggNames", "FuseCategories",
    }) do
        local selected = Settings[settingsKey]
        if type(selected) == "table" then
            for category in pairs(selected) do
                if not spawnCategorySet[category] then selected[category] = nil end
            end
        end
    end

    -- Keep the picker in reverse physical map order (farthest to nearest). Read
    -- the real area directory so a
    -- future spawning area is included automatically, then append unknown areas
    -- alphabetically after the currently verified live areas.
    local preferredAreaOrder = {
        "Titan Temple", "Cherry Blossom", "Cosmic", "Prehistoric", "Abyss Ocean", "Volcano",
        "Snow", "Jungle", "Desert", "Lake", "Forest",
    }
    local spawnAreaSet = {}
    pcall(function()
        local Areas = require(ReplicatedStorage.Data.Areas)
        for areaKey, area in pairs(Areas.Directory or {}) do
            if type(area) == "table" and type(area.DropTable) == "table"
                and next(area.DropTable) ~= nil then
                local areaId = tostring(area._id or areaKey)
                spawnAreaSet[areaId] = true
            end
        end
    end)
    if next(spawnAreaSet) == nil then
        for _, areaId in ipairs(preferredAreaOrder) do spawnAreaSet[areaId] = true end
    end
    for _, areaId in ipairs(preferredAreaOrder) do
        if spawnAreaSet[areaId] then
            TargetAreaItems[#TargetAreaItems + 1] = areaId
            spawnAreaSet[areaId] = nil
        end
    end
    local extraAreas = {}
    for areaId in pairs(spawnAreaSet) do extraAreas[#extraAreas + 1] = areaId end
    table.sort(extraAreas)
    for _, areaId in ipairs(extraAreas) do TargetAreaItems[#TargetAreaItems + 1] = areaId end
    local areaColors = {
        Forest = "#62D96B", Lake = "#51BCEC", Desert = "#E6B85C",
        Jungle = "#42C98A", Snow = "#B9DFFB", Volcano = "#FF6B5F",
        ["Abyss Ocean"] = "#5E8CFF", Prehistoric = "#D49A65",
        Cosmic = "#B37BFF", ["Cherry Blossom"] = "#FF8FB8",
        ["Titan Temple"] = "#F0C86A",
    }
    for _, areaId in ipairs(TargetAreaItems) do
        TargetAreaDM[areaId] = ('<font color="%s"><b>%s</b></font>')
            :format(areaColors[areaId] or "#FFFFFF", areaId)
    end
    local validAreas = {}
    for _, areaId in ipairs(TargetAreaItems) do validAreas[areaId] = true end
    for _, settingsKey in ipairs({ "TargetAreas", "EggESPAreas" }) do
        for areaId in pairs(Settings[settingsKey]) do
            if not validAreas[areaId] then Settings[settingsKey][areaId] = nil end
        end
    end
end

