local function setStealStatus(txt)
    -- Capacity may become full while the final accepted carry is returning. Any
    -- late transaction status must not overwrite the reason Auto-Steal stopped.
    if RuntimeStatus.inventoryFullStopped
        and not (autoStealTgl and autoStealTgl.Value) then
        txt = "🟠 Inventory full · Auto-Steal off"
    end
    local nextStatus = "🥷 Steal: " .. tostring(txt):gsub("^[^%w%s]+%s*", "")
    RuntimeStatus.set("steal", nextStatus)
    RuntimeStatus.setLabel(stealStatusLbl, txt)
    if type(RuntimeStatus.resizeStealStatus) == "function" then
        RuntimeStatus.resizeStealStatus()
    end
end

