-- ════════════════════════════════════════════
-- [[ 5. AUTO-STEAL ENGINE ]] --
-- Flow: filter and rank the live area eggs → use the proven continuous mover at
-- Settings.StealSpeed → verify RequestCarryAreaEgg produced the target carry →
-- cross __OBJECTS.Areas.SeparationLine → require positive claim feedback → yield.
-- ════════════════════════════════════════════
local EggCmds, AssetsDir, MutationsMod
pcall(function()
    local EggState = require(ReplicatedStorage.Client.EggState)
    local EggRecords = require(ReplicatedStorage.Shared.Util.EggRecords)
    local AreaEggCycle = require(ReplicatedStorage.Shared.Util.AreaEggCycle)
    -- v428 renamed the egg client contract. Keep the rest of the automation on
    -- one compatibility surface while using the game's current implementation.
    EggCmds = {
        GetAreaEggSnapshot = EggState.ReadFieldEggs,
        AreaEggSnapshotUpdated = EggState.FieldRefreshed,
        AreaEggRecordUpdated = EggState.FieldShifted,
        AreaEggRecordRemoved = EggState.FieldGone,
        AreaEggCarryStateChanged = EggState.CarryChanged,
        AreaEggClaimed = EggState.FieldClaimed,
        RequestCarryAreaEgg = EggState.CarryFieldEgg,
        DropAreaEgg = EggState.DropFieldEgg,
        GetRuntimeSnapshot = EggState.ReadOwnedEggs,
        RuntimeSnapshotUpdated = EggState.SnapshotRefreshed,
        RuntimeResetCountdown = EggState.ResetCountdown,
        RequestEquipTool = EggState.WearEggTool,
        RequestUnequipTool = EggState.DoffEggTool,
        RequestPlaceEgg = EggState.PlantEgg,
        IsLocalEggReady = EggState.IsReadyToHatch,
        RequestHatchEgg = EggState.BeginHatch,
        RequestCompleteHatchEgg = EggState.FinishHatch,
        EggRecords = EggRecords,
        -- Hatch readiness has no dedicated signal. Predict the next deadline
        -- with the same timing functions used by the native egg UI; callers
        -- reschedule at day/night boundaries and replicated boost changes.
        SecondsUntilReady = function(record)
            if type(record) ~= "table" or type(record.Placement) ~= "table" then return nil end
            local now = workspace:GetServerTimeNow()
            local multiplier = math.max(0.01, tonumber(record.GrowthSpeedMultiplier) or 1)
            local nightCredit = EggRecords.CurrentNightCredit(record, now, multiplier)
            if EggRecords.IsGrown(record, now, multiplier, nightCredit, LocalPlayer) then return 0 end
            local remaining = EggRecords.GrowthSecondsRemaining(
                record, now, multiplier, nightCredit, LocalPlayer)
            local rate = multiplier
            pcall(function() rate += math.max(0, EggRecords.ServerGrowthBoostMultiplier()) end)
            pcall(function()
                if AreaEggCycle.IsNightPhase(now) then
                    rate += math.max(0, AreaEggCycle.NightGrowthRate())
                end
            end)
            local deadline = remaining / math.max(0.01, rate)
            pcall(function()
                local phaseRemaining = AreaEggCycle.SecondsUntilPhaseEnd(now)
                if phaseRemaining > 0 then deadline = math.min(deadline, phaseRemaining + 0.05) end
            end)
            return math.max(0.05, deadline)
        end,
    }
end)

-- ESP-only native helpers are optional dependencies. Keep them outside the
-- controller bootstrap so a future formatter/earnings module rename degrades
-- only display values instead of disabling Steal, Place, and Hatch together.
if EggCmds then
    pcall(function()
        EggCmds.AssetItems = require(ReplicatedStorage.Shared.Util.AssetItems)
    end)
    pcall(function()
