    end)
end

-- 🚨 THE "walks to the egg and never steals" BUG (fixed v1.8, 2026-08-20)
-- `GetAreaEggSnapshot().Records` contains TWO kinds of egg:
--   * normal eggs      → Uid = 32-hex, e.g. "01336952a1db4ef88491a25ac65856ff"
--   * FIRST-AREA eggs  → Uid = "FirstAreaEgg_<userId>_<serial>_<Area>:<NestId>"
-- and these first-area ones are the CLOSEST eggs to spawn, so Auto-Steal picked
-- them every single time. `RequestCarryAreaEgg(uid)` on one returns
-- **false, "Egg not found"** forever — it needs a SECOND argument.
-- The game's own ProximityPrompt handler (PlayerScripts.Game.AreaEggs:190) does:
--     local key = AreaEggSlotIdentity.IsFirstAreaUid(rec.Uid)
--         and AreaEggSlotIdentity.BuildSlotKey(rec.AreaId, rec.NestId) or nil
--     EggCmds.RequestCarryAreaEgg(rec.Uid, key)
-- Verified live: uid only -> "Egg not found"; uid + "Forest:Slot_002" -> ok=true,
-- egg state Carried, carried home, EggInventory 4 -> 5.
local AreaEggSlotIdentity
pcall(function()
    local identity = require(ReplicatedStorage.Shared.Util.AreaEggSlotIdentity)
    AreaEggSlotIdentity = {
        IsFirstAreaUid = identity.LooksLikeFirstAreaUid,
        BuildSlotKey = identity.SlotKey,
    }
end)

-- ⏳ RESET-WALL GATE + EVENT-DRIVEN SCANNER
-- Egg records are replaced before the night/reset wall has necessarily opened.
-- The snapshot alone therefore is not permission to move. The game's own
-- AreaEggResetWall.IsClosed() is authoritative, and Changed wakes the scanner
-- only when that state changes. SnapshotUpdated wakes it for real egg changes.
local ResetWall
pcall(function() ResetWall = require(ReplicatedStorage.Client.AreaEggResetWall) end)

local scanWake = Instance.new("BindableEvent")
getgenv().__CHSAE_ScanWake = scanWake
getgenv().__CHSAE_ScanConns = {}

wakeEggScanner = function(reason)
    if sessionAlive() then pcall(function() scanWake:Fire(reason or "change") end) end
end

local wallOpenedAt = 0
local function resetWallClosed()
    if not (ResetWall and type(ResetWall.IsSealed) == "function") then return false end
    local ok, closed = pcall(ResetWall.IsSealed)
    return ok and closed == true
end

wallOpenedAt = resetWallClosed() and 0 or os.clock()

local function trackScanConnection(signal, callback)
    if not signal then return end
    local ok, conn = pcall(function() return signal:Connect(callback) end)
    if ok and conn then
        table.insert(getgenv().__CHSAE_ScanConns, conn)
    end
end


if ResetWall then
    trackScanConnection(ResetWall.Changed, function()
        local closed = resetWallClosed()
        if not closed then wallOpenedAt = os.clock() end
        wakeEggScanner(closed and "wall-closed" or "wall-open")
    end)
end

if EggCmds then
    trackScanConnection(EggCmds.AreaEggSnapshotUpdated, function(snapshot)
        -- CandidateIndex is installed later, after rarity/value helpers exist.
        -- Once available, this signal becomes the only hot-path rebuild trigger.
        local index = RuntimeStatus.candidateIndex
        if index and type(index.Rebuild) == "function" then
            index:Rebuild(snapshot)
        end
        if type(RuntimeStatus.refreshEggESP) == "function" then
            RuntimeStatus.refreshEggESP()
        end
        -- FieldShifted normally starts dropped-egg recovery. Reconcile the full
        -- snapshot too: some executors can miss an individual signal while the
        -- fatal guard hit is replacing the character.
        if type(RuntimeStatus.reconcileCarryLossSnapshot) == "function" then
            task.defer(RuntimeStatus.reconcileCarryLossSnapshot, snapshot)
        end
        wakeEggScanner("snapshot")
    end)
end

-- Event wait with a low-frequency timeout only as a resilience fallback. Each
-- waiter has its own event so an old timeout cannot wake a later scanner pass.
local function waitForScannerWake(timeout, readyFn)
    local waiter = Instance.new("BindableEvent")
    local active = true
    local conn = scanWake.Event:Connect(function(reason)
        if active then waiter:Fire(reason) end
    end)
    task.delay(timeout or 8, function()
        if active then waiter:Fire("fallback") end
    end)

    -- Close the small check→subscribe race: the wall may have opened after the
    -- caller tested it but just before this listener was attached.
    if readyFn then
        local ok, ready = pcall(readyFn)
        if ok and ready then
            active = false
            conn:Disconnect()
            waiter:Destroy()
            return "already-ready"
        end
    end

    local reason = waiter.Event:Wait()
    active = false
    conn:Disconnect()
    waiter:Destroy()
    return reason
end

local areaResetUntil = 0
local function areaResetActive()
    return resetWallClosed() or os.clock() < areaResetUntil
end
local function markAreaReset(seconds)
    areaResetUntil = os.clock() + (seconds or 3)
end

-- 🛡️ GUARD ESCAPE GATE (v2.0) — why one account farms and another dies
-- Measured 2026-08-20 by comparing our two live clients:
--   * the WORKING instance (void26v1) runs **WalkSpeed ≈ 159**
--   * the dying instance  (void26v3) runs **WalkSpeed ≈ 35.8** (SpeedPower 2075)
-- `GuardChasePolicy.ResolveWalkSpeed` lets a guard accelerate to **4× its base
-- WalkSpeed**, and `ResolveCatchDuration` returns nil ("can never catch you") only
-- when your speed beats that. Base speeds: Forest 16 · Lake 35 · Desert 62 ·
-- Jungle 82 · Snow 98 · Volcano 113 · Abyss 130 · Cosmic 200.
--   → Forest needs > 64, Lake > 140, Desert > 248 …
-- So void26v1 (159) outruns Forest and Lake; void26v3 (35.8) outruns NOTHING.
-- When a guard catches you the server deals a single **-100 = instant death**
-- (captured live: `HP 100->0 (-100)` with the nearest guard 14 studs away, well
-- outside its 2.5-stud melee, KillPartIgnore armed and no deleted volume in range).
-- ⚠️ Hopping faster does NOT help: the catch is resolved from your legit
-- `Humanoid.WalkSpeed`, not from how fast we move the CFrame.
local GuardsDir
pcall(function() GuardsDir = require(ReplicatedStorage.Data.Guards) end)

-- true when that area's guard can run us down; also returns its top chase speed
-- ⚠️ v2.8 CRASH FIX: this used to call `getCharParts()`, which is declared ~120 lines
-- BELOW here, so the upvalue was still nil when this ran → "attempt to call a nil
-- value" → the error killed the whole Auto-Steal thread. Symptom: the status froze on
-- "Scanning…" forever and the character never moved. Read the Humanoid directly.
local function guardCanCatch(areaId)
    local cfg = GuardsDir and GuardsDir.Directory and GuardsDir.Directory[tostring(areaId)]
    local base = cfg and tonumber(cfg.WalkSpeed)
    if not base then return false, 0 end
    local maxChase = base * 4 -- GuardChasePolicy caps the chase at 4x base
    local ch = LocalPlayer.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local mine = (hum and hum.WalkSpeed) or 0
    return mine <= maxChase, maxChase
end

-- 💀 LETHAL-AREA MEMORY (v2.3) — learn instead of pre-restricting
-- Measured on void26v3 (SpeedPower 1,987,577 · WalkSpeed 128.1), the two systems are
-- INDEPENDENT and only the second one kills on long runs:
--   1. ENTRY gate (the sign's number vs your SpeedPower)  → Forest/Lake/Desert/
--      Jungle/Snow/Volcano all say ENTER-OK; Abyss/Prehistoric/Cosmic are locked.
--   2. GUARD CATCH (4× guard WalkSpeed vs your Humanoid.WalkSpeed) → only **Forest**
--      (chase 64) is outrunnable at 128. Lake 140, Desert 248, Jungle 328, Snow 392,
--      Volcano 452, Abyss 520, Cosmic 800 all CATCH us.
-- Captured on the farthest-egg run (Cosmic, 2,866 studs): **HP 100 -> -1000** at
-- sd = 292, which is just inside **Desert** (entry-OK, chase 248) — i.e. the guard
-- catch, not the entry lock. The corpse then stays gone for ~25 s, and a carry fired
-- while dead is refused ("Enter the gameplay area first"), so "keep stealing at 0 HP"
-- does not work on this path.
-- So instead of pre-filtering anything, we remember where we actually died and stop
-- feeding that area for a few minutes. As your speed grows, it simply retries.

-- The game's old ReplicatedStorage.Library hierarchy was removed. Keep the same
-- X/Z-oriented bounds test locally so death-area tracking survives game updates
-- without depending on a private module path.
local function isWorldPositionInsideXZBounds(bounds, worldPosition)
    if not (bounds and bounds:IsA("BasePart") and worldPosition) then return false end
    local localPosition = bounds.CFrame:PointToObjectSpace(worldPosition)
    local halfSize = bounds.Size * 0.5
    return math.abs(localPosition.X) <= halfSize.X
        and math.abs(localPosition.Z) <= halfSize.Z
end

local function areaAtPosition(pos)
    local gf = workspace:FindFirstChild("__OBJECTS")
    gf = gf and gf:FindFirstChild("Areas")
    gf = gf and gf:FindFirstChild("GuardAreas")
    if not (gf and pos) then return nil end
    for _, area in ipairs(gf:GetChildren()) do
        local b = area:FindFirstChild("Bounds")
        if b and b:IsA("BasePart") then
            local ok, inside = pcall(isWorldPositionInsideXZBounds, b, pos)
            if ok and inside then return area.Name end
        end
    end
    return nil
end

local function nearestGuardAt(pos)
    local objects = workspace:FindFirstChild("__OBJECTS")
    local areas = objects and objects:FindFirstChild("Areas")
    local guardAreas = areas and areas:FindFirstChild("GuardAreas")
    local bestName, bestDistance = "none", math.huge
    if not (guardAreas and pos) then return bestName, bestDistance end
    for _, area in ipairs(guardAreas:GetChildren()) do
        local model = area:FindFirstChild("Guard") or area:FindFirstChild("ForestGuardAuthored")
        local guardRoot = model and (model.PrimaryPart or model:FindFirstChild("HumanoidRootPart", true))
        if guardRoot then
            local distance = ((guardRoot.Position - pos) * Vector3.new(1, 0, 1)).Magnitude
            if distance < bestDistance then bestName, bestDistance = area.Name, distance end
        end
    end
    return bestName, bestDistance
end

-- watch every character we get; a catastrophic hit teaches us which area did it
RuntimeStatus.deathWatchedHumanoids = setmetatable({}, {__mode = "k"})
local function watchDeaths(char)
    task.spawn(function()
        local hum  = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
        local root = char:FindFirstChild("HumanoidRootPart") or char:WaitForChild("HumanoidRootPart", 5)
        if not (hum and root) then return end
        if RuntimeStatus.deathWatchedHumanoids[hum] then return end
        RuntimeStatus.deathWatchedHumanoids[hum] = true
        local last = hum.Health
        local deathReported = false
        local conn = hum.HealthChanged:Connect(function(h)
            if not sessionAlive() then return end
            if h <= 0 or h < last - 90 then      -- a catch is one huge hit (-100 / -1000)
                local area = areaAtPosition(root.Position)
                local state = rawget(getgenv(), "__CHSAE_IntegrityState")
                local evidence = type(state) == "table" and rawget(state, "Evidence") or nil
                local context = type(state) == "table" and rawget(state, "ImpulseContext") or nil
                local sample = type(state) == "table"
                    and (rawget(state, "LastObservedSample") or rawget(state, "LastSample")) or nil
                local contextTtl = type(context) == "table" and type(sample) == "table"
                    and ((tonumber(rawget(context, "ExpiresAt")) or 0)
                        - (tonumber(rawget(sample, "Timestamp")) or 0)) or -1
                local guardName, guardDistance = nearestGuardAt(root.Position)
                local pending = rawget(getgenv(), "__CHSAE_CarryRequest")
                warn(("[CloverHub-SAE][death] hp=%.1f->%.1f area=%s pos=%.1f,%.1f,%.1f ws=%.1f killIgnore=%s threat=%s S%s/T%s/F%s ctx=%.2f correction=%s guard=%s@%.1f carryFlight=%s"):format(
                    tonumber(last) or -1, tonumber(h) or -1, tostring(area or "Start/Unknown"),
                    root.Position.X, root.Position.Y, root.Position.Z, tonumber(hum.WalkSpeed) or -1,
                    tostring(root:GetAttribute("KillPartIgnore")),
                    tostring(type(state) == "table" and rawget(state, "ThreatLevel") or "--"),
                    tostring(type(evidence) == "table" and rawget(evidence, "Speed") or 0),
                    tostring(type(evidence) == "table" and rawget(evidence, "Teleport") or 0),
                    tostring(type(evidence) == "table" and rawget(evidence, "Flight") or 0),
                    contextTtl,
                    tostring(type(state) == "table" and rawget(state, "CorrectionContext") ~= nil),
                    tostring(guardName), tonumber(guardDistance) or -1,
                    tostring(type(pending) == "table" and pending.inFlight == true)))
                -- The logger used to stop here. That left Auto-Steal holding the
                -- dead character's target transaction after respawn.
                if h <= 0 and not deathReported then
                    deathReported = true
                    local onDeath = RuntimeStatus.onAutoStealDeath
                    if type(onDeath) == "function" then task.defer(onDeath, char) end
                end
            end
            last = h
        end)
        local runtimeConns = getgenv().__CHSAE_RuntimeConns
        if type(runtimeConns) == "table" then runtimeConns[#runtimeConns + 1] = conn end
    end)
end
if LocalPlayer.Character then watchDeaths(LocalPlayer.Character) end
getgenv().__CHSAE_RuntimeConns = getgenv().__CHSAE_RuntimeConns or {}
getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = LocalPlayer.CharacterAdded:Connect(watchDeaths)

-- NOTE (v2.1): we do NOT filter targets on this any more — the hub hunts whatever
-- matches your rarity/priority, exactly like before. `guardCanCatch` is kept only so
-- the status line can warn you, because on a slow character a deep egg WILL end in a
-- guard catch (instant -100) no matter how the movement is written.

-- The 2nd arg RequestCarryAreaEgg wants (nil for ordinary eggs).
local function carrySlotKey(rec)
    if not (AreaEggSlotIdentity and rec and rec.Uid) then return nil end
    local key
    pcall(function()
        if AreaEggSlotIdentity.IsFirstAreaUid(rec.Uid) then
            key = AreaEggSlotIdentity.BuildSlotKey(rec.AreaId, rec.NestId)
        end
    end)
    return key
end
pcall(function() AssetsDir = require(ReplicatedStorage.Data.Assets) end)
pcall(function()
    local NativeMutations = require(ReplicatedStorage.Shared.Modules.Mutations)
    MutationsMod = {
        MutationNames = NativeMutations.Ids(),
        GetTotalMutationsEarningMulti = NativeMutations.EarningsFor,
        GetDisplayName = NativeMutations.LabelOf,
        GetMutation = function(id)
            local mutation = NativeMutations.Get(id)
            if type(mutation) ~= "table" then return nil end
            return {
                Color = mutation.Tint,
                ValueMulti = mutation.EarningsScalar,
                DisplayName = mutation.Label,
                _id = mutation.Id,
            }
        end,
    }
end)

-- rec.Mutations is an array of mutation names ({"Silver"}); "None" doesn't count.
local function getMutations(rec)
    local out = {}
    if type(rec.Mutations) == "table" then
        for _, m in pairs(rec.Mutations) do
            if type(m) == "string" and m ~= "None" then out[#out + 1] = m end
        end
    end
    return out
end

-- Native value = the exact income/sec used by the game's egg and inventory
-- tooltips. The older linear estimate remains ranking-only fallback data; a
-- value filter fails closed when the authoritative native result is unavailable.
local function valueScore(rec)
    local nativeValue
    pcall(function()
        if type(rec) ~= "table" then return end
        local item = type(rec.ItemData) == "table" and rec.ItemData or rec
        if not (type(item.Category) == "string" and type(item.Scale) == "number"
            and type(item.Mutations) == "table") then
            local records = EggCmds and EggCmds.EggRecords
            if records and type(records.ToAssetItemData) == "function" then
                local okItem, converted = pcall(records.ToAssetItemData, rec)
                if okItem and type(converted) == "table" then item = converted end
            end
        end
        local earnings = EggCmds and EggCmds.AssetEarnings
        if type(item) == "table" and earnings
            and type(earnings.MutationOnlyRatePerSecond) == "function" then
            local okValue, result = pcall(earnings.MutationOnlyRatePerSecond, item)
            if okValue and type(result) == "number" then nativeValue = result end
        end
    end)
    if type(nativeValue) == "number" and nativeValue == nativeValue
        and nativeValue > -math.huge and nativeValue < math.huge then
        return math.max(nativeValue, 0), true
    end

    local fallback
    pcall(function()
        if type(rec) ~= "table" then return end
        local item = type(rec.ItemData) == "table" and rec.ItemData or rec
        local category = item.AssetCategory or item.Category or rec.AssetCategory or rec.Category
        local scale = item.AssetScale or item.Scale or rec.AssetScale or rec.Scale
        local entry = AssetsDir.Directory[category]
        local base = tonumber(entry and entry.EarningRate)
        if not base or tonumber(scale) == nil then return end
        local mult  = 1
        local muts  = getMutations(rec)
        if #muts > 0 and MutationsMod then
            local ok, m = pcall(MutationsMod.GetTotalMutationsEarningMulti, muts)
            if ok and tonumber(m) then mult = tonumber(m) end
        end
        fallback = base * mult * tonumber(scale)
    end)
    if type(fallback) ~= "number" or fallback ~= fallback
        or fallback <= -math.huge or fallback >= math.huge then fallback = 0 end
    return math.max(fallback, 0), false
end
RuntimeStatus.riftValueScore = valueScore

function RuntimeStatus.valueFilterMatches(recordOrValue, threshold, mode, known)
    if not RuntimeStatus.valueFilterActive(threshold) then return true end
    local limit = tonumber(threshold)
    if not limit or limit <= 0 then return false end

    local value = recordOrValue
    if type(value) ~= "number" then
        value, known = valueScore(recordOrValue)
    elseif known == nil then
        known = true
    end
    if known ~= true or type(value) ~= "number" or value ~= value
        or value <= -math.huge or value >= math.huge then return false end
    if mode == "atLeast" then return value >= limit end
    -- A seller threshold is a keep floor: only values strictly below it match.
    -- Zero is kept as suspicious/unknown because all current asset base rates are
    -- positive and selling an unverified zero would be irreversible.
    if mode == "below" then return value > 0 and value < limit end
    return false
end

-- Authoritative visual KG from ReplicatedStorage.Library.Util.AssetItemUtil:
-- Assets.Directory[Category].ModelWeight * max(Scale, 0)^3. The game's
-- Commas formatter rounds that value to a whole KG for display. Area/incubator
-- records use AssetCategory/AssetScale; deserialized pets use Category/Scale.
local function weightKg(rec)
    local weight
    pcall(function()
        if type(rec) ~= "table" then return end
        local itemData = type(rec.ItemData) == "table" and rec.ItemData or rec
        local category = itemData.AssetCategory or itemData.Category
            or rec.AssetCategory or rec.Category
        local rawScale = itemData.AssetScale or itemData.Scale
            or rec.AssetScale or rec.Scale
        local entry = category and AssetsDir and AssetsDir.Directory
            and AssetsDir.Directory[category]
        local modelWeight = tonumber(entry and entry.ModelWeight)
        local scale = tonumber(rawScale)
        if modelWeight == nil or scale == nil then return end
        weight = modelWeight * math.max(scale, 0) ^ 3
    end)
    return weight
end

function RuntimeStatus.kgFilterMatches(recordOrWeight, mode, threshold, known)
    if not RuntimeStatus.kgFilterActive(mode, threshold) then return true end
    local limit = tonumber(threshold)
    if limit == nil or limit < 0 then return false end

    local weight = recordOrWeight
    if type(weight) ~= "number" then
        weight = weightKg(recordOrWeight)
        known = weight ~= nil
    elseif known == nil then
        known = true
    end
    if not known or type(weight) ~= "number" then return false end

    -- Match the number the player sees, not the misleading Tool.Weight value
    -- (ModelWeight * Scale) and not hidden fractional precision.
    local displayedWeight = math.round(math.max(weight, 0))
    if mode == "Below" then return displayedWeight <= limit end
    return displayedWeight >= limit
end

local carrying = false
local stealRuntime = {
    claimSequence = 0,
    lastClaim = nil,
    webhookTarget = nil,
    persistentUid = nil,
    -- The chosen egg remains transaction-locked through every recoverable
    -- request failure. Persistent Steal extends that lock across drops/other
    -- carriers; it is no longer required merely to survive a position retry.
    lockedUid = nil,
    requestFailureUid = nil,
    requestFailureCount = 0,
    requestFailureAt = 0,
    lastRequestError = "",
    lastRequestKind = "",
    carriedUid = nil,
    -- Keep one short-lived, positively observed ownership fact outside the
    -- transient CarryChanged/field-record state. On a fatal catch the server can
    -- publish Carry=false or FieldGone before Humanoid.HealthChanged reaches us;
    -- the death handler still needs the exact UID from the last verified frame.
    lastPositiveCarryUid = nil,
    lastPositiveCarryAt = 0,
    lastDroppedUid = nil,
    -- How long a guard drop stays reclaimable while stealFeatureEnabled() is
    -- momentarily false. Long enough to outlast a Rift hand-off,
    -- short enough that a genuinely retired egg cannot linger as a target.
    disabledRecoveryHold = 25,
    -- Set when stealFeatureEnabled() first reads false while an egg is in hand.
    -- Bounds how long the worker may outlive a disabled feature to finish it.
    featureGraceAt = 0,
    featureGrace = 12,
    dropDetectedAt = 0,
    dropCount = 0,
    -- A guard catch is fatal, so the dropped egg can outlive the character that
    -- carried it. Keep that exact, positively-owned UID through respawn until the
    -- field snapshot proves it was dropped, reset/claimed, or taken by somebody.
    deathRecoveryUid = nil,
    deathRecoveryAt = 0,
    deathRecoveryMissingAt = 0,
    deathRecoveryMissingReason = "",
    dropRecoveryRecord = nil,
    dropRecoveryRecordUid = nil,
    dropRecoveryRecordAt = 0,
    attemptUid = nil,
    lastPickupSettle = 0,
    lastPickupRequiredSettle = 0,
    lastPickupDistance = math.huge,
    lastPickupFromTreadmill = false,
    respawnGeneration = 0,
    characterToken = LocalPlayer.Character,
}
-- Long enough for executors that miss the final HealthChanged packet and only
-- enter recovery from CharacterAdded after Roblox's respawn delay.
stealRuntime.deathCarryEvidenceTtl = 12
stealRuntime.deathRecoveryMissingGrace = 15

stealRuntime.rememberPositiveCarry = function(uid)
    if uid == nil then return end
    stealRuntime.lastPositiveCarryUid = uid
    stealRuntime.lastPositiveCarryAt = os.clock()
end

stealRuntime.recentPositiveCarryUid = function()
    local uid = stealRuntime.lastPositiveCarryUid
    local age = os.clock() - (tonumber(stealRuntime.lastPositiveCarryAt) or 0)
    if uid ~= nil and age >= 0 and age <= stealRuntime.deathCarryEvidenceTtl then return uid end
    return nil
end

stealRuntime.clearPositiveCarryEvidence = function(uid)
    if uid == nil or tostring(stealRuntime.lastPositiveCarryUid) == tostring(uid) then
        stealRuntime.lastPositiveCarryUid = nil
        stealRuntime.lastPositiveCarryAt = 0
    end
end

clearPersistentTarget = function()
    stealRuntime.persistentUid = nil
    stealRuntime.lockedUid = nil
    stealRuntime.attemptUid = nil
    stealRuntime.lastDroppedUid = nil
    stealRuntime.dropDetectedAt = 0
    stealRuntime.deathRecoveryUid = nil
    stealRuntime.deathRecoveryAt = 0
    stealRuntime.deathRecoveryMissingAt = 0
    stealRuntime.deathRecoveryMissingReason = ""
    stealRuntime.dropRecoveryRecord = nil
    stealRuntime.dropRecoveryRecordUid = nil
    stealRuntime.dropRecoveryRecordAt = 0
    RuntimeStatus.pendingDroppedUid = nil
    stealRuntime.clearPositiveCarryEvidence()
    local kind = tostring(stealRuntime.lastRequestKind or "")
    if kind == "carry-loss-sync" or kind == "death-drop-sync" or kind == "carry-drop" then
        stealRuntime.requestFailureUid = nil
        stealRuntime.requestFailureCount = 0
        stealRuntime.requestFailureAt = 0
        stealRuntime.lastRequestKind = ""
        stealRuntime.lastRequestError = ""
    end
end

-- Process-wide carry request lock. A RemoteFunction Invoke cannot be cancelled;
-- keeping this in getgenv() prevents a reload from issuing a second request while
-- an older server call is still blocked.
if type(getgenv().__CHSAE_CarryRequest) ~= "table" then
    getgenv().__CHSAE_CarryRequest = nil
end
-- [[ DELIVERY WALK RECOVERY ]] --
RuntimeStatus.noteDeliveryFailure = function(message)
    if not sessionAlive()
        or message ~= "Delivery failed! The egg was returned to its nest." then return false end
    local request = getgenv().__CHSAE_CarryRequest
    -- The alert contains no UID. Attribute it only to this session's proven
    -- target carry; other workers, old characters and completed claims cannot
    -- change the movement policy. Never retire an uncancellable Invoke here.
    if type(request) ~= "table" or request.owner ~= "Steal"
        or request.accepted ~= true or request.carrySeen ~= true
        or request.claimSeen == true or request.deliveryRejected == true
        or request.session ~= SESSION.Marker
        or request.character ~= LocalPlayer.Character
        or request.generation ~= stealRuntime.respawnGeneration
        or request.uid == nil or stealRuntime.lockedUid == nil
        or tostring(request.uid) ~= tostring(stealRuntime.lockedUid) then return false end
    request.deliveryRejected = true
    RuntimeStatus.deliveryRejections = (RuntimeStatus.deliveryRejections or 0) + 1
    RuntimeStatus.lastDeliveryRejectedUid = request.uid
    -- Retain the exact target and let carry/drop replication settle it.
    -- A rejected delivery never changes the selected return movement.
    if wakeEggScanner then wakeEggScanner("delivery-retry") end
    return true
end
-- [[ END DELIVERY WALK RECOVERY ]] --
do
    local packages = ReplicatedStorage:FindFirstChild("Packages")
    local networking = packages and packages:FindFirstChild("Networking")
    local alerts = networking and networking:FindFirstChild("RE/Alerts/Raise")
    if alerts and alerts:IsA("RemoteEvent") then
        trackScanConnection(alerts.OnClientEvent, function(_, _, payload)
            if type(payload) == "table" then RuntimeStatus.noteDeliveryFailure(payload.Message) end
        end)
    end
end
if EggCmds then
    pcall(function()
        trackScanConnection(EggCmds.AreaEggCarryStateChanged, function(state)
            if not sessionAlive() then return end
            if RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.observeCarry(state) then return end
            local packetUid = type(state) == "table" and state.Uid or nil
            -- This signal carries a TABLE, not a boolean. Treating every table as
            -- true made a drop look like an active carry until another event fixed it.
            local wasCarrying = carrying
            local previousCarriedUid = stealRuntime.carriedUid
            carrying = type(state) == "table" and state.IsCarrying == true
                or type(state) ~= "table" and state == true
            if carrying then
                local resolvedCarryUid = packetUid
                if resolvedCarryUid == nil and wasCarrying and previousCarriedUid ~= nil then
                    -- Anonymous carry packets can retain previously proven ownership.
                    resolvedCarryUid = previousCarriedUid
                end
                stealRuntime.carriedUid = resolvedCarryUid
                stealRuntime.rememberPositiveCarry(stealRuntime.carriedUid)
                local liveRequest = getgenv().__CHSAE_CarryRequest
                if type(liveRequest) == "table"
                    and tostring(liveRequest.uid) == tostring(stealRuntime.carriedUid) then
                    liveRequest.carrySeen = true
                    liveRequest.carryActive = true
                    liveRequest.carryEndedSeen = false
                    liveRequest.droppedSeen = false
                end
                if tostring(RuntimeStatus.pendingDroppedUid)
                    == tostring(stealRuntime.carriedUid) then
                    RuntimeStatus.pendingDroppedUid = nil
                end
                if tostring(stealRuntime.deathRecoveryUid)
                    == tostring(stealRuntime.carriedUid) then
                    stealRuntime.deathRecoveryUid = nil
                    stealRuntime.deathRecoveryAt = 0
                    stealRuntime.deathRecoveryMissingAt = 0
                    stealRuntime.deathRecoveryMissingReason = ""
                end
                if tostring(stealRuntime.dropRecoveryRecordUid)
                    == tostring(stealRuntime.carriedUid) then
                    stealRuntime.dropRecoveryRecord = nil
                    stealRuntime.dropRecoveryRecordUid = nil
                    stealRuntime.dropRecoveryRecordAt = 0
                end
                -- CarryRunBackEffects resolves the one chasing guard from this
                -- exact AreaId. Preserve a previously selected target only if an
                -- older replication packet omits AreaId.
                if type(state) == "table" and state.AreaId ~= nil then
                    RuntimeStatus.activeGuardAreaId = tostring(state.AreaId)
                end
            else
                -- AreaEggCarryState.Uid is optional on a false/drop packet. Save
                -- the last positively carried UID before clearing it so the
                -- worker can reacquire the exact egg instead of returning empty.
                local droppedUid = type(state) == "table" and state.Uid
                    or previousCarriedUid
                    or stealRuntime.lockedUid
                    or stealRuntime.attemptUid
                local liveRequest = getgenv().__CHSAE_CarryRequest
                if type(liveRequest) == "table"
                    and tostring(liveRequest.uid) == tostring(droppedUid) then
                    -- Carry=false is only an edge notification. It also precedes a
                    -- successful AreaEggClaimed delivery, so do not call it a drop
                    -- until the authoritative field row says State=Dropped.
                    liveRequest.carryActive = false
                    liveRequest.carryEndedSeen = true
                end
                local requestProvedCarry = type(liveRequest) == "table"
                    and tostring(liveRequest.uid) == tostring(droppedUid)
                    and liveRequest.carrySeen == true
                local deathProvedCarry = tostring(stealRuntime.deathRecoveryUid)
                    == tostring(droppedUid)
                if droppedUid ~= nil
                    and (wasCarrying or requestProvedCarry or deathProvedCarry) then
                    if RuntimeStatus.isCaptureEventUid(droppedUid) then
                        stealRuntime.rememberPositiveCarry(droppedUid)
                        if tostring(stealRuntime.lockedUid) == tostring(droppedUid) then
                            stealRuntime.lockedUid = nil
                        end
                        if tostring(stealRuntime.persistentUid) == tostring(droppedUid) then
                            stealRuntime.persistentUid = nil
                        end
                        local wakeAdmin = getgenv().__CHSAE_AdminEventWake
                        if wakeAdmin then pcall(function() wakeAdmin:Fire("capture-dropped") end) end
                    else
                        stealRuntime.rememberPositiveCarry(droppedUid)
                        stealRuntime.lastDroppedUid = droppedUid
                        stealRuntime.dropDetectedAt = os.clock()
                        stealRuntime.lockedUid = droppedUid
                        stealRuntime.requestFailureUid = droppedUid
                        stealRuntime.requestFailureAt = stealRuntime.dropDetectedAt
                        -- Carry=false also precedes a normal AreaEggClaimed delivery.
                        -- Treat it as provisional until the field record proves that
                        -- this UID is actually Dropped.
                        stealRuntime.lastRequestKind = deathProvedCarry
                            and "death-drop-sync" or "carry-loss-sync"
                        stealRuntime.lastRequestError = "carry ended; checking delivery or drop"
                        RuntimeStatus.pendingDroppedUid = droppedUid
                        if type(liveRequest) == "table"
                            and tostring(liveRequest.uid) == tostring(droppedUid) then
                            liveRequest.carrySeen = true
                        end
                        if type(RuntimeStatus.armDroppedEggReacquire) == "function" then
                            task.defer(RuntimeStatus.armDroppedEggReacquire, droppedUid,
                                "carry state reported a drop")
                        end
                        if wakeEggScanner then wakeEggScanner("carry-dropped") end
                    end
                end
                stealRuntime.carriedUid = nil
                RuntimeStatus.activeGuardAreaId = nil
            end
            -- An anonymous positive edge without an exact or isolated-bait UID is
            -- not ownership proof. The field snapshot will supply identity; until
            -- then it must not make the selected target look carried.
            if carrying and stealRuntime.carriedUid == nil then
                carrying = false
                RuntimeStatus.activeGuardAreaId = nil
            end
            RuntimeStatus.carry = carrying and "📦 Carry: locally verified"
                or "📦 Carry: none"
            RuntimeStatus.wakeOverlay("carry-state")
        end)
        if EggCmds.AreaEggRecordUpdated then
            trackScanConnection(EggCmds.AreaEggRecordUpdated, function(first, second)
                if not sessionAlive() then return end
                -- Current EggState emits the record directly. Accept (uid, record)
                -- as well so a contract wrapper/update cannot silently discard the
                -- authoritative Dropped transition.
                local record = type(first) == "table" and first
                    or type(second) == "table" and second or nil
                local uid = record and (record.Uid or record.UID or record.EggUid)
                    or (type(first) ~= "table" and first)
                    or (type(second) ~= "table" and second)
                if uid == nil or type(record) ~= "table" then return end
                if RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.isBait(uid) then return end
                if tonumber(record.CarrierUserId) == LocalPlayer.UserId then
                    stealRuntime.rememberPositiveCarry(uid)
                end
                if type(RuntimeStatus.queueCandidateIndexRebuild) == "function" then
                    RuntimeStatus.queueCandidateIndexRebuild("field-shifted")
                end
                local exactTracked = tostring(uid) == tostring(stealRuntime.lockedUid)
                    or tostring(uid) == tostring(stealRuntime.attemptUid)
                    or tostring(uid) == tostring(stealRuntime.carriedUid)
                    or tostring(uid) == tostring(stealRuntime.lastDroppedUid)
                    or tostring(uid) == tostring(stealRuntime.deathRecoveryUid)
                local priorOwned = carrying
                    or tostring(uid) == tostring(stealRuntime.carriedUid)
                    or tostring(uid) == tostring(stealRuntime.lastDroppedUid)
                    or tostring(uid) == tostring(stealRuntime.deathRecoveryUid)
                local liveRequest = getgenv().__CHSAE_CarryRequest
                if type(liveRequest) == "table"
                    and tostring(liveRequest.uid) == tostring(uid)
                    and liveRequest.carrySeen == true then
                    priorOwned = true
                end
                local recordCarrierId = tonumber(record.CarrierUserId)
                local recordState = tostring(record.State)
                local recordRecoveryReady = ((recordState == "Slot"
                        or recordState == "Dropped") and record.BottomCFrame ~= nil)
                    or recordCarrierId == LocalPlayer.UserId
                if tostring(stealRuntime.deathRecoveryUid) == tostring(uid) then
                    if recordRecoveryReady then
                        stealRuntime.deathRecoveryMissingAt = 0
                        stealRuntime.deathRecoveryMissingReason = ""
                    elseif recordState ~= "Claimed"
                        and not (recordCarrierId ~= nil and recordCarrierId > 0
                            and recordCarrierId ~= LocalPlayer.UserId)
                        and (tonumber(stealRuntime.deathRecoveryMissingAt) or 0) <= 0 then
                        stealRuntime.deathRecoveryMissingAt = os.clock()
                        stealRuntime.deathRecoveryMissingReason = "record-transitioning"
                    end
                end
                if exactTracked and priorOwned and tostring(record.State) == "Dropped"
                    and record.BottomCFrame then
                    stealRuntime.dropRecoveryRecord = record
                    stealRuntime.dropRecoveryRecordUid = uid
                    stealRuntime.dropRecoveryRecordAt = os.clock()
                    if tostring(stealRuntime.lastDroppedUid) ~= tostring(uid)
                        or (tonumber(stealRuntime.dropDetectedAt) or 0) <= 0 then
                        stealRuntime.dropDetectedAt = os.clock()
                    end
                    stealRuntime.lastDroppedUid = uid
                    stealRuntime.lockedUid = uid
                    stealRuntime.requestFailureUid = uid
                    stealRuntime.requestFailureAt = stealRuntime.dropDetectedAt
                    stealRuntime.lastRequestKind = tostring(stealRuntime.deathRecoveryUid)
                        == tostring(uid) and "death-drop-sync" or "carry-loss-sync"
                    stealRuntime.lastRequestError = "field egg shifted to dropped"
                    RuntimeStatus.pendingDroppedUid = uid
                    carrying = false
                    stealRuntime.carriedUid = nil
                    RuntimeStatus.activeGuardAreaId = nil
                    if type(liveRequest) == "table"
                        and tostring(liveRequest.uid) == tostring(uid) then
                        liveRequest.carrySeen = true
                        liveRequest.carryActive = false
                        liveRequest.carryEndedSeen = true
                        liveRequest.droppedSeen = true
                    end
                    if type(RuntimeStatus.armDroppedEggReacquire) == "function" then
                        task.defer(RuntimeStatus.armDroppedEggReacquire, uid,
                            "field egg shifted to dropped", record)
                    end
                    if wakeEggScanner then wakeEggScanner("field-egg-dropped") end
                    RuntimeStatus.wakeOverlay("field-egg-dropped")
                elseif exactTracked
                    and tostring(stealRuntime.dropRecoveryRecordUid) == tostring(uid) then
                    stealRuntime.dropRecoveryRecord = nil
                    stealRuntime.dropRecoveryRecordUid = nil
                    stealRuntime.dropRecoveryRecordAt = 0
                end
            end)
        end
        if EggCmds.AreaEggRecordRemoved then
            trackScanConnection(EggCmds.AreaEggRecordRemoved, function(uid)
                if not sessionAlive() then return end
                if type(uid) == "table" then uid = uid.Uid or uid.UID or uid.EggUid end
                if uid == nil then return end
                if RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.isBait(uid) then return end
                if type(RuntimeStatus.queueCandidateIndexRebuild) == "function" then
                    RuntimeStatus.queueCandidateIndexRebuild("field-gone")
                end
                local exactRecovery = tostring(uid) == tostring(stealRuntime.lastDroppedUid)
                    or tostring(uid) == tostring(stealRuntime.deathRecoveryUid)
                if exactRecovery then
                    local positiveUid = stealRuntime.recentPositiveCarryUid()
                    local preserveAcrossDeath = tostring(stealRuntime.deathRecoveryUid)
                            == tostring(uid)
                        or tostring(positiveUid) == tostring(uid)
                    if preserveAcrossDeath then
                        -- FieldGone is not final during a fatal carry transition:
                        -- the same UID may reappear as Dropped/guard-carried/Slot.
                        -- Hold the exact transaction through respawn and let the
                        -- worker clear it only after a bounded missing-record grace.
                        stealRuntime.lockedUid = uid
                        if (tonumber(stealRuntime.deathRecoveryMissingAt) or 0) <= 0 then
                            stealRuntime.deathRecoveryMissingAt = os.clock()
                        end
                        stealRuntime.deathRecoveryMissingReason = "field-gone"
                        RuntimeStatus.pendingDroppedUid = uid
                    else
                        if type(RuntimeStatus.clearCarryLossRecovery) == "function" then
                            RuntimeStatus.clearCarryLossRecovery(uid)
                        end
                        if tostring(stealRuntime.lockedUid) == tostring(uid) then
                            stealRuntime.lockedUid = nil
                        end
                        if tostring(stealRuntime.persistentUid) == tostring(uid) then
                            stealRuntime.persistentUid = nil
                        end
                    end
                end
                if wakeEggScanner then wakeEggScanner("field-egg-gone") end
            end)
        end
        trackScanConnection(EggCmds.AreaEggClaimed, function(feedback)
            if not sessionAlive() then return end
            if RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.observeClaim(feedback) then return end
            local priorCarriedUid = carrying and stealRuntime.carriedUid or nil
            local claimRequest = getgenv().__CHSAE_CarryRequest
            local requestProvedUid = type(claimRequest) == "table"
                and claimRequest.carrySeen == true and claimRequest.uid or nil
            carrying = false
            stealRuntime.carriedUid = nil
            RuntimeStatus.activeGuardAreaId = nil
            stealRuntime.attemptUid = nil
            stealRuntime.claimSequence += 1
            RuntimeStatus.steals = (RuntimeStatus.steals or 0) + 1
            local feedbackCategory = type(feedback) == "table" and feedback.AssetCategory or nil
            local feedbackUid = type(feedback) == "table"
                and (feedback.Uid or feedback.UID or feedback.EggUid) or nil
            -- Some claim payloads omit Uid. Infer it only from positive local
            -- ownership, never merely from a lock that an unrelated event could
            -- otherwise retire while death recovery is in progress.
            feedbackUid = feedbackUid or priorCarriedUid or requestProvedUid
            if type(claimRequest) == "table" and feedbackUid ~= nil
                and tostring(claimRequest.uid) == tostring(feedbackUid) then
                claimRequest.carryActive = false
                claimRequest.claimSeen = true
            end
            local activeRecoveryUid = stealRuntime.deathRecoveryUid
                or stealRuntime.lastDroppedUid
            local unscopedClaimCanClear = feedbackUid == nil and activeRecoveryUid == nil
            if unscopedClaimCanClear
                or tostring(stealRuntime.lastPositiveCarryUid) == tostring(feedbackUid) then
                stealRuntime.clearPositiveCarryEvidence(feedbackUid)
            end
            if unscopedClaimCanClear
                or tostring(RuntimeStatus.pendingDroppedUid) == tostring(feedbackUid) then
                RuntimeStatus.pendingDroppedUid = nil
            end
            -- The field claim can arrive one replication packet before the new
            -- EggInventory record. Reserve this exact Crane immediately so the
            -- scanner cannot begin a second unlock steal inside that gap.
            local claimDetails = stealRuntime.webhookTarget
            local unlockClaimCategory = feedbackCategory
                or (type(claimDetails) == "table" and claimDetails.category)
            local unlockClaimUid = feedbackUid
                or (type(claimDetails) == "table" and claimDetails.uid)
                or stealRuntime.lockedUid
            if type(claimDetails) == "table"
                and claimDetails.source == "rift"
                and feedbackUid ~= nil and claimDetails.uid ~= nil
                and tostring(feedbackUid) == tostring(claimDetails.uid) then
                RuntimeStatus.riftClaimHandoffUid = feedbackUid
                RuntimeStatus.riftClaimHandoffAt = os.clock()
                RuntimeStatus.riftReservedEggs[tostring(feedbackUid)] = true
                RuntimeStatus.riftEggHandoffs[tostring(feedbackUid)] = {
                    category = claimDetails.category, at = os.clock(),
                }
                local riftWake = getgenv().__CHSAE_RiftWake
                if riftWake then
                    task.defer(function()
                        if sessionAlive() then
                            pcall(function() riftWake:Fire("field-claim-handoff") end)
                        end
                    end)
                end
            end
            if Settings.AutoUnlockGreatBloom == true
                and RuntimeStatus.greatBloomUnlockStealWanted == true
                and tostring(unlockClaimCategory or "") == "Crane" then
                RuntimeStatus.greatBloomUnlockStealWanted = false
                RuntimeStatus.greatBloomUnlockClaimedAt = os.clock()
                RuntimeStatus.greatBloomUnlockClaimedEggUid = unlockClaimUid
                RuntimeStatus.greatBloomUnlock.reservedEggUid = unlockClaimUid
                if wakeEggScanner then wakeEggScanner("crane-claim-sync") end
                if type(RuntimeStatus.wakeGreatBloomUnlock) == "function" then
                    task.defer(RuntimeStatus.wakeGreatBloomUnlock, "crane-claimed")
                end
            end
            if unscopedClaimCanClear
                or tostring(stealRuntime.lastDroppedUid) == tostring(feedbackUid) then
                stealRuntime.lastDroppedUid = nil
                stealRuntime.dropDetectedAt = 0
                if stealRuntime.lastRequestKind == "carry-loss-sync"
                    or stealRuntime.lastRequestKind == "death-drop-sync"
                    or stealRuntime.lastRequestKind == "carry-drop" then
                    stealRuntime.requestFailureUid = nil
                    stealRuntime.requestFailureCount = 0
                    stealRuntime.requestFailureAt = 0
                    stealRuntime.lastRequestKind = ""
                    stealRuntime.lastRequestError = ""
                end
            end
            if unscopedClaimCanClear
                or tostring(stealRuntime.deathRecoveryUid) == tostring(feedbackUid) then
                stealRuntime.deathRecoveryUid = nil
                stealRuntime.deathRecoveryAt = 0
                stealRuntime.deathRecoveryMissingAt = 0
                stealRuntime.deathRecoveryMissingReason = ""
            end
            if unscopedClaimCanClear
                or tostring(stealRuntime.dropRecoveryRecordUid) == tostring(feedbackUid) then
                stealRuntime.dropRecoveryRecord = nil
                stealRuntime.dropRecoveryRecordUid = nil
                stealRuntime.dropRecoveryRecordAt = 0
            end
            stealRuntime.lastClaim = {
                Sequence = stealRuntime.claimSequence,
                AssetCategory = feedbackCategory,
                Uid = feedbackUid,
                Scoped = not (feedbackUid == nil and activeRecoveryUid ~= nil),
                At = os.clock(),
            }
            -- Claim feedback is authoritative. Remove the completed UID from
            -- both transaction locks and the selection cache immediately so a
            -- stale Slot snapshot cannot issue a duplicate carry request.
            if feedbackUid ~= nil then
                if tostring(stealRuntime.lockedUid) == tostring(feedbackUid) then
                    stealRuntime.lockedUid = nil
                end
                if tostring(stealRuntime.persistentUid) == tostring(feedbackUid) then
                    stealRuntime.persistentUid = nil
                end
                local candidateIndex = RuntimeStatus.candidateIndex
                if candidateIndex and type(candidateIndex.Invalidate) == "function" then
                    candidateIndex:Invalidate(feedbackUid, "local claim verified")
                end
            end
            RuntimeStatus.carry = "📦 Carry: delivery verified"
            if type(RuntimeStatus.sendWebhook) == "function" then
                local details = stealRuntime.webhookTarget
                if details and feedbackUid and details.uid
                    and tostring(details.uid) ~= tostring(feedbackUid) then details = nil end
                if details and feedbackCategory and details.category
                    and tostring(details.category) ~= tostring(feedbackCategory) then details = nil end
                -- AreaEggClaimed is shared by ordinary Auto Steal, Rift,
                -- internal collection, and even untracked/manual claims. Only a
                -- target explicitly chosen by the ordinary Steal Filter may
                -- authorize Steal Alerts; missing/mismatched metadata fails closed.
                local shouldNotify = details and details.source == "steal-filter"
                stealRuntime.webhookTarget = nil
                if shouldNotify then
                    task.spawn(RuntimeStatus.sendWebhook, "steal", "Egg Claimed",
                        details, 0x49E685, false)
                end
            end
        end)
    end)
end

local function areaEggRecords()
    -- CandidateIndex is deliberately a selection cache. Transaction proof must
    -- use the newest replicated snapshot: live testing showed the index still
    -- saying Slot while GetAreaEggSnapshot already said Carried by this player,
    -- which caused a second request and a false "already claimed" failure.
    local snapshot
    pcall(function() snapshot = EggCmds and EggCmds.GetAreaEggSnapshot() end)
    local records = snapshot and (snapshot.Records or snapshot)
    if type(records) == "table" then return records end
    local index = RuntimeStatus.candidateIndex
    return index and type(index.records) == "table" and index.records or {}
end

local function findAreaEgg(uid)
    for _, rec in pairs(areaEggRecords()) do
        local recUid = rec.Uid or rec.UID or rec.EggUid
        if tostring(recUid) == tostring(uid) then return rec end
    end
    return nil
end

-- Carry=false can precede the field's ownership update. An old self-owned row
-- must not revive that ended carry or send either movement type home empty.
-- A new pickup request may use field ownership as proof if its carry signal is
-- missed; the old request (including a late successful reply) cannot do so.
RuntimeStatus.carryLossAwaitingProof = function(uid)
    if uid == nil or tostring(RuntimeStatus.pendingDroppedUid) ~= tostring(uid) then
        return false
    end
    local request = getgenv().__CHSAE_CarryRequest
    return type(request) ~= "table" or tostring(request.uid) ~= tostring(uid)
        or request.carryEndedSeen == true
        or (tonumber(request.started) or 0) <= (tonumber(stealRuntime.dropDetectedAt) or 0)
end

local function carriedAreaEgg()
    for _, rec in pairs(areaEggRecords()) do
        local state = tostring(rec.State or "")
        if state ~= "Dropped" and state ~= "GuardCarried" and state ~= "Claimed"
            and tonumber(rec.CarrierUserId) == LocalPlayer.UserId
            and not RuntimeStatus.carryLossAwaitingProof(rec.Uid)
            and not (RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.isBait(rec.Uid)) then return rec end
    end
    return nil
end

local function stillCarrying(uid)
    local liveRequest = getgenv().__CHSAE_CarryRequest
    local exactRequest = type(liveRequest) == "table"
        and tostring(liveRequest.uid) == tostring(uid)
    local rec = findAreaEgg(uid)
    if rec ~= nil then
        local state = tostring(rec.State or "")
        local carrierUserId = tonumber(rec.CarrierUserId)
        -- State=Dropped/Claimed is the final authority even if a stale carrier
        -- field or hand model lingers for one replication packet.
        if state == "Dropped" or state == "GuardCarried" or state == "Claimed" then
            -- Recover a field-confirmed guard transfer even if CarryChanged was
            -- missed. Retain the exact UID while the guard releases the egg.
            if state ~= "Claimed"
                and (tostring(stealRuntime.carriedUid) == tostring(uid)
                    or (exactRequest and liveRequest.carrySeen == true))
                and tostring(RuntimeStatus.pendingDroppedUid) ~= tostring(uid) then
                stealRuntime.lastDroppedUid = uid
                stealRuntime.dropDetectedAt = os.clock()
                stealRuntime.lockedUid = uid
                stealRuntime.lastRequestKind = "carry-loss-sync"
                stealRuntime.lastRequestError = "guard carry loss; waiting to reclaim egg"
                RuntimeStatus.pendingDroppedUid = uid
            end
            if tostring(stealRuntime.carriedUid) == tostring(uid) then carrying = false end
            if exactRequest then
                liveRequest.carryActive = false
                if state == "Dropped" or state == "GuardCarried" then
                    liveRequest.carryEndedSeen = true
                    liveRequest.droppedSeen = true
                end
            end
            return false
        end
        if carrierUserId == LocalPlayer.UserId then
            if RuntimeStatus.carryLossAwaitingProof(uid) then return false end
            -- Field ownership is authoritative even when CarryChanged was missed
            -- or arrived one replication packet late on another executor.
            carrying = true
            stealRuntime.carriedUid = uid
            stealRuntime.rememberPositiveCarry(uid)
            if exactRequest then
                liveRequest.carrySeen = true
                liveRequest.carryActive = true
                liveRequest.carryEndedSeen = false
                liveRequest.droppedSeen = false
            end
            return true
        end
        -- Never let a stale local carry bit override an authoritative drop,
        -- claim, or transfer to another player.
        if carrierUserId ~= nil and carrierUserId ~= LocalPlayer.UserId then
            -- Zero/unassigned can be the preceding Slot snapshot while a new
            -- CarryChanged(true) is arriving. Keep that signal's worker grace;
            -- only a positive foreign owner conclusively ends this local carry.
            if carrierUserId > 0 and tostring(stealRuntime.carriedUid) == tostring(uid) then
                carrying = false
            end
            if exactRequest then liveRequest.carryActive = false end
            return false
        end
    end
    if carrying and stealRuntime.carriedUid ~= nil
        and tostring(stealRuntime.carriedUid) == tostring(uid)
        and not RuntimeStatus.carryLossAwaitingProof(uid) then
        stealRuntime.rememberPositiveCarry(uid)
        if exactRequest then
            liveRequest.carrySeen = true
            liveRequest.carryActive = true
            liveRequest.carryEndedSeen = false
            liveRequest.droppedSeen = false
        end
        return true
    end
    if exactRequest then liveRequest.carryActive = false end
    return false
end

local function droppedAreaEgg(uid)
    local rec = uid and findAreaEgg(uid)
    return rec ~= nil and tostring(rec.State) == "Dropped"
end

-- A guard/bat drop remains one transaction until this exact UID is claimed,
-- disappears, or becomes owned by somebody else. This intentionally has no
-- short timeout: a slow carry RemoteFunction must not turn recovery into a fresh
-- TrackStart route just because its server response took more than six seconds.
RuntimeStatus.getDroppedRecoveryRecord = function(uid)
    uid = uid or stealRuntime.lastDroppedUid
        or stealRuntime.deathRecoveryUid
        or (tostring(stealRuntime.lastRequestKind) == "carry-drop"
            and stealRuntime.lockedUid or nil)
    if uid == nil then return nil end
    local recordedDrop = tostring(stealRuntime.lastDroppedUid) == tostring(uid)
        or tostring(stealRuntime.deathRecoveryUid) == tostring(uid)
        or (tostring(stealRuntime.lastRequestKind) == "carry-drop"
            and tostring(stealRuntime.lockedUid) == tostring(uid))
    if not recordedDrop then return nil end
    local rec = findAreaEgg(uid)
    if rec and tostring(rec.State) == "Dropped" and rec.BottomCFrame then
        stealRuntime.dropRecoveryRecord = rec
        stealRuntime.dropRecoveryRecordUid = uid
        stealRuntime.dropRecoveryRecordAt = os.clock()
        return rec
    end
    -- FieldShifted can publish one scheduler turn before ReadFieldEggs exposes the
    -- same record. Keep its authoritative position only for that short cache gap.
    local cached = stealRuntime.dropRecoveryRecord
    local cachedAge = os.clock() - (tonumber(stealRuntime.dropRecoveryRecordAt) or 0)
    if type(cached) == "table" and cached.Uid ~= nil
        and tostring(stealRuntime.dropRecoveryRecordUid) == tostring(uid)
        and tostring(cached.State) == "Dropped" and cached.BottomCFrame
        and cachedAge <= 2.5 then return cached end
    return nil
end

RuntimeStatus.clearCarryLossRecovery = function(uid, preservePositiveEvidence)
    if uid == nil then return end
    local matchesLastDrop = tostring(stealRuntime.lastDroppedUid) == tostring(uid)
    local matchesDeath = tostring(stealRuntime.deathRecoveryUid) == tostring(uid)
    if matchesLastDrop then
        stealRuntime.lastDroppedUid = nil
        stealRuntime.dropDetectedAt = 0
    end
    if matchesDeath then
        stealRuntime.deathRecoveryUid = nil
        stealRuntime.deathRecoveryAt = 0
    end
    if matchesLastDrop or matchesDeath then
        stealRuntime.deathRecoveryMissingAt = 0
        stealRuntime.deathRecoveryMissingReason = ""
    end
    if tostring(stealRuntime.dropRecoveryRecordUid) == tostring(uid) then
        stealRuntime.dropRecoveryRecord = nil
        stealRuntime.dropRecoveryRecordUid = nil
        stealRuntime.dropRecoveryRecordAt = 0
    end
    if tostring(RuntimeStatus.pendingDroppedUid) == tostring(uid) then
        RuntimeStatus.pendingDroppedUid = nil
    end
    if preservePositiveEvidence ~= true then
        stealRuntime.clearPositiveCarryEvidence(uid)
    end
    local kind = tostring(stealRuntime.lastRequestKind or "")
    if (matchesLastDrop or matchesDeath)
        and (kind == "carry-loss-sync" or kind == "death-drop-sync" or kind == "carry-drop") then
        stealRuntime.requestFailureUid = nil
        stealRuntime.requestFailureCount = 0
        stealRuntime.requestFailureAt = 0
        stealRuntime.lastRequestKind = ""
        stealRuntime.lastRequestError = ""
    end
end

-- Positive delivery proof. Losing the carry is NOT success: traps produce the
-- same loss while leaving the egg in a Dropped state. The local claim-feedback
-- event is server-issued to this claimant; a global snapshot is never proof.
local function claimConfirmed(uid, assetCategory, afterSequence)
    local last = stealRuntime.lastClaim
    if last and last.Sequence > (afterSequence or -1)
        and last.Scoped ~= false
        -- A UID-less claim can belong to a manual/internal transaction. It is
        -- delivery proof only when the carry callback inferred this exact UID
        -- from positive local ownership.
        and last.Uid ~= nil and uid ~= nil and tostring(last.Uid) == tostring(uid)
        and (assetCategory == nil or last.AssetCategory == nil or last.AssetCategory == assetCategory) then
        return true
    end
    -- A snapshot's `Claimed` state is global: it can mean another player won the
    -- egg.  Only this client's server-issued AreaEggClaimed event proves delivery.
    return false
end

-- ══════════════════════════════════════════
-- 🧠 TASK ARBITER — one character, many features
-- ══════════════════════════════════════════
-- The problem: Auto-Steal drives the character, Auto-Place TELEPORTS it
-- into the pen, and Auto-Hatch / Equip / Sell fire remotes — each on its own
-- independent task.spawn loop. Two of them running at once = the character is
-- yanked mid-walk, a carried egg is dropped, or a place fires from the void.
--
-- The rule (user's design): STEALING ALWAYS WINS. Pen/pet features only get the
-- body when there is nothing to steal (no matching egg in the area AND nothing
-- being carried). Quiet features never move the character, but sellers do hold
-- Tools; they run only through their stricter serialized gate.
--
--   BODY  tasks (drive the character): Steal(100) > Event(70) > Place(50)
--   QUIET tasks: Hatch · Equip (remote) · Sell (held Tool) — separately gated
--
-- Ordering that falls out of this: Steal → Hatch → Place → Equip → Sell.
local placeEggsNow -- forward decl (defined in the Auto-Place section below)

local Arb = {
    owner      = nil,   -- name of the task currently holding the body
    prio       = 0,
    heartbeat  = 0,     -- the holder refreshes this; a stale holder loses the body
    yieldTo    = nil,   -- a higher-prio task is waiting → holder should bail out
    stealWants = false, -- Auto-Steal has work RIGHT NOW (carrying, or a live target)
    stealBeat  = 0,     -- last sign of life from the steal loop (see WANTS_STALE)
    critical   = false, -- inside a delicate steal step (grab / carry-home)
    sellDuringSteal = false, -- Tool-selling window: outbound travel only
    sellWake   = Instance.new("BindableEvent"), -- wake seller when that short window opens
    petsBusy   = false, -- inventory mutation mutex, separate from body ownership
    sellerActive = false, -- UID-sale confirmation never owns the character
    placeBusy  = false, -- a pen pass is running (worker loop vs. between-steals hook)
    remoteActivity = nil,
    treadmillTraining = false,
    hatchBusy = false,
    -- Main Steal, boss event, pet submission/event work, then idle maintenance.
    PRIO       = { Steal = 140, RiftBoss = 120, AdminEvent = 110, Event = 100, Place = 50, Treadmill = 20 },
    STALE      = 60,    -- s — a holder that stops beating (loop died) is evicted
    WANTS_STALE= 30,    -- s — if the steal loop dies, stop starving the pen tasks
}
getgenv().__CHSAE_SellWake = Arb.sellWake

-- [[ INVENTORY WORKER SCHEDULER ]] --
Arb.sellerGeneration, Arb.sellerPending = 0, false
function Arb.cancelSellerTimer()
    Arb.sellerGeneration += 1
    local timer = Arb.sellerTimer
    Arb.sellerTimer = nil
    if timer then pcall(task.cancel, timer) end
end
function Arb.wakeSeller()
    if not sessionAlive() then return end
    Arb.sellerPending = true
    if Arb.sellerWakeQueued then return end
    Arb.sellerWakeQueued = true
    task.defer(function()
        Arb.sellerWakeQueued = false
        if sessionAlive() then Arb.sellWake:Fire() end
    end)
end
function Arb.waitSeller(seconds)
    Arb.cancelSellerTimer()
    if Arb.sellerPending then
        Arb.sellerPending = false
        task.wait(0.1)
        return
    end
    local generation = Arb.sellerGeneration
    Arb.sellerTimer = task.delay(seconds, function()
        if generation ~= Arb.sellerGeneration or not sessionAlive() then return end
        Arb.sellerTimer = nil
        Arb.wakeSeller()
    end)
    Arb.sellWake.Event:Wait()
    Arb.cancelSellerTimer()
    Arb.sellerPending = false
end
SESSION.InventoryWake = function()
    if Arb.inventoryWakeQueued or not sessionAlive() then return end
    Arb.inventoryWakeQueued = true
    task.defer(function()
        Arb.inventoryWakeQueued = false
        if not sessionAlive() then return end
        Arb.wakeSeller()
        if RuntimeStatus.wakeRiftPen then RuntimeStatus.wakeRiftPen("inventory/config") end
    end)
end
getgenv().__CHSAE_SellCancel = Arb.cancelSellerTimer
-- [[ END INVENTORY WORKER SCHEDULER ]] --

function Arb.free()
    if Arb.owner and (os.clock() - Arb.heartbeat) > Arb.STALE then
        Arb.owner, Arb.prio, Arb.yieldTo = nil, 0, nil
    end
    return Arb.owner == nil
end

-- Is Auto-Steal actually alive and wanting the body? (A dead/crashed steal loop
-- must not starve the pen tasks forever.)
function Arb.stealBusy()
    if not Arb.stealWants then return false end
    if os.clock() - (Arb.stealBeat or 0) > Arb.WANTS_STALE then
        Arb.stealWants = false
        return false
    end
    return true
end

-- May `name` take (or keep) the body right now?
-- Arena exits are a movement boundary shared by every automation lane.
RuntimeStatus.bossArenaOccupied = function()
    if LocalPlayer:GetAttribute("InBossArena") ~= true then return false end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then return false end
    local arena = workspace:FindFirstChild("BossArena")
    local floor = arena and arena:FindFirstChild("Floor")
    if not floor or not floor:IsA("BasePart") then return true end
    local p = floor.CFrame:PointToObjectSpace(root.Position)
    return math.abs(p.X) <= floor.Size.X * 0.5 + 32
        and math.abs(p.Z) <= floor.Size.Z * 0.5 + 32
        and math.abs(p.Y) <= floor.Size.Y * 0.5 + 120
end
RuntimeStatus.blockArenaDeparture = function(name)
    if name == "RiftBoss" or not RuntimeStatus.bossArenaOccupied() then return false end
    if name == "Place" then return true end -- placement never requests an arena exit
    if name == "Steal" or Settings.AutoRiftBoss ~= true or RuntimeStatus.bossArenaIdle then
        RuntimeStatus.bossArenaExitRequested = true
    end
    return true
end
function Arb.protectedStealTransaction(name)
    if name == "RiftBoss" and RuntimeStatus.bossArenaExiting then return false end
    if name ~= "AdminEvent" and name ~= "RiftBoss" then return false end
    -- A fatal catch can temporarily remove the character and field row while the
    -- exact dropped-egg recovery transaction is still reserved for Steal.
    if type(RuntimeStatus.carryLossRecoveryPending) == "function"
        and RuntimeStatus.carryLossRecoveryPending() then return true end
    if Arb.owner ~= "Steal" then return false end
    local carryRequest = getgenv().__CHSAE_CarryRequest
    return Arb.critical or stealRuntime.lockedUid ~= nil
        or carrying or carriedAreaEgg() ~= nil
        or type(carryRequest) == "table"
            and (carryRequest.inFlight == true or carryRequest.carrySeen == true)
end

-- Arena exit is a necessary movement handoff, never a boss-priority override.
function Arb.prioOf(name)
    if name == "RiftBoss" and RuntimeStatus.bossArenaExiting then return Arb.PRIO.Steal + 20 end
    return Arb.PRIO[name] or 0
end

function Arb.canTake(name)
    if name == "Treadmill" and (Arb.placeBusy
        or (RuntimeStatus.placeBatchPending and RuntimeStatus.placeBatchPending())) then return false end
    if RuntimeStatus.blockArenaDeparture(name) then return false end
    local p = Arb.prioOf(name)
    -- Admin events may interrupt ordinary outbound travel, but never evict a
    -- carry/grab/recovery transaction, including a field-owned carry whose local
    -- CarryChanged signal was missed.
    if Arb.protectedStealTransaction(name) then return false end
    -- steal priority: everything below Steal waits while Auto-Steal has work
    if p < Arb.PRIO.Steal and Arb.stealBusy() then
        return false
    end
    -- A holder must not erase a higher-priority yield request by repeatedly
    -- acquiring its own lane on each worker tick.
    if Arb.owner == name and Arb.yieldTo ~= nil
        and Arb.prioOf(Arb.yieldTo) > p then
        return false
    end
    return Arb.free() or Arb.owner == name
end

-- NOTE: a higher-prio task never SNATCHES the body mid-step — it raises
-- `yieldTo`, the holder sees Arb.hold() == false at its next checkpoint (≤0.5s)
-- and releases cleanly. That's what keeps a place-teleport from firing into the
-- middle of a walk. Timed-out acquisition leaves the live holder in control.
function Arb.acquire(name)
    if RuntimeStatus.blockArenaDeparture(name) then return false end
    local protectedSteal = Arb.protectedStealTransaction(name)
    if not Arb.canTake(name) then
        if not protectedSteal and Arb.owner and Arb.owner ~= name
            and Arb.prioOf(name) > Arb.prioOf(Arb.owner) then
            Arb.yieldTo = name -- ask the lower-prio holder to bail out
        end
        return false
    end
    local changed = Arb.owner ~= name
    Arb.owner, Arb.prio, Arb.heartbeat = name, Arb.prioOf(name), os.clock()
    Arb.yieldTo = nil
    if changed then RuntimeStatus.wakeOverlay("arbiter") end
    return true
end

-- Acquire, giving a lower-prio holder up to `secs` to release safely.
function Arb.acquireWait(name, secs)
    local deadline = os.clock() + (secs or 3)
    while sessionAlive() do
        if Arb.acquire(name) then return true end
        -- A deadline is not proof that the live holder stopped. Only Arb.free's
        -- stale-heartbeat policy may evict it; protected carry checks still apply.
        if os.clock() >= deadline then return false end
        task.wait(0.1)
    end
    return false
end

-- Keep-alive + "do I still own the body?" — polled inside the movement loops.
function Arb.hold(name)
    if RuntimeStatus.blockArenaDeparture(name) then return false end
    if Arb.owner ~= name then return false end
    Arb.heartbeat = os.clock()
    return Arb.yieldTo == nil
end

function Arb.release(name)
    if Arb.owner == name then
        Arb.owner, Arb.prio, Arb.yieldTo = nil, 0, nil
        RuntimeStatus.wakeOverlay("arbiter")
    end
end

-- Remote-only features: OK unless a steal is at its delicate moment or the pen
-- pass is mid-flight.
RuntimeStatus.deferInventoryForBait = function()
    local tp = RuntimeStatus.ChickenTP
    local phase = tp and tp.active and tp.active.phase
    return (RuntimeStatus.clientFPS or 60) < 35 and Arb.owner == "Steal" and Arb.critical
        and (phase == "staging" or phase == "approach" or phase == "contact")
end

function Arb.quietOk()
    if Arb.critical or carrying or Arb.stealBusy() then return false end
    if RuntimeStatus.greatBloomUnlockReturnPending == true then return false end
    if Arb.owner == "RiftBoss" or Arb.owner == "Place" or Arb.owner == "Event" or Arb.owner == "AdminEvent"
        or Arb.placeBusy then return false end
    return true
end

-- Background-safe remote work never equips tools and never moves the avatar.
-- It may overlap movement, including Bloom and steal travel, but still pauses
-- during carry validation and pen placement transactions.
function Arb.backgroundOk()
    if Arb.critical or carrying then return false end
    if Arb.owner == "RiftBoss" or Arb.owner == "Place" or Arb.placeBusy then return false end
    return true
end

-- Hatching is a proximity-free remote transaction. It may overlap Steal travel,
-- carrying, Great Bloom movement, and an established treadmill session. Only
-- pen placement and inventory tool transactions are serialized against it.
function Arb.hatchOk()
    if Arb.hatchBusy or Arb.placeBusy or Arb.petsBusy or Arb.owner == "Place" then return false end
    if type(RuntimeStatus.reconcileNewPetUids) == "function" then
        pcall(RuntimeStatus.reconcileNewPetUids)
    end
    return not Arb.hatchBusy and not Arb.placeBusy and not Arb.petsBusy
        and RuntimeStatus.hatchPetOutputPending ~= true
        and RuntimeStatus.petUidBaselineReady == true
        and Arb.owner ~= "Place"
end

-- Sales use explicit inventory UIDs without equipping. Keep inventory mutation
-- serialized with hatch/placement/trade and protected egg transactions.
function Arb.sellOk()
    if Arb.critical or carrying or Arb.placeBusy or Arb.hatchBusy then return false end
    if type(RuntimeStatus.hatchPetSaleGuardActive) == "function"
        and RuntimeStatus.hatchPetSaleGuardActive() then return false end
    if RuntimeStatus.greatBloomUnlockReturnPending == true then return false end
    if Arb.treadmillTraining or Arb.owner == "Treadmill" then return false end
    if Arb.owner == "Steal" or Arb.stealBusy() then return false end
    if RuntimeStatus.riftCollecting == true or RuntimeStatus.riftWantsBody == true
        or RuntimeStatus.riftPlacementWanted == true then return false end
    if RuntimeStatus.normalStealPending() then return false end
    if Arb.owner == "RiftBoss" or Arb.owner == "Event" or Arb.owner == "AdminEvent" or Arb.owner == "Place" then return false end
    return true
end

-- Run one pets action at a time (the Equip Best button vs. the auto loop).
-- Returns false if another pets pass was already running.
function Arb.petsSerial(fn, activity)
    if Arb.petsBusy or Arb.hatchBusy or RuntimeStatus.hatchPetOutputPending == true
        or not Arb.quietOk() then return false end
    Arb.petsBusy = true
    Arb.remoteActivity = activity or "Managing inventory"
    Arb.remoteOnlyActive = true -- current callers are native Equip Best and Fuse
    local ok, err = pcall(fn)
    Arb.petsBusy, Arb.remoteOnlyActive = false, false
    Arb.remoteActivity = nil
    if not ok then warn("[CloverHub] pets task error: " .. tostring(err)) end
    return true
end

-- One seller at a time. Kept separate from petsSerial so remote-only Equip Best
-- can retain its broader overlap rules while filtered inventory sales stay
-- serialized with other inventory transactions.
function Arb.sellSerial(fn, activity)
    if Arb.petsBusy or not Arb.sellOk() then return false end
    Arb.petsBusy = true
    Arb.remoteActivity = activity or "Selling inventory"
    Arb.sellerActive = true
    local results = table.pack(pcall(fn))
    if type(RuntimeStatus.stopHoldingSellerTool) == "function" then
        pcall(RuntimeStatus.stopHoldingSellerTool)
    end
    Arb.petsBusy, Arb.sellerActive = false, false
    Arb.remoteActivity = nil
    if not results[1] then
        warn("[CloverHub] sell task error: " .. tostring(results[2]))
        return true
    end
    return true, table.unpack(results, 2, results.n)
end

-- [[ PET TRANSACTION HANDOFF ]] --
function Arb.inventoryBlocksSteal()
    -- A dispatched UID sale/Rift request keeps the inventory mutex until its
    -- result is verified. It does not equip a Tool or require an idle character.
    -- Never clear that mutex or cancel/retry an unknown remote to start moving.
    if RuntimeStatus.sellerHeldTool ~= nil then return true end
    return Arb.petsBusy and not Arb.sellerActive and not Arb.remoteOnlyActive
        and type(getgenv().__CHSAE_RiftTransaction) ~= "table"
end
function Arb.waitPets(valid, seconds)
    local deadline = os.clock() + (seconds or 4)
    if Arb.inventoryBlocksSteal() then
        setStealStatus("⏳ Finishing inventory handoff")
    end
    while Arb.inventoryBlocksSteal() and sessionAlive() and valid() do
        if not Arb.hold("Steal") or os.clock() >= deadline then return false end
        RunService.Heartbeat:Wait()
    end
    return sessionAlive() and valid() and Arb.hold("Steal") and not Arb.inventoryBlocksSteal()
end
-- [[ END PET TRANSACTION HANDOFF ]] --

-- Human-readable chip for the SETTINGS ▸ Automation Priority status label.
function Arb.status()
    if Arb.owner == "Steal" then
        if Arb.petsBusy and string.find(tostring(Arb.remoteActivity), "Selling", 1, true) then
            return "🥷 Stealing · 💰 " .. tostring(Arb.remoteActivity)
        end
        return carrying and "🥷 Stealing (carrying)" or "🥷 Stealing"
    elseif Arb.owner == "RiftBoss" then
        return "⚔️ " .. tostring(RuntimeStatus.riftBossController and RuntimeStatus.riftBossController.bossStatus or "Rift Boss")
    elseif Arb.owner == "AdminEvent" then
        return "🌀 Rift trade"
    elseif Arb.owner == "Event" then
        return RuntimeStatus.greatBloomUnlockReturnPending == true
            and "🔓 Returning Crane" or "🌸 Farming Great Bloom"
    elseif Arb.owner == "Place" then
        return "🥚 Placing eggs"
    elseif Arb.owner == "Treadmill" then
        return "🏃 Entering treadmill"
    elseif Arb.stealBusy() then
        return "🥷 Steal armed"
    elseif Arb.treadmillTraining and Arb.hatchBusy then
        return "🏃 Training · 🥚 Hatching"
    elseif Arb.hatchBusy then
        return "🥚 Hatching eggs"
    elseif Arb.treadmillTraining and Arb.petsBusy then
        return "🏃 Training · 📦 " .. tostring(Arb.remoteActivity or "Managing inventory")
    elseif Arb.petsBusy then
        return "📦 " .. tostring(Arb.remoteActivity or "Managing inventory")
    elseif RuntimeStatus.riftActive and Settings.AutoRift then
        return "🌀 Rift active"
    elseif Arb.treadmillTraining then
        return "🏃 Training on treadmill"
    -- The control is the runtime authority. Config/UI restore paths can update
    -- the toggle one scheduler turn before the mirrored Settings field, which
    -- previously produced "Idle" while the Auto-Steal worker was enabled.
    elseif (autoStealTgl and autoStealTgl.Value == true) or Settings.AutoSteal then
        return "🎯 Waiting for target"
    elseif Settings.AutoPlace
        or (Settings.PlaceAfterIncubation and type(RuntimeStatus.getIncubatedPlaceCount) == "function"
            and RuntimeStatus.getIncubatedPlaceCount() > 0) then
        return Settings.PlaceInRangeOnly and "🥚 Waiting for pen range" or "🥚 Auto-Place standby"
    elseif Settings.AutoTreadmill then
        return "🏃 Treadmill standby"
    end
    return "💤 Idle"
end

local function rarityOfRecord(rec)
    local ok, r = pcall(function()
        local itemData = type(rec.ItemData) == "table" and rec.ItemData or rec
        local category = itemData.AssetCategory or itemData.Category
            or rec.AssetCategory or rec.Category
        return AssetsDir.Directory[category].Rarity
    end)
    if ok and type(r) == "table" then return r end
    return nil
end

-- Event-driven candidate index. Snapshot changes perform one bounded rebuild;
-- scanner passes then reuse cached rarity, mutation, value, position and sorted
-- views instead of requiring and ranking every record on every wake/fallback.
do
    local index = {
        version = 0,
        signature = nil,
        records = {},
        entries = {},
        byUid = {},
        sorted = {},
        rejected = {},
        lastRebuildAt = 0,
    }
    local fieldRebuildScheduled = false

    RuntimeStatus.queueCandidateIndexRebuild = function()
        if fieldRebuildScheduled then return end
        fieldRebuildScheduled = true
        task.defer(function()
            fieldRebuildScheduled = false
            if sessionAlive() and type(index.Rebuild) == "function" then index:Rebuild() end
        end)
    end

    local function cloneEntries(source)
        local out = table.create(#source)
        for i, value in ipairs(source) do out[i] = value end
        return out
    end

    local function stableUid(entry)
        return tostring(entry.uid or "")
    end

    function index:Rebuild(snapshot)
        if type(snapshot) ~= "table" or type(snapshot.Records or snapshot) ~= "table" then
            local ok, current = pcall(EggCmds.GetAreaEggSnapshot)
            if not ok or type(current) ~= "table" then return false end
            snapshot = current
        end
        local source = snapshot.Records or snapshot
        local signatureParts, records = {}, {}
        for _, rec in pairs(source) do
            if type(rec) == "table" then
                local recUid = tostring(rec.Uid or "")
                local rejected = self.rejected[recUid]
                if rejected and tostring(rec.State) ~= "Slot" then
                    self.rejected[recUid] = nil
                    rejected = nil
                end
                if not rejected then records[#records + 1] = rec end
                local signaturePosition = rec.BottomCFrame and rec.BottomCFrame.Position
                local signatureMutations = getMutations(rec)
                table.sort(signatureMutations)
                signatureParts[#signatureParts + 1] = table.concat({
                    tostring(rec.Uid or ""), tostring(rec.State or ""),
                    tostring(rec.CarrierUserId or ""), tostring(rec.AssetCategory or ""),
                    tostring(rec.AreaId or ""), tostring(rec.AssetScale or ""),
                    tostring(rec.BaseMutation or ""),
                    signaturePosition and ("%.2f,%.2f,%.2f"):format(
                        signaturePosition.X, signaturePosition.Y, signaturePosition.Z) or "",
                    table.concat(signatureMutations, ","),
                }, "\0")
            end
        end
        table.sort(signatureParts)
        local signature = table.concat(signatureParts, "\1")
        if signature == self.signature then return false end

        local entries, byUid = {}, {}
        for _, rec in ipairs(records) do
            local rarity = rarityOfRecord(rec)
            local mutations = getMutations(rec)
            local position = rec.BottomCFrame and rec.BottomCFrame.Position or nil
            local weight = weightKg(rec)
            local value, valueKnown = valueScore(rec)
            local entry = {
                rec = rec,
                uid = tostring(rec.Uid or ""),
                state = tostring(rec.State or ""),
                rarity = rarity,
                rarityId = rarity and tostring(rarity._id) or "Unknown",
                rarityNumber = rarity and (tonumber(rarity.RarityNumber) or 0) or 0,
                mutations = mutations,
                mutationCount = #mutations,
                value = value,
                valueKnown = valueKnown,
                weight = weight or 0,
                weightKnown = weight ~= nil,
                position = position,
                area = tostring(rec.AreaId or ""),
                category = tostring(rec.AssetCategory or ""),
            }
            entries[#entries + 1] = entry
            if entry.uid ~= "" then byUid[entry.uid] = entry end
        end

        local valueSorted = cloneEntries(entries)
        table.sort(valueSorted, function(a, b)
            if a.value ~= b.value then return a.value > b.value end
            if a.rarityNumber ~= b.rarityNumber then return a.rarityNumber > b.rarityNumber end
            return stableUid(a) < stableUid(b)
        end)
        local raritySorted = cloneEntries(entries)
        table.sort(raritySorted, function(a, b)
            if a.rarityNumber ~= b.rarityNumber then return a.rarityNumber > b.rarityNumber end
            if a.value ~= b.value then return a.value > b.value end
            return stableUid(a) < stableUid(b)
        end)
        local mutationSorted = cloneEntries(entries)
        table.sort(mutationSorted, function(a, b)
            if a.mutationCount ~= b.mutationCount then return a.mutationCount > b.mutationCount end
            if a.value ~= b.value then return a.value > b.value end
            if a.rarityNumber ~= b.rarityNumber then return a.rarityNumber > b.rarityNumber end
            return stableUid(a) < stableUid(b)
        end)
        local weightSorted = cloneEntries(entries)
        table.sort(weightSorted, function(a, b)
            if a.weight ~= b.weight then return a.weight > b.weight end
            if a.rarityNumber ~= b.rarityNumber then return a.rarityNumber > b.rarityNumber end
            if a.value ~= b.value then return a.value > b.value end
            return stableUid(a) < stableUid(b)
        end)

        self.signature = signature
        self.records = records
        self.entries = entries
        self.byUid = byUid
        self.sorted = {
            Value = valueSorted,
            Rarity = raritySorted,
            Mutation = mutationSorted,
            Weight = weightSorted,
            Farthest = entries,
            Nearest = entries,
        }
        self.version += 1
        self.lastRebuildAt = os.clock()
        RuntimeStatus.candidateCount = #entries
        if type(RuntimeStatus.refreshEggESP) == "function" then
            RuntimeStatus.refreshEggESP()
        end
        return true
    end

    function index:GetEntries(priority)
        return self.sorted[priority] or self.entries
    end

    function index:Invalidate(uid, reason)
        uid = tostring(uid or "")
        if uid == "" or not self.byUid[uid] then return false end
        local function withoutUid(source, recordsOnly)
            local out = {}
            for _, value in ipairs(source or {}) do
                local candidateUid = recordsOnly and tostring(value.Uid or "")
                    or tostring(value.uid or "")
                if candidateUid ~= uid then out[#out + 1] = value end
            end
            return out
        end
        self.records = withoutUid(self.records, true)
        self.entries = withoutUid(self.entries, false)
        for key, source in pairs(self.sorted) do
            self.sorted[key] = withoutUid(source, false)
        end
        self.byUid[uid] = nil
        self.rejected[uid] = { reason = tostring(reason or "unavailable"), at = os.clock() }
        self.version += 1
        self.lastInvalidation = { uid = uid, reason = tostring(reason or "unavailable"), at = os.clock() }
        RuntimeStatus.candidateCount = #self.entries
        if type(RuntimeStatus.refreshEggESP) == "function" then
            RuntimeStatus.refreshEggESP()
        end
        wakeEggScanner("candidate-invalidated")
        return true
    end

    RuntimeStatus.candidateIndex = index
    task.defer(function()
        if sessionAlive() and EggCmds then index:Rebuild(nil) end
    end)
end

-- ══════════════════════════════════════════
-- 👁 ESP — event-driven area and placed-pen egg labels
-- ══════════════════════════════════════════
-- Area labels read the authoritative field snapshot independently from Auto-Steal's
-- selection/rejection cache. Placed pen eggs come from EggCmds' authoritative
-- runtime snapshot and use PlotCmds' CenterPoint transform. Both sources reconcile
-- only on their native update events; there is no RenderStepped projection loop or
-- repeated Workspace scan. One invisible local anchor holds lightweight
-- Attachments + BillboardGuis, so labels stay stable when Roblox streams or
-- recreates the rendered egg models.
do
    (function()
        local manager = {
            areaEnabled = false,
            penEnabled = false,
            queued = false,
            folder = nil,
            anchor = nil,
            markers = {},
            count = 0,
            PlotCmds = nil,
        }
        function manager.trackConnection(connection)
            if typeof(connection) ~= "RBXScriptConnection" then return end
            local runtimeConns = getgenv().__CHSAE_RuntimeConns
            if type(runtimeConns) == "table" then
                runtimeConns[#runtimeConns + 1] = connection
            else
                pcall(function() connection:Disconnect() end)
            end
        end
        pcall(function()
            local PlotState = require(ReplicatedStorage.Client.PlotState)
            manager.PlotCmds = {
                GetPlotData = PlotState.ResolvePlot,
                OnAnyPlotUpdated = PlotState.PlotChanged,
            }
        end)

        local function escapeRichText(value)
            return tostring(value or "")
                :gsub("&", "&amp;")
                :gsub("<", "&lt;")
                :gsub(">", "&gt;")
                :gsub('"', "&quot;")
        end

        local function destroyFolder()
            local folder = manager.folder
            manager.folder, manager.anchor, manager.markers, manager.count = nil, nil, {}, 0
            RuntimeStatus.eggESPCount = 0
            RuntimeStatus.penESPCount = 0
            if folder then pcall(function() folder:Destroy() end) end
            if getgenv().__CHSAE_EggESPFolder == folder then
                getgenv().__CHSAE_EggESPFolder = nil
            end
        end

        local function ensureAnchor()
            if manager.anchor and manager.anchor.Parent then return manager.anchor end
            destroyFolder()
            local stale = workspace:FindFirstChild("__CHSAE_EggESP")
            if stale then pcall(function() stale:Destroy() end) end

            local folder = Instance.new("Folder")
            folder.Name = "__CHSAE_EggESP"
            local anchor = Instance.new("Part")
            anchor.Name = "Anchor"
            anchor.Anchored = true
            anchor.CanCollide = false
            anchor.CanTouch = false
            anchor.CanQuery = false
            anchor.CastShadow = false
            anchor.Transparency = 1
            anchor.Size = Vector3.new(0.05, 0.05, 0.05)
            anchor.CFrame = CFrame.new()
            anchor.Parent = folder
            folder.Parent = workspace

            manager.folder, manager.anchor = folder, anchor
            getgenv().__CHSAE_EggESPFolder = folder
            return anchor
        end

        local function anyEnabled()
            return manager.areaEnabled or manager.penEnabled
        end

        local function mutationSuffix(rec)
            local names, seen = {}, {}
            local function add(mutation)
                mutation = tostring(mutation or "")
                if mutation == "" or mutation == "None" or seen[mutation] or #names >= 2 then return end
                seen[mutation] = true
                local display = mutation
                if MutationsMod and type(MutationsMod.GetDisplayName) == "function" then
                    pcall(function() display = MutationsMod.GetDisplayName(mutation) or mutation end)
                end
                names[#names + 1] = escapeRichText(display)
            end
            add(rec and rec.BaseMutation)
            for _, mutation in ipairs(rec and rec.Mutations or {}) do add(mutation) end
            return #names > 0 and (" · " .. table.concat(names, "+")) or ""
        end

        local function nativeAssetItem(rec)
            if type(rec) ~= "table" then return nil end
            local item = type(rec.ItemData) == "table" and rec.ItemData or rec
            if type(item.Category) == "string" and type(item.Scale) == "number"
                and type(item.Mutations) == "table" then
                return item
            end
            local records = EggCmds and EggCmds.EggRecords
            if records and type(records.ToAssetItemData) == "function" then
                local ok, converted = pcall(records.ToAssetItemData, rec)
                if ok and type(converted) == "table" then return converted end
            end
            return nil
        end

        local function nativeWeightKg(rec)
            local item = nativeAssetItem(rec)
            local assetItems = EggCmds and EggCmds.AssetItems
            if item and assetItems and type(assetItems.WeightKg) == "function" then
                local ok, result = pcall(assetItems.WeightKg, item)
                if ok and type(result) == "number" then return result end
            end
            return weightKg(rec)
        end

        local function nativeIncomePerSecond(rec)
            local item = nativeAssetItem(rec)
            local earnings = EggCmds and EggCmds.AssetEarnings
            if not (item and earnings and type(earnings.MutationOnlyRatePerSecond) == "function") then
                return nil
            end
            local ok, result = pcall(earnings.MutationOnlyRatePerSecond, item)
            if ok and type(result) == "number" then return result end
            return nil
        end

        local function compactNative(value)
            local formatter = EggCmds and EggCmds.FormatCompact
            if type(formatter) == "function" then
                local ok, result = pcall(formatter, value, ".#")
                if ok and type(result) == "string" then return result end
            end
            return short(value)
        end

        local function wholeNative(value)
            local formatter = EggCmds and EggCmds.AddCommas
            if type(formatter) == "function" then
                local ok, result = pcall(formatter, value)
                if ok and type(result) == "string" then return result end
            end
            return tostring(math.round(value))
        end

        local function labelText(entry)
            local rec = entry.rec or {}
            local asset = AssetsDir and AssetsDir.Directory and AssetsDir.Directory[entry.category]
            local displayName = asset and (asset.DisplayName or asset.Name) or entry.category
            local rarityId = entry.rarityId ~= "" and entry.rarityId or "Unknown"
            local rarityColor = entry.rarity and entry.rarity.Color
            local rarityHex = typeof(rarityColor) == "Color3" and toHex(rarityColor) or "#FFFFFF"

            local kg = entry.weightKnown and entry.weight or nativeWeightKg(rec)
            local income = nativeIncomePerSecond(rec)

            local kgText = type(kg) == "number"
                and (wholeNative(math.max(kg, 0)) .. " KG") or "-- KG"
            local incomeText = type(income) == "number"
                and ("$" .. compactNative(math.max(income, 0)) .. "/s") or "$--/s"
            return ('<b><font color="#F4F4F5">%s</font></b> <font color="%s">[%s]</font>'
                .. '<font color="#C4B5FD">%s</font>\n'
                .. '<font color="#E5E7EB">%s</font> <font color="#71717A">·</font> '
                .. '<font color="#58E083"><b>%s</b></font>')
                :format(escapeRichText(displayName), rarityHex, escapeRichText(rarityId),
                    mutationSuffix(rec), kgText, incomeText)
        end

        local function markerName(source, uid)
            local safeUid = tostring(uid):gsub("[^%w_%-]", "_")
            return (source == "pen" and "Pen_" or "Area_") .. safeUid
        end

        local function setMarkerSource(marker, source, uid)
            marker.source = source
            marker.attachment.Name = markerName(source, uid)
            marker.billboard.Name = source == "pen" and "PenESP" or "EggESP"
        end

        local function createMarker(uid, source)
            local attachment = Instance.new("Attachment")
            attachment.Parent = ensureAnchor()

            local billboard = Instance.new("BillboardGui")
            billboard.Adornee = attachment
            billboard.AlwaysOnTop = true
            billboard.LightInfluence = 0
            billboard.MaxDistance = 6000
            billboard.Size = UDim2.fromOffset(210, 52)
            billboard.Parent = attachment

            local label = Instance.new("TextLabel")
            label.Name = "Info"
            label.BackgroundTransparency = 1
            label.BorderSizePixel = 0
            label.Size = UDim2.fromScale(1, 1)
            label.Font = Enum.Font.GothamMedium
            label.RichText = true
            label.TextColor3 = Color3.fromRGB(245, 245, 245)
            label.TextSize = 14
            label.TextStrokeColor3 = Color3.new(0, 0, 0)
            label.TextStrokeTransparency = 0.45
            label.TextWrapped = true
            label.Parent = billboard

            local marker = { attachment = attachment, billboard = billboard, label = label }
            setMarkerSource(marker, source, uid)
            manager.markers[uid] = marker
            return marker
        end

        local function selectedAreaFilterActive()
            for _, enabled in pairs(Settings.EggESPAreas or {}) do
                if enabled == true then return true end
            end
            return false
        end

        local function buildAreaEntries()
            local wanted = {}
            if not manager.areaEnabled then return wanted end
            if not (EggCmds and type(EggCmds.GetAreaEggSnapshot) == "function") then return wanted end
            local ok, snapshot = pcall(EggCmds.GetAreaEggSnapshot)
            if not ok or type(snapshot) ~= "table" then return wanted end
            local records = snapshot.Records or snapshot
            if type(records) ~= "table" then return wanted end
            local filtered = selectedAreaFilterActive()
            for _, rec in pairs(records) do
                local uid = type(rec) == "table" and tostring(rec.Uid or "") or ""
                local state = type(rec) == "table" and tostring(rec.State or "") or ""
                local position = type(rec) == "table" and typeof(rec.BottomCFrame) == "CFrame"
                    and rec.BottomCFrame.Position or nil
                local category = type(rec) == "table" and tostring(rec.AssetCategory or "") or ""
                local area = type(rec) == "table" and tostring(rec.AreaId or "") or ""
                if uid ~= "" and position and (state == "Slot" or state == "Dropped")
                    and (not filtered or Settings.EggESPAreas[area] == true) then
                    local rarity = rarityOfRecord(rec)
                    local weight = nativeWeightKg(rec)
                    local entry = {
                        rec = rec,
                        uid = uid,
                        state = state,
                        rarity = rarity,
                        rarityId = rarity and tostring(rarity._id) or "Unknown",
                        weight = weight or 0,
                        weightKnown = weight ~= nil,
                        position = position,
                        area = area,
                        category = category,
                    }
                    local boundsY = tonumber(rec.BoundsSize and rec.BoundsSize.Y) or 2
                    wanted[uid] = {
                        source = "area",
                        entry = entry,
                        offset = math.clamp(boundsY * 0.5 + 2, 2.5, 10),
                    }
                end
            end
            return wanted
        end

        local function plotCenterCFrame(ownerUserId)
            if not manager.PlotCmds then return nil end
            local player = Players:GetPlayerByUserId(tonumber(ownerUserId) or 0)
            if not player then return nil end
            local plot
            pcall(function() plot = manager.PlotCmds.GetPlotData(player) end)
            if type(plot) ~= "table" then return nil end
            local center = plot.CenterPoint
            if typeof(center) == "CFrame" then return center end
            if typeof(center) == "Instance" and center:IsA("BasePart") then
                return center.CFrame
            end
            local petArea = plot.PetArea
            if typeof(petArea) == "Instance" and petArea:IsA("BasePart") then
                return petArea.CFrame
            end
            return nil
        end

        local function buildPenEntries()
            local wanted = {}
            if not manager.penEnabled then return wanted end
            if not (EggCmds and type(EggCmds.GetRuntimeSnapshot) == "function") then return wanted end
            local ok, snapshot = pcall(EggCmds.GetRuntimeSnapshot)
            if not ok or type(snapshot) ~= "table" then return wanted end

            -- Pen ESP is personal information, not a server-wide overlay. Resolve
            -- the local transform once and ignore every remote owner's records.
            -- This also avoids one PlotState lookup and one label tree per player.
            local localUserId = LocalPlayer.UserId
            local localOwnerKey = tostring(localUserId)
            local center = plotCenterCFrame(localUserId)
            if not center then return wanted end
            for _, ownerEntry in pairs(snapshot) do
                if type(ownerEntry) == "table" and type(ownerEntry.Records) == "table"
                    and tostring(ownerEntry.OwnerUserId) == localOwnerKey then
                    for recordUid, rawRecord in pairs(ownerEntry.Records) do
                        local placement = type(rawRecord) == "table" and rawRecord.Placement
                        local localCFrame = type(placement) == "table" and placement.LocalCFrame
                        if typeof(localCFrame) == "CFrame" then
                            local record = type(rawRecord.ItemData) == "table"
                                and rawRecord.ItemData or rawRecord
                            local uid = tostring(record.Uid or rawRecord.Uid or recordUid or "")
                            local category = tostring(record.AssetCategory or record.Category or "")
                            local rarity = rarityOfRecord(record)
                            local weight = nativeWeightKg(record)
                            local scale = tonumber(record.AssetScale or record.Scale
                                or rawRecord.AssetScale or rawRecord.Scale) or 1
                            if uid ~= "" and category ~= "" then
                                wanted[uid] = {
                                    source = "pen",
                                    entry = {
                                        rec = record,
                                        uid = uid,
                                        state = "Placed",
                                        rarity = rarity,
                                        rarityId = rarity and tostring(rarity._id) or "Unknown",
                                        weight = weight or 0,
                                        weightKnown = weight ~= nil,
                                        position = (center * localCFrame).Position,
                                        area = "",
                                        category = category,
                                        ownerUserId = localUserId,
                                    },
                                    offset = math.clamp(2.5 + math.max(scale, 0) * 2, 3, 10),
                                }
                            end
                        end
                    end
                    break
                end
            end
            return wanted
        end

        function manager:reconcile()
            if not anyEnabled() or not sessionAlive() then return end
            local wanted = buildAreaEntries()
            -- A claimed UID can briefly exist in both snapshots. Pen wins so the
            -- same egg never receives two labels during that replication edge.
            for uid, descriptor in pairs(buildPenEntries()) do
                wanted[uid] = descriptor
            end

            local areaCount, penCount = 0, 0
            for uid, descriptor in pairs(wanted) do
                local marker = self.markers[uid] or createMarker(uid, descriptor.source)
                if marker.source ~= descriptor.source then
                    setMarkerSource(marker, descriptor.source, uid)
                end
                local entry = descriptor.entry
                marker.attachment.Position = entry.position
                    + Vector3.new(0, descriptor.offset, 0)
                local text = labelText(entry)
                if marker.label.Text ~= text then marker.label.Text = text end
                if descriptor.source == "pen" then penCount += 1 else areaCount += 1 end
            end
            for uid, marker in pairs(self.markers) do
                if not wanted[uid] then
                    self.markers[uid] = nil
                    pcall(function() marker.attachment:Destroy() end)
                end
            end
            local count = 0
            for _ in pairs(self.markers) do count += 1 end
            self.count = count
            RuntimeStatus.eggESPCount = areaCount
            RuntimeStatus.penESPCount = penCount
        end

        local function queueReconcile()
            if not anyEnabled() or manager.queued then return end
            manager.queued = true
            task.defer(function()
                manager.queued = false
                if anyEnabled() and sessionAlive() then manager:reconcile() end
            end)
        end

        function RuntimeStatus.refreshEggESP()
            if manager.areaEnabled then queueReconcile() end
        end

        function RuntimeStatus.refreshPenESP()
            if manager.penEnabled then queueReconcile() end
        end

        function RuntimeStatus.setEggESP(enabled)
            manager.areaEnabled = enabled == true
            if anyEnabled() then queueReconcile() else destroyFolder() end
        end

        function RuntimeStatus.setPenESP(enabled)
            manager.penEnabled = enabled == true
            if anyEnabled() then queueReconcile() else destroyFolder() end
        end

        -- A failed previous reload may not have reached its unload closure.
        local stale = workspace:FindFirstChild("__CHSAE_EggESP")
        if stale then pcall(function() stale:Destroy() end) end

        pcall(function()
            manager.trackConnection(EggCmds.RuntimeSnapshotUpdated:Connect(function()
                RuntimeStatus.refreshPenESP()
            end))
        end)
        pcall(function()
            manager.trackConnection(EggCmds.AreaEggRecordUpdated:Connect(function()
                RuntimeStatus.refreshEggESP()
            end))
        end)
        pcall(function()
            manager.trackConnection(EggCmds.AreaEggRecordRemoved:Connect(function()
                RuntimeStatus.refreshEggESP()
            end))
        end)
        pcall(function()
            manager.trackConnection(manager.PlotCmds.OnAnyPlotUpdated:Connect(function()
                RuntimeStatus.refreshPenESP()
            end))
        end)

        getgenv().__CHSAE_EggESPRestore = function()
            manager.areaEnabled = false
            manager.penEnabled = false
            manager.queued = false
            destroyFolder()
        end
    end)()
end

-- Native inventory income ESP. Pet and unhatched-egg values use the exact
-- AssetEarnings path used by BackpackController. Pet card pairing mirrors the
-- native eligibility/sort rules; eggs use BackpackController's public UID-slot
-- lookup, so neither path depends on executor-specific GC/debug APIs.
do
    (function()
        local VALUE_LABEL_NAME = "__CHSAE_InventoryValue"
        local TOTAL_LABEL_NAME = "__CHSAE_InventoryTotal"
        local manager = {
            enabled = false,
            ready = false,
            loading = false,
            queued = false,
            queuedAt = 0,
            queueToken = 0,
            generation = 0,
            worker = 0,
            retryDelay = 0.08,
            coreConnections = {},
            guiConnections = {},
            cardConnections = {},
            inventory = nil,
            scroll = nil,
            eggRecords = nil,
            backpackController = nil,
            categoryLabel = nil,
            valueScope = "pets",
            nextExactResolveAt = 0,
        }
        local queueReconcile
        local reconcile

        local function disconnect(connection)
            if connection then pcall(function() connection:Disconnect() end) end
        end

        local function disconnectList(list)
            for _, connection in ipairs(list or {}) do disconnect(connection) end
            table.clear(list)
        end

        local function connectInto(list, signal, callback)
            if not signal then return nil end
            local ok, connection = pcall(function()
                return signal:Connect(callback)
            end)
            if ok and connection then
                table.insert(list, connection)
                return connection
            end
            return nil
        end

        local function destroyCardLabel(card)
            if not card then return end
            local label = card:FindFirstChild(VALUE_LABEL_NAME)
            if label then pcall(function() label:Destroy() end) end
        end

        local function clearCardConnections()
            for card, connections in pairs(manager.cardConnections) do
                disconnectList(connections)
                manager.cardConnections[card] = nil
            end
        end

        local function removeInjected(inventory, scroll)
            inventory = inventory or manager.inventory
            scroll = scroll or manager.scroll
            if inventory then
                local total = inventory:FindFirstChild(TOTAL_LABEL_NAME)
                if total then pcall(function() total:Destroy() end) end
            end
            if scroll then
                for _, card in ipairs(scroll:GetChildren()) do
                    destroyCardLabel(card)
                end
            end
        end

        local function locateInventory()
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local backpackGui = playerGui and playerGui:FindFirstChild("BackpackGui")
            local backpack = backpackGui and backpackGui:FindFirstChild("Backpack")
            local main = backpack and backpack:FindFirstChild("Main")
            local inventory = main and main:FindFirstChild("Inventory")
            local scroll = inventory and inventory:FindFirstChild("ScrollingFrame")
            if inventory and inventory:IsA("GuiObject")
                and scroll and scroll:IsA("ScrollingFrame") then
                return inventory, scroll
            end
            return nil, nil
        end

        local function ensureTotalLabel(inventory)
            local label = inventory:FindFirstChild(TOTAL_LABEL_NAME)
            if label and not label:IsA("TextLabel") then
                pcall(function() label:Destroy() end)
                label = nil
            end
            if not label then
                label = Instance.new("TextLabel")
                label.Name = TOTAL_LABEL_NAME
                label.Parent = inventory
            end

            -- Keep this text-only: the inventory already provides its own header panel.
            -- Styling is reapplied on every reconcile so stale labels cannot remain tiny.
            label.AnchorPoint = Vector2.new(0.5, 0)
            -- Shift the total toward the open left side of the native header and
            -- give the longer income text enough room without covering Search.
            label.Position = UDim2.new(0.42, 0, 0.005, 0)
            label.Size = UDim2.new(0.56, 0, 0.13, 0)
            label.BackgroundTransparency = 1
            label.BorderSizePixel = 0
            label.Font = Enum.Font.SourceSansBold
            label.TextColor3 = Color3.fromRGB(188, 255, 126)
            label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            label.TextStrokeTransparency = 0.05
            label.TextScaled = false
            label.TextSize = 28
            label.TextWrapped = false
            label.TextXAlignment = Enum.TextXAlignment.Center
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.ZIndex = 50
            label.Active = false
            label.Selectable = false

            for _, child in ipairs(label:GetChildren()) do
                if child:IsA("UICorner")
                    or child:IsA("UIStroke")
                    or child:IsA("UITextSizeConstraint") then
                    pcall(function() child:Destroy() end)
                end
            end
            return label
        end

        local function ensureValueLabel(card)
            local label = card:FindFirstChild(VALUE_LABEL_NAME)
            if label and not label:IsA("TextLabel") then
                pcall(function() label:Destroy() end)
                label = nil
            end
            if not label then
                label = Instance.new("TextLabel")
                label.Name = VALUE_LABEL_NAME
                label.Parent = card
            end

            -- A fixed pixel size is more legible than TextScaled on these compact cards.
            label.AnchorPoint = Vector2.new(0.5, 0)
            label.Position = UDim2.new(0.5, 0, 0.035, 0)
            label.Size = UDim2.new(0.92, 0, 0.22, 0)
            label.BackgroundColor3 = Color3.fromRGB(7, 12, 8)
            label.BackgroundTransparency = 0.16
            label.BorderSizePixel = 0
            label.Font = Enum.Font.SourceSansBold
            label.TextColor3 = Color3.fromRGB(220, 255, 196)
            label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            label.TextStrokeTransparency = 0.05
            label.TextScaled = false
            label.TextSize = 15
            label.TextWrapped = false
            label.TextXAlignment = Enum.TextXAlignment.Center
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.ZIndex = 60
            label.Active = false
            label.Selectable = false

            local corner = nil
            for _, child in ipairs(label:GetChildren()) do
                if child:IsA("UICorner") and not corner then
                    corner = child
                elseif child:IsA("UICorner")
                    or child:IsA("UIStroke")
                    or child:IsA("UITextSizeConstraint") then
                    pcall(function() child:Destroy() end)
                end
            end
            if not corner then
                corner = Instance.new("UICorner")
                corner.Parent = label
            end
            corner.CornerRadius = UDim.new(0.3, 0)
            return label
        end

        local function compactMoney(value, skeleton)
            local formatter = manager.numberFormatter
            if formatter and type(formatter.FormatCompact) == "function" then
                local ok, result = pcall(formatter.FormatCompact, value, skeleton or ".##")
                if ok and type(result) == "string" and result ~= "" then
                    return result
                end
            end
            return short(value)
        end

        local function hasLocalAssetTool(uid)
            local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
            for _, container in ipairs({ backpack, LocalPlayer.Character }) do
                if container then
                    for _, child in ipairs(container:GetChildren()) do
                        if child:IsA("Tool") and child:GetAttribute("UID") == uid then
                            return true
                        end
                    end
                end
            end
            return false
        end

        local function nativeDisplayText(item)
            local category = type(item) == "table" and item.Category or nil
            local config = category and manager.assetDirectory[category] or manager.baseAssetConfig
            local displayName
            if type(category) == "string" and manager.assetDirectory[category] then
                local ok, value = pcall(manager.itemDisplay.GetNameFromItemData, item)
                if ok and type(value) == "string" then displayName = value end
            end
            displayName = displayName
                or (type(item) == "table" and item.DisplayName)
                or (config and config.DisplayName)
                or category
                or "Asset"

            local weight = "?Kg"
            local okWeight, value = pcall(manager.assetItems.WeightLabel, item)
            if okWeight and type(value) == "string" then weight = value end
            return tostring(displayName) .. " (" .. tostring(weight) .. ")"
        end

        local function rarityNumber(item)
            local config = manager.assetDirectory[item.Category] or manager.baseAssetConfig
            local rarity = config and config.Rarity
            if type(rarity) == "table" and type(rarity.RarityNumber) == "number" then
                return rarity.RarityNumber
            end
            local row = rarity and manager.rarityDirectory[rarity]
            if type(row) == "table" and type(row.RarityNumber) == "number" then
                return row.RarityNumber
            end
            return math.huge
        end

        local function earningRate(item)
            local ok, value = pcall(manager.assetEarnings.MutationOnlyRatePerSecond, item)
            return ok and type(value) == "number" and value or nil
        end

        local function resolveEggRecords()
            local records = manager.eggRecords
            if type(records) == "table"
                and type(records.ToAssetItemData) == "function"
                and type(records.DisplayNameWithWeight) == "function" then
                return records
            end
            local ok, loaded = pcall(function()
                return require(ReplicatedStorage.Shared.Util.EggRecords)
            end)
            if ok and type(loaded) == "table" then
                manager.eggRecords = loaded
                return loaded
            end
            return nil
        end

        local function resolveBackpackController()
            local controller = manager.backpackController
            if type(controller) == "table" and type(controller.GetEggSlotFrame) == "function" then
                return controller
            end
            local playerScripts = LocalPlayer:FindFirstChild("PlayerScripts")
            local gui = playerScripts and playerScripts:FindFirstChild("GUI")
            local backpack = gui and gui:FindFirstChild("BackpackController")
            local main = backpack and backpack:FindFirstChild("Main")
            if not main then return nil end
            local ok, loaded = pcall(require, main)
            if ok and type(loaded) == "table" then
                manager.backpackController = loaded
                return loaded
            end
            return nil
        end

        local function buildEggRecords()
            local recordsModule = resolveEggRecords()
            if not recordsModule then return {}, nil end
            local okSave, save = pcall(manager.save.Get)
            if not okSave or type(save) ~= "table" then
                return nil, "save-not-ready"
            end

            local controller = resolveBackpackController()
            local records = {}
            for uid, raw in pairs(save.EggInventory or {}) do
                if type(uid) == "string" and type(raw) == "table" and raw.Placement == nil then
                    local okItem, item = pcall(recordsModule.ToAssetItemData, raw)
                    local income = okItem and type(item) == "table" and earningRate(item) or nil
                    local okDisplay, display = pcall(recordsModule.DisplayNameWithWeight, raw)
                    if type(income) == "number" and okDisplay and type(display) == "string" then
                        local frame
                        if controller then
                            local okFrame, result = pcall(
                                controller.GetEggSlotFrame,
                                controller,
                                uid
                            )
                            if okFrame and typeof(result) == "Instance" then frame = result end
                        end
                        table.insert(records, {
                            uid = uid,
                            item = item,
                            income = income,
                            display = display,
                            frame = frame,
                            source = frame and "egg-slot-api" or "egg-record",
                        })
                    end
                end
            end
            table.sort(records, function(a, b) return a.uid < b.uid end)
            return records, nil
        end

        local function oddsDenominator(item, dropWeight)
            if type(dropWeight) ~= "number" or dropWeight <= 0 then return 0 end
            local ok, factor = pcall(
                manager.mutations.RarityFactorFor,
                item.Mutations,
                item.BaseMutation
            )
            return ok and type(factor) == "number" and (factor / dropWeight) or 0
        end

        local function recordLess(a, b)
            if a.favorite ~= b.favorite then return a.favorite end
            if a.rarity ~= b.rarity then return a.rarity > b.rarity end
            if a.earning ~= b.earning then return a.earning > b.earning end
            if a.odds ~= b.odds then return a.odds > b.odds end
            if a.dropWeight ~= b.dropWeight then return a.dropWeight < b.dropWeight end
            return a.uid < b.uid
        end

        local function buildEligibleRecords()
            local okSave, save = pcall(manager.save.Get)
            if not okSave or type(save) ~= "table" or type(save.Inventory) ~= "table" then
                return nil, "save-not-ready"
            end

            local okPlaced, placed = pcall(
                manager.assetRoster.ReadOwnerPen,
                LocalPlayer.UserId
            )
            if not okPlaced or type(placed) ~= "table" then
                return nil, "pen-roster-not-ready"
            end

            local equipped = {}
            for _, uid in ipairs(save.EquippedAssets or {}) do
                if type(uid) == "string" then equipped[uid] = true end
            end

            local records = {}
            for uid, raw in pairs(save.Inventory) do
                if type(uid) == "string" and type(raw) == "table" then
                    local okDecode, item = pcall(manager.assetItems.Decode, raw)
                    if okDecode and type(item) == "table"
                        and item.InFuse ~= true
                        and (not equipped[uid] or hasLocalAssetTool(uid))
                        and placed[uid] == nil then
                        local income = earningRate(item)
                        if type(income) == "number" then
                            local config = manager.assetDirectory[item.Category] or manager.baseAssetConfig
                            local dropWeight = config and config.DropWeight
                            if type(dropWeight) ~= "number" then dropWeight = math.huge end
                            table.insert(records, {
                                uid = uid,
                                item = item,
                                income = income,
                                display = nativeDisplayText(item),
                                favorite = item.IsFavorite == true,
                                rarity = rarityNumber(item),
                                earning = income,
                                odds = oddsDenominator(item, dropWeight),
                                dropWeight = dropWeight,
                            })
                        end
                    end
                end
            end
            table.sort(records, recordLess)
            return records, nil
        end

        local function collectAssetCards(scroll)
            local cards = {}
            for _, card in ipairs(scroll:GetChildren()) do
                if card:IsA("TextButton")
                    and card:GetAttribute("IsInventorySlot") == true
                    and card:GetAttribute("HasAssetOverlay") == true then
                    local toolName = card:FindFirstChild("ToolName")
                    if toolName and toolName:IsA("TextLabel") then
                        table.insert(cards, card)
                    end
                end
            end
            table.sort(cards, function(a, b)
                if a.LayoutOrder ~= b.LayoutOrder then return a.LayoutOrder < b.LayoutOrder end
                return (tonumber(a.Name) or math.huge) < (tonumber(b.Name) or math.huge)
            end)
            return cards
        end

        local function collectEggCards(scroll)
            local cards = {}
            for _, card in ipairs(scroll:GetChildren()) do
                if card:IsA("TextButton")
                    and card:GetAttribute("IsInventorySlot") == true
                    and card:GetAttribute("HasEggOverlay") == true then
                    local toolName = card:FindFirstChild("ToolName")
                    if toolName and toolName:IsA("TextLabel") then
                        table.insert(cards, card)
                    end
                end
            end
            table.sort(cards, function(a, b)
                if a.LayoutOrder ~= b.LayoutOrder then return a.LayoutOrder < b.LayoutOrder end
                return (tonumber(a.Name) or math.huge) < (tonumber(b.Name) or math.huge)
            end)
            return cards
        end

        -- BackpackController keeps its selected category private, but mirrors it
        -- into this native header label. Reading that label avoids guessing from
        -- card visibility, which is ambiguous for empty or search-filtered views.
        local function resolveValueScope(inventory)
            local categoryLabel = inventory and inventory:FindFirstChild("CategoryLabel")
            if categoryLabel and categoryLabel:IsA("TextLabel") then
                local category = string.lower(tostring(categoryLabel.Text or ""))
                category = category:match("^%s*(.-)%s*$")
                if category == "eggs" then
                    manager.valueScope = "eggs"
                elseif category == "pets" then
                    manager.valueScope = "pets"
                end
            end
            return manager.valueScope
        end

        local function mapRecordsToCards(records, cards)
            local mapping = {}
            if #records == #cards then
                local ordered = true
                for index, card in ipairs(cards) do
                    local toolName = card:FindFirstChild("ToolName")
                    if not toolName or toolName.Text ~= records[index].display then
                        ordered = false
                        break
                    end
                end
                if ordered then
                    for index, card in ipairs(cards) do mapping[card] = records[index] end
                    return mapping, true
                end
            end

            -- Safe update/future-layout fallback: exact display buckets. Unique pets
            -- map directly. Duplicate-looking pets map in native sort order when
            -- their counts match; if a hotbar pet makes a bucket ambiguous, that
            -- bucket is shown only when every candidate has the exact same income.
            -- Other unambiguous cards keep their values instead of all going blank.
            local recordBuckets = {}
            for _, record in ipairs(records) do
                local bucket = recordBuckets[record.display]
                if not bucket then bucket = {}; recordBuckets[record.display] = bucket end
                table.insert(bucket, record)
            end
            local cardBuckets = {}
            for _, card in ipairs(cards) do
                local display = card.ToolName.Text
                local bucket = cardBuckets[display]
                if not bucket then bucket = {}; cardBuckets[display] = bucket end
                table.insert(bucket, card)
            end

            local resolved = 0
            for display, cardBucket in pairs(cardBuckets) do
                local recordBucket = recordBuckets[display]
                if recordBucket and #recordBucket == #cardBucket then
                    for index, card in ipairs(cardBucket) do
                        mapping[card] = recordBucket[index]
                        resolved = resolved + 1
                    end
                elseif recordBucket and #recordBucket > #cardBucket then
                    local income = recordBucket[1].income
                    local equalIncome = true
                    for index = 2, #recordBucket do
                        if recordBucket[index].income ~= income then
                            equalIncome = false
                            break
                        end
                    end
                    if equalIncome then
                        for _, card in ipairs(cardBucket) do
                            mapping[card] = {
                                uid = nil,
                                income = income,
                                display = display,
                            }
                            resolved = resolved + 1
                        end
                    end
                end
            end
            return mapping, resolved == #cards
        end

        -- Optional exact adapter for executors that expose sUNC-style filtergc.
        -- The portable native-order resolver above remains the primary path; this
        -- adapter is attempted only for an otherwise ambiguous duplicate bucket.
        local function tryExactSlotMapping(records, cards, scroll)
            if os.clock() < manager.nextExactResolveAt then return nil, false end
            manager.nextExactResolveAt = os.clock() + 5
            local environment = getgenv()
            local filterGc = environment and (environment.filtergc or environment.filter_gc)
            if type(filterGc) ~= "function" then return nil, false end

            local okMatches, matches = pcall(filterGc, "table", {
                Keys = { "Tool", "Index", "Frame" },
            }, false)
            if not okMatches or type(matches) ~= "table" then return nil, false end
            if rawget(matches, "Tool") ~= nil and rawget(matches, "Frame") ~= nil then
                matches = { matches }
            end

            local cardSet = {}
            local recordByUid = {}
            for _, card in ipairs(cards) do cardSet[card] = true end
            for _, record in ipairs(records) do recordByUid[record.uid] = record end

            local candidates = {}
            for _, slot in pairs(matches) do
                if type(slot) == "table" then
                    local frame = rawget(slot, "Frame")
                    local tool = rawget(slot, "Tool")
                    if cardSet[frame] and frame.Parent == scroll then
                        local uid
                        pcall(function()
                            if type(tool) == "table" then
                                uid = rawget(tool, "UID")
                                    or (type(tool.GetAttribute) == "function"
                                        and tool:GetAttribute("UID"))
                            elseif typeof(tool) == "Instance" then
                                uid = tool:GetAttribute("UID")
                            end
                        end)
                        local record = type(uid) == "string" and recordByUid[uid] or nil
                        local toolName = frame:FindFirstChild("ToolName")
                        if record and toolName and toolName.Text == record.display then
                            local previous = candidates[frame]
                            if previous == nil then
                                candidates[frame] = record
                            elseif previous ~= record then
                                candidates[frame] = false
                            end
                        end
                    end
                end
            end

            local mapping = {}
            local resolved = 0
            for _, card in ipairs(cards) do
                local record = candidates[card]
                if type(record) == "table" then
                    mapping[card] = {
                        uid = record.uid,
                        income = record.income,
                        display = record.display,
                        source = "native-slot",
                    }
                    resolved = resolved + 1
                end
            end
            return mapping, resolved == #cards
        end

        local function unwatchCard(card, removeLabel)
            local connections = manager.cardConnections[card]
            if connections then
                disconnectList(connections)
                manager.cardConnections[card] = nil
            end
            if removeLabel then destroyCardLabel(card) end
        end

        local function watchCard(card)
            if not card or not card:IsA("TextButton") or manager.cardConnections[card] then
                return
            end
            local connections = {}
            manager.cardConnections[card] = connections
            connectInto(connections, card:GetPropertyChangedSignal("LayoutOrder"), function()
                queueReconcile(0.04)
            end)
            connectInto(connections, card:GetAttributeChangedSignal("HasAssetOverlay"), function()
                queueReconcile(0.04)
            end)
            connectInto(connections, card:GetAttributeChangedSignal("HasEggOverlay"), function()
                queueReconcile(0.04)
            end)
            connectInto(connections, card:GetAttributeChangedSignal("IsInventorySlot"), function()
                queueReconcile(0.04)
            end)
            connectInto(connections, card.ChildAdded, function(child)
                if child.Name == "ToolName" then
                    if child:IsA("TextLabel") then
                        connectInto(connections, child:GetPropertyChangedSignal("Text"), function()
                            queueReconcile(0.06)
                        end)
                    end
                    queueReconcile(0.04)
                end
            end)
            connectInto(connections, card.AncestryChanged, function(_, parent)
                if not parent then unwatchCard(card, false) end
                queueReconcile(0.04)
            end)
            local toolName = card:FindFirstChild("ToolName")
            if toolName and toolName:IsA("TextLabel") then
                connectInto(connections, toolName:GetPropertyChangedSignal("Text"), function()
                    queueReconcile(0.06)
                end)
            end
        end

        local function bindGui(inventory, scroll)
            if manager.inventory == inventory and manager.scroll == scroll then return end
            removeInjected(manager.inventory, manager.scroll)
            disconnectList(manager.guiConnections)
            clearCardConnections()
            manager.inventory = inventory
            manager.scroll = scroll
            manager.categoryLabel = nil
            manager.valueScope = "pets"

            local function watchCategoryLabel(categoryLabel)
                if not categoryLabel or not categoryLabel:IsA("TextLabel")
                    or manager.categoryLabel == categoryLabel then
                    return
                end
                manager.categoryLabel = categoryLabel
                connectInto(manager.guiConnections,
                    categoryLabel:GetPropertyChangedSignal("Text"), function()
                        resolveValueScope(inventory)
                        queueReconcile(0)
                    end)
                connectInto(manager.guiConnections, categoryLabel.AncestryChanged, function(_, parent)
                    if not parent and manager.categoryLabel == categoryLabel then
                        manager.categoryLabel = nil
                    end
                    queueReconcile(0)
                end)
            end

            watchCategoryLabel(inventory:FindFirstChild("CategoryLabel"))
            resolveValueScope(inventory)

            connectInto(manager.guiConnections, scroll.ChildAdded, function(card)
                task.defer(function()
                    if manager.enabled and card.Parent == scroll then watchCard(card) end
                    queueReconcile(0.05)
                end)
            end)
            connectInto(manager.guiConnections, scroll.ChildRemoved, function(card)
                unwatchCard(card, false)
                queueReconcile(0.05)
            end)
            connectInto(manager.guiConnections, inventory.AncestryChanged, function(_, parent)
                if not parent then queueReconcile(0.08) end
            end)
            connectInto(manager.guiConnections, inventory.ChildAdded, function(child)
                if child.Name == "CategoryLabel" then
                    watchCategoryLabel(child)
                    resolveValueScope(inventory)
                    queueReconcile(0)
                end
            end)
            for _, card in ipairs(scroll:GetChildren()) do watchCard(card) end
        end

        reconcile = function()
            if not manager.enabled or not manager.ready or not sessionAlive() then return end
            local inventory, scroll = locateInventory()
            if not inventory then
                removeInjected(manager.inventory, manager.scroll)
                manager.inventory, manager.scroll = nil, nil
                manager.retryDelay = math.min(2, manager.retryDelay * 2)
                queueReconcile(manager.retryDelay)
                return
            end
            bindGui(inventory, scroll)
            local totalLabel = ensureTotalLabel(inventory)
            local records = buildEligibleRecords()
            local eggRecords = buildEggRecords()
            local cards = collectAssetCards(scroll)
            local eggCards = collectEggCards(scroll)
            for card in pairs(manager.cardConnections) do
                if card.Parent ~= scroll then
                    unwatchCard(card, true)
                end
            end
            for _, card in ipairs(cards) do watchCard(card) end
            if not records or not eggRecords then
                totalLabel.Text = "Total Value: loading..."
                totalLabel:SetAttribute("ExactValue", nil)
                totalLabel:SetAttribute("ExactIncomePerSecond", nil)
                totalLabel:SetAttribute("ExactPetIncomePerSecond", nil)
                totalLabel:SetAttribute("ExactEggIncomePerSecond", nil)
                manager.retryDelay = math.min(2, manager.retryDelay * 2)
                queueReconcile(manager.retryDelay)
                return
            end

            -- Follow the native inventory category. Each subtotal still covers
            -- eligible hotbar occupants; pen/fuse-only pets and placed eggs stay
            -- excluded just as they are from the native inventory views.
            local petIncome, eggIncome = 0, 0
            for _, record in ipairs(records) do petIncome = petIncome + record.income end
            for _, record in ipairs(eggRecords) do eggIncome = eggIncome + record.income end
            local valueScope = resolveValueScope(inventory)
            local displayedIncome = valueScope == "eggs" and eggIncome or petIncome
            local valueKind = valueScope == "eggs" and "Egg" or "Pet"
            totalLabel.Text = "Total " .. valueKind .. " Value: $"
                .. compactMoney(displayedIncome, ".###") .. "/s"
            totalLabel:SetAttribute("ExactValue", displayedIncome)
            totalLabel:SetAttribute("ExactIncomePerSecond", displayedIncome)
            totalLabel:SetAttribute("ExactPetIncomePerSecond", petIncome)
            totalLabel:SetAttribute("ExactEggIncomePerSecond", eggIncome)
            totalLabel:SetAttribute("InventoryCategory", valueKind .. "s")
            totalLabel:SetAttribute("Scope", valueScope == "eggs"
                and "native-unplaced-egg-income" or "native-eligible-pet-income")

            local mapping, mappingComplete = mapRecordsToCards(records, cards)
            local eggCardSet = {}
            local mappedEggCards = 0
            for _, card in ipairs(eggCards) do eggCardSet[card] = true end
            for _, record in ipairs(eggRecords) do
                local frame = record.frame
                local toolName = frame and frame:FindFirstChild("ToolName")
                if frame and eggCardSet[frame] and not mapping[frame]
                    and toolName and toolName:IsA("TextLabel")
                    and toolName.Text == record.display then
                    mapping[frame] = record
                    mappedEggCards = mappedEggCards + 1
                end
            end
            mappingComplete = mappingComplete and mappedEggCards == #eggCards
            if not mappingComplete then
                local allRecords, allCards = {}, {}
                for _, record in ipairs(records) do table.insert(allRecords, record) end
                for _, record in ipairs(eggRecords) do table.insert(allRecords, record) end
                for _, card in ipairs(cards) do table.insert(allCards, card) end
                for _, card in ipairs(eggCards) do table.insert(allCards, card) end
                local exactMapping, exactComplete = tryExactSlotMapping(allRecords, allCards, scroll)
                if exactMapping then
                    for card, record in pairs(exactMapping) do mapping[card] = record end
                    mappingComplete = exactComplete
                    if not mappingComplete then
                        local resolved = 0
                        for _, card in ipairs(allCards) do
                            if mapping[card] then resolved = resolved + 1 end
                        end
                        mappingComplete = resolved == #allCards
                    end
                end
            end

            local mappedCount = 0
            for _, card in ipairs(scroll:GetChildren()) do
                local record = mapping[card]
                if record then
                    local label = ensureValueLabel(card)
                    label.Text = "$" .. compactMoney(record.income, ".#") .. "/s"
                    label:SetAttribute("ExactValue", record.income)
                    label:SetAttribute("ExactIncomePerSecond", record.income)
                    label:SetAttribute("UID", record.uid)
                    label:SetAttribute("Source", record.source
                        or (record.uid and "native-order" or "equal-income-signature"))
                    mappedCount = mappedCount + 1
                else
                    destroyCardLabel(card)
                end
            end

            totalLabel:SetAttribute("ResolvedCards", mappedCount)
            totalLabel:SetAttribute("TotalCards", #cards + #eggCards)
            if mappingComplete then
                manager.retryDelay = 0.08
            else
                manager.retryDelay = math.min(2, manager.retryDelay * 2)
                queueReconcile(manager.retryDelay)
            end
        end

        queueReconcile = function(delaySeconds)
            if not manager.enabled then return end
            local delay = math.max(0, tonumber(delaySeconds) or 0.04)
            local dueAt = os.clock() + delay
            if manager.queued and dueAt >= (manager.queuedAt or 0) - 0.001 then return end
            manager.queued = true
            manager.queuedAt = dueAt
            manager.queueToken = manager.queueToken + 1
            local queueToken = manager.queueToken
            local generation = manager.generation
            task.delay(delay, function()
                if manager.queueToken ~= queueToken then return end
                manager.queued = false
                manager.queuedAt = 0
                if manager.enabled and manager.generation == generation and sessionAlive() then
                    local ok = pcall(reconcile)
                    if not ok then
                        manager.retryDelay = math.min(2, manager.retryDelay * 2)
                        queueReconcile(manager.retryDelay)
                    end
                end
            end)
        end

        local function bindCoreConnections()
            disconnectList(manager.coreConnections)
            local function changed()
                queueReconcile(0.10)
            end
            for _, field in ipairs({ "Inventory", "EquippedAssets", "EggInventory" }) do
                pcall(function()
                    connectInto(manager.coreConnections, manager.save.FieldSignal(field), changed)
                end)
            end
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if playerGui then connectInto(manager.coreConnections, playerGui.ChildAdded, changed) end
            connectInto(manager.coreConnections, LocalPlayer.CharacterAdded, changed)
            connectInto(manager.coreConnections, manager.assetRoster.OwnerRefreshed, function(userId)
                if userId == LocalPlayer.UserId then changed() end
            end)
            connectInto(manager.coreConnections, manager.assetRoster.OwnerCleared, function(userId)
                if userId == LocalPlayer.UserId then changed() end
            end)
        end

        local function startWorker()
            manager.worker = manager.worker + 1
            local worker = manager.worker
            task.spawn(function()
                while manager.enabled and manager.worker == worker and sessionAlive() do
                    task.wait(12)
                    if manager.enabled and manager.worker == worker then queueReconcile(0.04) end
                end
            end)
        end

        local function loadModules(generation)
            if manager.ready or manager.loading then return end
            manager.loading = true
            task.spawn(function()
                local ok, saveMod, assetItems, itemDisplay, assets, rarityData,
                    assetEarnings, mutations, assetRoster, numberFormatter = pcall(function()
                        return require(ReplicatedStorage.Shared.Save),
                            require(ReplicatedStorage.Shared.Util.AssetItems),
                            require(ReplicatedStorage.Shared.Modules.ItemDisplay),
                            require(ReplicatedStorage.Data.Assets),
                            require(ReplicatedStorage.Data.Rarity),
                            require(ReplicatedStorage.Shared.Util.AssetEarnings),
                            require(ReplicatedStorage.Shared.Modules.Mutations),
                            require(ReplicatedStorage.Client.AssetRoster),
                            require(ReplicatedStorage.Packages.FormatNumber.Simple)
                    end)
                manager.loading = false
                if not ok or not manager.enabled or manager.generation ~= generation
                    or not sessionAlive() then
                    if manager.enabled and sessionAlive() then
                        task.delay(1, function()
                            if manager.enabled and not manager.ready and sessionAlive() then
                                loadModules(manager.generation)
                            end
                        end)
                    end
                    return
                end
                manager.save = saveMod
                manager.assetItems = assetItems
                manager.itemDisplay = itemDisplay
                manager.assetDirectory = assets.Directory
                manager.baseAssetConfig = assets.BaseConfig
                manager.rarityDirectory = rarityData.Rarities
                manager.assetEarnings = assetEarnings
                manager.mutations = mutations
                manager.assetRoster = assetRoster
                manager.numberFormatter = numberFormatter
                manager.ready = type(manager.assetDirectory) == "table"
                    and type(manager.rarityDirectory) == "table"
                if manager.ready then
                    bindCoreConnections()
                    queueReconcile(0.08)
                else
                    task.delay(1, function()
                        if manager.enabled and not manager.ready and sessionAlive() then
                            loadModules(manager.generation)
                        end
                    end)
                end
            end)
        end

        local function stop()
            manager.enabled = false
            manager.generation = manager.generation + 1
            manager.worker = manager.worker + 1
            manager.queued = false
            manager.queuedAt = 0
            manager.queueToken = manager.queueToken + 1
            RuntimeStatus.inventoryESPEnabled = false
            disconnectList(manager.coreConnections)
            disconnectList(manager.guiConnections)
            clearCardConnections()
            removeInjected(manager.inventory, manager.scroll)
            local inventory, scroll = locateInventory()
            removeInjected(inventory, scroll)
            manager.inventory, manager.scroll, manager.categoryLabel = nil, nil, nil
            manager.valueScope = "pets"
        end

        if getgenv().__CHSAE_InventoryESPRestore then
            pcall(getgenv().__CHSAE_InventoryESPRestore)
        end
        getgenv().__CHSAE_InventoryESPRestore = stop

        function RuntimeStatus.setInventoryESP(enabled)
            enabled = enabled == true
            if manager.enabled == enabled then
                RuntimeStatus.inventoryESPEnabled = enabled
                if enabled then queueReconcile(0.04) else removeInjected() end
                return
            end
            if not enabled then
                stop()
                return
            end

            manager.enabled = true
            manager.generation = manager.generation + 1
            manager.retryDelay = 0.08
            RuntimeStatus.inventoryESPEnabled = true
            local generation = manager.generation
            if manager.ready then
                bindCoreConnections()
                queueReconcile(0.08)
            else
                loadModules(generation)
            end
            startWorker()
        end
    end)()
end

local function getCharParts()
    local ch = LocalPlayer.Character
    if not ch then return nil, nil end
    return ch:FindFirstChild("HumanoidRootPart"), ch:FindFirstChildOfClass("Humanoid")
end

local function getNetworkPingSeconds()
    local seconds = 0.08
    pcall(function()
        seconds = math.max(0, Stats.Network.ServerStatsItem["Data Ping"]:GetValue()) / 1000
    end)
    return seconds
end

local function getSeparationLine()
    local n = workspace:FindFirstChild("__OBJECTS")
    n = n and n:FindFirstChild("Areas")
    return n and n:FindFirstChild("SeparationLine")
end

-- Which side of the SeparationLine are we on? This is the same signed-distance
-- calculation the game's retired GuardAreaLookupUtil used: LookVector · (pos - linePos),
-- **> 0 = inside the gameplay area**, <= 0 = home/base side. The claim fires when
-- the server sees you cross from + to -. Measured live: eggs sit at +946…+2834,
-- base and StartArea at about -10.
local function lineSide(pos)
    local sep = getSeparationLine()
    if not (sep and pos) then return nil end
    return sep.CFrame.LookVector:Dot(pos - sep.Position)
end

-- Exit target: step straight across the line to `extraStuds` past it on the base
-- side, keeping our lateral offset (no wandering sideways to a fixed X/Z).
local function getExitTarget(extraStuds)
    local sep = getSeparationLine()
    local root = getCharParts()
    if not (sep and root) then return nil end
    local d = lineSide(root.Position) or 0
    return root.Position - sep.CFrame.LookVector.Unit * (d + 1 + (extraStuds or 0))
end

local function getStartArea()
    local n = workspace:FindFirstChild("__OBJECTS")
    n = n and n:FindFirstChild("Areas")
    return n and n:FindFirstChild("StartArea")
end

-- Canonical entrance center for every base -> gameplay-area movement. StartArea
-- is a wide horizontal rectangle, so using its nearest edge from a side pen can
-- create a diagonal route through the wall. TrackStart is the map's centered,
-- invisible entrance marker. Do not substitute the wide StartArea: its center or
-- nearest edge can recreate the diagonal corner route this marker prevents.
RuntimeStatus.getTrackStart = function()
    local n = workspace:FindFirstChild("__OBJECTS")
    n = n and n:FindFirstChild("Build")
    n = n and n:FindFirstChild("MainMap")
    local trackStart = n and n:FindFirstChild("TrackStart")
    if trackStart and trackStart:IsA("BasePart") then return trackStart end
    return nil
end

-- Forward-declared because the proven ground snap reads the validator's expected
-- character dimensions when the integrity guard is active.
local integrityState

-- Compact health signal for the Session card and overlay.  Registered impulses
-- are expected and do not count as flags; only evidence/tamper/heartbeat/kick state does.
RuntimeStatus.getSafetySummary = function()
    local state = integrityState
    if type(state) ~= "table" then
        return RuntimeStatus.defaultMoveFallback
            and "🚶 Safe fallback" or "🛡️ Guard unavailable", 0
    end
    local flags = 0
    local evidence = rawget(state, "Evidence")
    local speed = type(evidence) == "table" and tonumber(rawget(evidence, "Speed")) or 0
    local teleport = type(evidence) == "table" and tonumber(rawget(evidence, "Teleport")) or 0
    local flight = type(evidence) == "table" and tonumber(rawget(evidence, "Flight")) or 0
    flags += math.max(0, speed or 0) + math.max(0, teleport or 0) + math.max(0, flight or 0)
    flags += math.max(0, tonumber(rawget(state, "TamperScore")) or 0)
    flags += math.max(0, tonumber(rawget(state, "InvalidHeartbeatCount")) or 0)
    -- A registered travel impulse intentionally creates CorrectionContext and
    -- ThreatLevel="Observing".  That is coverage, not evidence.  Counting it as
    -- a flag made a healthy high-speed trip look unsafe in the overlay.
    if rawget(state, "KickQueued") == true then flags += 4 end
    local threat = tostring(rawget(state, "ThreatLevel") or "Unknown")
    if flags == 0 then return "🛡️ " .. (threat == "Unknown" and "Trusted" or threat), 0 end
    return "⚠️ " .. threat, flags
end

-- This is the exact ground snap used by the working standalone automation. Keep
-- one RaycastParams object and refresh only its character exclusion; rebuilding
-- it inside every movement frame subtly changed the tested movement behaviour.
local GROUND_RP = RaycastParams.new()
GROUND_RP.FilterType = Enum.RaycastFilterType.Exclude
-- Egg visuals and area marker volumes are queryable but not walking surfaces.
GROUND_RP.RespectCanCollide = true

local function refreshGroundFilter()
    local character = LocalPlayer.Character
    if character then GROUND_RP.FilterDescendantsInstances = { character } end
end

refreshGroundFilter()

local function groundY(x, z, fallbackY)
    local _, humanoid = getCharParts()
    local character = LocalPlayer.Character
    if not (humanoid and character) then return nil end
    GROUND_RP.FilterDescendantsInstances = { character }
    local hit = workspace:Raycast(
        Vector3.new(x, fallbackY + 30, z),
        Vector3.new(0, -400, 0),
        GROUND_RP
    )
    if not hit then return nil end
    local state = integrityState
    local hip = (state and tonumber(rawget(state, "ExpectedHipHeight")))
        or humanoid.HipHeight or 2
    local half = (state and tonumber(rawget(state, "ExpectedRootHalfHeight"))) or 1
    local candidateY = hit.Position.Y + hip + half
    -- The old +30 ray origin could hit a roof, nest, egg or treadmill surface
    -- above the route. Stress telemetry caught the root jumping from Y=70.6 to
    -- Y=103-104 immediately before a Correcting death. A ground sample is only
    -- valid when it stays near the current walking plane; otherwise preserve the
    -- current height and let a later frame reacquire genuine nearby ground.
    if candidateY > fallbackY + 4 or candidateY < fallbackY - 8 then
        return fallbackY
    end
    return candidateY
end

-- Glide follows registered ground-level steps; native walking remains the recovery path.

-- [[ 🚧 AREA SPEED GATE — THE REAL CAUSE OF THE DEATHS (solved 2026-08-20) ]] --
-- PROVEN by a controlled boundary test on void26v3 (SpeedPower 1121):
--     Lake   (requires   900) -> tween in, hold 4s -> died=false hp=100
--     Desert (requires 10000) -> tween in          -> died=true  hp=-1000
-- Same speed, same code, same tween — only the AREA differed. Entering a zone
-- whose SpeedPower requirement you do not meet is an instant -1000 execution
-- (then respawn at base). This is why every "movement fix" failed identically:
-- it was never the movement. Each area posts its requirement on a sign, e.g.
--   Forest 11 · Lake 900 · Desert 10K · Jungle 40K · Snow 170K
--   Volcano 900K · Abyss 2.5M · Prehistoric 17M · Cosmic 700M
-- Bounds come from GuardAreas.<Area>.Bounds, so the gate is read live.
local AreaGate = { map = nil, at = 0, save = nil }

local function parseSpeedText(t)
    local num, suf = tostring(t):match("([%d%.]+)%s*([KMBTkmbt]?)")
    local n = tonumber(num)
    if not n then return nil end
    local m = ({ K = 1e3, M = 1e6, B = 1e9, T = 1e12 })[(suf or ""):upper()]
    return n * (m or 1)
end

-- { [areaId] = { req = <SpeedPower>, minX, maxX, minZ, maxZ } }
local function areaGateMap()
    if AreaGate.map and (os.clock() - AreaGate.at) < 30 then return AreaGate.map end
    local map = {}
    pcall(function()
        local gf = workspace:FindFirstChild("__OBJECTS")
        gf = gf and gf:FindFirstChild("Areas")
        gf = gf and gf:FindFirstChild("GuardAreas")
        if not gf then return end
        for _, area in ipairs(gf:GetChildren()) do
            local b = area:FindFirstChild("Bounds")
            local req
            for _, d in ipairs(area:GetDescendants()) do
                if d:IsA("TextLabel") then
                    local v = parseSpeedText(d.Text)
                    if v then req = v break end
                end
            end
            if b and b:IsA("BasePart") then
                map[area.Name] = {
                    req = req,
                    minX = b.Position.X - b.Size.X / 2, maxX = b.Position.X + b.Size.X / 2,
                    minZ = b.Position.Z - b.Size.Z / 2, maxZ = b.Position.Z + b.Size.Z / 2,
                }
            end
        end
    end)
    AreaGate.map, AreaGate.at = map, os.clock()
    return map
end

local function mySpeedPower()
    local v
    pcall(function()
        if not AreaGate.save then
            local loaded = require(ReplicatedStorage.Shared.Save)
            AreaGate.save = { Get = function() return loaded.Get() end }
        end
        v = tonumber(AreaGate.save.Get().SpeedPower)
    end)
    return v or 0
end

-- true when we are allowed in that area (unknown requirement = allow)
local function areaAllowed(areaId)
    local e = areaGateMap()[tostring(areaId)]
    if not (e and e.req) then return true end
    return mySpeedPower() >= e.req
end

-- [[ 🛡️ KillPartIgnore — THE FIX FOR THE TWEEN DEATH (solved 2026-08-19) ]] --
-- Decompiled from the game's own client module `ReplicatedFirst.UGI.
-- ContentCatalog.Volume` (nil-parented after load, which is why it never showed
-- up in a normal search). It runs on Heartbeat:
--
--   for every part tagged COLLISION_PART it stores {CFrame, Size}; if that part
--   later leaves Workspace (deleted OR streamed out) it is flagged Deleted.
--   Each frame, if your HumanoidRootPart is inside the bounds of ANY deleted
--   collision part -> `Humanoid.Health = 0`.  Instant, silent, client-side.
--
--   ...UNLESS:  HumanoidRootPart:GetAttribute("KillPartIgnore") == true
--   -> the check returns early and never kills.
--
-- That is an anti-noclip trap, and a fast CFrame tween trips it constantly
-- because it flies through regions whose collision parts have streamed out.
-- It is ALSO why the reference script survives 1700 studs/s at WalkSpeed 152
-- (measured live on void26v1: spd=1712 ws=152 vel=0|0|0 attrs=[KillPartIgnore=true])
-- — it is not "riding the speed limit", it simply disarms this check.
local function keepKillPartIgnore()
    local root = getCharParts()
    if root and root:GetAttribute("KillPartIgnore") ~= true then
        pcall(function() root:SetAttribute("KillPartIgnore", true) end)
    end
end

-- Keep it armed through the attribute's own signal instead of polling four
-- times per second for the whole session. CharacterAdded is the only respawn
-- path; a server/client reset of the attribute wakes this watcher immediately.
local killIgnoreConn
local function watchKillPartIgnore(character)
    if killIgnoreConn then pcall(function() killIgnoreConn:Disconnect() end) end
    killIgnoreConn = nil
    task.spawn(function()
        local root = character and (character:FindFirstChild("HumanoidRootPart")
            or character:WaitForChild("HumanoidRootPart", 5))
        if not (sessionAlive() and root and root:IsA("BasePart")) then return end
        refreshGroundFilter()
        keepKillPartIgnore()
        killIgnoreConn = root:GetAttributeChangedSignal("KillPartIgnore"):Connect(function()
            if sessionAlive() and root:GetAttribute("KillPartIgnore") ~= true then
                keepKillPartIgnore()
            end
        end)
        getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = killIgnoreConn
    end)
end
if LocalPlayer.Character then watchKillPartIgnore(LocalPlayer.Character) end
getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
    = LocalPlayer.CharacterAdded:Connect(watchKillPartIgnore)

-- Register fast travel through the game's own movement-integrity API. Unlike the
-- old per-frame guard, BeginImpulse creates a valid ImpulseContext and lets the
-- evaluator finish its normal receipt lifecycle. We never clear evidence,
-- CorrectionContext, history, heartbeat/monitor state, or kick/tamper state.
local integrityBridge
local setIntegrityGuard
local integrityLastBeginAt = 0
local integrityReport
local integrityRejected = false

-- [[ MOVEMENT EXECUTOR COMPATIBILITY ]] --
do
    local createCompatibility = function(api)
    local c = {}
    local cache, busy = {}, false
    local function call(fn, ...)
        if type(fn) ~= "function" then return false, nil end
        return pcall(fn, ...)
    end
    c.upvalues = function(fn)
        for _, reader in ipairs(api.upvalueReaders) do
            local ok, result = call(reader, fn)
            if ok and type(result) == "table" then return result end
        end
        return nil, "movement API unavailable: getupvalues"
    end
    c.name = function(fn)
        local ok, name = call(api.info, fn, "n")
        if ok and type(name) == "string" and name ~= "" then return name end
        local read, detail = call(api.getinfo, fn)
        if read and type(detail) == "table" then return rawget(detail, "name") end
        return nil
    end
    c.frozen = function(value)
        local ok, frozen = call(api.isfrozen, value)
        return ok and frozen == true
    end
    c.ready = function()
        if #api.upvalueReaders == 0 then return false, "movement API unavailable: getupvalues" end
        if type(api.info) ~= "function" and type(api.getinfo) ~= "function" then
            return false, "movement API unavailable: function names"
        end
        if type(api.isfrozen) ~= "function" then return false, "movement API unavailable: table.isfrozen" end
        return true
    end
    c.filter = function(kind, predicate)
        local fields = kind == "table" and predicate.Keys or predicate.Constants
        if type(fields) ~= "table" then return nil, "unsupported discovery predicate" end
        local key = kind .. ":" .. table.concat(fields, "\0")
        local entry = cache[key]
        if entry and api.now() < entry.untilAt then return entry.values, entry.reason end
        if busy then return nil, "movement discovery in progress" end
        busy = true
        local ok, values, reason = pcall(function()
            for _, filter in ipairs(api.filters) do
                local found, matches = call(filter, kind, predicate, false)
                if found and type(matches) == "table" then return matches end
            end
            if type(api.getgc) ~= "function" then
                return nil, "movement API unavailable: filtergc or getgc"
            end
            if kind == "function" and #api.constantReaders == 0 then
                return nil, "movement API unavailable: getconstants"
            end
            local read, objects = call(api.getgc, true)
            if not read or type(objects) ~= "table" then return nil, "movement discovery failed: getgc" end
            local matches, count, sliceAt = {}, 0, api.now()
            for _, value in pairs(objects) do
                count += 1
                if count > 250000 then return nil, "movement discovery limit reached" end
                if count % 128 == 0 and api.now() - sliceAt >= 0.004 then
                    api.pause()
                    if not api.alive() then return nil, "movement discovery cancelled" end
                    sliceAt = api.now()
                end
                if type(value) == kind then
                    local constants
                    if kind == "function" then
                        for _, reader in ipairs(api.constantReaders) do
                            local got, result = call(reader, value)
                            if got and type(result) == "table" then constants = result break end
                        end
                    end
                    local match = kind == "table" or constants ~= nil
                    if match then
                        for _, field in ipairs(fields) do
                            local present = false
                            if kind == "table" then present = rawget(value, field) ~= nil
                            else
                                for _, constant in pairs(constants) do
                                    if constant == field then present = true break end
                                end
                            end
                            if not present then match = false break end
                        end
                    end
                    if match then
                        matches[#matches + 1] = value
                        if #matches > 64 then return nil, "movement discovery ambiguous" end
                    end
                end
            end
            return matches
        end)
        busy = false
        if not ok then values, reason = nil, "movement discovery failed" end
        cache[key] = {values = values, reason = reason, untilAt = api.now() + 2}
        return values, reason
    end
    return c
end
    local env = getgenv()
    local function functions(...)
        local result = {}
        local args = table.pack(...)
        for index = 1, args.n do
            local value = args[index]
            if type(value) == "function" and not table.find(result, value) then result[#result + 1] = value end
        end
        return result
    end
    RuntimeStatus.MovementCompat = createCompatibility({
        filters = functions(filtergc, env.filtergc, env.filter_gc),
        getgc = getgc or env.getgc,
        upvalueReaders = functions(getupvalues, env.getupvalues, debug and debug.getupvalues),
        constantReaders = functions(getconstants, env.getconstants, debug and debug.getconstants),
        info = debug and debug.info, getinfo = debug and debug.getinfo,
        isfrozen = table.isfrozen, now = os.clock,
        pause = function() task.wait() end, alive = sessionAlive,
    })
end
-- [[ END MOVEMENT EXECUTOR COMPATIBILITY ]] --

RuntimeStatus.findMovementDispatcher = function(root, humanoid)
    local compat = RuntimeStatus.MovementCompat
    local function unavailable(reason)
        RuntimeStatus.movementCompatibility = reason
        return nil, reason
    end
    if not (root and humanoid and humanoid.Health > 0) then return unavailable("waiting for live character") end
    local ready, reason = compat.ready()
    if not ready then return unavailable(reason) end
    local handlers, searchReason = compat.filter("function", {
        Constants = { "Relocate action requires twelve CFrame components" },
    })
    if type(handlers) ~= "table" then return unavailable(searchReason) end
    for _, handler in ipairs(handlers) do
        local ups, upvalueReason = compat.upvalues(handler)
        if not ups and upvalueReason then reason = upvalueReason end
        if type(ups) == "table" then
            local b, tokens = {}, 0
            for _, value in pairs(ups) do
                if type(value) == "function" then
                    local name = compat.name(value)
                    if name then
                        if name == "ResetMovementState" then b.reset = value
                        elseif name == "MakeSample" then b.sample = value
                        elseif name == "AdoptTeleportBaseline" then b.adopt = value
                        elseif name == "BeginImpulse" then b.beginImpulse = value end
                    end
                elseif type(value) == "table" then
                    if rawget(value, "RootPart") == root and rawget(value, "Humanoid") == humanoid
                        and rawget(value, "Character") == LocalPlayer.Character then b.state = value
                    elseif next(value) == nil and compat.frozen(value) then
                        b.token, tokens = value, tokens + 1
                    end
                end
            end
            -- Read the capability from the very dispatcher that passes it to
            -- BeginImpulse. Do not guess a constructor upvalue or mix old rigs.
            if b.state and b.reset and b.sample and b.adopt and b.beginImpulse and tokens == 1 then
                b.capabilityPath = "live-movement-dispatcher"
                RuntimeStatus.movementCompatibility = "ready"
                return b
            end
        end
    end
    return unavailable(reason or "waiting for live movement dispatcher")
end

local function findIntegrityBridge()
    local root, humanoid = getCharParts()
    return RuntimeStatus.findMovementDispatcher(root, humanoid)
end

local function registerIntegrityTravel(root, direction, speed, distance, requestedImpulse, forceRenew)
    if not (root and typeof(direction) == "Vector3" and direction.Magnitude > 0) then return false end
    speed = tonumber(speed)
    if not speed or speed ~= speed or speed <= 0 or speed == math.huge then return false end
    if integrityRejected then return false end
    if not integrityBridge and not setIntegrityGuard then return false end
    if not integrityBridge and not setIntegrityGuard(true) then return false end
    local bridge = integrityBridge
    local state = bridge and bridge.state
    local humanoid = state and rawget(state, "Humanoid")
    if not (state and humanoid and bridge.beginImpulse and bridge.token) then return false end
    if not LocalPlayer.Character
        or humanoid ~= LocalPlayer.Character:FindFirstChildOfClass("Humanoid") then
        return false, false, "controller changed"
    end
    if rawget(state, "RootPart") ~= root or rawget(state, "Humanoid") ~= humanoid
        or rawget(state, "Character") ~= root.Parent then
        return false, false, "integrity rig mismatch"
    end
    local mass = root.AssemblyMass
    if mass ~= mass or mass <= 0 or mass == math.huge then return false end
    local hasRequestedImpulse = typeof(requestedImpulse) == "Vector3"
    if hasRequestedImpulse and (requestedImpulse.X ~= requestedImpulse.X
        or requestedImpulse.Y ~= requestedImpulse.Y or requestedImpulse.Z ~= requestedImpulse.Z
        or math.abs(requestedImpulse.X) == math.huge
        or math.abs(requestedImpulse.Y) == math.huge
        or math.abs(requestedImpulse.Z) == math.huge) then
        return false, false, "invalid impulse"
    end

    -- A correction is not travel coverage. The old implementation returned true
    -- here, so moveTo kept writing CFrames while the controller was trying to
    -- recover; that is the exact Observing/Correcting -> death gap from the stress
    -- log. Pause the mover until the native controller finishes instead.
    if rawget(state, "CorrectionContext") ~= nil then
        return false, false, "correcting"
    end

    -- Impact.BeginImpulse intentionally supports renewing an existing context
    -- (it carries PreMovementSafeSample forward). Reuse it only while it has both
    -- time AND radial-distance budget for this remaining segment. Merely waiting
    -- four seconds was unsafe: short contexts can expire sooner, while a new route
    -- can exceed an older context's radius even before its timer expires.
    local context = rawget(state, "ImpulseContext")
    if not forceRenew and type(context) == "table" then
        local expiresAt = tonumber(rawget(context, "ExpiresAt"))
        local origin = rawget(context, "OriginPosition")
        local maxDistance = tonumber(rawget(context, "MaxHorizontalDistance"))
        local maxSpeed = tonumber(rawget(context, "MaxHorizontalSpeed"))
        -- Integrity timestamps use os.clock(). LastObservedSample can be an old
        -- frame after a low-FPS stall, so it must never extend an expired context.
        local timeLeft = expiresAt and (expiresAt - os.clock()) or 0
        local used = typeof(origin) == "Vector3"
            and ((root.Position - origin) * Vector3.new(1, 0, 1)).Magnitude or math.huge
        local needed = math.max(0, tonumber(distance) or 0)
        -- CFrame steps must fit the speed envelope too. A still-live context
        -- from a slower leg is not coverage for a faster slider/calibration value.
        local prospectiveFits = maxSpeed ~= nil and maxSpeed < math.huge
            and speed + 5 <= maxSpeed
        if hasRequestedImpulse then
            local velocity = root.AssemblyLinearVelocity
            local prospective = velocity + requestedImpulse / mass
            local horizontal = Vector3.new(prospective.X, 0, prospective.Z).Magnitude
            prospectiveFits = horizontal == horizontal and horizontal < math.huge
                and maxSpeed ~= nil and maxSpeed < math.huge
                and horizontal + 5 <= maxSpeed
        end
        if timeLeft > 0.35 and maxDistance and used + needed + 24 < maxDistance
            and prospectiveFits then
            return true, true, nil
        end
    end

    -- Debounce only same-frame callers. This does not replace the real context
    -- checks above and therefore cannot create an uncovered interval.
    if os.clock() - integrityLastBeginAt < 0.08 then
        return false, false, "renewing"
    end

    -- Impact clamps the requested duration to five seconds and adds its native
    -- recovery tail. The live budget checks above decide when renewal is needed.
    local duration = math.clamp((math.max(0, tonumber(distance) or 0) / speed) + 0.75, 0.05, 5)
    -- Physics Velocity passes the exact impulse it will apply so the registered
    -- envelope and the physical velocity change describe the same operation.
    -- Legacy CFrame callers retain the original speed-sized theoretical impulse.
    local impulse = hasRequestedImpulse
        and requestedImpulse or direction.Unit * speed * mass
    local ok, receipt = pcall(
        bridge.beginImpulse,
        bridge.token,
        state,
        humanoid.WalkSpeed,
        duration,
        impulse,
        root
    )
    local registered = ok and receipt ~= nil
    if registered then
        integrityLastBeginAt = os.clock()
    else
        -- A bad capability used to be retried on every Auto-Steal pass. Besides
        -- preventing the first CFrame write, that flooded the integrity monitor
        -- until the client froze or died. Quarantine it for this character.
        integrityRejected = true
        integrityBridge = nil
        integrityState = nil
        RuntimeStatus.defaultMoveFallback = true
        getgenv().__CHSAE_IntegrityState = nil
        warn("[CloverHub-SAE][integrity] registration rejected; quarantined until respawn/reload")
    end
    if registered then return registered, false, nil end
    return registered, false, "rejected"
end

setIntegrityGuard = function(enabled)
    local development = RuntimeStatus.DevChickenTween
    if development and development.lease then
        if enabled then return development.alive(development.lease) end
        development.restore("movement guard disabled")
    end
    local env = getgenv()
    if not enabled then
        local conn = env.__CHSAE_IntegrityConn
        if conn then pcall(function() conn:Disconnect() end) end
        env.__CHSAE_IntegrityConn, env.__CHSAE_IntegrityState = nil, nil
        integrityState, integrityBridge = nil, nil
        return true
    end
    if integrityRejected then
        RuntimeStatus.defaultMoveFallback = true
        return false
    end
    -- Disconnect a guard connection left by an older loaded build. The new
    -- registered-movement bridge has no per-frame integrity callback.
    local oldConn = env.__CHSAE_IntegrityConn
    if oldConn then pcall(function() oldConn:Disconnect() end) end
    env.__CHSAE_IntegrityConn = nil
    if integrityBridge and integrityBridge.state then
        local root, humanoid = getCharParts()
        local state = integrityBridge.state
        if root and humanoid and rawget(state, "RootPart") == root
            and rawget(state, "Humanoid") == humanoid
            and rawget(state, "Character") == LocalPlayer.Character then
            RuntimeStatus.defaultMoveFallback = false
            return true
        end
        integrityBridge, integrityState = nil, nil
    end
    integrityBridge = findIntegrityBridge()
    integrityState = integrityBridge and integrityBridge.state or nil
    RuntimeStatus.defaultMoveFallback = integrityBridge == nil
    env.__CHSAE_IntegrityState = integrityState
    local report = integrityBridge
        and ("ready via " .. tostring(integrityBridge.capabilityPath or "legacy-dispatcher"))
        or "unavailable"
    if report ~= integrityReport then
        integrityReport = report
        if integrityBridge then
            print("[CloverHub-SAE][integrity] " .. report)
        else
            warn("[CloverHub-SAE][integrity] unavailable — no live guard was invoked")
        end
    end
    return integrityBridge ~= nil
end

getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = LocalPlayer.CharacterAdded:Connect(function()
    -- Invalidate the dead character's bridge before yielding. Previously the
    -- Auto-Steal worker could run during this 0.5-second window, see the stale
    -- bridge as ready, register the dead root, then CFrame the new root without
    -- coverage. That produces the immediate respawn/death loop seen in stress
    -- logs. Default movement owns this short rebind window instead.
    integrityRejected = true
    integrityLastBeginAt = 0
    setIntegrityGuard(false)
    RuntimeStatus.defaultMoveFallback = true
    task.wait(0.5)
    if sessionAlive() then
        integrityRejected = false
        local pending = getgenv().__CHSAE_CarryRequest
        if type(pending) == "table" and pending.inFlight ~= true then
            getgenv().__CHSAE_CarryRequest = nil -- completed cooldown belongs to the dead character
        end
        setIntegrityGuard(true)
    end
end)

-- Capability discovery can take a long time after a game update or hot reload.
-- Never block construction of ESP, treadmill, and the remaining UI behind it.
-- Normal movement is the safe fallback until the background probe succeeds.
RuntimeStatus.defaultMoveFallback = true
task.spawn(function()
    if sessionAlive() then setIntegrityGuard(true) end
end)

-- Track the server-authored trap instances by the same CollectionService tag
-- used by the game's TrapGameplayHighlightController. Enemy hitboxes are made
-- non-touching in the local physics simulation and nearby character touch parts
-- are suppressed before contact while carrying. Movement stays on its normal
-- direct route because contact suppression already handles the trap itself.
-- We never clear IsTrapped or fight the server anchor after a trap has fired.
local TrapAvoid = { tag = "PlacedTrap", hitboxes = {}, characterTouch = {} }
pcall(function()
    local Constants = require(ReplicatedStorage.Shared.Globals.Constants)
    TrapAvoid.tag = Constants.TAGS_MAP.Traps.PLACED_TRAP or TrapAvoid.tag
end)

local function isEnemyArmedTrap(trap)
    return trap and trap.Parent
        and trap:GetAttribute("Owner") ~= LocalPlayer.Name
        and trap:GetAttribute("TrapActive") ~= true
end

local function setTrapTouch(record, blocked)
    local hitbox = record and record.hitbox
    if not (hitbox and hitbox.Parent) then return end
    if blocked then
        if not record.suppressed then
            record.originalCanTouch = hitbox.CanTouch
            record.suppressed = true
        end
        -- Reapply every refresh in case replication rewrites the property.
        hitbox.CanTouch = false
    elseif record.suppressed then
        hitbox.CanTouch = record.originalCanTouch ~= false
        record.suppressed = false
    end
end

local function setCharacterTouch(blocked)
    local character = LocalPlayer.Character
    if blocked and character then
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and TrapAvoid.characterTouch[part] == nil then
                TrapAvoid.characterTouch[part] = part.CanTouch
                part.CanTouch = false
            end
        end
    elseif not blocked then
        for part, original in pairs(TrapAvoid.characterTouch) do
            if part and part.Parent then part.CanTouch = original end
            TrapAvoid.characterTouch[part] = nil
        end
    end
end

local function trackTrap(instance)
    if not instance then return end
    local hitbox = instance:FindFirstChild("Hitbox")
    if not (hitbox and hitbox:IsA("BasePart")) and instance:IsA("BasePart") then
        hitbox = instance
    end
    if hitbox and hitbox:IsA("BasePart") then
        local record = { hitbox = hitbox, originalCanTouch = hitbox.CanTouch, suppressed = false }
        TrapAvoid.hitboxes[instance] = record
        setTrapTouch(record, Settings.PreventTraps and isEnemyArmedTrap(instance))
    end
end
for _, instance in ipairs(CollectionService:GetTagged(TrapAvoid.tag)) do trackTrap(instance) end
getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
    = CollectionService:GetInstanceAddedSignal(TrapAvoid.tag):Connect(trackTrap)
getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
    = CollectionService:GetInstanceRemovedSignal(TrapAvoid.tag):Connect(function(instance)
        setTrapTouch(TrapAvoid.hitboxes[instance], false)
        TrapAvoid.hitboxes[instance] = nil
    end)

refreshTrapProtection = function()
    for trap, record in pairs(TrapAvoid.hitboxes) do
        if not (trap and trap.Parent and record.hitbox and record.hitbox.Parent) then
            setTrapTouch(record, false)
            TrapAvoid.hitboxes[trap] = nil
        else
            setTrapTouch(record, Settings.PreventTraps and isEnemyArmedTrap(trap))
        end
    end
    if not Settings.PreventTraps then setCharacterTouch(false) end
end

getgenv().__CHSAE_TrapRestore = function()
    for _, record in pairs(TrapAvoid.hitboxes) do setTrapTouch(record, false) end
    setCharacterTouch(false)
end
refreshTrapProtection()

-- A local hitbox-only change is not enough on every network-ownership handoff.
-- While an egg is carried, suppress the character's touch transmitters before it
-- enters a 24-stud warning ring. The setting is restored immediately outside it,
-- preserving treadmills, pen zones, and other normal touch interactions.
getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
    = RunService.PreSimulation:Connect(function()
        local danger = false
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if Settings.PreventTraps and carrying and root then
            for trap, record in pairs(TrapAvoid.hitboxes) do
                local hitbox = record.hitbox
                if isEnemyArmedTrap(trap) and hitbox and hitbox.Parent then
                    setTrapTouch(record, true)
                    local flat = ((root.Position - hitbox.Position) * Vector3.new(1, 0, 1)).Magnitude
                    local radius = math.max(hitbox.Size.X, hitbox.Size.Z) * 0.5 + 24
                    if flat <= radius and math.abs(root.Position.Y - hitbox.Position.Y) <= 18 then
                        danger = true
                        break
                    end
                end
            end
        end
        setCharacterTouch(danger)
    end)

RuntimeStatus.chickenReactionActive = function()
    local tp = RuntimeStatus.ChickenTP
    local active = tp and tp.active
    return active ~= nil and (active.phase == "contact" or active.phase == "landing"
        or (active.development == true and active.phase == "travel"))
end

-- Forest is client-simulated and predicts its own ForestStrike. Higher guards
-- are server-simulated and publish RagdollEndTime before their client ragdoll
-- request. Arm from either early signal, suppress ApplyClientRagdoll, and cancel
-- only velocity writes made during the exact hit window. Never hold CFrame.
do
if not sessionAlive() then return end
local GuardProtection = {
    armedUntil = 0,
    character = nil,
    ragdollSignalUntil = 0,
    ragdollSignalCharacter = nil,
    recoveryUntil = 0,
    attackTarget = nil,
    ragdollTargets = {},
    velocityCancelGeneration = 0,
    velocityCancelUntil = 0,
    velocityCancelCharacter = nil,
    baselineLinear = Vector3.zero,
    baselineAngular = Vector3.zero,
    jointReleaseGeneration = 0,
    jointReleaseQueued = false,
    velocityConnections = {},
}
local GuardDiagnostics = {
    ForestArms = 0,
    RagdollSignalArms = 0,
    RagdollsSeen = 0,
    Suppressed = 0,
    Passed = 0,
    LastReason = "idle",
    LastImpulseMagnitude = 0,
    LastSignalRemaining = 0,
    RagdollTarget = "unavailable",
    VelocityCancels = 0,
    MaxCancelledVelocity = 0,
    PhysicsSeen = 0,
    StateRecoveries = 0,
    LastRecoveredState = "none",
    JointReleases = 0,
}
getgenv().__CHSAE_GuardDiagnostics = GuardDiagnostics
pcall(function()
    GuardProtection.ragdollJoints = require(ReplicatedStorage.Shared.Modules.RagdollJoints)
end)

RuntimeStatus.guardProtectionActive = function()
    return false
end


local function clearGuardArm()
    GuardProtection.armedUntil = 0
    GuardProtection.character = nil
    GuardProtection.ragdollSignalUntil = 0
    GuardProtection.ragdollSignalCharacter = nil
end

local function stopVelocityCancellation()
    GuardProtection.velocityCancelGeneration += 1
    GuardProtection.recoveryUntil = 0
    GuardProtection.velocityCancelUntil = 0
    GuardProtection.velocityCancelCharacter = nil
    GuardProtection.jointReleaseQueued = false
    for _, connection in ipairs(GuardProtection.velocityConnections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(GuardProtection.velocityConnections)
end

GuardProtection.stopActive = function()
    clearGuardArm()
    stopVelocityCancellation()
end
getgenv().__CHSAE_GuardStopActive = GuardProtection.stopActive

local function chickenLandingProtected(character)
    local tp = RuntimeStatus.ChickenTP
    return tp ~= nil and tp.isLandingProtected ~= nil and tp.isLandingProtected(character)
end

local function startVelocityCancellation(character, duration, chickenLanding)
    local function enabled()
        if chickenLanding then return chickenLandingProtected(character) end
        return Settings.GuardProtection
    end
    if not (sessionAlive() and character and enabled()) then return end
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not (root and root:IsA("BasePart") and humanoid) then return end

    duration = math.clamp(tonumber(duration) or 0.85, 0.25, 3.5)
    stopVelocityCancellation()
    GuardProtection.velocityCancelGeneration += 1
    local generation = GuardProtection.velocityCancelGeneration
    GuardProtection.jointReleaseQueued = false
    GuardProtection.recoveryUntil = os.clock() + duration
    -- The state guard follows the server's full ragdoll window. Impulse rejection
    -- is intentionally much shorter so normal Humanoid movement is never pinned.
    GuardProtection.velocityCancelUntil = os.clock() + math.min(duration, 0.22)
    GuardProtection.velocityCancelCharacter = character
    GuardProtection.baselineLinear = root.AssemblyLinearVelocity
    GuardProtection.baselineAngular = root.AssemblyAngularVelocity

    local changing = false
    local function stabilize()
        if changing or generation ~= GuardProtection.velocityCancelGeneration then return end
        if not (sessionAlive()
            and enabled()
            and os.clock() <= GuardProtection.recoveryUntil
            and LocalPlayer.Character == character and root.Parent == character) then
            return
        end

        changing = true
        pcall(function()
            humanoid.PlatformStand = false
            -- Higher-tier hits bind server-replicated ragdoll constraints and
            -- disable Motor6Ds before RagdollEndTime reaches the client. Release
            -- that rig even when our RigDriver hook already prevented Physics.
            if GuardProtection.jointReleaseGeneration ~= generation then
                local bound = false
                for _, descendant in ipairs(character:GetDescendants()) do
                    if descendant:GetAttribute("RagdollConstraint") ~= nil
                        or (descendant:IsA("Motor6D") and not descendant.Enabled) then
                        bound = true
                        break
                    end
                end
                if bound and type(GuardProtection.ragdollJoints) == "table"
                    and type(GuardProtection.ragdollJoints.Release) == "function" then
                    local released = pcall(GuardProtection.ragdollJoints.Release, character)
                    if released then
                        GuardProtection.jointReleaseGeneration = generation
                        GuardDiagnostics.JointReleases += 1
                    end
                end
            end
            local state = humanoid:GetState()
            if state == Enum.HumanoidStateType.Physics
                or state == Enum.HumanoidStateType.Ragdoll
                or state == Enum.HumanoidStateType.FallingDown
                or state == Enum.HumanoidStateType.PlatformStanding then
                GuardDiagnostics.StateRecoveries += 1
                GuardDiagnostics.LastRecoveredState = state.Name
                pcall(humanoid.ChangeState, humanoid, Enum.HumanoidStateType.Running)
            end

            if os.clock() <= GuardProtection.velocityCancelUntil then
                local linear = root.AssemblyLinearVelocity
                local angular = root.AssemblyAngularVelocity
                local linearDelta = (linear - GuardProtection.baselineLinear).Magnitude
                local angularDelta = (angular - GuardProtection.baselineAngular).Magnitude
                if linearDelta > 0.05 or angularDelta > 0.05 then
                    GuardDiagnostics.VelocityCancels += 1
                    GuardDiagnostics.MaxCancelledVelocity = math.max(
                        GuardDiagnostics.MaxCancelledVelocity,
                        linear.Magnitude
                    )
                    root.AssemblyLinearVelocity = GuardProtection.baselineLinear
                    root.AssemblyAngularVelocity = GuardProtection.baselineAngular
                end
            end
        end)
        changing = false
    end

    GuardProtection.velocityConnections[#GuardProtection.velocityConnections + 1] =
        humanoid.StateChanged:Connect(function(_, state)
            if state == Enum.HumanoidStateType.Physics
                or state == Enum.HumanoidStateType.Ragdoll
                or state == Enum.HumanoidStateType.FallingDown
                or state == Enum.HumanoidStateType.PlatformStanding then
                GuardDiagnostics.PhysicsSeen += 1
                stabilize()
            end
        end)
    GuardProtection.velocityConnections[#GuardProtection.velocityConnections + 1] =
        character.DescendantAdded:Connect(function(descendant)
            if descendant:GetAttribute("RagdollConstraint") == nil
                or GuardProtection.jointReleaseQueued then return end
            GuardProtection.jointReleaseQueued = true
            task.defer(function()
                if generation ~= GuardProtection.velocityCancelGeneration then return end
                GuardProtection.jointReleaseQueued = false
                -- Allow another release if this replication batch arrived after
                -- an earlier one was already cleared in the same hit window.
                GuardProtection.jointReleaseGeneration = 0
                stabilize()
            end)
        end)
    GuardProtection.velocityConnections[#GuardProtection.velocityConnections + 1] =
        root:GetPropertyChangedSignal("AssemblyLinearVelocity"):Connect(stabilize)
    GuardProtection.velocityConnections[#GuardProtection.velocityConnections + 1] =
        RunService.PreSimulation:Connect(stabilize)
    GuardProtection.velocityConnections[#GuardProtection.velocityConnections + 1] =
        RunService.PostSimulation:Connect(stabilize)
    stabilize()
    task.delay(duration + 0.05, function()
        if generation == GuardProtection.velocityCancelGeneration then
            stopVelocityCancellation()
        end
    end)
end

-- A landing-only recovery: the initial chicken contact and the server's
-- RagdollEndTime/pickup gate remain intact. Never rearm every frame.
RuntimeStatus.recoverChickenLanding = function(t)
    if not t or t.guardRecoveryStarted or not chickenLandingProtected(t.character) then return end
    t.guardRecoveryStarted = true
    startVelocityCancellation(t.character, 3.5, true)
end

local function armRagdollSignal()
    if not (sessionAlive() and Settings.GuardProtection)
        or RuntimeStatus.chickenReactionActive() then return end
    local serverNow = workspace:GetServerTimeNow()
    local ragdollEnd = tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0
    local now = os.clock()
    if ragdollEnd <= serverNow then return end
    local remaining = ragdollEnd - serverNow
    local recoveryDuration = math.clamp(remaining + 0.35, 0.45, 3.5)
    GuardProtection.ragdollSignalCharacter = LocalPlayer.Character
    GuardProtection.ragdollSignalUntil = now + recoveryDuration
    startVelocityCancellation(LocalPlayer.Character, recoveryDuration)
    GuardDiagnostics.RagdollSignalArms += 1
    GuardDiagnostics.LastReason = "ragdoll-signal-armed"
    GuardDiagnostics.LastSignalRemaining = remaining
end

do
    local conn = LocalPlayer:GetAttributeChangedSignal("RagdollEndTime"):Connect(armRagdollSignal)
    local runtimeConns = getgenv().__CHSAE_RuntimeConns
    if type(runtimeConns) == "table" then runtimeConns[#runtimeConns + 1] = conn end
    if (tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0) > workspace:GetServerTimeNow() then
        armRagdollSignal()
    end
end


-- [[ LIVE FOREST ATTACK BINDING ]] --
-- Hooking a GC-matched Attack function can mutate a shared prototype on this
-- executor. Its live sibling then calls a trampoline absent from its environment.
-- Bind the actual component field instead, leaving native closures untouched.
GuardProtection.attackBindings = {}
GuardProtection.attackDisplaced = setmetatable({}, { __mode = "k" })
GuardProtection.attackBindingStopped = false
GuardProtection.liveForestGuard = function()
    local objects = workspace:FindFirstChild("__OBJECTS")
    local areas = objects and objects:FindFirstChild("Areas")
    local guardAreas = areas and areas:FindFirstChild("GuardAreas")
    local forest = guardAreas and guardAreas:FindFirstChild("Forest")
    local guard = forest and forest:FindFirstChild("Guard")
    return guard and guard:IsA("Model") and guard or nil
end
GuardProtection.isLiveAttackComponent = function(component, guard)
    if type(component) ~= "table" or not guard
        or rawget(component, "_areaId") ~= "Forest"
        or rawget(component, "_guardModel") ~= guard then return false end
    local root = rawget(component, "_root")
    return typeof(root) == "Instance" and root:IsA("BasePart")
        and root:IsDescendantOf(guard) and guard:IsDescendantOf(workspace)
end
GuardProtection.restoreAttackBindings = function()
    GuardProtection.attackBindingStopped = true
    if GuardProtection.attackBindingConnection then
        GuardProtection.attackBindingConnection:Disconnect()
        GuardProtection.attackBindingConnection = nil
    end
    for component, record in pairs(GuardProtection.attackBindings) do
        if rawget(component, "_attackHandler") == record.wrapper then
            rawset(component, "_attackHandler", record.original)
        end
        GuardProtection.attackBindings[component] = nil
    end
    GuardDiagnostics.ForestAttackBinding = "stopped"
end
GuardProtection.reconcileAttackBindings = function()
    if GuardProtection.attackBindingStopped or not sessionAlive() then return false end
    local guard = GuardProtection.liveForestGuard()
    local active = false
    for component, record in pairs(GuardProtection.attackBindings) do
        local current = rawget(component, "_attackHandler")
        if GuardProtection.isLiveAttackComponent(component, guard)
            and current == record.wrapper then
            active = true
        else
            if current == record.wrapper then
                rawset(component, "_attackHandler", record.original)
            else
                -- Do not fight another owner that deliberately replaced us.
                GuardProtection.attackDisplaced[component] = true
            end
            GuardProtection.attackBindings[component] = nil
        end
    end
    if active then
        GuardDiagnostics.ForestAttackBinding = "live component"
        return true
    end
    GuardDiagnostics.ForestAttackBinding = "waiting for live Forest component"
    if not guard then return false end
    local components, reason = RuntimeStatus.MovementCompat.filter("table", {
        Keys = { "_attackHandler", "_areaId", "_guardModel", "_root" },
    })
    if not components and reason then GuardDiagnostics.ForestAttackBinding = reason end
    if type(components) ~= "table" or not sessionAlive()
        or GuardProtection.attackBindingStopped then return false end
    for _, component in ipairs(components) do
        if GuardProtection.isLiveAttackComponent(component, guard)
            and not GuardProtection.attackDisplaced[component] then
            local original = rawget(component, "_attackHandler")
            if type(original) == "function" then
                local record = { original = original }
                record.wrapper = function(hit, ...)
                    if not GuardProtection.attackBindingStopped and sessionAlive()
                        and Settings.GuardProtection and not RuntimeStatus.chickenReactionActive()
                        and type(hit) == "table"
                        and hit.Player == LocalPlayer and hit.EggUid ~= nil
                        and rawget(component, "_attackHandler") == record.wrapper
                        and GuardProtection.isLiveAttackComponent(
                            component, GuardProtection.liveForestGuard()) then
                        -- Protection instrumentation must never prevent the
                        -- original native attack from receiving its arguments.
                        pcall(function()
                            GuardProtection.character = LocalPlayer.Character
                            GuardProtection.armedUntil = os.clock() + 2
                            startVelocityCancellation(LocalPlayer.Character, 2.35)
                            GuardDiagnostics.ForestArms += 1
                            GuardDiagnostics.LastReason = "forest-armed"
                        end)
                    end
                    local results = table.pack(original(hit, ...))
                    if RuntimeStatus.ChickenTP then
                        pcall(RuntimeStatus.ChickenTP.noteHit, hit)
                    end
                    return table.unpack(results, 1, results.n)
                end
                if sessionAlive() and not GuardProtection.attackBindingStopped
                    and GuardProtection.liveForestGuard() == guard
                    and rawget(component, "_attackHandler") == original then
                    rawset(component, "_attackHandler", record.wrapper)
                    GuardProtection.attackBindings[component] = record
                    GuardDiagnostics.ForestAttackBinding = "live component"
                    return true
                end
            end
        end
    end
    return false
end
-- [[ END LIVE FOREST ATTACK BINDING ]] --

local function restoreGuardHooks()
    GuardProtection.stopActive()
    GuardProtection.restoreAttackBindings()
    if type(restorefunction) == "function" then
        if type(GuardProtection.attackTarget) == "function" then
            pcall(restorefunction, GuardProtection.attackTarget)
        end
        for _, ragdollTarget in ipairs(GuardProtection.ragdollTargets) do
            if type(ragdollTarget) == "function" then
                pcall(restorefunction, ragdollTarget)
            end
        end
    end
    GuardProtection.attackTarget = nil
    table.clear(GuardProtection.ragdollTargets)
    if getgenv().__CHSAE_GuardDiagnostics == GuardDiagnostics then
        getgenv().__CHSAE_GuardDiagnostics = nil
    end
    if getgenv().__CHSAE_GuardStopActive == GuardProtection.stopActive then
        getgenv().__CHSAE_GuardStopActive = nil
    end
end

-- A superseded initializer must not restore or overwrite the current session's
-- native callbacks when two autoexec paths start before either UI is ready.
if not sessionAlive() then return end
if getgenv().__CHSAE_GuardRestore then pcall(getgenv().__CHSAE_GuardRestore) end
getgenv().__CHSAE_GuardRestore = restoreGuardHooks

GuardProtection.reconcileAttackBindings()
GuardProtection.attackBindingNextScan = os.clock() + 1
GuardProtection.attackBindingConnection = RunService.Heartbeat:Connect(function()
    if not sessionAlive() then
        GuardProtection.restoreAttackBindings()
        return
    end
    if os.clock() < GuardProtection.attackBindingNextScan then return end
    GuardProtection.attackBindingNextScan = os.clock() + 1
    GuardProtection.reconcileAttackBindings()
end)
do
    local runtimeConns = getgenv().__CHSAE_RuntimeConns
    if type(runtimeConns) == "table" then
        runtimeConns[#runtimeConns + 1] = GuardProtection.attackBindingConnection
    end
end

local okRagdoll, ragdollTargets = pcall(function()
    if type(filtergc) ~= "function" then return nil end
    return filtergc("function", {
        Constants = { "Ragdoll duration must be non-negative" },
    }, false)
end)

if okRagdoll and type(ragdollTargets) == "function" then
    ragdollTargets = { ragdollTargets }
end
if okRagdoll and type(ragdollTargets) == "table" and type(hookfunction) == "function" then
    local seenRagdollTargets = {}
    for _, matchedRagdollTarget in ipairs(ragdollTargets) do
        local ragdollTarget = matchedRagdollTarget
        if type(ragdollTarget) == "function" and not seenRagdollTargets[ragdollTarget] then
            seenRagdollTargets[ragdollTarget] = true
            local originalRagdoll
            local hooked = pcall(function()
                originalRagdoll = hookfunction(ragdollTarget, function(token, duration, impulse)
            local now = os.clock()
            -- RigDriver receives an action token, not the Character. This closure
            -- is the local player's dispatcher and resolves Character/Humanoid/HRP
            -- from its own upvalue immediately after our hook.
            local character = LocalPlayer.Character
            local isLocalCharacter = character ~= nil
            local forestContext = isLocalCharacter and character == GuardProtection.character
                and now <= GuardProtection.armedUntil
            local signalContext = isLocalCharacter
                and character == GuardProtection.ragdollSignalCharacter
                and now <= GuardProtection.ragdollSignalUntil
            -- Read the live attribute too so a same-frame remote cannot outrun
            -- the AttributeChanged callback in an executor scheduler. This is an
            -- exact native ragdoll signal, so it remains valid after the egg drops.
            if isLocalCharacter and not signalContext then
                signalContext = (tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0)
                    > workspace:GetServerTimeNow()
            end
            local landingContext = sessionAlive() and isLocalCharacter and chickenLandingProtected(character)
            local suppress = landingContext or (sessionAlive() and Settings.GuardProtection and isLocalCharacter
                and not RuntimeStatus.chickenReactionActive()
                and RuntimeStatus.adminMonsterActive ~= true
                and (forestContext or signalContext))

            if isLocalCharacter then
                GuardDiagnostics.RagdollsSeen += 1
                GuardDiagnostics.LastImpulseMagnitude = typeof(impulse) == "Vector3"
                    and impulse.Magnitude or 0
            end
            if suppress then
                local recoveryDuration = math.clamp(tonumber(duration) or 0.85, 0.45, 3.5)
                if signalContext then
                    local signalRemaining = GuardProtection.ragdollSignalUntil - now
                    recoveryDuration = math.max(recoveryDuration, signalRemaining)
                end
                if landingContext then
                    RuntimeStatus.recoverChickenLanding(RuntimeStatus.ChickenTP.active)
                else
                    startVelocityCancellation(character, recoveryDuration)
                end
                if forestContext then
                    GuardProtection.armedUntil = 0
                    GuardProtection.character = nil
                end
                GuardDiagnostics.Suppressed += 1
                GuardDiagnostics.LastReason = landingContext and "chicken-landing-suppressed"
                    or forestContext and "forest-suppressed"
                    or "ragdoll-signal-suppressed"
                local humanoid = character:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    humanoid.PlatformStand = false
                    if humanoid:GetState() == Enum.HumanoidStateType.Physics then
                        pcall(humanoid.ChangeState, humanoid, Enum.HumanoidStateType.Running)
                    end
                end
                -- RigDriver also begins the native action and records its token.
                -- Its end callback needs that record to finish recovery. Keep
                -- the paired native callbacks intact when protecting movement.
                -- The recovery listeners above handle the physical response.
                GuardDiagnostics.NativeRecoveryActions = (GuardDiagnostics.NativeRecoveryActions or 0) + 1
                return originalRagdoll(token, duration, impulse)
            end
            if isLocalCharacter then
                GuardDiagnostics.Passed += 1
                GuardDiagnostics.LastReason = "ragdoll-passed"
            end
                    return originalRagdoll(token, duration, impulse)
                end)
            end)
            if hooked then
                GuardProtection.ragdollTargets[#GuardProtection.ragdollTargets + 1] = ragdollTarget
            end
        end
    end
    if #GuardProtection.ragdollTargets > 0 then
        GuardDiagnostics.RagdollTarget = ("RigDriver x%d"):format(#GuardProtection.ragdollTargets)
    end
end

if #GuardProtection.ragdollTargets == 0 then
    warn("[CloverHub-SAE] Guard Protection controller hooks unavailable")
end
end

-- Safe degraded mover. It uses Roblox's ordinary Humanoid locomotion and keeps
-- the account's current game-provided WalkSpeed; it never writes WalkSpeed,
-- CFrame, velocity, Heartbeat, or CharacterIntegrity state. The same reach,
-- cancellation, trap-steering and route-waypoint contracts remain available to
-- the steal state machine when registered fast movement cannot be discovered.
RuntimeStatus.defaultMoveTo = function(pos, reachDist, keepGoing, onReached, abortFn)
    if RuntimeStatus.blockArenaDeparture(Arb.owner) then return false, "boss-arena-exit" end
    local bestDist, lastGain = math.huge, os.clock()
    local lastCommandAt, lastGoal = 0, nil

    local function finish(ok, reason)
        local root, hum = getCharParts()
        if root and hum and hum.Health > 0 then
            pcall(hum.MoveTo, hum, root.Position)
        end
        return ok, reason
    end

    while sessionAlive() and keepGoing() do
        local root, hum = getCharParts()
        if not (root and hum) then return finish(false, "character unavailable") end
        if hum.Health <= 0 then return finish(false, "dead") end
        if RuntimeStatus.guardProtectionActive(root) then
            pcall(hum.MoveTo, hum, root.Position)
            lastGain = os.clock()
            RunService.Heartbeat:Wait()
            continue
        end
        if Settings.PreventTraps and carrying and LocalPlayer.Character
            and LocalPlayer.Character:GetAttribute("IsTrapped") == true then
            return finish(false, "trapped")
        end

        if onReached and onReached() then return finish(true) end
        if abortFn and abortFn() then return finish(false, "aborted") end

        local cur = root.Position
        local d = Vector3.new(pos.X - cur.X, 0, pos.Z - cur.Z)
        local flat = d.Magnitude
        if flat <= reachDist then return finish(true) end

        if flat < bestDist - 1 then
            bestDist, lastGain = flat, os.clock()
        elseif os.clock() - lastGain > 3 then
            return finish(false, "blocked")
        end

        keepKillPartIgnore()
        local goal = pos

        local now = os.clock()
        local goalChanged = lastGoal == nil
            or ((goal - lastGoal) * Vector3.new(1, 0, 1)).Magnitude > 3
        if goalChanged or now - lastCommandAt >= 0.25 then
            hum:MoveTo(goal)
            lastGoal, lastCommandAt = goal, now
        end
        RunService.Heartbeat:Wait()
    end

    return finish(false, "cancelled")
end

-- Adaptive speed profile. Guard Integrity remains the authority for every step;
-- calibration only changes the requested registered speed between transactions.
do
    local calibration = {
        current = nil,
        base = nil,
        stable = nil,
        previousStable = nil,
        successes = 0,
        failures = 0,
        lastResultAt = 0,
        lastReason = "idle",
        fps = 60,
        pingMs = 80,
        telemetrySamples = 0,
        environment = "Warming up",
        probeStep = 15,
        requiredSuccesses = 4,
    }
    RuntimeStatus.speedCalibration = calibration

    local function refreshCalibrationEnvironment()
        local measuredFps = tonumber(calibration.fps) or 60
        local measuredPing = tonumber(calibration.pingMs) or 80
        if measuredFps < 20 or measuredPing > 350 then
            calibration.environment = "Paused"
            calibration.probeStep = 0
            calibration.requiredSuccesses = 5
        elseif measuredFps < 30 or measuredPing > 250 then
            calibration.environment = "Cautious"
            calibration.probeStep = 10
            calibration.requiredSuccesses = 5
        elseif measuredFps < 45 or measuredPing > 160 then
            calibration.environment = "Balanced"
            calibration.probeStep = 15
            calibration.requiredSuccesses = 4
        else
            calibration.environment = "Fast"
            calibration.probeStep = 25
            calibration.requiredSuccesses = 3
        end
    end

    function RuntimeStatus.updateCalibrationTelemetry(measuredFps, measuredPing)
        measuredFps, measuredPing = tonumber(measuredFps), tonumber(measuredPing)
        local firstSample = calibration.telemetrySamples == 0
        if measuredFps and measuredFps > 0 then
            calibration.fps = firstSample and measuredFps
                or calibration.fps * 0.75 + measuredFps * 0.25
        end
        if measuredPing and measuredPing >= 0 then
            calibration.pingMs = firstSample and measuredPing
                or calibration.pingMs * 0.75 + measuredPing * 0.25
        end
        calibration.telemetrySamples += 1

        local previousSpeed = tonumber(calibration.current)
        refreshCalibrationEnvironment()
        if Settings.AutoCalibrateSpeed and calibration.probeStep == 0 then
            calibration.successes = 0
            if calibration.current and calibration.stable
                and calibration.current > calibration.stable then
                calibration.current = calibration.stable
                calibration.lastReason = "environment hold"
            end
        end
        if previousSpeed and calibration.current ~= previousSpeed
            and type(RuntimeStatus.syncSpeedSlider) == "function" then
            pcall(RuntimeStatus.syncSpeedSlider, calibration.current)
        end
        if type(RuntimeStatus.syncCalibrationStatus) == "function" then
            pcall(RuntimeStatus.syncCalibrationStatus)
        end
    end

    function RuntimeStatus.getMovementSpeed()
        local configured = math.clamp(tonumber(Settings.StealSpeed) or 800, 100, 1000)
        if not Settings.AutoCalibrateSpeed then
            calibration.current = configured
            calibration.base = configured
            calibration.stable = configured
            calibration.previousStable = configured
            calibration.successes, calibration.failures = 0, 0
            calibration.lastReason = "manual"
            return configured
        end
        if not calibration.current or calibration.base ~= configured or calibration.current > 1000 then
            calibration.current = configured
            calibration.base = configured
            calibration.stable = configured
            calibration.previousStable = configured
            calibration.successes, calibration.failures = 0, 0
            calibration.lastReason = "baseline"
        end
        return math.clamp(calibration.current, 100, 1000)
    end

    function RuntimeStatus.recordSpeedResult(success, reason)
        if not Settings.AutoCalibrateSpeed then return end
        local now = os.clock()
        if now - calibration.lastResultAt < 0.5 then return end
        calibration.lastResultAt = now
        local resultReason = tostring(reason or (success and "verified" or "failed"))
        local floorSpeed = math.clamp(tonumber(Settings.StealSpeed) or 800, 100, 1000)
        local previousSpeed = tonumber(calibration.current) or floorSpeed
        local stableSpeed = math.clamp(tonumber(calibration.stable) or floorSpeed, floorSpeed, 1000)
        if success then
            calibration.failures = 0
            if calibration.probeStep <= 0 then
                calibration.successes = 0
                calibration.current = stableSpeed
                calibration.lastReason = "environment hold"
            else
                calibration.successes += 1
                calibration.lastReason = resultReason
                if calibration.successes >= calibration.requiredSuccesses then
                    calibration.successes = 0
                    calibration.previousStable = stableSpeed
                    calibration.stable = previousSpeed
                    local nextSpeed = math.min(1000, previousSpeed + calibration.probeStep)
                    calibration.current = nextSpeed
                    calibration.lastReason = nextSpeed > previousSpeed
                        and "testing higher" or "maximum verified"
                end
            end
        else
            calibration.successes = 0
            calibration.failures += 1
            calibration.lastReason = resultReason
            if previousSpeed > stableSpeed then
                -- A candidate failed: return immediately to the last speed that
                -- completed the required clean-steal window.
                calibration.current = stableSpeed
                calibration.lastReason = "rollback · " .. resultReason
            elseif calibration.failures >= 2 and stableSpeed > floorSpeed then
                -- Repeated failure at a previously stable speed can follow a
                -- device/network degradation. Step back one proven tier, but
                -- never below the user's configured base.
                local rollback = math.max(floorSpeed,
                    tonumber(calibration.previousStable) or (stableSpeed - 25))
                calibration.stable = rollback
                calibration.current = rollback
                calibration.failures = 0
                calibration.lastReason = "stability rollback"
            else
                calibration.current = stableSpeed
            end
        end
        local effectiveSpeed = math.clamp(tonumber(calibration.current) or floorSpeed, 100, 1000)
        if effectiveSpeed ~= previousSpeed and type(RuntimeStatus.syncSpeedSlider) == "function" then
            pcall(RuntimeStatus.syncSpeedSlider, effectiveSpeed)
        end
        if type(RuntimeStatus.syncCalibrationStatus) == "function" then
            pcall(RuntimeStatus.syncCalibrationStatus)
        end
        RuntimeStatus.wakeOverlay("speed-calibration")
    end

    function RuntimeStatus.getCalibrationLabel()
        local baseSpeed = math.clamp(tonumber(Settings.StealSpeed) or 800, 100, 1000)
        if not Settings.AutoCalibrateSpeed then
            return ("🧭 Auto Calibrate off · Base %d"):format(baseSpeed)
        end
        local effective = math.floor(RuntimeStatus.getMovementSpeed() + 0.5)
        local stable = math.floor((tonumber(calibration.stable) or baseSpeed) + 0.5)
        local phase
        if calibration.probeStep <= 0 then
            phase = "holding"
        elseif effective >= 1000 and stable >= 1000 then
            phase = "max stable"
        elseif effective > stable then
            phase = ("testing %d/%d"):format(calibration.successes, calibration.requiredSuccesses)
        else
            phase = ("learning %d/%d"):format(calibration.successes, calibration.requiredSuccesses)
        end
        return ("🧭 Base %d · Effective %d · %s\n📶 %d FPS · %d ms · %s"):format(
            baseSpeed, effective, phase,
            math.floor((tonumber(calibration.fps) or 0) + 0.5),
            math.floor((tonumber(calibration.pingMs) or 0) + 0.5),
            calibration.environment
        )
    end

    RuntimeStatus.updateCalibrationTelemetry(fps, getNetworkPingSeconds() * 1000)
end


-- [[ GLIDE RELIABILITY HELPERS ]] --
RuntimeStatus.glideMovementBlocked = function(root)
    local development = RuntimeStatus.DevChickenTween
    if development and development.lease and development.lease.root == root
        and development.alive(development.lease) then return false end
    local state = integrityState
    if type(state) ~= "table" or rawget(state, "RootPart") ~= root then return false end
    local threat = tostring(rawget(state, "ThreatLevel") or "")
    return rawget(state, "CorrectionContext") ~= nil
        or rawget(state, "RecoveryLocked") == true
        or rawget(state, "KickQueued") == true
        or threat == "Correcting" or threat == "Impossible"
end

RuntimeStatus.glideRetryClass = function(reason)
    return reason == "relocated" or reason == "correcting" or reason == "renewing"
        or reason == "blocked" or reason == "integrity"
        or reason == "integrity rig mismatch" or reason == "ownership lost"
end

RuntimeStatus.glidePickupStationary = function(root, humanoid, previousPosition, distance, reach)
    local development = RuntimeStatus.DevChickenTween
    if development and development.lease and development.lease.root == root then
        local drift = previousPosition and (root.Position - previousPosition).Magnitude or 0
        return development.alive(development.lease) and distance <= reach and drift <= 0.15
            and root.AssemblyLinearVelocity.Magnitude <= 2
    end
    local drift = previousPosition and root.Position - previousPosition or Vector3.zero
    local velocity = root.AssemblyLinearVelocity
    return distance <= reach and (drift * Vector3.new(1, 0, 1)).Magnitude <= 0.15
        and math.abs(drift.Y) <= 0.10
        and (velocity * Vector3.new(1, 0, 1)).Magnitude <= 1
        and math.abs(velocity.Y) <= 2 and humanoid.FloorMaterial ~= Enum.Material.Air
        and not RuntimeStatus.glideMovementBlocked(root)
end

RuntimeStatus.brakeGlidePickup = function(root)
    -- Let gravity finish landing; freezing Y can keep a root parked above an egg.
    root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
    root.AssemblyAngularVelocity = Vector3.zero
end

RuntimeStatus.glidePickupReapproach = function(pos, keepGoing, abortFn)
    local root, humanoid = getCharParts()
    if not root or not humanoid or humanoid.Health <= 0 then return false, "character unavailable" end
    local deadline = os.clock() + 1.5
    local function alive()
        local current = getCharParts()
        return current == root and humanoid.Health > 0 and os.clock() < deadline
            and keepGoing()
    end
    local direction = (root.Position - pos) * Vector3.new(1, 0, 1)
    if direction.Magnitude <= 0.25 then
        direction = root.CFrame.LookVector * Vector3.new(1, 0, 1)
    end
    if direction.Magnitude <= 0.01 then return false, "direction unavailable" end
    RuntimeStatus.glidePickupReapproaches = (RuntimeStatus.glidePickupReapproaches or 0) + 1
    -- A local pickup correction uses registered Glide and never switches to walking.
    local moved, reason = RuntimeStatus.stealOutboundMoveTo(pos + direction.Unit * 3, 0.65, alive, nil, abortFn)
    if not moved then return false, reason end
    return RuntimeStatus.stealOutboundMoveTo(pos, 0.35, alive, nil, abortFn)
end
-- [[ END GLIDE RELIABILITY HELPERS ]] --

local function moveTo(pos, reachDist, keepGoing, onReached, abortFn, routeWaypoint)
    if RuntimeStatus.blockArenaDeparture(Arb.owner) then return false, "boss-arena-exit" end
    local development = RuntimeStatus.DevChickenTween
    if development and development.enabled and development.lease and Arb.owner == "Steal" then
        return development.groundMove(pos, reachDist, keepGoing, onReached, abortFn)
    end
    local explicitWalk = Arb.owner == "Steal" and RuntimeStatus.movementPhase == "return"
        and Settings.StealRoute == "Default"
    local useDefault = explicitWalk or (Arb.owner ~= "Steal" and RuntimeStatus.defaultMoveFallback)
    if Arb.owner == "Steal" and not explicitWalk and RuntimeStatus.defaultMoveFallback then
        if not setIntegrityGuard(true) then
            setStealStatus("TP · waiting for Glide controller")
            return false, "integrity"
        end
        useDefault = false
    end
    if useDefault then
        return RuntimeStatus.defaultMoveTo(pos, reachDist, keepGoing, onReached, abortFn)
    end

    local bestDist, lastGain = math.huge, os.clock()
    local lastStep = os.clock()
    local correctionWaitStarted
    local movementRoot, expectedPosition
    while sessionAlive() and keepGoing() do
        local root, hum = getCharParts()
        if not root then return false end
        if hum and hum.Health <= 0 then return false, "dead" end
        if movementRoot and root ~= movementRoot then return false, "character changed" end
        movementRoot = root
        -- Cancellation and authoritative relocation take precedence over a
        -- locally reached coordinate. Never fight a correction with another write.
        if abortFn and abortFn() then return false, "aborted" end
        if RuntimeStatus.glideMovementBlocked(root) then
            local now = os.clock()
            correctionWaitStarted = correctionWaitStarted or now
            if now - correctionWaitStarted > 1.5 then return false, "correcting" end
            expectedPosition = nil
            bestDist, lastGain, lastStep = math.huge, now, now
            RunService.Heartbeat:Wait()
            continue
        end
        if expectedPosition
            and ((root.Position - expectedPosition) * Vector3.new(1, 0, 1)).Magnitude
                > math.max(6, math.max(0, tonumber(hum and hum.WalkSpeed) or 0)
                    * math.min(math.max(0, os.clock() - lastStep), 0.25) * 1.25 + 2) then
            RuntimeStatus.glideRelocations = (RuntimeStatus.glideRelocations or 0) + 1
            return false, "relocated"
        end
        if RuntimeStatus.guardProtectionActive(root) then
            lastGain, lastStep = os.clock(), os.clock()
            expectedPosition = nil
            RunService.Heartbeat:Wait()
            continue
        end
        if Settings.PreventTraps and carrying and LocalPlayer.Character
            and LocalPlayer.Character:GetAttribute("IsTrapped") == true then
            return false, "trapped"
        end

        if onReached and onReached() then return true end

        local cur = root.Position
        local d   = Vector3.new(pos.X - cur.X, 0, pos.Z - cur.Z)
        local flat = ((cur - pos) * Vector3.new(1, 0, 1)).Magnitude
        if flat <= reachDist then return true end

        if flat < bestDist - 2 then
            bestDist, lastGain = flat, os.clock()      -- real ground gained
        elseif os.clock() - lastGain > 1.5 then
            return false, "blocked"
        end

        keepKillPartIgnore()

        -- Calculate active elapsed time, apply this frame's movement, then yield.
        -- Correction/guard waits reset lastStep so their delay cannot accumulate.
        local nowT = os.clock()
        local dt = nowT - lastStep
        lastStep = nowT
        -- Preserve the selected speed at normal FPS, but discard stalled-frame
        -- catch-up time instead of converting it into a large position jump.
        if dt > 1 / 30 then dt = 1 / 30 end
        if dt <= 0 then dt = 1 / 60 end
        local speed = RuntimeStatus.getMovementSpeed()
        local travelD = d
        local registered, _, integrityReason = registerIntegrityTravel(root, travelD.Unit, speed, flat)
        if not registered then
            if integrityReason == "correcting" or integrityReason == "renewing" then
                correctionWaitStarted = correctionWaitStarted or nowT
                if nowT - correctionWaitStarted > 1.5 then
                    return false, "correcting"
                end
                -- Do not let the progress watchdog or a large resumed dt turn a
                -- native correction wait into a false block or a 60-stud jump.
                lastGain, lastStep = nowT, nowT
                RunService.Heartbeat:Wait()
                continue
            end
            return false, "integrity"
        end
        correctionWaitStarted = nil
        local stepCap = 32
        local step = math.min(speed * dt, stepCap, travelD.Magnitude)
        local nextP = cur + travelD.Unit * step
        local surfY = groundY(nextP.X, nextP.Z, cur.Y)
        if surfY then nextP = Vector3.new(nextP.X, surfY, nextP.Z) end
        -- Sideways presentation is part of the registered mover. Keeping one
        -- orientation path avoids configuration drift between route methods.
        local facing = Vector3.new(-travelD.Unit.Z, 0, travelD.Unit.X)
        root.CFrame = CFrame.lookAt(nextP, nextP + facing)
        root.AssemblyLinearVelocity  = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        expectedPosition = root.Position
        RunService.Heartbeat:Wait()
    end
    return false, "cancelled"
end

-- [[ END MOVEMENT DISPATCH ]] --

-- The carry packet names one AreaId, and the game's run-back controller waits
-- specifically for GuardAreas[AreaId].Guard to enter Chasing. Sleeping guards in
-- unrelated areas do not define this route. Escape the owning guard first, then
-- vary the remaining wall choices freely so consecutive trips do not trace the
-- old authored top/bottom guard pattern.
RuntimeStatus.guardRouteRandom = Random.new()
RuntimeStatus.wallSpacingInsets = function()
    return 28, 36
end
RuntimeStatus.guardRoutePoints = function(from, target, guardAreaId)
    if not (from and target) or math.abs(target.X - from.X) < 80 then return {} end
    local guardRouteRandom = RuntimeStatus.guardRouteRandom
    local objects = workspace:FindFirstChild("__OBJECTS")
    local areas = objects and objects:FindFirstChild("Areas")
    local guardAreas = areas and areas:FindFirstChild("GuardAreas")
    if not guardAreas then return {} end

    local minEdgeZ, maxEdgeZ = math.huge, -math.huge
    for _, area in ipairs(guardAreas:GetChildren()) do
        local bounds = area:FindFirstChild("Bounds")
        if bounds and bounds:IsA("BasePart") then
            minEdgeZ = math.min(minEdgeZ, bounds.Position.Z - bounds.Size.Z * 0.5)
            maxEdgeZ = math.max(maxEdgeZ, bounds.Position.Z + bounds.Size.Z * 0.5)
        end
    end
    if minEdgeZ == math.huge then return {} end

    local direction = target.X >= from.X and 1 or -1
    local wallInsetMin, wallInsetMax = RuntimeStatus.wallSpacingInsets()
    local centerZ = (minEdgeZ + maxEdgeZ) * 0.5
    local activeAreaId = RuntimeStatus.movementPhase == "return"
        and (guardAreaId ~= nil and tostring(guardAreaId)
            or RuntimeStatus.activeGuardAreaId) or nil
    local activeArea = activeAreaId and guardAreas:FindFirstChild(tostring(activeAreaId))
    -- CarryRunBackEffects resolves this exact runtime child. The Forest-authored
    -- sibling is only a hidden template and must never stand in for the chaser.
    local activeGuard = activeArea and activeArea:FindFirstChild("Guard")
    local activeGuardRoot = activeGuard
        and (activeGuard.PrimaryPart or activeGuard:FindFirstChild("HumanoidRootPart", true))
    if RuntimeStatus.movementPhase == "return" and not activeGuardRoot then
        -- A return without an exact owner is not randomized around a guessed
        -- guard. The caller falls through to its direct centered approach while
        -- diagnostics expose the missing mapping.
        RuntimeStatus.guardRoutePlanSequence = (RuntimeStatus.guardRoutePlanSequence or 0) + 1
        RuntimeStatus.lastGuardRoutePlan = {
            Sequence = RuntimeStatus.guardRoutePlanSequence,
            Phase = "return",
            ActiveAreaId = activeAreaId,
            MissingTargetGuard = true,
            PointCount = 0,
            SideSignature = "",
        }
        return {}
    end
    -- Returning starts on the wall opposite the one pursuing guard. Outbound
    -- Wall-to-Wall has no active pursuer, so even its initial wall is random.
    local useTopWall
    if activeGuardRoot then
        useTopWall = activeGuardRoot.Position.Z < centerZ
    else
        useTopWall = guardRouteRandom:NextNumber() < 0.5
    end
    local function sampleLane(topWall)
        return topWall
            and maxEdgeZ - guardRouteRandom:NextNumber(wallInsetMin, wallInsetMax)
            or minEdgeZ + guardRouteRandom:NextNumber(wallInsetMin, wallInsetMax)
    end

    local distance = math.abs(target.X - from.X)
    local finalReserve = math.min(distance * 0.22, guardRouteRandom:NextNumber(70, 125))
    local usableDistance = math.max(0, distance - finalReserve)
    local firstTravel = math.min(usableDistance, guardRouteRandom:NextNumber(65, 110))
    -- The first opposite-wall escape completes during the target guard's 0.63 s
    -- wake animation. Delay any later cross-corridor switch until roughly 75%
    -- of a short route or 650 X studs of a long one have already been covered.
    local switchClearance = math.min(usableDistance,
        math.max(firstTravel, math.min(650, usableDistance * 0.75)))
    local out, lastX = {}, from.X
    local function appendPoint(x, z)
        x = math.clamp(x, math.min(from.X, target.X), math.max(from.X, target.X))
        if (direction > 0 and x <= lastX + 1) or (direction < 0 and x >= lastX - 1) then return end
        out[#out + 1] = Vector3.new(x, from.Y, z)
        lastX = x
    end

    if firstTravel > 5 then
        appendPoint(from.X + direction * firstTravel, sampleLane(useTopWall))
    end
    local remainingDistance = math.max(0, usableDistance - firstTravel)
    local bendCount = remainingDistance >= 80 and math.clamp(
        math.floor(remainingDistance / guardRouteRandom:NextNumber(360, 620)), 1, 5
    ) or 0
    for index = 1, bendCount do
        local progress = index / (bendCount + 1)
            + guardRouteRandom:NextNumber(-0.22, 0.22) / (bendCount + 1)
        local travelled = firstTravel
            + remainingDistance * math.clamp(progress, 0.05, 0.95)
        if travelled >= switchClearance and guardRouteRandom:NextNumber() < 0.62 then
            useTopWall = not useTopWall
        end
        appendPoint(from.X + direction * travelled, sampleLane(useTopWall))
    end
    if remainingDistance > 30 then
        if usableDistance >= switchClearance and guardRouteRandom:NextNumber() < 0.35 then
            useTopWall = not useTopWall
        end
        appendPoint(from.X + direction * usableDistance, sampleLane(useTopWall))
    end

    local sideSignature = {}
    for _, point in ipairs(out) do
        sideSignature[#sideSignature + 1] = point.Z >= centerZ and "T" or "B"
    end
    RuntimeStatus.guardRoutePlanSequence = (RuntimeStatus.guardRoutePlanSequence or 0) + 1
    RuntimeStatus.lastGuardRoutePlan = {
        Sequence = RuntimeStatus.guardRoutePlanSequence,
        Phase = RuntimeStatus.movementPhase,
        ActiveAreaId = activeAreaId,
        ActiveGuardState = activeGuard and activeGuard:GetAttribute("GuardState") or nil,
        SwitchClearance = switchClearance,
        PointCount = #out,
        SideSignature = table.concat(sideSignature),
    }
    return out
end

-- Titan Temple carries a 134 x 30 stud collision block named TEMPLE whose inner
-- face stands about 22 studs proud of the left wall's inner face. Wall to Wall
-- samples its bottom lane at Z -426..-418 (Normal) or -416..-408 (Wide), and the
-- block spans Z -441.7..-411.3 across X 4626..4761 — so the Normal lane is
-- entirely inside it and the Wide lane mostly is. A runner wedges on that block
-- and the leg dies as "blocked". Clear that one block's collision; every WALL
-- volume stays solid so the route keeps the boundaries it steers by.
RuntimeStatus.routeObstacleCleared = setmetatable({}, { __mode = "k" })
RuntimeStatus.routeObstacleCheckedAt = 0

RuntimeStatus.clearRouteObstacles = function()
    local now = os.clock()
    if now - (tonumber(RuntimeStatus.routeObstacleCheckedAt) or 0) < 2 then return end
    RuntimeStatus.routeObstacleCheckedAt = now
    local objects = workspace:FindFirstChild("__OBJECTS")
    local build = objects and objects:FindFirstChild("Build")
    local zone = build and build:FindFirstChild("TitanTempleZone")
    local temple = zone and zone:FindFirstChild("TEMPLE")
    if not temple then return end
    for _, part in ipairs(temple:GetDescendants()) do
        -- Never a wall, even if the map later parents one under TEMPLE. The
        -- route reads the wall edges to place its lanes; losing them would send
        -- the runner straight out of the corridor.
        local holder = part.Parent
        local label = (part.Name .. " " .. (holder and holder.Name or "")):upper()
        if part:IsA("BasePart") and part.CanCollide
            and not label:find("WALL", 1, true) then
            RuntimeStatus.routeObstacleCleared[part] = true
            pcall(function() part.CanCollide = false end)
        end
    end
end

RuntimeStatus.restoreRouteObstacles = function()
    for part in pairs(RuntimeStatus.routeObstacleCleared) do
        if part and part.Parent then pcall(function() part.CanCollide = true end) end
        RuntimeStatus.routeObstacleCleared[part] = nil
    end
    RuntimeStatus.routeObstacleCheckedAt = 0
end
getgenv().__CHSAE_RestoreRouteObstacles = RuntimeStatus.restoreRouteObstacles

-- Owned by its own loop, not by a worker. The route this clears for is chosen in
-- Settings long before any transaction starts, and a player checking the map with
-- Auto-Steal off must still see it cleared. The function keeps its own 2 s
-- cooldown, so the extra calls from the workers below cost nothing and stay as a
-- pre-movement guarantee after a map rebuild.
task.spawn(function()
    while sessionAlive() do
        RuntimeStatus.clearRouteObstacles()
        task.wait(2)
    end
end)

RuntimeStatus.guardedMoveTo = function(pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
    local root = getCharParts()
    if not root then return false, "character unavailable" end
    for _, waypoint in ipairs(RuntimeStatus.guardRoutePoints(root.Position, pos, guardAreaId)) do
        -- Complete the lane change before starting the next segment. The former
        -- nine-stud radius allowed diagonal corner cutting into the side wall.
        local reached, reason = moveTo(waypoint, 3.5, keepGoing, nil, abortFn, true)
        if not reached then return false, reason end
    end
    return moveTo(pos, reachDist, keepGoing, onReached, abortFn)
end

-- TP return routes share configured speed, ground snap and integrity context.
-- Turbo Hybrid uses guard-aware wall switches; Straight travels directly.
RuntimeStatus.stealMoveTo = function(pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
    if Settings.StealRoute == "Default" then
        return RuntimeStatus.defaultMoveTo(pos, reachDist, keepGoing, onReached, abortFn)
    end
    if Settings.StealRoute == "Straight" or Settings.StealRoute == "Fly" then
        return moveTo(pos, reachDist, keepGoing, onReached, abortFn)
    end
    return RuntimeStatus.guardedMoveTo(pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
end

-- Chicken TP owns fresh outbound travel. Local retries go directly to the
-- exact egg without consulting the return-method picker.
RuntimeStatus.stealOutboundMoveTo = function(pos, reachDist, keepGoing, onReached, abortFn)
    RuntimeStatus.movementPhase = "outbound"
    local reached, reason = moveTo(pos, reachDist, keepGoing, onReached, abortFn)
    RuntimeStatus.movementPhase = nil
    return reached, reason
end

RuntimeStatus.stealReturnMoveTo = function(pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
    RuntimeStatus.movementPhase = "return"
    local reached, reason
    if Settings.StealRoute == "Turbo Hybrid" then
        reached, reason = RuntimeStatus.guardedMoveTo(
            pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
    else
        reached, reason = RuntimeStatus.stealMoveTo(
            pos, reachDist, keepGoing, onReached, abortFn, guardAreaId)
    end
    RuntimeStatus.movementPhase = nil
    return reached, reason
end

-- Finish every delivery through the proven centered entrance.
-- Early claim feedback is deliberately not a movement-completion condition.
RuntimeStatus.centeredStealReturnTo = function(fallbackHome, keepGoing, abortFn, guardAreaId)
    local development = RuntimeStatus.DevChickenTween
    if not development then return false, "shared delivery controller unavailable" end
    local ready, reason = development.begin(true)
    if not ready then return false, reason end
    return development.returnHome(keepGoing, abortFn, guardAreaId)
end

-- The server can relocate a successful claimant to the plot-side landing point
-- shortly after the boundary crossing. Hold Steal ownership through that packet
-- and restore TrackStart before another character task is allowed to run.
RuntimeStatus.settleClaimAtTrackStart = function(keepGoing)
    keepGoing = type(keepGoing) == "function" and keepGoing or sessionAlive
    local trackStart = RuntimeStatus.getTrackStart()
    if not (trackStart and trackStart:IsA("BasePart")) then return false end
    local stage = trackStart.Position + Vector3.new(0, 3, 0)
    local pingSeconds = 0.08
    pcall(function()
        pingSeconds = math.max(0, Stats.Network.ServerStatsItem["Data Ping"]:GetValue()) / 1000
    end)
    local stableWindow = math.clamp(pingSeconds * 1.5 + 0.04, 0.12, 0.30)
    local deadline = os.clock() + math.clamp(stableWindow + 0.35, 0.55, 0.8)
    local stableSince
    while sessionAlive() and keepGoing() and os.clock() < deadline do
        local root, humanoid = getCharParts()
        if not root or (humanoid and humanoid.Health <= 0) then return false end
        local flat = ((root.Position - stage) * Vector3.new(1, 0, 1)).Magnitude
        if flat > 1.5 then
            stableSince = nil
            if Arb.owner ~= "Steal" then
                -- Treadmill and placement own their own cancellation/body lease.
                -- The egg-delivery rig requires Steal ownership and an enabled
                -- steal feature; using it here strands post-boss training.
                local mover = RuntimeStatus.progressionTweenTo
                if not mover then return false, "Tween controller starting" end
                local reached, reason = mover(Arb.owner, stage, 1.5, keepGoing)
                if not reached then return false, reason end
            else
                local development = RuntimeStatus.DevChickenTween
                local existingLease = development and development.lease
                local ready = development and development.begin(true)
                if not ready then return false end
                local reached = development.groundMove(stage, 1.5, keepGoing, nil, nil,
                    RuntimeStatus.getDeliverySpeed(development.lease.movementType))
                -- Keep an outbound staging lease; standalone claim corrections
                -- restore their original rig and native integrity baseline.
                local restored = existingLease ~= nil or development.restore("claim settled")
                reached = reached and restored
                if not reached then return false end
            end
        else
            stableSince = stableSince or os.clock()
            if os.clock() - stableSince >= stableWindow then return true end
            RunService.Heartbeat:Wait()
        end
    end
    local root = getCharParts()
    return sessionAlive() and keepGoing() and root ~= nil
        and ((root.Position - stage) * Vector3.new(1, 0, 1)).Magnitude <= 3
end

RuntimeStatus.settleVerifiedClaim = function(keepGoing)
    return RuntimeStatus.settleClaimAtTrackStart(keepGoing)
end

-- ══════════════════════════════════════════
-- 🏡 PROGRESSION — native pen, cash and index actions
-- ══════════════════════════════════════════
local PenBox, TreadmillBox, TrailBox
local ProgressionCtl = {
    treadmillSuppressed = false,
    placePending = false,
    eventPending = false,
    treadmillBlockedUntil = 0,
    treadmillIdleSince = 0,
    placeBeat = 0,
    PLACE_STALE = 8,
}
-- Event reservations include ordinary Great Bloom, the Crane unlock return and
-- the higher-priority Admin Event worker. Independent inputs prevent one event's
-- replication callback from clearing another event's body handoff.
function ProgressionCtl.refreshEventPending(bloomPending)
    if bloomPending ~= nil then
        RuntimeStatus.greatBloomBodyPending = bloomPending == true
    end
    ProgressionCtl.eventPending = RuntimeStatus.greatBloomBodyPending == true
        or RuntimeStatus.greatBloomUnlockReturnPending == true
        or RuntimeStatus.adminEventPending == true
        or RuntimeStatus.riftBossBodyPending == true
    return ProgressionCtl.eventPending
end
function ProgressionCtl.blockTreadmill(seconds)
    ProgressionCtl.treadmillBlockedUntil = math.max(
        tonumber(ProgressionCtl.treadmillBlockedUntil) or 0,
        os.clock() + math.max(0, tonumber(seconds) or 0)
    )
    ProgressionCtl.treadmillIdleSince = 0
end
do
PenBox = ProgressionTab:AddLeftGroupbox("🏡 Pen")
do
    local penStatusLbl
    CHK.Merge(PenBox, function()
        penStatusLbl = PenBox:AddLabel("PenProgressStatusLabel", {
            Text = "💤 Progression standby", DoesWrap = true,
        })
    end)
    local function setPenStatus(text)
        RuntimeStatus.setLabel(penStatusLbl, text)
    end

    local ProgressSave, BaseUpgradeClient, ProgressNet, ProgressPlotCmds
    local OfflineEndpoints, IndexEndpoints
    pcall(function()
        local Save = require(ReplicatedStorage.Shared.Save)
        local BaseUpgrade = require(ReplicatedStorage.Client.BaseUpgrade)
        local Remotes = require(ReplicatedStorage.Shared.Remotes)
        local PlotState = require(ReplicatedStorage.Client.PlotState)
        ProgressSave = { Get = function() return Save.Get() end }
        BaseUpgradeClient = {
            GetNextConfig = BaseUpgrade.ResolveNextTier,
            CanAffordNext = BaseUpgrade.IsNextTierAffordable,
            RequestCashUpgrade = BaseUpgrade.PurchaseNextTier,
        }
        ProgressNet = {
            Invoke = function(remote, ...) return remote:InvokeServer(...) end,
        }
        ProgressPlotCmds = { GetMySlot = PlotState.ResolveLocalSlot }
        OfflineEndpoints = { REQUEST_REDEEM = Remotes.AwayEarnings.AskCollect }
        IndexEndpoints = { REQUEST_CLAIM_ALL = Remotes.Codex.AskRedeemAll }
    end)

    local penUpgradeToggle = PenBox:AddToggle("AutoUpgradePenToggle", {
        Text = "Upgrade Pen",
        Default = Settings.AutoUpgradePen,
        Tooltip = "Buy affordable pen upgrades.",
    })
    penUpgradeToggle:OnChanged(function(value)
        Settings.AutoUpgradePen = value
        setPenStatus(value and "🟡 Watching pen upgrades" or "💤 Progression standby")
        SESSION.WakeIdleWorkers("pen-toggle")
    end)

    local collectCashToggle = PenBox:AddToggle("AutoCollectCashToggle", {
        Text = "Collect Cash",
        Default = Settings.AutoCollectCash,
        Tooltip = "Collect cash from your pen.",
    })
    collectCashToggle:OnChanged(function(value)
        Settings.AutoCollectCash = value
        if value then setPenStatus("🟡 Watching pen cash") end
        SESSION.WakeIdleWorkers("cash-toggle")
    end)

    local claimIndexToggle = PenBox:AddToggle("AutoClaimIndexToggle", {
        Text = "Claim Index",
        Default = Settings.AutoClaimIndex,
        Tooltip = "Claim completed Index rewards.",
    })
    claimIndexToggle:OnChanged(function(value)
        Settings.AutoClaimIndex = value
        if value then setPenStatus("🟡 Watching Index rewards") end
        SESSION.WakeIdleWorkers("index-toggle")
    end)

    local function hasOfflineCashPile()
        if not ProgressPlotCmds then return false end
        local slot = ProgressPlotCmds.GetMySlot()
        local plots = workspace:FindFirstChild("Plots")
        local plot = slot and plots and plots:FindFirstChild(tostring(slot))
        return plot and plot:FindFirstChild("LocalOfflineMoneyClaim") ~= nil
    end

    task.spawn(function()
        local nextPenCheck, nextCashCheck, nextIndexCheck = 0, 0, 0
        while sessionAlive() do
            if not (Settings.AutoUpgradePen or Settings.AutoCollectCash or Settings.AutoClaimIndex) then
                SESSION.IdleWorkerWake.Event:Wait()
                continue
            end
            local now = os.clock()

            if Settings.AutoUpgradePen and now >= nextPenCheck then
                nextPenCheck = now + 4
                if not (ProgressSave and BaseUpgradeClient) then
                    setPenStatus("⚠️ Pen upgrade unavailable")
                elseif Arb.backgroundOk() then
                    local ok, save = pcall(ProgressSave.Get)
                    local nextLevel, nextConfig
                    if ok and type(save) == "table" then
                        pcall(function()
                            nextLevel, nextConfig = BaseUpgradeClient.GetNextConfig(save)
                        end)
                    end
                    if not nextLevel or not nextConfig then
                        setPenStatus("✅ Pen is max level")
                    else
                        local canAfford = false
                        pcall(function() canAfford = BaseUpgradeClient.CanAffordNext(save) == true end)
                        if canAfford then
                            local requested, accepted = pcall(BaseUpgradeClient.RequestCashUpgrade)
                            setPenStatus(requested and accepted and "🟢 Pen upgrade purchased"
                                or "🟡 Pen upgrade retrying")
                        else
                            setPenStatus("🟡 Saving for pen level " .. tostring(nextLevel))
                        end
                    end
                end
            end

            if Settings.AutoCollectCash and now >= nextCashCheck then
                nextCashCheck = now + 6
                if hasOfflineCashPile() and ProgressNet and OfflineEndpoints
                    and OfflineEndpoints.REQUEST_REDEEM and Arb.backgroundOk() then
                    local invoked, accepted, _, result = pcall(
                        ProgressNet.Invoke,
                        OfflineEndpoints.REQUEST_REDEEM,
                        { Kind = "Claim" }
                    )
                    if invoked and accepted == true then
                        local amount = type(result) == "table" and tonumber(result.AwardedAmount) or nil
                        setPenStatus(amount and amount > 0
                            and ("💰 Collected $" .. short(amount))
                            or "💰 Pen cash collected")
                    end
                end
            end

            if Settings.AutoClaimIndex and now >= nextIndexCheck then
                nextIndexCheck = now + 15
                if ProgressNet and IndexEndpoints and IndexEndpoints.REQUEST_CLAIM_ALL
                    and Arb.backgroundOk() then
                    local invoked, accepted, _, results = pcall(
                        ProgressNet.Invoke,
                        IndexEndpoints.REQUEST_CLAIM_ALL
                    )
                    if invoked and accepted == true and type(results) == "table" and next(results) ~= nil then
                        setPenStatus("🎁 Index rewards claimed")
                    end
                end
            end

            task.wait(0.5)
        end
    end)
end

-- ══════════════════════════════════════════
-- 🏃 AUTO TREADMILL — lowest-priority body task
-- ══════════════════════════════════════════
-- The game's TreadmillStaticController enters only after the root is standing
-- over the local treadmill render, then invokes REQUEST_EQUIP_STATIC itself.
-- Leaving uses the exact same REQUEST_UNEQUIP call as the game's JumpRequest.
TreadmillBox = ProgressionTab:AddRightGroupbox("🏃 Treadmill")
local treadmillStatusLbl, treadmillUpgradeStatusLbl
CHK.Merge(TreadmillBox, function()
    treadmillStatusLbl = TreadmillBox:AddLabel("TreadmillStatusLabel", {
        Text = "🔴 Off", DoesWrap = true,
    })
    treadmillUpgradeStatusLbl = TreadmillBox:AddLabel("TreadmillUpgradeStatusLabel", {
        Text = "💤 Upgrade standby", DoesWrap = true,
    })
end)
local function setTreadmillStatus(text)
    RuntimeStatus.setLabel(treadmillStatusLbl, text)
end
local function setTreadmillUpgradeStatus(text)
    RuntimeStatus.setLabel(treadmillUpgradeStatusLbl, text)
end

local TreadmillNet, TreadmillEndpoints, TreadmillDirectory, TreadmillSave
local TreadmillPlotCmds, TreadmillRegistry
pcall(function()
    local Remotes = require(ReplicatedStorage.Shared.Remotes)
    local Save = require(ReplicatedStorage.Shared.Save)
    local PlotState = require(ReplicatedStorage.Client.PlotState)
    local Registry = require(ReplicatedStorage.Client.Modules.RuntimeInstanceRegistry)
    TreadmillNet = {
        Invoke = function(remote, ...) return remote:InvokeServer(...) end,
        Fired = function(remote) return remote.OnClientEvent end,
    }
    TreadmillEndpoints = {
        REQUEST_UNEQUIP = Remotes.Treadmill.AskDoff,
        REQUEST_UPGRADE = Remotes.Treadmill.AskTierRaise,
        -- RenderStateShifted has a new structured payload; physical mounted state
        -- remains the stable source of truth for the current movement arbiter.
    }
    TreadmillDirectory = require(ReplicatedStorage.Data.Treadmills)
    TreadmillSave = { Get = function() return Save.Get() end }
    TreadmillPlotCmds = { GetMySlot = PlotState.ResolveLocalSlot }
    TreadmillRegistry = { Get = Registry.Peek }
end)

-- ACTIVE_TREADMILL_EVENT is the source of truth. Keep it across a development
-- reload so the new session does not need to probe RuntimeInstanceRegistry.
-- The old detector called Registry.Get once per treadmill id and was also used
-- inside moveTo's per-frame abort callback. Under stress that call blocked for
-- 30+ seconds at line 2895, disconnected the executor websocket, and closed the
-- game instance. A cached event read is constant-time and cannot yield.
local treadmillActiveId = rawget(getgenv(), "__CHSAE_TreadmillActiveId")
local PHYSICAL_TREADMILL_SENTINEL = "__physical_treadmill__"
local treadmillEventChangedAt = 0
local treadmillInactiveEventAt = 0
local function physicallyMountedOnTreadmill()
    local root = getCharParts()
    if not root or not root.Anchored or root.AssemblyMass ~= math.huge then return false end
    local plots = workspace:FindFirstChild("Plots")
    if plots then
        for _, plot in ipairs(plots:GetChildren()) do
            local bottom = plot:FindFirstChild("TreadmillBottom")
            if bottom and bottom:IsA("BasePart") and (bottom.Position - root.Position).Magnitude <= 12 then
                return true
            end
        end
    end
    local renders = workspace:FindFirstChild("__ClientTreadmillRenders")
    if not renders then return false end
    for _, render in ipairs(renders:GetChildren()) do
        for _, part in ipairs(render:GetDescendants()) do
            if part:IsA("BasePart") and (part.Name == "Root" or part.Name == "BoundingBoxPart")
                and (part.Position - root.Position).Magnitude <= 10 then
                return true
            end
        end
    end
    return false
end

-- ACTIVE_TREADMILL_EVENT can clear a frame before the client restores the
-- character's physics. Movement must never use that event alone as proof that
-- it may depart: an anchored, infinite-mass root accepts no MoveTo/CFrame steps.
ProgressionCtl.characterReadyToMove = function()
    local root, humanoid = getCharParts()
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
        and not root.Anchored and root.AssemblyMass ~= math.huge
end
if treadmillActiveId ~= nil and not physicallyMountedOnTreadmill() then
    -- A prior runtime may be unloaded after the native unequip event already
    -- fired. Never let that stale cross-reload ID suppress the next entry.
    treadmillActiveId = nil
    getgenv().__CHSAE_TreadmillActiveId = nil
elseif treadmillActiveId == nil and physicallyMountedOnTreadmill() then
    treadmillActiveId = PHYSICAL_TREADMILL_SENTINEL
    getgenv().__CHSAE_TreadmillActiveId = treadmillActiveId
end
Arb.treadmillTraining = treadmillActiveId ~= nil
local function treadmillSuppressed()
    -- A yielded/unsupported placement request must not suppress treadmill entry
    -- forever. The placement worker refreshes this lease while it is progressing.
    -- If it stops responding, release only its body ownership and let the next
    -- placement pass retry cleanly without starving other automation.
    if ProgressionCtl.placePending and not Arb.placeBusy then
        local beat = tonumber(ProgressionCtl.placeBeat) or 0
        if beat <= 0 or os.clock() - beat > ProgressionCtl.PLACE_STALE then
            ProgressionCtl.placePending = false
            if Arb.owner == "Place" then Arb.release("Place") end
        end
    end
    local eventBlocks = RuntimeStatus.greatBloomUnlockReturnPending == true
        or ProgressionCtl.eventPending
    if type(ProgressionCtl.greatBloomActive) == "function" then
        local ok, active = pcall(ProgressionCtl.greatBloomActive)
        if ok then
            eventBlocks = eventBlocks or active
        else
            eventBlocks = eventBlocks or ProgressionCtl.eventPending
        end
    else
        eventBlocks = eventBlocks or ProgressionCtl.eventPending
    end
    if ProgressionCtl.placePending or Arb.placeBusy then return true, "Placing eggs" end
    if eventBlocks then
        return true, RuntimeStatus.riftBossBodyPending and "Boss event has priority"
            or RuntimeStatus.adminEventPending and "Rift submission has priority"
            or "Event movement has priority"
    end
    if ProgressionCtl.treadmillSuppressed then return true, "Steal movement pending" end
    if os.clock() < (tonumber(ProgressionCtl.treadmillBlockedUntil) or 0) then
        return true, "Finishing pen handoff"
    end
    return false
end

local function detectActiveTreadmill()
    local physicallyMounted = physicallyMountedOnTreadmill()
    if treadmillActiveId ~= nil and not physicallyMounted
        and os.clock() - treadmillEventChangedAt > 1 then
        treadmillActiveId = nil
        getgenv().__CHSAE_TreadmillActiveId = nil
        Arb.treadmillTraining = false
    elseif treadmillActiveId == nil and physicallyMounted then
        treadmillActiveId = PHYSICAL_TREADMILL_SENTINEL
        getgenv().__CHSAE_TreadmillActiveId = treadmillActiveId
        Arb.treadmillTraining = true
    end
    return treadmillActiveId
end

if TreadmillNet and TreadmillEndpoints then
    pcall(function()
        getgenv().__CHSAE_TreadmillConn = TreadmillNet.Fired(
            TreadmillEndpoints.ACTIVE_TREADMILL_EVENT
        ):Connect(function(id)
            treadmillEventChangedAt = os.clock()
            if id == nil then treadmillInactiveEventAt = treadmillEventChangedAt end
            treadmillActiveId = id
            getgenv().__CHSAE_TreadmillActiveId = id
            Arb.treadmillTraining = id ~= nil
            if id ~= nil then
                setTreadmillStatus(treadmillSuppressed() and "🟡 Leaving treadmill…" or "🟢 Training")
            elseif Settings.AutoTreadmill and not treadmillSuppressed() then
                setTreadmillStatus("🟡 Returning to treadmill…")
            else
                setTreadmillStatus(Settings.AutoTreadmill and "🟡 Standby" or "🔴 Off")
            end
            if wakeEggScanner then wakeEggScanner("treadmill-state") end
        end)
    end)
end

-- A RemoteFunction can remain yielded forever when a server's treadmill session
-- is stale. Never call it on the steal worker: one unanswered request previously
-- froze Auto-Steal on "Target locked" until its heartbeat became stale. Keep a
-- single background request and let the native anchored/infinite-mass state be
-- the authoritative completion signal.
ProgressionCtl.treadmillExitRequest = {
    inFlight = false,
    startedAt = 0,
    accepted = nil,
    error = nil,
}

local function beginTreadmillExitRequest()
    local exitState = ProgressionCtl.treadmillExitRequest
    if exitState.inFlight or not (TreadmillNet and TreadmillEndpoints) then
        return exitState.inFlight
    end
    exitState.inFlight = true
    exitState.startedAt = os.clock()
    exitState.accepted = nil
    exitState.error = nil
    local requestSession = SESSION.Marker
    task.spawn(function()
        local invoked, accepted = pcall(
            TreadmillNet.Invoke,
            TreadmillEndpoints.REQUEST_UNEQUIP
        )
        if getgenv().__CloverHubSAE_Session ~= requestSession then return end
        exitState.inFlight = false
        exitState.accepted = invoked and accepted == true
        if not invoked then
            exitState.error = tostring(accepted)
        elseif accepted ~= true then
            exitState.error = "Server rejected treadmill exit"
        end
    end)
    return true
end
local function requestTreadmillExit()
    local active = detectActiveTreadmill()
    if not active and ProgressionCtl.characterReadyToMove() then return true end
    if not (TreadmillNet and TreadmillEndpoints) then return false end
    setTreadmillStatus("🟡 Leaving treadmill…")
    beginTreadmillExitRequest()
    local deadline = os.clock() + 3.5
    local clearSince
    local transitionSettle = math.clamp(getNetworkPingSeconds() * 1.5 + 0.08, 0.16, 0.35)
    -- Session ownership is the cancellation authority. `keepGoing` was never
    -- defined by CloverHub and existed only accidentally in some executors.
    while sessionAlive() and os.clock() < deadline do
        local inactive = detectActiveTreadmill() == nil
        local movable = ProgressionCtl.characterReadyToMove()
        local exitState = ProgressionCtl.treadmillExitRequest
        local serverRetired = treadmillInactiveEventAt >= (tonumber(exitState.startedAt) or math.huge)
            or (not exitState.inFlight and exitState.accepted == true)
        if inactive and movable and serverRetired then
            clearSince = clearSince or os.clock()
            if os.clock() - clearSince >= transitionSettle then break end
        else
            clearSince = nil
        end
        RunService.Heartbeat:Wait()
    end

    local inactive = detectActiveTreadmill() == nil
    local movable = ProgressionCtl.characterReadyToMove()
    local exitState = ProgressionCtl.treadmillExitRequest
    local serverRetired = treadmillInactiveEventAt >= (tonumber(exitState.startedAt) or math.huge)
        or (not exitState.inFlight and exitState.accepted == true)
    if sessionAlive() and not (inactive and movable and serverRetired)
        and ProgressionCtl.treadmillExitRequest.inFlight
    then
        ProgressionCtl.treadmillExitRequest.error = "Treadmill server response pending"
        setTreadmillStatus("🟡 Treadmill server pending")
    end
    if inactive and movable and serverRetired then
        setTreadmillStatus(Settings.AutoTreadmill and "🟡 Standby" or "🔴 Off")
    end
    return inactive and movable and serverRetired
end

-- Tool actions can finish locally before their unequip reaches the server. A
-- carry request issued during that gap is intermittently rejected even at zero
-- distance, so activity handoff requires a tool-free, ping-scaled stable window.
ProgressionCtl.waitForToolFree = function(timeout)
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not (character and humanoid and humanoid.Health > 0) then return false end
    local settle = math.clamp(getNetworkPingSeconds() * 1.5 + 0.06, 0.12, 0.30)
    local equippedAtEntry = character:FindFirstChildWhichIsA("Tool")
    if not equippedAtEntry and not ProgressionCtl.toolRetiredAt then return true end

    local deadline = os.clock() + math.max(0.5, tonumber(timeout) or 1.5)
    local stableSince
    while sessionAlive() and os.clock() < deadline do
        character = LocalPlayer.Character
        humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not (character and humanoid and humanoid.Health > 0) then return false end
        local equipped = character:FindFirstChildWhichIsA("Tool")
        if equipped then
            stableSince = nil
            ProgressionCtl.toolRetiredAt = os.clock()
            pcall(function() humanoid:UnequipTools() end)
        else
            stableSince = stableSince or os.clock()
            if os.clock() - stableSince >= settle then
                ProgressionCtl.toolRetiredAt = nil
                return true
            end
        end
        RunService.Heartbeat:Wait()
    end
    return false
end

local function treadmillTarget()
    if not TreadmillPlotCmds then return nil end
    local slot = TreadmillPlotCmds.GetMySlot()
    if not slot then return nil end

    -- Follow the native controller's entry test. It raycasts against the
    -- local plot's TreadmillBottom, which remains stable even when the
    -- rendered treadmill model or its decorative belt hierarchy changes.
    local plots = workspace:FindFirstChild("Plots")
    local plot = plots and plots:FindFirstChild(tostring(slot))
    local bottom = plot and plot:FindFirstChild("TreadmillBottom")
    if bottom and bottom:IsA("BasePart") then
        return Vector3.new(bottom.Position.X, bottom.Position.Y + 4, bottom.Position.Z)
    end

    local render = rawget(getgenv(), "__CHSAE_TreadmillRender")
    if typeof(render) ~= "Instance" or render.Parent == nil then
        local renders = workspace:FindFirstChild("__ClientTreadmillRenders")
        render = renders and renders:FindFirstChild("TreadmillRender_" .. tostring(slot)) or nil
        getgenv().__CHSAE_TreadmillRender = render
    end
    if not render then return nil end
    local belt = render:FindFirstChild("Belt.001", true)
        or render:FindFirstChild("BoundingBoxPart", true)
        or render:FindFirstChild("Root", true)
    local pos = belt and belt:IsA("BasePart") and belt.Position or render:GetPivot().Position
    return Vector3.new(pos.X, pos.Y + 3, pos.Z)
end

-- Arrive once, then let ordinary character physics and the native controller
-- finish mounting. Re-teleporting during this wait restarts the landing.
local function teleportIntoTreadmill(target)
    local root, hum = getCharParts()
    local character = LocalPlayer.Character
    if not (root and hum) or hum.Health <= 0 then return false, "character unavailable" end
    local function alive()
        return sessionAlive() and Settings.AutoTreadmill and not treadmillSuppressed()
            and not carrying and not Arb.stealBusy() and not Arb.petsBusy
            and Arb.hold("Treadmill") and LocalPlayer.Character == character
            and root.Parent == character and hum.Health > 0
    end
    if not alive() then return false, "cancelled" end
    if detectActiveTreadmill() then return true, "mounted" end
    if root.Anchored or root.AssemblyMass == math.huge then return false, "character anchored" end
    local dev = RuntimeStatus.DevChickenTween
    if dev and dev.lease then return false, "movement restoration pending" end

    local entry = { phase = "approach", startedAt = os.clock() }
    ProgressionCtl.treadmillEntry = entry
    local function finish(ok, reason)
        entry.phase, entry.reason = ok and "mounted" or "waiting", reason
        return ok, reason
    end
    target = Vector3.new(target.X, groundY(target.X, target.Z, target.Y), target.Z)
    hum.Sit = false
    if not RuntimeStatus.progressionTweenTo then return finish(false, "Tween controller starting") end
    local reached, reason = RuntimeStatus.progressionTweenTo("Treadmill", target, 1.5, alive)
    if not alive() then return finish(false, "cancelled") end
    if detectActiveTreadmill() then return finish(true, "mounted") end
    if not reached then return finish(false, reason or "treadmill tween interrupted") end

    entry.phase = "mount wait"
    setTreadmillStatus("🟡 Waiting for treadmill mount…")
    local ping = math.clamp(tonumber(getNetworkPingSeconds()) or 0, 0, 1.5)
    local frame = math.clamp(tonumber(RuntimeStatus.clientFrameSeconds) or 1 / 60, 1 / 240, 0.25)
    local arrivedAt = os.clock()
    local deadline = arrivedAt + math.max(3.5, ping * 2 + 1.5 + frame * 3)
    while alive() and os.clock() < deadline do
        if detectActiveTreadmill() then return finish(true, "mounted") end
        if root.Anchored or root.AssemblyMass == math.huge then
            return finish(false, "character anchored")
        end
        local flat = ((root.Position - target) * Vector3.new(1, 0, 1)).Magnitude
        if flat > 4 then return finish(false, "moved away from treadmill") end
        RunService.Heartbeat:Wait()
    end
    if not alive() then return finish(false, "cancelled") end
    if detectActiveTreadmill() then return finish(true, "mounted") end
    return finish(false, "native mount pending")
end

local autoUpgradeTreadmillTgl = TreadmillBox:AddToggle("AutoUpgradeTreadmillToggle", {
    Text = "Upgrade Treadmill",
    Default = Settings.AutoUpgradeTreadmill,
    Tooltip = "Buy affordable treadmill upgrades.",
})
autoUpgradeTreadmillTgl:OnChanged(function(value)
    Settings.AutoUpgradeTreadmill = value
    setTreadmillUpgradeStatus(value and "🟡 Watching upgrades" or "💤 Upgrade standby")
end)

local autoTreadmillTgl = TreadmillBox:AddToggle("AutoTreadmillToggle", {
    Text = "Auto Treadmill",
    Default = Settings.AutoTreadmill,
    Tooltip = "Use the treadmill when idle.",
})
autoTreadmillTgl:OnChanged(function(v)
    Settings.AutoTreadmill = v
    if not v then
        ProgressionCtl.treadmillSuppressed = false
        task.spawn(function()
            requestTreadmillExit()
            setTreadmillStatus("🔴 Off")
        end)
    else
        setTreadmillStatus(detectActiveTreadmill() and "🟢 Training" or "🟡 Standby")
    end
end)
task.spawn(function()
    local treadmillRetryAt = 0
    local nextUpgradeCheck = 0
    -- Give the higher-priority placement worker one short scheduler window after
    -- a target-free transition. This is not the old 3.5-second idle delay.
    local MIN_TRAINING_WINDOW = 0.75
    while sessionAlive() do
        local workerOk, workerError = xpcall(function()
        local now = os.clock()
        local active = detectActiveTreadmill()

        local suppressed, blockReason = treadmillSuppressed()
        if carrying then blockReason = "Carrying egg"
        elseif Arb.stealBusy() then blockReason = "Steal has priority" end
        ProgressionCtl.treadmillBlockReason = blockReason
        if suppressed or blockReason then
            ProgressionCtl.treadmillIdleSince = 0
            if Settings.AutoTreadmill and not active then
                setTreadmillStatus("⏸️ " .. tostring(blockReason))
            end
        elseif ProgressionCtl.treadmillIdleSince == 0 then
            ProgressionCtl.treadmillIdleSince = now
        end
        local idleWindowReady = ProgressionCtl.treadmillIdleSince > 0
            and now - ProgressionCtl.treadmillIdleSince >= MIN_TRAINING_WINDOW

        local upgradeAttempted = false
        if Settings.AutoUpgradeTreadmill and now >= nextUpgradeCheck then
            nextUpgradeCheck = now + 4
            if not (TreadmillSave and TreadmillDirectory and TreadmillNet and TreadmillEndpoints) then
                setTreadmillUpgradeStatus("⚠️ Upgrade unavailable")
            elseif Arb.quietOk() and not Arb.stealBusy() then
                local ok, save = pcall(TreadmillSave.Get)
                local baseLevel = ok and type(save) == "table" and tonumber(save.BaseUpgradeLevel) or 0
                local upgradeLevel = ok and type(save) == "table" and tonumber(save.TreadmillUpgradeLevel) or 0
                local nextConfig
                if upgradeLevel then
                    pcall(function()
                        nextConfig = TreadmillDirectory.GetByUpgradeLevel(upgradeLevel + 1)
                    end)
                end
                if baseLevel <= 0 then
                    setTreadmillUpgradeStatus("🔒 Upgrade the pen first")
                elseif not nextConfig then
                    setTreadmillUpgradeStatus("✅ Treadmill is max level")
                else
                    local price = tonumber(nextConfig.Price) or math.huge
                    local money = tonumber(save.Money) or 0
                    if money < price then
                        setTreadmillUpgradeStatus("🟡 Saving $" .. short(price))
                    else
                        if active then
                            requestTreadmillExit()
                            active = detectActiveTreadmill()
                        end
                        if not active and TreadmillEndpoints.REQUEST_UPGRADE then
                            local invoked, accepted = pcall(
                                TreadmillNet.Invoke,
                                TreadmillEndpoints.REQUEST_UPGRADE,
                                nextConfig._id
                            )
                            upgradeAttempted = true
                            treadmillRetryAt = now + 4
                            setTreadmillUpgradeStatus(invoked and accepted == true
                                and "🟢 Treadmill upgraded"
                                or "🟡 Upgrade retrying")
                        end
                    end
                end
            end
        end

        if not upgradeAttempted and Settings.AutoTreadmill and not treadmillSuppressed()
            and not carrying and not Arb.stealBusy() and not Arb.petsBusy
            and (active or idleWindowReady) then
            if active then
                setTreadmillStatus("🟢 Training")
            elseif now < treadmillRetryAt then
                setTreadmillStatus("🟡 Entry cooling down")
            elseif Arb.acquire("Treadmill") then
                -- Center before treadmill entry, except for a direct handoff
                -- from a freshly completed placement.
                local handoffAlive = function()
                    return sessionAlive() and Settings.AutoTreadmill
                        and not treadmillSuppressed() and not carrying
                        and not Arb.stealBusy() and not Arb.petsBusy
                        and Arb.hold("Treadmill")
                end
                local centered = true
                local trackStart = RuntimeStatus.getTrackStart()
                local root = getCharParts()
                -- Home/pen-side travel is direct even after long hatch waits or
                -- retries. Only gameplay-side recovery needs the central entrance.
                local side = root and lineSide(root.Position)
                local directFromPlace = side ~= nil and side <= 0
                local entryTarget = treadmillTarget()
                local alreadyAtTreadmill = root and entryTarget
                    and ((root.Position - entryTarget) * Vector3.new(1, 0, 1)).Magnitude <= 2
                if not directFromPlace and not alreadyAtTreadmill and trackStart and root
                    and ((root.Position - trackStart.Position) * Vector3.new(1, 0, 1)).Magnitude > 3 then
                    setTreadmillStatus("↩️ Returning to TrackStart…")
                    centered = RuntimeStatus.settleClaimAtTrackStart(handoffAlive)
                end
                local target = centered and handoffAlive() and treadmillTarget() or nil
                if target then
                    setTreadmillStatus("↗️ Tweening to treadmill…")
                    local entered, entryReason = teleportIntoTreadmill(target)
                    if not entered then treadmillRetryAt = os.clock() + 8 end
                    if detectActiveTreadmill() then
                        setTreadmillStatus("🟢 Training")
                    elseif entryReason == "movement trust pending" or entryReason == "renewing" then
                        setTreadmillStatus("🟡 Tween movement pending")
                    elseif RuntimeStatus.defaultMoveFallback then
                        setTreadmillStatus("🟡 Compatibility entry retrying")
                    else
                        setTreadmillStatus("🟡 " .. tostring(entryReason or "Native mount pending"))
                    end
                elseif not centered and handoffAlive() then
                    setTreadmillStatus("🟡 TrackStart return interrupted · retrying")
                    treadmillRetryAt = os.clock() + 2
                elseif centered and handoffAlive() then
                    setTreadmillStatus("🟡 Treadmill unavailable")
                    treadmillRetryAt = os.clock() + 8
                end
                Arb.release("Treadmill")
            else
                ProgressionCtl.treadmillBlockReason = "Waiting for " .. tostring(Arb.owner or "movement handoff")
                setTreadmillStatus("⏸️ " .. ProgressionCtl.treadmillBlockReason)
            end
        elseif Settings.AutoTreadmill and not active and Arb.petsBusy then
            ProgressionCtl.treadmillBlockReason = "Finishing inventory action"
            setTreadmillStatus("⏸️ " .. ProgressionCtl.treadmillBlockReason)
        elseif Settings.AutoTreadmill and not active and not treadmillSuppressed()
            and not carrying and not Arb.stealBusy() and not idleWindowReady then
            setTreadmillStatus("🟡 Waiting for useful idle window")
        elseif active and treadmillSuppressed() then
            requestTreadmillExit()
        elseif not Settings.AutoTreadmill then
            setTreadmillStatus("🔴 Off")
        end
        end, debug.traceback)
        if not workerOk then
            -- A transient rig/plot error must not silently kill training until
            -- reload. Restore only this worker's movement before releasing it.
            getgenv().__CHSAE_TreadmillWorkerError = tostring(workerError)
            local dev = RuntimeStatus.DevChickenTween
            if dev and dev.lease and dev.lease.owner == "Treadmill" then
                dev.restore("treadmill worker recovery")
            end
            Arb.release("Treadmill")
            ProgressionCtl.treadmillIdleSince = 0
            ProgressionCtl.treadmillBlockReason = "Retrying treadmill after error"
            setTreadmillStatus("🟡 " .. ProgressionCtl.treadmillBlockReason)
            treadmillRetryAt = os.clock() + 2
        end
        task.wait(0.5)
    end
    Arb.release("Treadmill")
end)
ProgressionCtl.detectActiveTreadmill = detectActiveTreadmill
ProgressionCtl.requestTreadmillExit = requestTreadmillExit

-- ── PROGRESSION ▸ Trail Shop (native cash purchase action) ──
-- The controller has no UI objects. Saved settings are authoritative; views
-- issue commands and observe status asynchronously, never on the purchase stack.
function RuntimeStatus.CreateTrailController(deps)
    local settings = deps.settings
    local controller = {}
    local status = "💤 Purchase standby"
    local nextAttempt = 0
    local equipPendingId, equipPendingLabel
    local observers = {}
    local ownedConnections = {}
    local destroyed, stepBusy, epoch, worker = false, false, 0, nil
    local function owned() return not destroyed and deps.alive() end
    local function cancelThread(thread)
        if type(thread) ~= "thread" or thread == coroutine.running() then return false end
        return pcall(task.cancel, thread)
    end
    local function disconnectObserver(observer)
        observer.active = false
        observers[observer] = nil
        cancelThread(observer.thread)
        observer.thread, observer.callback = nil, nil
    end
    local queueObserver
    queueObserver = function(observer)
        if not owned() or not observer.active or observer.queued or observer.delivered == status then return end
        observer.queued = true
        observer.thread = task.defer(function()
            if not observer.active or not owned() then observer.queued = false; return end
            local snapshot = status
            local ok, rendered = pcall(observer.callback, snapshot)
            observer.queued, observer.thread = false, nil
            if ok and rendered ~= false then observer.delivered = snapshot end
            -- A yielding UI may finish after newer status. Catch up once; a
            -- failed unchanged render waits for the next publish, not a loop.
            if status ~= snapshot then queueObserver(observer) end
        end)
    end
    local function setTrailStatus(text)
        if not owned() then return end
        status = tostring(text)
        for observer in pairs(observers) do queueObserver(observer) end
    end
    function controller:GetStatus() return status end
    function controller:ObserveStatus(callback)
        local observer = { callback = callback, active = true, queued = false }
        local connection = {}
        function connection:Disconnect()
            disconnectObserver(observer)
        end
        if not owned() then observer.active, observer.callback = false, nil; return connection end
        observers[observer] = true
        queueObserver(observer)
        return connection
    end
    function controller:SetEnabled(value)
        if not owned() then return end
        if settings.AutoBuyTrail ~= (value == true) then epoch += 1 end
        settings.AutoBuyTrail = value == true
        setTrailStatus(settings.AutoBuyTrail and "🟡 Watching trails" or "💤 Purchase standby")
        deps.wake("trail-toggle")
    end
    function controller:Stop() self:SetEnabled(false) end
    function controller:SelectionChanged()
        if not owned() then return end
        local count = 0
        for _, selected in pairs(settings.TrailNames) do if selected then count += 1 end end
        setTrailStatus(count > 0 and ("🟡 %d selected"):format(count) or "🟡 Pick trails")
        deps.wake("trail-selection")
    end
    local function runStep()
        local operationEpoch = epoch
        local function current()
            return owned() and settings.AutoBuyTrail and epoch == operationEpoch
        end
        local save
        pcall(function() save = deps.getSave() end)
        if not current() then return end
        if not deps.ready() or type(save) ~= "table" then
            setTrailStatus("⚠️ Trail shop unavailable")
            return
        end
        local inventory = type(save.TrailInventory) == "table" and save.TrailInventory or {}
        if equipPendingId then
            if save.EquippedTrail == equipPendingId then
                setTrailStatus("✅ Equipped " .. tostring(equipPendingLabel or equipPendingId))
                equipPendingId, equipPendingLabel = nil, nil
                nextAttempt = deps.clock() + 1
            elseif not inventory[equipPendingId] then
                setTrailStatus("🟡 Purchase syncing…")
            elseif deps.clock() >= nextAttempt then
                nextAttempt = deps.clock() + 2
                setTrailStatus("🟡 Equipping " .. tostring(equipPendingLabel or equipPendingId) .. "…")
                local invoked, accepted, reason = pcall(deps.equip, equipPendingId)
                if not owned() then return end
                if invoked and accepted == true then
                    if current() then setTrailStatus("✅ Equipped " .. tostring(equipPendingLabel or equipPendingId)) end
                    equipPendingId, equipPendingLabel = nil, nil
                elseif current() then
                    setTrailStatus("🟡 Equip retry · " .. tostring(reason or accepted or "waiting"))
                end
            end
        else
            local selectedCount, ownedCount, pendingLabel = 0, 0, nil
            for _, label in ipairs(deps.items) do
                if settings.TrailNames[label] then
                    selectedCount += 1
                    local id = deps.byLabel[label]
                    if inventory[id] then ownedCount += 1
                    elseif not pendingLabel then pendingLabel = label end
                end
            end
            if selectedCount == 0 then
                setTrailStatus("🟡 Pick trails")
            elseif not pendingLabel then
                setTrailStatus(("✅ Selected trails owned · %d/%d"):format(ownedCount, selectedCount))
                nextAttempt = deps.clock() + 5
            elseif deps.clock() >= nextAttempt then
                nextAttempt = deps.clock() + 6
                local selectedId = deps.byLabel[pendingLabel]
                settings.TrailName = selectedId -- retain the legacy config field
                setTrailStatus("🟡 Buying " .. pendingLabel .. "…")
                local invoked, accepted, reason = pcall(deps.purchase, selectedId)
                if not owned() then return end
                if invoked and accepted == true then
                    -- Preserve an acknowledged purchase across OFF/ON, but never
                    -- send its follow-up from a stopped/superseded operation.
                    equipPendingId, equipPendingLabel = selectedId, pendingLabel
                    nextAttempt = deps.clock() + 0.15
                    if not current() then return end
                    local equipInvoked, equipAccepted = pcall(deps.equip, selectedId)
                    if not owned() then return end
                    if equipInvoked and equipAccepted == true then
                        if current() then setTrailStatus("✅ Purchased + equipped " .. pendingLabel) end
                        equipPendingId, equipPendingLabel = nil, nil
                    elseif current() then
                        setTrailStatus("✅ Purchased " .. pendingLabel .. " · equipping")
                    end
                elseif current() then
                    setTrailStatus(tostring(reason or accepted):lower():find("afford", 1, true)
                        and "🟡 Waiting for cash" or "🟡 Purchase waiting")
                end
            else
                setTrailStatus(("🟡 %d/%d owned"):format(ownedCount, selectedCount))
            end
        end
    end
    function controller:Step()
        if not owned() or not settings.AutoBuyTrail or stepBusy then return false end
        -- Never overlap an unresolved request, even after rapid OFF/ON/Start.
        local operationEpoch = epoch
        stepBusy = true
        local ok = pcall(runStep)
        stepBusy = false
        if not ok and owned() and settings.AutoBuyTrail and epoch == operationEpoch then
            setTrailStatus("⚠️ Trail shop retrying")
        end
        return ok
    end
    function controller:Own(connection)
        if destroyed then pcall(function() connection:Disconnect() end)
        else ownedConnections[#ownedConnections + 1] = connection end
        return connection
    end
    function controller:Destroy()
        if destroyed then return end
        destroyed, epoch = true, epoch + 1
        -- An already-sent remote cannot be recalled. Let that step return into
        -- its ownership guard; cancel only our idle/sleeping/queued worker.
        if worker and worker.phase ~= "stepping" and cancelThread(worker.thread) then worker = nil end
        for observer in pairs(observers) do disconnectObserver(observer) end
        for _, connection in ipairs(ownedConnections) do pcall(function() connection:Disconnect() end) end
        table.clear(ownedConnections)
        equipPendingId, equipPendingLabel, nextAttempt = nil, nil, 0
        -- Deliberately do not change saved AutoBuyTrail during session cleanup.
    end
    controller.Disconnect = controller.Destroy
    function controller:Start()
        if not owned() then return false end
        if worker then return true end
        local record = { phase = "queued" }
        worker = record -- publish ownership before scheduling the coroutine
        record.thread = task.defer(function()
            local ok = pcall(function()
                while owned() do
                    if not settings.AutoBuyTrail then
                        record.phase = "idle"
                        deps.waitIdle()
                    else
                        record.phase = "stepping"
                        self:Step()
                        if not owned() then break end
                        record.phase = "sleeping"
                        task.wait(1)
                    end
                end
            end)
            if worker == record then worker = nil end
            if not deps.alive() then self:Destroy()
            elseif not ok then setTrailStatus("⚠️ Trail worker stopped") end
        end)
        return true
    end
    function controller:GetLifecycle()
        local observerCount = 0
        for _ in pairs(observers) do observerCount += 1 end
        return { destroyed = destroyed, worker = worker and worker.phase or "none",
            busy = stepBusy, observers = observerCount, connections = #ownedConnections }
    end
    return controller
end

-- [[ TRAIL GAME ADAPTER ]] --
do
    local TrailDirectory, TrailNet, TrailSave, TrailPurchaseEndpoint, TrailSelectEndpoint
    local trailItems, trailByLabel, trailDisplay = {}, {}, {}
    pcall(function()
        local Remotes = require(ReplicatedStorage.Shared.Remotes)
        local Save = require(ReplicatedStorage.Shared.Save)
        TrailDirectory = require(ReplicatedStorage.Data.Trails)
        TrailNet = { Invoke = function(remote, ...) return remote:InvokeServer(...) end }
        TrailSave = { Get = function() return Save.Get() end }
        TrailPurchaseEndpoint = Remotes.Trailwear.AskPurchase
        TrailSelectEndpoint = Remotes.Trailwear.AskChoose

        local entries = {}
        for id, trail in pairs(TrailDirectory.Directory or {}) do
            if type(trail) == "table" and trail.DisplayInShop then
                entries[#entries + 1] = { id = tostring(id), data = trail }
            end
        end
        table.sort(entries, function(a, b)
            return (tonumber(a.data.Price) or 0) < (tonumber(b.data.Price) or 0)
        end)
        for _, entry in ipairs(entries) do
            local trail = entry.data
            local label = tostring(trail.DisplayName or entry.id)
            local rarity = trail.Rarity
            local hex = type(rarity) == "table" and typeof(rarity.Color) == "Color3"
                and toHex(rarity.Color) or "#FFFFFF"
            trailItems[#trailItems + 1] = label
            trailByLabel[label] = entry.id
            trailDisplay[label] = ('<b>%s</b> <font color="%s">%s</font> <font color="#9AA0AA">$%s · ×%s</font>')
                :format(label, hex, tostring(type(rarity) == "table" and (rarity._id or rarity.DisplayName) or ""),
                    short(tonumber(trail.Price) or 0), tostring(trail.SpeedMultiplier or 1))
        end
    end)

    -- Migrate the previous single trail ID into the new multi-select labels.
    if next(Settings.TrailNames) == nil then
        for label, id in pairs(trailByLabel) do
            if id == Settings.TrailName then Settings.TrailNames[label] = true break end
        end
    end
    for label in pairs(Settings.TrailNames) do
        if not trailByLabel[label] then Settings.TrailNames[label] = nil end
    end

    local trailController = RuntimeStatus.CreateTrailController({
        settings = Settings,
        items = trailItems,
        byLabel = trailByLabel,
        alive = sessionAlive,
        clock = os.clock,
        wake = SESSION.WakeIdleWorkers,
        waitIdle = function() SESSION.IdleWorkerWake.Event:Wait() end,
        getSave = function() return TrailSave and TrailSave.Get() end,
        ready = function() return TrailNet and TrailPurchaseEndpoint and TrailSelectEndpoint end,
        purchase = function(id) return TrailNet.Invoke(TrailPurchaseEndpoint, id) end,
        equip = function(id) return TrailNet.Invoke(TrailSelectEndpoint, id) end,
    })
    -- One lifecycle owner releases the worker, observers and view connection.
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = trailController
    trailController:Start()

    -- Trail UI adapter: commands go in, status snapshots come out. Keep it
    -- eager for now; separating UI files/deferred gameplay tabs is a later step.
    TrailBox = ProgressionTab:AddRightGroupbox("✨ Trail Shop")
    local trailStatusLbl
    CHK.Merge(TrailBox, function()
        trailStatusLbl = TrailBox:AddLabel("TrailShopStatusLabel", {
            Text = trailController:GetStatus(), DoesWrap = true,
        })
    end)
    BindDropdownOverlay(TrailBox, "TrailShopDropdown", "Trails", trailItems, {
        configKey = "TrailNames",
        multi = true,
        store = Settings.TrailNames,
        text = "Trails",
        tooltip = "Choose trails to buy.",
        displayMap = trailDisplay,
        onChange = function()
            trailController:SelectionChanged()
        end,
    })

    local autoBuyTrailTgl = TrailBox:AddToggle("AutoBuyTrailToggle", {
        Text = "Auto Buy Trail",
        Default = Settings.AutoBuyTrail,
        Tooltip = "Buy the selected trail when affordable.",
    })
    autoBuyTrailTgl:OnChanged(function(value)
        trailController:SetEnabled(value)
    end)
    local statusConnection = trailController:ObserveStatus(function(text)
        local ok = RuntimeStatus.setLabel(trailStatusLbl, text)
        -- This legacy writer pre-caches the value. Undo that on failure so the
        -- next engine status publish can retry instead of poisoning the view.
        if not ok then RuntimeStatus.statusLabelCache[trailStatusLbl] = nil end
        return ok
    end)
    trailController:Own(TrailBox.Container.Destroying:Connect(function() statusConnection:Disconnect() end))
end
end -- scoped PROGRESSION helpers (exports only the controls needed by Auto-Steal)

-- Use the same authoritative capacity rule as the game's FuseMachine UI:
-- DictionaryLength(Save.EggInventory) >= Eggs.MAX_INVENTORY.  Checking this
-- before target acquisition prevents a guaranteed server rejection and the old
-- Steal -> Great Bloom -> Steal loop when the backpack cannot accept another egg.
do
local EggInventorySave, EggInventoryTypes
pcall(function()
    local Save = require(ReplicatedStorage.Shared.Save)
    EggInventorySave = {
        Get = function() return Save.Get() end,
        ConnectForDataChanged = function(field, callback)
            return Save.FieldSignal(field):Connect(callback)
        end,
    }
    EggInventoryTypes = require(ReplicatedStorage.Shared.Types.Eggs)
end)

RuntimeStatus.eggInventoryCapacityState = function()
    local save
    pcall(function() save = EggInventorySave and EggInventorySave.Get() end)
    local inventory = type(save) == "table" and save.EggInventory or nil
    local capacity = tonumber(EggInventoryTypes and EggInventoryTypes.MAX_INVENTORY)
    if type(inventory) ~= "table" or not capacity or capacity <= 0 then
        return false, 0, capacity
    end
    local count = 0
    for _ in pairs(inventory) do count += 1 end
    return count >= capacity, count, capacity
end

-- The current client exposes the egg maximum but not a dedicated pet maximum.
-- Prefer a future save/attribute capacity if one appears; 115 is the current
-- live inventory boundary and keeps this opt-in mode useful meanwhile.
RuntimeStatus.petInventoryCapacityState = function()
    local save
    pcall(function() save = EggInventorySave and EggInventorySave.Get() end)
    local inventory = type(save) == "table" and save.Inventory or nil
    local capacity = type(save) == "table" and tonumber(
        save.PetInventoryCapacity or save.InventoryCapacity or save.MaxInventory) or nil
    if not capacity then
        capacity = tonumber(LocalPlayer:GetAttribute("PetInventoryCapacity"))
            or tonumber(LocalPlayer:GetAttribute("InventoryCapacity"))
            or tonumber(EggInventoryTypes and EggInventoryTypes.MAX_INVENTORY)
            or 115
    end
    if type(inventory) ~= "table" or capacity <= 0 then return false, 0, capacity end
    local count = 0
    for _ in pairs(inventory) do count += 1 end
    return count >= capacity, count, capacity
end

RuntimeStatus.isEggInventoryFullError = function(reason)
    local text = string.lower(tostring(reason or ""))
    return text:find("egg inventory is full", 1, true) ~= nil
        or text:find("inventory is full", 1, true) ~= nil
end

local eggInventoryFullAlerted = false
RuntimeStatus.stopAutoStealForFullInventory = function(count, capacity, reason)
    -- Save replication can report the final slot as full one scheduler turn
    -- before the steal worker consumes AreaEggClaimed. Preserve the active timer
    -- through that boundary so STEAL TIME and AVG STEAL include the successful
    -- delivery, then let the next top-of-loop capacity check turn Auto-Steal off.
    local pendingCarry = getgenv().__CHSAE_CarryRequest
    local timer = RuntimeStatus.stealTimer
    local timingActive = timer.active == true and type(pendingCarry) == "table"
    local claimVerified = timingActive and claimConfirmed(
        pendingCarry.uid, pendingCarry.category, pendingCarry.claimSequenceAtStart)
    if claimVerified then
        RuntimeStatus.inventoryFullGraceUntil = 0
        setStealStatus("🟠 Inventory full · finalizing steal")
        return false
    end
    if timingActive and pendingCarry.carrySeen == true then
        local now = os.clock()
        local graceUntil = tonumber(RuntimeStatus.inventoryFullGraceUntil) or 0
        if graceUntil <= 0 then
            graceUntil = now + 0.25
            RuntimeStatus.inventoryFullGraceUntil = graceUntil
        end
        if now < graceUntil then
            if not RuntimeStatus.inventoryFullGraceScheduled then
                RuntimeStatus.inventoryFullGraceScheduled = true
                task.delay(math.max(0.01, graceUntil - now), function()
                    RuntimeStatus.inventoryFullGraceScheduled = false
                    if sessionAlive() and autoStealTgl and autoStealTgl.Value == true then
                        local stillFull, liveCount, liveCapacity =
                            RuntimeStatus.eggInventoryCapacityState()
                        if stillFull then
                            RuntimeStatus.stopAutoStealForFullInventory(
                                liveCount, liveCapacity, reason)
                        else
                            RuntimeStatus.inventoryFullGraceUntil = 0
                        end
                    end
                end)
            end
            return false
        end
    end
    RuntimeStatus.inventoryFullGraceUntil = 0
    if Settings.SellEggsWhenFull then
        -- Keep Auto-Steal armed while the seller creates space, but relinquish
        -- character ownership so the sell worker can run immediately.
        if type(pendingCarry) == "table" and pendingCarry.inFlight ~= true then
            getgenv().__CHSAE_CarryRequest = nil
        end
        carrying = false
        ProgressionCtl.treadmillSuppressed = false
        Arb.stealWants, Arb.critical = false, false
        Arb.release("Steal")
        RuntimeStatus.pauseStealTimer()
        RuntimeStatus.carry = "📦 Carry: none"
        RuntimeStatus.set("target", "🎯 Target: none")
        setStealStatus(("🟠 Eggs full %d/%d · selling matches"):format(
            tonumber(count) or 0, tonumber(capacity) or 0))
        return false
    end
    local wasEnabled = autoStealTgl and autoStealTgl.Value == true
    -- Stop the worker state immediately, then drive the actual Obsidian control
    -- through SetValue so its knob/color and OnChanged callback agree. Repeat on
    -- the deferred UI turn because this function can run inside Save's own data
    -- changed callback while Obsidian is already processing another update.
    Settings.AutoSteal = false
    local function syncVisibleToggleOff()
        if not (sessionAlive() and autoStealTgl) then return end
        pcall(autoStealTgl.SetValue, autoStealTgl, false)
        Settings.AutoSteal = false
    end
    syncVisibleToggleOff()
    task.defer(syncVisibleToggleOff)
    RuntimeStatus.inventoryFullStopped = true
    ProgressionCtl.treadmillSuppressed = false
    clearPersistentTarget()
    -- A claim can fill the final slot and disable Auto-Steal before the worker's
    -- success branch gets another scheduler turn. Retire only a completed request;
    -- a genuinely yielding Invoke must remain protected by the single-flight lock.
    if type(pendingCarry) == "table" and pendingCarry.inFlight ~= true then
        getgenv().__CHSAE_CarryRequest = nil
    end
    Arb.stealWants, Arb.critical = false, false
    Arb.release("Steal")
    RuntimeStatus.carry = "📦 Carry: none"
    RuntimeStatus.pauseStealTimer()
    RuntimeStatus.set("target", "🎯 Target: none")
    setStealStatus("🟠 Inventory full · Auto-Steal off")

    if not eggInventoryFullAlerted then
        eggInventoryFullAlerted = true
        local details = {
            count = tonumber(count) or 0,
            capacity = tonumber(capacity) or 0,
            reason = tostring(reason or "Egg inventory is full"),
        }
        if type(RuntimeStatus.sendWebhook) == "function" then
            task.spawn(RuntimeStatus.sendWebhook, "inventory-full", "Egg Inventory Full",
                ("Auto-Steal was turned off. Egg inventory: **%d / %d**.")
                    :format(details.count, details.capacity), 0xF59E0B, false)
        else
            RuntimeStatus.pendingInventoryFullAlert = details
        end
        Library:Notify(("🥚 Inventory full (%d/%d) · Auto-Steal turned off.")
            :format(details.count, details.capacity), 6)
    end
    return wasEnabled
end

-- Save replication is the primary wake-up. The per-cycle check below remains a
-- cheap fail-safe for executors where ConnectForDataChanged is unavailable.
pcall(function()
    local conn = EggInventorySave.ConnectForDataChanged("EggInventory", function()
        local full, count, capacity = RuntimeStatus.eggInventoryCapacityState()
        if not full then
            eggInventoryFullAlerted = false
            RuntimeStatus.inventoryFullStopped = false
            RuntimeStatus.inventoryFullGraceUntil = 0
            if autoStealTgl and not autoStealTgl.Value then setStealStatus("🔴 Off") end
            if wakeEggScanner then wakeEggScanner("inventory-space") end
        elseif autoStealTgl and autoStealTgl.Value then
            task.defer(RuntimeStatus.stopAutoStealForFullInventory, count, capacity,
                "Your egg inventory is full!")
        end
    end)
    if typeof(conn) == "RBXScriptConnection" then
        local runtimeConns = getgenv().__CHSAE_RuntimeConns
        if type(runtimeConns) == "table" then runtimeConns[#runtimeConns + 1] = conn end
    end
end)
end

function RuntimeStatus.greatBloomUnlockNeedsCrane()
    return Settings.AutoUnlockGreatBloom == true
        and RuntimeStatus.greatBloomUnlockStealWanted == true
end

function RuntimeStatus.greatBloomUnlockHasCraneReservation()
    if Settings.AutoUnlockGreatBloom ~= true
        or RuntimeStatus.greatBloomUnlock.locked == false then return false end
    local claimedAt = tonumber(RuntimeStatus.greatBloomUnlockClaimedAt) or 0
    local claimGrace = tonumber(RuntimeStatus.greatBloomUnlockClaimGrace) or 8
    local claimSync = claimedAt > 0 and os.clock() - claimedAt <= claimGrace
    local state = RuntimeStatus.greatBloomUnlock
    return claimSync or state.reservedEggUid ~= nil or state.reservedPetUid ~= nil
        or RuntimeStatus.greatBloomUnlockReturnPending == true
end

function RuntimeStatus.greatBloomUnlockReturnHasPriority()
    return Settings.AutoUnlockGreatBloom == true
        and RuntimeStatus.greatBloomUnlockReturnPending == true
        and not RuntimeStatus.normalStealPending()
end

function RuntimeStatus.carryRequestInFlight()
    local request = getgenv().__CHSAE_CarryRequest
    return type(request) == "table" and request.inFlight == true
end

-- A successful Invoke is not ownership proof. If its bounded replication grace
-- expires with the same egg still available, retain the transaction for a local
-- retry instead of treating the next pass as a fresh TrackStart departure.
RuntimeStatus.retainUnverifiedPickup = function(request)
    -- An accepted request still needs authoritative ownership before returning.
    if not sessionAlive() or type(request) ~= "table" then return false end
    local backend = request.movementBackend or Settings.StealMovementBackend
    if backend ~= "Glide" or request.owner ~= "Steal"
        or request.purpose == "tp-bait" or request.done ~= true
        or request.inFlight ~= false or request.accepted ~= true
        or request.carrySeen or request.carryEndedSeen or request.droppedSeen
        or request.claimSeen or request.cancelledByDeath
        or request.supersededByDrop or request.supersededByRecovery
        or request.character ~= LocalPlayer.Character
        or request.generation ~= stealRuntime.respawnGeneration
        or getgenv().__CHSAE_CarryRequest ~= request
        or tostring(stealRuntime.lockedUid) ~= tostring(request.uid)
        or resetWallClosed() or not Arb.hold("Steal") then return false end
    local now = os.clock()
    if now < (tonumber(request.proofDeadline) or math.huge) then return false end
    if stillCarrying(request.uid)
        or claimConfirmed(request.uid, request.category, request.claimSequenceAtStart) then
        return false
    end
    local root, humanoid = getCharParts()
    local live = findAreaEgg(request.uid)
    local state = live and tostring(live.State)
    local carrierId = live and tonumber(live.CarrierUserId)
    if not root or not humanoid or humanoid.Health <= 0
        or (lineSide(root.Position) or -1) <= 0
        or not live or not live.BottomCFrame or (state ~= "Slot" and state ~= "Dropped")
        or (carrierId ~= nil and carrierId > 0 and carrierId ~= LocalPlayer.UserId) then
        return false
    end
    stealRuntime.requestFailureUid = request.uid
    stealRuntime.requestFailureAt = now
    stealRuntime.lastRequestKind = "position-sync"
    stealRuntime.lastRequestError = "carry accepted but ownership not replicated"
    ProgressionCtl.treadmillSuppressed = true
    Arb.stealWants, Arb.critical = true, true
    Arb.stealBeat = now
    RuntimeStatus.pickupProofRetries = (RuntimeStatus.pickupProofRetries or 0) + 1
    return true
end

function RuntimeStatus.stealFeatureEnabled()
    return sessionAlive() and EggCmds
        and ((autoStealTgl and autoStealTgl.Value == true)
            or RuntimeStatus.riftCollecting == true
            or RuntimeStatus.greatBloomUnlockNeedsCrane())
end

local function carryLossRecoveryPending()
    local uid = stealRuntime.deathRecoveryUid or stealRuntime.lastDroppedUid
    local kind = tostring(stealRuntime.lastRequestKind or "")
    return uid ~= nil and tostring(stealRuntime.lockedUid) == tostring(uid)
        and (kind == "carry-loss-sync" or kind == "death-drop-sync" or kind == "carry-drop")
end
RuntimeStatus.carryLossRecoveryPending = carryLossRecoveryPending

-- Stop on the carry-loss edge before a stale field row can complete the return.
-- Near TrackStart this may be normal delivery: the caller checks exact claim
-- confirmation, and the worker waits for claim/drop evidence in place.
RuntimeStatus.carryLostInField = function(uid)
    if uid == nil or stillCarrying(uid) then return false end
    if RuntimeStatus.carryLossAwaitingProof(uid) then return true end
    local root = getCharParts()
    local side = root and lineSide(root.Position)
    return type(side) == "number" and side > 60
end

-- An egg already in hand, or a guard drop still being reclaimed, outranks a
-- momentary stealFeatureEnabled() dip. riftCollecting falls to false the
-- instant its field target leaves the field — which is the exact moment we picked
-- that egg up — so the plain check cancelled the run to the safe zone about a
-- tenth of a second after every Rift grab, stranding the egg mid-field.
-- The window is bounded, so a genuine Auto-Steal off still ends the worker once
-- the egg it was holding has been delivered.
RuntimeStatus.stealWorkerAlive = function()
    if RuntimeStatus.stealFeatureEnabled() then
        stealRuntime.featureGraceAt = 0
        return true
    end
    if not (carrying or carryLossRecoveryPending()) then
        stealRuntime.featureGraceAt = 0
        return false
    end
    local now = os.clock()
    if (tonumber(stealRuntime.featureGraceAt) or 0) <= 0 then
        stealRuntime.featureGraceAt = now
    end
    return now - stealRuntime.featureGraceAt <= stealRuntime.featureGrace
end

local function stealOn()
    if not RuntimeStatus.stealWorkerAlive() then return false end
    local recoveringCarryLoss = carryLossRecoveryPending()
    local committedSteal = Arb.owner == "Steal" and stealRuntime.lockedUid ~= nil
    -- Finish a real grab/carry, but stop an ordinary outbound target so the
    -- hatched Crane can take the shared Event body lane without starvation.
    if RuntimeStatus.greatBloomUnlockReturnHasPriority()
        and not recoveringCarryLoss
        and not carrying and not Arb.critical
        and not RuntimeStatus.carryRequestInFlight() then return false end
    if RuntimeStatus.adminEventHasPriority() and not recoveringCarryLoss
        and not committedSteal
        and (Arb.owner == "AdminEvent"
            or (not carrying and not Arb.critical
                and not RuntimeStatus.carryRequestInFlight())) then return false end
    local root, humanoid = getCharParts()
    if not (root and humanoid and humanoid.Health > 0) then return false end
    local ownsBody = Arb.hold("Steal")
    Arb.stealBeat = os.clock()   -- …and prove the steal loop is still alive
    return ownsBody
end

-- A movement cancellation is not a failed steal while the exact UID is still
-- owned by this player. Revalidate through the carry signal + authoritative
-- field record, clear any stale arbiter yield, and keep the transaction locked
-- for an immediate safe-zone retry. Only State=Dropped may enter re-pick logic.
RuntimeStatus.preserveCarriedReturn = function(uid, reason)
    if uid == nil or not RuntimeStatus.stealFeatureEnabled() then return false end
    local root, humanoid = getCharParts()
    if not (root and humanoid and humanoid.Health > 0) then return false end

    local graceDeadline = os.clock()
        + math.clamp(getNetworkPingSeconds() * 2 + 0.05, 0.12, 0.35)
    local held = false
    repeat
        if droppedAreaEgg(uid) then return false end
        if stillCarrying(uid) then
            held = true
            break
        end
        if os.clock() >= graceDeadline then break end
        RunService.Heartbeat:Wait()
    until not sessionAlive()
    if not held or not sessionAlive()
        or not RuntimeStatus.stealFeatureEnabled() then return false end

    local live = findAreaEgg(uid)
    carrying = true
    stealRuntime.carriedUid = uid
    stealRuntime.lockedUid = uid
    stealRuntime.rememberPositiveCarry(uid)
    if live and live.AreaId ~= nil then
        RuntimeStatus.activeGuardAreaId = tostring(live.AreaId)
    end
    local request = getgenv().__CHSAE_CarryRequest
    if type(request) == "table" and tostring(request.uid) == tostring(uid) then
        request.carrySeen = true
        request.carryActive = true
        request.carryEndedSeen = false
        request.droppedSeen = false
    end

    ProgressionCtl.treadmillSuppressed = true
    Arb.stealWants, Arb.critical = true, true
    Arb.stealBeat = os.clock()
    -- A protected carry outranks every unrelated body task. This also repairs an
    -- AdminEvent owner that slipped in during a missed-replication frame.
    if Arb.owner and Arb.owner ~= "Steal" then Arb.release(Arb.owner) end
    if not Arb.acquire("Steal") then return false end

    RuntimeStatus.returnResumeCount = (RuntimeStatus.returnResumeCount or 0) + 1
    RuntimeStatus.lastReturnResumeAt = os.clock()
    RuntimeStatus.lastReturnResumeReason = tostring(reason or "cancelled")
    RuntimeStatus.lastReturnResumeUid = uid
    RuntimeStatus.carry = "📦 Carry: verified · resuming home"
    return true
end

-- A bat/guard drop is still the same steal transaction. Keep the exact UID and
-- body ownership, then let the normal pickup path route from the current position
-- to the egg's new Dropped BottomCFrame. Persistent Steal is not required here.
local function armDroppedEggReacquire(uid, reason, authoritativeRecord)
    uid = uid or (os.clock() - (tonumber(stealRuntime.dropDetectedAt) or 0) <= 3
        and (stealRuntime.lastDroppedUid or stealRuntime.deathRecoveryUid) or nil)
    local authoritativeDrop = type(authoritativeRecord) == "table"
        and tostring(authoritativeRecord.State) == "Dropped"
        and authoritativeRecord.BottomCFrame ~= nil
        and (authoritativeRecord.Uid == nil
            or tostring(authoritativeRecord.Uid) == tostring(uid))
    if uid == nil or (not authoritativeDrop and not droppedAreaEgg(uid)) then return false end

    if authoritativeDrop then
        stealRuntime.dropRecoveryRecord = authoritativeRecord
        stealRuntime.dropRecoveryRecordUid = uid
        stealRuntime.dropRecoveryRecordAt = os.clock()
    end

    local newlyConfirmed = tostring(stealRuntime.lastRequestKind) ~= "carry-drop"
        or tostring(stealRuntime.lastDroppedUid) ~= tostring(uid)
    stealRuntime.lastDroppedUid = uid
    if (tonumber(stealRuntime.dropDetectedAt) or 0) <= 0 then
        stealRuntime.dropDetectedAt = os.clock()
    end
    if newlyConfirmed then
        stealRuntime.dropCount = (tonumber(stealRuntime.dropCount) or 0) + 1
    end
    -- Once this exact request produced a carried egg and the authoritative field
    -- record says Dropped, it is a completed old transaction even if InvokeServer
    -- is still yielding locally. Retire only that request so a fresh pickup is not
    -- blocked beside the egg; its late result is isolated below.
    local liveRequest = getgenv().__CHSAE_CarryRequest
    if type(liveRequest) == "table"
        and tostring(liveRequest.uid) == tostring(uid)
        and liveRequest.carrySeen == true then
        if liveRequest.inFlight then liveRequest.supersededByDrop = true end
        if getgenv().__CHSAE_CarryRequest == liveRequest then
            getgenv().__CHSAE_CarryRequest = nil
        end
    end
    stealRuntime.lockedUid = uid
    stealRuntime.requestFailureUid = uid
    stealRuntime.requestFailureAt = stealRuntime.dropDetectedAt
    stealRuntime.lastRequestKind = "carry-drop"
    stealRuntime.lastRequestError = tostring(reason or "egg dropped during return")
    RuntimeStatus.pendingDroppedUid = uid
    RuntimeStatus.dropReacquireArmedAt = os.clock()
    if Settings.PersistentSteal then stealRuntime.persistentUid = uid end

    carrying = false
    RuntimeStatus.carry = "📦 Carry: dropped · reclaiming"
    ProgressionCtl.treadmillSuppressed = true
    Arb.stealWants, Arb.critical = true, true
    Arb.stealBeat = os.clock()
    if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.25) end
    if wakeEggScanner then wakeEggScanner("reacquire-dropped-egg") end
    return true
end
RuntimeStatus.armDroppedEggReacquire = armDroppedEggReacquire

RuntimeStatus.activeDroppedRecoveryRecord = function(uid)
    local kind = tostring(stealRuntime.lastRequestKind or "")
    local exactLock = uid ~= nil
        and tostring(stealRuntime.lockedUid) == tostring(uid)
        and (tostring(stealRuntime.lastDroppedUid) == tostring(uid)
            or tostring(stealRuntime.deathRecoveryUid) == tostring(uid))
    if not exactLock or (kind ~= "carry-drop" and kind ~= "death-drop-sync"
        and kind ~= "carry-loss-sync") then return nil end
    local dropped = RuntimeStatus.getDroppedRecoveryRecord(uid)
    if dropped then return dropped end
    -- A fatal catch can restore the exact egg to Slot before the replacement
    -- character spawns. That is still this proven carry transaction, not a fresh
    -- target that should be staged through TrackStart again.
    local rec = findAreaEgg(uid)
    if (kind == "carry-drop" or kind == "death-drop-sync")
        and rec and tostring(rec.State) == "Slot" and rec.BottomCFrame then return rec end
    return nil
end

-- Exact dropped carries already own this transaction. Keep the normal retry
-- margin after a handoff/rejection; otherwise use a short replication window.
RuntimeStatus.droppedPickupSettle = function(uid, state, normal, ping, requiresFullSettle)
    if requiresFullSettle or state ~= "Dropped"
        or RuntimeStatus.activeDroppedRecoveryRecord(uid) == nil then return normal end
    return math.min(normal, math.clamp(ping * 1.5 + 0.08, 0.12, 0.30))
end

RuntimeStatus.reconcileCarryLossSnapshot = function(snapshot)
    local uid = stealRuntime.lastDroppedUid or stealRuntime.deathRecoveryUid
    if uid == nil then return end
    local records = type(snapshot) == "table" and (snapshot.Records or snapshot) or nil
    if type(records) ~= "table" then return end
    for _, rec in pairs(records) do
        local recUid = type(rec) == "table" and (rec.Uid or rec.UID or rec.EggUid) or nil
        if recUid ~= nil and tostring(recUid) == tostring(uid) then
            local carrierId = tonumber(rec.CarrierUserId)
            local recState = tostring(rec.State)
            local recoveryReady = ((recState == "Slot" or recState == "Dropped")
                    and rec.BottomCFrame ~= nil)
                or carrierId == LocalPlayer.UserId
            if tostring(stealRuntime.deathRecoveryUid) == tostring(uid) then
                if recoveryReady then
                    stealRuntime.deathRecoveryMissingAt = 0
                    stealRuntime.deathRecoveryMissingReason = ""
                elseif recState ~= "Claimed"
                    and not (carrierId ~= nil and carrierId > 0
                        and carrierId ~= LocalPlayer.UserId)
                    and (tonumber(stealRuntime.deathRecoveryMissingAt) or 0) <= 0 then
                    stealRuntime.deathRecoveryMissingAt = os.clock()
                    stealRuntime.deathRecoveryMissingReason = "snapshot-transitioning"
                end
            end
            if tostring(rec.State) == "Dropped" and rec.BottomCFrame then
                armDroppedEggReacquire(uid, "full snapshot confirmed dropped egg", rec)
            elseif tostring(stealRuntime.deathRecoveryUid) == tostring(uid)
                and tostring(rec.State) == "Slot" and rec.BottomCFrame then
                stealRuntime.lockedUid = uid
                if wakeEggScanner then wakeEggScanner("death-recovery-slot") end
            end
            return
        end
    end
    if tostring(stealRuntime.deathRecoveryUid) == tostring(uid) then
        if (tonumber(stealRuntime.deathRecoveryMissingAt) or 0) <= 0 then
            stealRuntime.deathRecoveryMissingAt = os.clock()
        end
        stealRuntime.deathRecoveryMissingReason = "snapshot-missing"
    end
end

-- [[ DELIVERY SPEED RUNTIME ]] --
function RuntimeStatus.getDeliverySpeed(mode)
    mode = mode or Settings.StealMovementType
    local key = mode == "Tween" and "TweenReturnSpeed" or "TPReturnSpeed"
    local speed = tonumber(Settings[key])
    if not speed or speed ~= speed or speed == math.huge or speed == -math.huge then
        speed = mode == "Tween" and 500 or 1000
    end
    return math.clamp(math.floor(speed + 0.5), 100, 1000)
end
function RuntimeStatus.setDeliverySpeed(value)
    local mode = Settings.StealMovementType == "Tween" and "Tween" or "TP"
    local speed = tonumber(value)
    if not speed or speed ~= speed or speed == math.huge or speed == -math.huge then
        speed = RuntimeStatus.getDeliverySpeed(mode)
    end
    speed = math.clamp(math.floor(speed + 0.5), 100, 1000)
    Settings[mode .. "ReturnSpeed"], Settings.StealSpeed = speed, speed
    return speed
end
-- [[ END DELIVERY SPEED RUNTIME ]] --

-- [[ DEVELOPMENT CHICKEN TWEEN ]] --
do
    local dev = { enabled = Settings.StealMovementType == "Tween", lease = nil, phase = "off", reason = "idle", launches = 0,
        engine = "TweenService CFrame" }
    if dev.enabled then dev.phase = "idle" end
    RuntimeStatus.DevChickenTween = dev
    function dev.alive(l)
        return (dev.enabled or l.delivery == true) and dev.lease == l and sessionAlive()
            and LocalPlayer.Character == l.character and l.root.Parent == l.character
            and l.original.Health > 0 and l.temporary.Health > 0
            and l.temporary.Parent == l.character and l.original.Parent == nil
            and not l.root.Anchored and Arb.owner == l.owner
            and os.clock() - l.lastUse < 45
            and ((l.progression and l.keepGoing()) or (not l.progression
                and (RuntimeStatus.stealFeatureEnabled()
                    or (l.rift and Settings.AutoRift == true and RuntimeStatus.stealWorkerAlive()))))
    end
    function dev.stopTween(l, hold)
        if l.tween then
            -- Heartbeat can finish the leg before PreSimulation observes its
            -- final displacement. Retain that speed for the pending sample only.
            l.pendingTweenSpeed = l.speed
            l.tween:Cancel()
            l.tween:Destroy()
            l.tween = nil
        end
        l.holdCFrame = hold and l.root.CFrame or nil
    end
    function dev.syncHandoff(l)
        -- Detached Humanoids cannot produce native movement samples. Rejoin at
        -- the actual landing before the integrity monitor evaluates normal walking.
        -- Never carry a frozen outbound history into a low-base-speed delivery.
        if l.handoffSynced then return true end
        local b = l.handoffBridge
        local state = b and b.state
        if LocalPlayer.Character ~= l.character or l.root.Parent ~= l.character
            or l.original.Parent ~= l.character or l.original.Health <= 0 then
            return true -- real death/respawn cleanup must not reset another rig
        end
        if not state or state.Character ~= l.character or state.RootPart ~= l.root
            or state.Humanoid ~= l.original then
            return true -- a replacement controller owns its own history
        end
        local sample = b.sample(state, os.clock(), l.original.WalkSpeed)
        if type(sample) ~= "table" or typeof(sample.Position) ~= "Vector3"
            or (sample.Position - l.root.Position).Magnitude > 0.01 then
            error("native handoff sample unavailable")
        end
        b.adopt(b.token, state, sample)
        l.handoffSynced = true
        dev.handoffCount = (dev.handoffCount or 0) + 1
        dev.handoffAt, dev.handoffSpeed = os.clock(), sample.WalkSpeed
        return true
    end
    function dev.holdAfterPhysics(l, dt)
        if dev.lease ~= l or l.cancelled or l.tween or not l.holdCFrame then return end
        if not dev.alive(l) then dev.restore("movement cancelled"); return end
        -- Pickup is evaluated after physics. PreSimulation alone leaves gravity
        -- velocity/drift in that sample, especially on slower or uneven frames.
        -- Hold only our stationary rig; active TweenService legs keep one writer.
        local drift = l.root.Position - l.holdCFrame.Position
        local elapsed = math.clamp(tonumber(dt) or 1 / 60, 0, 0.25)
        local verticalAllowance = math.max(3, (tonumber(workspace.Gravity) or 196.2) * elapsed * elapsed + 2)
        if (drift * Vector3.new(1, 0, 1)).Magnitude > 6 or math.abs(drift.Y) > verticalAllowance then
            dev.restore("character relocated during hold"); return
        end
        l.root.CFrame = l.holdCFrame
        l.root.AssemblyLinearVelocity, l.root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
    end
    function dev.restore(reason)
        local l = dev.lease
        dev.reason, dev.phase = reason or "restored", dev.enabled and "idle" or "off"
        if not l then return true end
        l.stopReason = l.stopReason or reason or "movement restored"
        l.cancelled = true
        if l.connection then l.connection:Disconnect(); l.connection = nil end
        if l.postConnection then l.postConnection:Disconnect(); l.postConnection = nil end
        -- Restore only the rig we borrowed. A respawn's Humanoid is never moved.
        local ok, err = pcall(function()
            dev.stopTween(l, false)
            if l.original.Parent == nil and l.character.Parent then
                l.original.Parent = l.character
            end
            if l.original.Parent ~= l.character and l.character.Parent then
                error("original Humanoid restoration unavailable")
            end
            local camera = workspace.CurrentCamera
            if camera and camera.CameraSubject == l.temporary then
                local current = LocalPlayer.Character
                camera.CameraSubject = current == l.character and l.original
                    or (current and current:FindFirstChildOfClass("Humanoid"))
            end
            l.temporary:Destroy()
            if LocalPlayer.Character == l.character and l.original.Parent == l.character then
                l.original.AutoRotate = l.autoRotate
                l.original.PlatformStand, l.original.Sit = l.platformStand, l.sit
                l.original.WalkSpeed = l.walkSpeed
                l.root.AssemblyLinearVelocity, l.root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
                l.original:Move(Vector3.zero, false)
                dev.syncHandoff(l)
                if l.original.Health > 0 and not l.platformStand and not l.sit then
                    l.original:ChangeState(Enum.HumanoidStateType.Running)
                end
                if l.animate and l.animate.Parent == l.character and l.animateDisabled ~= nil then
                    if l.animateDisabled == false then
                        local animator = l.original:FindFirstChildOfClass("Animator")
                        if animator then
                            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do track:Stop(0) end
                        end
                    end
                    l.animate.Disabled = l.animateDisabled
                end
            end
        end)
        if not ok then
            dev.reason = "restore failed: " .. tostring(err)
            return false -- retain the lease so watchdog/unload can retry
        end
        dev.lease = nil
        return true
    end
    function dev.begin(delivery, owner, keepGoing)
        owner = owner or "Steal"
        local progression = owner == "Place" or owner == "Treadmill"
        if owner ~= "Steal" and not progression then return false, "invalid movement owner" end
        if progression and (type(keepGoing) ~= "function" or not keepGoing()) then return false, "cancelled" end
        if dev.lease and dev.lease.owner ~= owner then return false, "another movement owns the rig" end
        if not dev.enabled and delivery ~= true then return false, "development movement disabled" end
        if dev.lease and dev.alive(dev.lease) then
            if delivery then dev.lease.delivery = true end
            return true
        end
        if not dev.restore("starting") then return false, dev.reason end
        local root, original = getCharParts()
        local character = LocalPlayer.Character
        local rift = type(stealRuntime.webhookTarget) == "table" and stealRuntime.webhookTarget.source == "rift"
        if not root or not original or original.Health <= 0 or root.Anchored
            or Arb.owner ~= owner or not (progression or RuntimeStatus.stealFeatureEnabled()
                or (delivery and rift and Settings.AutoRift == true and RuntimeStatus.stealWorkerAlive())) then
            return false, "character activity unavailable"
        end
        -- Do not borrow a replacement Humanoid owned by another automation.
        local state = integrityState
        if state and state.RootPart == root and state.Humanoid ~= original then
            return false, "another movement controller owns the Humanoid"
        end
        -- Resolve the native capability while the original Humanoid still belongs
        -- to the character. Restoration uses this exact bridge without yielding.
        local handoffBridge = integrityBridge
        if not handoffBridge or not handoffBridge.state or handoffBridge.state.Character ~= character
            or handoffBridge.state.RootPart ~= root or handoffBridge.state.Humanoid ~= original then
            handoffBridge = RuntimeStatus.findMovementDispatcher(root, original)
        end
        if not handoffBridge or not handoffBridge.token
            or type(handoffBridge.sample) ~= "function" or type(handoffBridge.adopt) ~= "function" then
            return false, "native movement handoff unavailable"
        end
        local archivable = original.Archivable
        local ok, temporary = pcall(function()
            original.Archivable = true
            return original:Clone()
        end)
        original.Archivable = archivable
        if not ok or not temporary then return false, "Humanoid clone unavailable" end
        temporary.Name, temporary.BreakJointsOnDeath = "Humanoid", false
        temporary.PlatformStand, temporary.AutoRotate = false, false
        local l = { character = character, root = root, original = original,
            owner = owner, progression = progression, keepGoing = keepGoing,
            temporary = temporary, delivery = delivery == true, rift = rift,
            handoffBridge = handoffBridge,
            movementType = Settings.StealMovementType,
            goal = root.Position, speed = 500, lastUse = os.clock(),
            autoRotate = original.AutoRotate, platformStand = original.PlatformStand,
            sit = original.Sit, walkSpeed = original.WalkSpeed,
            animate = character:FindFirstChild("Animate"),
            holdCFrame = root.CFrame, observed = root.Position, observedAt = os.clock() }
        dev.lease = l
        ok, temporary = pcall(function()
            -- Animate caches its Humanoid. Suspend it before detaching that
            -- Humanoid, then restart it only after the original rig is back.
            if l.animate then
                l.animateDisabled = l.animate.Disabled
                l.animate.Disabled = true
            end
            original.Parent = nil
            l.temporary.Parent = character
            local camera = workspace.CurrentCamera
            if camera and camera.CameraSubject == original then camera.CameraSubject = l.temporary end
        end)
        if not ok then dev.restore("clone setup failed"); return false, tostring(temporary) end
        local function step()
            if not dev.alive(l) or l.cancelled then dev.restore("movement cancelled"); return end
            local now = os.clock()
            local sampleSpeed = l.tween and l.speed or l.pendingTweenSpeed or 0
            local allowance = sampleSpeed * (math.max(0, now - l.observedAt) + 1 / 30)
            if (root.Position - l.observed).Magnitude > 80 + allowance then
                dev.restore("character relocated"); return
            end
            l.observed, l.observedAt = root.Position, now
            l.pendingTweenSpeed = nil
            -- TweenService is the only CFrame writer during an active leg.
            -- Stationary holds keep the bait/pickup wait from accumulating gravity.
            if l.tween then
                if l.tween.PlaybackState == Enum.PlaybackState.Cancelled then
                    dev.restore("engine tween cancelled"); return
                end
            elseif l.holdCFrame then
                root.CFrame = l.holdCFrame
            end
            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
        end
        l.connection = RunService.PreSimulation:Connect(function(dt)
            local stepped, err = pcall(step, dt)
            if not stepped then dev.restore("movement frame failed: " .. tostring(err)) end
        end)
        l.postConnection = RunService.PostSimulation:Connect(function(dt)
            local held, err = pcall(dev.holdAfterPhysics, l, dt)
            if not held then dev.restore("hold frame failed: " .. tostring(err)) end
        end)
        dev.phase, dev.reason = "staging", "temporary Humanoid active"
        return true
    end
    function dev.move(pos, reach, keepGoing, onReached, abortFn, speed)
        local l = dev.lease
        if not l or not dev.alive(l) then return false, "development rig unavailable" end
        local ticket = {}
        local ok, reached, reason = pcall(function()
            dev.stopTween(l, true)
            l.ticket, l.goal, l.speed = ticket, pos, speed or 500
            if l.speed <= 0 or l.speed ~= l.speed or l.speed == math.huge then return false, "invalid tween speed" end
            if not keepGoing() or (abortFn and abortFn()) then return false, "cancelled" end
            if onReached and onReached() then return true end
            local distance = (pos - l.root.Position).Magnitude
            if distance <= (reach or 0.35) then return true end
            local duration = distance / l.speed
            local deadline = os.clock() + duration + 4
            l.observed, l.observedAt = l.root.Position, os.clock()
            l.pendingTweenSpeed = nil
            l.tween = TweenService:Create(l.root, TweenInfo.new(duration, Enum.EasingStyle.Linear),
                { CFrame = CFrame.new(pos) * l.root.CFrame.Rotation })
            l.holdCFrame = nil
            l.tween:Play()
            local completedAt
            while dev.alive(l) and l.ticket == ticket and not l.cancelled do
                l.lastUse = os.clock()
                if not keepGoing() or (abortFn and abortFn()) then return false, "cancelled" end
                if onReached and onReached() then return true end
                if (l.root.Position - pos).Magnitude <= (reach or 0.35) then return true end
                local playback = l.tween and l.tween.PlaybackState
                if playback == Enum.PlaybackState.Cancelled then return false, "engine tween cancelled" end
                if playback == Enum.PlaybackState.Completed then
                    completedAt = completedAt or os.clock()
                    local settle = math.clamp((RuntimeStatus.clientFrameSeconds or 1 / 60) * 3, 0.08, 0.25)
                    if os.clock() - completedAt >= settle then return false, "tween ended away from goal" end
                end
                if os.clock() >= deadline then return false, "movement timeout" end
                RunService.Heartbeat:Wait()
            end
            if l.stopReason then return false, l.stopReason end
            if l.ticket ~= ticket then return false, "tween superseded" end
            if LocalPlayer.Character ~= l.character then return false, "character changed" end
            if l.original.Health <= 0 or l.temporary.Health <= 0 then return false, "character died" end
            if l.root.Anchored then return false, "character anchored" end
            if Arb.owner ~= l.owner then return false, "movement ownership lost" end
            return false, "tween rig released"
        end)
        if not ok then
            if dev.lease == l and l.ticket == ticket then
                dev.restore("tween error: " .. tostring(reached))
            end
            return false, tostring(reached)
        end
        -- A superseding move owns its own tween; the old waiter must not cancel it.
        if dev.lease == l and l.ticket == ticket then
            local stopped, err = pcall(dev.stopTween, l, true)
            if not stopped then dev.restore("tween cleanup failed"); return false, tostring(err) end
        end
        return reached, reason
    end
    function dev.groundMove(pos, reach, keepGoing, onReached, abortFn, speed)
        local l = dev.lease
        if not l then return false, "development rig unavailable" end
        local y = groundY(pos.X, pos.Z, pos.Y) or pos.Y
        return dev.move(Vector3.new(pos.X, y, pos.Z), reach, keepGoing, onReached, abortFn, speed or 500)
    end
    function dev.pickupHeightReady(pos)
        local l = dev.lease
        if not l then return true end
        local y = groundY(pos.X, pos.Z, pos.Y) or pos.Y
        return dev.alive(l) and math.abs(l.root.Position.Y - y) <= 1.5
    end
    function dev.recoverDrop(pos, reach, keepGoing, onReached, abortFn)
        if not keepGoing() or (abortFn and abortFn()) then return false, "cancelled" end
        local ready, reason = dev.begin(dev.lease and dev.lease.delivery)
        if not ready then return false, reason end
        local l = dev.lease
        -- Sample from the egg's plane: the raised return plane intentionally
        -- rejects a large ground-height change in the ordinary Glide sampler.
        local y = groundY(pos.X, pos.Z, pos.Y) or pos.Y
        l.returnHeight = l.returnHeight or math.max(l.root.Position.Y, y + 21)
        dev.phase = "drop descent"
        local lowered
        lowered, reason = dev.move(Vector3.new(l.root.Position.X, y, l.root.Position.Z),
            0.35, keepGoing, nil, abortFn, 500)
        if not lowered then return false, reason end
        dev.phase = "drop approach"
        return dev.move(Vector3.new(pos.X, y, pos.Z), reach, keepGoing, onReached, abortFn, 500)
        -- Carry proof is owned by the worker. Only returnHome raises the rig again.
    end
    function dev.launch(t, valid)
        local outboundSpeed = RuntimeStatus.getDeliverySpeed("Tween")
        if not t.hitAttempted or not valid() then return false, "chicken hit required" end
        -- Keep the native rig through entry and confirmed bait pickup. Borrow
        -- the Tween rig only when this transaction actually starts its flight.
        local ready, issue = dev.begin()
        if not ready then return false, issue end
        RuntimeStatus.recoverChickenLanding(t)
        local burst = Settings.BurstTween == true
        local start = t.root.Position
        local y = groundY(t.targetPosition.X, t.targetPosition.Z, start.Y) or start.Y
        local target = Vector3.new(t.targetPosition.X, y, t.targetPosition.Z)
        local delta = target - start
        local reached, reason
        if burst then
            -- Preserve the existing 5,000 stud/s burst and 500 stud/s approach.
            dev.phase = "fast outbound"
            local waypoint = delta.Magnitude > 2830 and start + delta.Unit * 2830 or target
            reached, reason = dev.move(waypoint, 0.35, valid, nil, t.abortFn, 5000)
            if not reached then return false, reason end
            dev.phase = "target approach"
            reached, reason = dev.move(target, 0.35, valid, nil, t.abortFn, 500)
        else
            -- Sample once per departure: one linear tween, no fast first leg
            -- or hardcoded slowdown near the egg. Return speed is independent.
            dev.phase = "outbound"
            reached, reason = dev.move(target, 0.35, valid, nil, t.abortFn, outboundSpeed)
        end
        if reached then
            dev.phase, dev.launches = "recovery wait", dev.launches + 1
            t.developmentReadyAt = math.max(os.clock(), t.hitAt + 3.1)
        end
        return reached, reason
    end
    function dev.returnHome(keepGoing, abortFn, guardAreaId)
        local l, track = dev.lease, RuntimeStatus.getTrackStart()
        if not l or not track then return false, "development return unavailable" end
        local root = l.root
        local reached, reason
        local route = Settings.StealRoute
        local raised = route == "Fly"
        if raised then
            -- Optional raised method keeps the same plane across carry losses.
            l.returnHeight = l.returnHeight or (root.Position.Y + 21)
            local height = l.returnHeight
            dev.phase = "return lift"
            reached, reason = dev.move(Vector3.new(root.Position.X, height, root.Position.Z),
                0.35, keepGoing, nil, abortFn, RuntimeStatus.getDeliverySpeed(l.movementType))
            if not reached then return false, reason end
            dev.phase = "raised return"
            reached, reason = dev.move(Vector3.new(track.Position.X, height, track.Position.Z),
                0.35, keepGoing, nil, abortFn, RuntimeStatus.getDeliverySpeed(l.movementType))
            if not reached then return false, reason end
        end
        if route == "Turbo Hybrid" then
            -- Reuse the exact owning-guard plan with the shared TweenService
            -- mover. The legacy route dispatcher is no longer on this path.
            local previousPhase = RuntimeStatus.movementPhase
            RuntimeStatus.movementPhase = "return"
            local planned, points = pcall(RuntimeStatus.guardRoutePoints,
                root.Position, track.Position, guardAreaId)
            RuntimeStatus.movementPhase = previousPhase
            if not planned then return false, "guard route unavailable: " .. tostring(points) end
            for _, waypoint in ipairs(points) do
                dev.phase = "guard evade"
                reached, reason = dev.groundMove(waypoint, 3.5, keepGoing, nil, abortFn,
                    RuntimeStatus.getDeliverySpeed(l.movementType))
                if not reached then return false, reason end
            end
        end
        -- Every method finishes at the same centered TrackStart claim point.
        dev.phase = raised and "TrackStart descent" or (route == "Turbo Hybrid" and "guard return" or "direct return")
        local landing = track.Position + Vector3.new(0, 3, 0)
        reached, reason = dev.groundMove(landing, 0.35, keepGoing, nil, abortFn, RuntimeStatus.getDeliverySpeed(l.movementType))
        if not reached then return false, reason end
        -- The ordinary carry worker retains ownership and verifies the actual claim.
        if not dev.restore("waiting for claim") then return false, dev.reason end
        dev.phase = "claim wait"
        return true
    end
    -- Shared TweenService leg for pen/training, under their own body owner.
    -- Restore the original rig before native placement or treadmill mounting.
    RuntimeStatus.progressionTweenTo = function(owner, pos, reach, keepGoing)
        if owner ~= "Place" and owner ~= "Treadmill" then return false, "invalid progression owner" end
        if dev.lease then return false, "movement restoration pending" end
        if not keepGoing() then return false, "cancelled" end
        local root = getCharParts()
        if not root then return false, "character unavailable" end
        local y = groundY(pos.X, pos.Z, pos.Y) or pos.Y
        local target = Vector3.new(pos.X, y, pos.Z)
        if (root.Position - target).Magnitude <= reach then return true end
        local ready, reason = dev.begin(true, owner, keepGoing)
        if not ready then return false, reason end
        local lease = dev.lease
        local ok, reached, issue = pcall(dev.move, target, reach, keepGoing, nil, nil, 500)
        if dev.lease == lease and not dev.restore("progression arrival") then return false, dev.reason end
        if not ok then return false, tostring(reached) end
        return reached, issue
    end
    function dev.setEnabled(value)
        -- Changing movers cancels the exact transaction before another can start.
        dev.enabled = value == true
        local tp = RuntimeStatus.ChickenTP
        if tp and tp.active then tp.active.failure = "movement toggle changed" end
        local restored = dev.restore("movement toggle changed")
        if wakeEggScanner then wakeEggScanner("development movement") end
        return restored
    end
    getgenv().__CHSAE_TPRestore = function(reason) return dev.restore(reason or "unload") end
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = RunService.Heartbeat:Connect(function()
        local l = dev.lease
        if l and (l.cancelled or not dev.alive(l)) then dev.restore("movement cancelled") end
    end)
end
-- [[ END DEVELOPMENT CHICKEN TWEEN ]] --

-- [[ CHICKEN TP TRANSACTION ]] --
do
    local createChickenTP = function(d)
    local m = { active = nil, retired = {}, jumps = 0, baitJumps = 0, contactJumps = 0,
        baitApproaches = 0, contactApproaches = 0, hitReports = 0, stages = 0, completed = 0, lastReason = "idle" }
    local function same(a, b) return a ~= nil and b ~= nil and tostring(a) == tostring(b) end
    local function tagged(r) return type(r) == "table" and r.purpose == "chicken-bait" end
    local function alive(t)
        return m.active == t and d.sessionAlive() and d.selected()
            and d.sameCharacter(t) and d.owns() and t.keepGoing()
            and not (t.abortFn and t.abortFn()) and not d.wallClosed()
    end
    local function retire(t, reason)
        if m.active == t then m.active = nil end
        m.retired[tostring(t.bait.Uid)] = d.now() + 15
        m.lastReason = reason
        if t.request then t.request.abandoned = not t.landedAt end
    end
    function m.isBait(uid)
        if uid == nil then return false end
        local r = d.pending()
        if tagged(r) and same(r.uid, uid) then return true end
        if type(r) == "table" and not tagged(r) and same(r.uid, uid) then return false end
        if m.active and same(m.active.bait.Uid, uid) then return true end
        local expiry = m.retired[tostring(uid)]
        if expiry and expiry > d.now() then return true end
        m.retired[tostring(uid)] = nil
        return false
    end
    function m.observeCarry(s)
        if type(s) ~= "table" then return false end
        local r = d.pending()
        if not tagged(r) then return false end
        if s.IsCarrying == true then
            if not same(s.Uid, r.uid) then return false end
            r.carrySeen, r.carryActive, r.carryEndedSeen = true, true, false
            return true
        end
        if s.IsCarrying == false and (same(s.Uid, r.uid)
            or (s.Uid == nil and r.carryActive == true)) then
            r.carryActive, r.carryEndedSeen = false, true
            return true
        end
        return false
    end
    function m.servicePending()
        local r = d.pending()
        if not tagged(r) or (m.active and m.active.request == r) then return false end
        if r.inFlight or r.cleanupInFlight then return true end
        if not d.requestCharacterAlive(r) then d.release(r) return false end
        local held = d.heldUid()
        if same(held, r.uid) then
            if (r.cleanupRetryAt or 0) > d.now() then return true end
            if (r.cleanupAttempts or 0) >= 3 then
                m.retired[tostring(r.uid)] = nil
                m.lastReason = "bait drop rejected; ordinary carry recovery"
                d.release(r)
                return false
            end
            r.cleanupAttempts = (r.cleanupAttempts or 0) + 1
            r.cleanupInFlight, r.inFlight = true, true
            -- The native drop has no UID argument. The adapter rechecks exact
            -- ownership immediately before invoking while the shared lock is held.
            d.drop(r, function()
                r.cleanupInFlight, r.inFlight = false, false
                r.cleanupRetryAt = d.now() + 0.75
                r.proofDeadline = d.now() + 1.5
            end)
            return true
        end
        if r.accepted and not r.carryEndedSeen and d.now() < (r.proofDeadline or 0) then
            return true
        end
        d.release(r)
        return false
    end
    function m.observeClaim(feedback)
        local r = d.pending()
        if not tagged(r) or not r.carrySeen then return false end
        local uid = type(feedback) == "table" and (feedback.Uid or feedback.UID or feedback.EggUid)
        if uid ~= nil and not same(uid, r.uid) then return false end
        r.claimSeen, r.carryEndedSeen, r.carryActive = true, true, false
        if m.active and m.active.request == r then m.active.failure = "chicken bait was claimed" end
        return true
    end
    local function startHitMovement(t)
        t.hitAttempted, t.hitAt = true, d.now()
        if t.development and d.travel then
            t.phase = "travel" -- the worker yields; the native attack callback never does
            return true
        end
        local ok, reason = d.relocate(t)
        if not ok then t.failure = reason or "chicken relocation failed" return false end
        t.landedAt, t.phase = d.now(), "landing"
        m.jumps += 1
        return true
    end
    function m.noteHit(hit)
        local t = m.active
        if not t or t.phase ~= "contact" or t.hitAttempted or not alive(t)
            or type(hit) ~= "table" or not d.ourHit(hit)
            or not same(hit.EggUid, t.bait.Uid) or not t.request
            or not (t.request.carrySeen or same(d.heldUid(), t.bait.Uid))
            or not d.nearChicken(t) or not d.targetAvailable(t.targetUid) then return false end
        return startHitMovement(t)
    end
    function m.reportHit(t)
        if m.active ~= t or not alive(t) or t.phase ~= "contact" or t.hitAttempted
            or t.hitReportAttempted or not t.request or not t.request.carrySeen
            or t.request.carryEndedSeen or not same(d.heldUid(), t.bait.Uid)
            or not d.targetAvailable(t.targetUid) then return false, "bait hit report unavailable" end
        -- One dispatch per transaction. A successful FireServer only proves a
        -- report was sent; replicated carry release/recovery still gate pickup.
        t.hitReportAttempted = true
        local ok, sent, reason = pcall(d.reportHit, t)
        if not ok or not sent then
            return false, ok and (reason or "bait hit report failed") or tostring(sent)
        end
        t.hitReportedAt = d.now()
        m.hitReports += 1
        if not alive(t) then return false, "bait hit report cancelled" end
        if t.hitAttempted then return not t.failure, t.failure end
        local started = startHitMovement(t)
        return started, t.failure
    end
    function m.pickupDelay(uid, default)
        local l = m.landing
        if l and same(l.uid, uid) and d.requestCharacterAlive(l)
            and d.now() >= l.readyAt then return 0 end
        return default
    end
    function m.isLandingProtected(character)
        local t = m.active
        if t and t.development and t.phase == "travel" and t.hitAt then
            return t.character == character and not t.failure and alive(t)
                and d.now() - t.hitAt < 30
        end
        return t ~= nil and t.phase == "landing" and t.landedAt ~= nil
            and not t.failure and t.character == character
            and d.now() - t.landedAt <= 3.5 and alive(t)
    end
    function m.maintainLanding()
        local t = m.active
        if not t or t.phase ~= "landing" or t.failure or not alive(t) then return false end
        local ok, held, reason = pcall(d.hold, t)
        if not ok or not held then
            t.failure = ok and (reason or "landing interrupted") or tostring(held)
            return false
        end
        return true
    end
    function m.move(uid, pos, reach, keepGoing, onReached, abortFn)
        if not d.selected() then return nil end
        m.retired[tostring(uid)] = nil
        if onReached and onReached() then return true end
        if not d.targetAvailable(uid) or d.heldUid() ~= nil then return false, "target unavailable" end
        if m.servicePending() or d.pending() ~= nil then return false, "carry request busy" end
        local landing = m.landing
        if landing and same(landing.uid, uid) and d.requestCharacterAlive(landing)
            and d.now() >= landing.readyAt and d.now() - landing.readyAt <= 6
            and d.retryingTarget(uid) then
            m.lastReason = "confirmed landing; local pickup retry"
            return nil, "pickup-retry"
        end
        m.landing = nil
        local character, root = d.character()
        if not character or not root then return false, "character unavailable" end
        local probe = {character=character,root=root,generation=d.generation()}
        local bait, bridge, nextProbe, waiting = nil, nil, 0, nil
        local deadline = d.now()+8
        -- Stay in this lightweight wait instead of restarting the full selector,
        -- tool arbitration and route setup every 0.35s when bait is unavailable.
        while d.now()<deadline do
            if not d.sessionAlive() or not d.selected() or not d.sameCharacter(probe)
                or not keepGoing() or (abortFn and abortFn()) or d.wallClosed()
                or not d.owns() then return false,"cancelled" end
            if d.now()>=nextProbe then
                if not d.targetAvailable(uid) or d.heldUid()~=nil then return false,"target unavailable" end
                bait=d.findBait(uid)
                bridge=bait and d.bridge() or nil
                if bait and bridge then break end
                local reason=bait and ((d.bridgeReason and d.bridgeReason()) or "waiting for relocation API") or "waiting for Forest bait"
                m.lastReason=reason
                if waiting~=reason then d.status("TP · "..reason); waiting=reason end
                nextProbe=d.now()+1
            end
            d.wait()
        end
        if not bait or not bridge then return false,m.lastReason end
        local t = {
            targetUid = uid, targetPosition = pos, bait = bait, bridge = bridge,
            character = character, root = root, generation = d.generation(),
            keepGoing = keepGoing, abortFn = abortFn, phase = "staging",
        }
        m.active = t
        local function valid() return alive(t) end
        local function fail(reason)
            m.lastFailurePhase, m.lastFailureReason = t.phase, reason or "cancelled"
            if d.failed then d.failed(t, reason) end
            retire(t, reason or "cancelled")
            m.servicePending()
            return false, reason or "cancelled"
        end
        if not d.reserve(valid) or not valid() then return fail("character activity busy") end
        d.status("↩️ TP · tweening to TrackStart")
        local staged, stageReason = d.stage(t, valid)
        if not staged or not valid() then return fail(stageReason or "TrackStart staging interrupted") end
        m.stages += 1
        local function preparePickup(attempt)
            if not d.toolFree() or not valid() then return false, "chicken pickup unavailable" end
            if d.baitSnapshot then
                bait = d.baitSnapshot(t.bait.Uid)
                if not bait then return false, "chicken bait unavailable" end
                t.bait = bait
            end
            t.phase = "approach"
            d.status("TP · approaching bait")
            local reached, reason = d.approachBait(t, valid)
            if not reached or not valid() then return false, reason end
            m.baitApproaches += 1
            local stableSince, previous
            local stableWindow = d.pickupSettleWindow and d.pickupSettleWindow(attempt, m.completed == 0) or 0.35
            local deadline = d.now() + 8 -- one bounded native readiness/settle phase
            while valid() and d.now() < deadline do
                if d.baitSnapshot then
                    local live = d.baitSnapshot(bait.Uid)
                    if not live then return false, "chicken bait unavailable" end
                    local moved = (live.BottomCFrame.Position - bait.BottomCFrame.Position).Magnitude > 0.35
                    bait, t.bait = live, live
                    if moved then
                        stableSince, previous = nil, nil
                        local aligned, issue = d.approachBait(t, function() return valid() and d.now() < deadline end)
                        if not aligned then return false, issue or "chicken bait moved" end
                    end
                end
                local position = d.position(root)
                local ready, readinessReason = true, nil
                if d.pickupReady then ready, readinessReason = d.pickupReady(t) end
                t.readinessReason = readinessReason
                if ready and d.stationary(root, previous, bait.BottomCFrame.Position, 0.35) then
                    stableSince = stableSince or d.now()
                    if d.now() - stableSince >= stableWindow then break end
                else stableSince = nil end
                previous = position
                d.brake(root)
                d.wait()
            end
            if not valid() or not stableSince or d.now() - stableSince < stableWindow then
                return false, t.readinessReason or "chicken pickup did not settle"
            end
            if not d.baitAvailable(bait.Uid) then return false, "chicken pickup unavailable" end
            if not valid() then return false, "cancelled" end
            return true
        end
        local r
        local function sendPickup()
            r = {
                purpose = "chicken-bait", owner = "Steal", uid = bait.Uid,
                category = bait.AssetCategory, character = character, generation = t.generation,
                started = d.now(), inFlight = true, done = false, accepted = false,
                carrySeen = false, carryActive = false, carryEndedSeen = false,
                movementBackend = "Glide", attempts = t.pickupAttempts,
            }
            if not d.publish(r) then return false, "carry request busy" end
            t.request, t.phase = r, "contact"
            d.allowChickenReaction()
            d.request(bait, r)
            return true
        end
        t.pickupAttempts = 1
        local prepared, prepareReason = preparePickup(t.pickupAttempts)
        if not prepared then return fail(prepareReason) end
        local published, publishReason = sendPickup()
        if not published then return fail(publishReason) end
        d.status("TP · confirming bait for hit report")
        local deadline = d.now() + 8
        t.contactDeadline = deadline
        -- Bait preparation ends at one confirmed carry and one hit report.
        -- Target travel is a separate phase; it cannot re-enter this pickup loop.
        while valid() and d.now() < deadline and not t.hitAttempted and not t.failure do
            if not r.carrySeen and same(d.heldUid(), bait.Uid) then
                r.carrySeen, r.carryActive = true, true
            end
            if r.done and not r.accepted and not r.carrySeen then
                -- Retry only a completed, explicit server proximity rejection.
                -- Unknown transport outcomes and in-flight invokes keep one lock.
                if t.pickupAttempts >= 3 or not d.canRetryBait or not d.canRetryBait(r) then
                    return fail(r.error or "chicken pickup rejected")
                end
                d.release(r)
                t.pickupAttempts += 1
                m.baitRetries = (m.baitRetries or 0) + 1
                d.status("TP · syncing bait pickup " .. tostring(t.pickupAttempts) .. "/3")
                local prepared, issue = preparePickup(t.pickupAttempts)
                if not prepared then return fail(issue) end
                local published, publishIssue = sendPickup()
                if not published then return fail(publishIssue) end
                deadline = d.now() + 8
                t.contactDeadline = deadline
                continue
            end
            if r.carrySeen and not t.hitAttempted then
                local started, hitReason = m.reportHit(t)
                if not started then return fail(hitReason or "bait hit report failed") end
            end
            if not t.landedAt then d.wait() end
        end
        if t.failure then return fail(t.failure) end
        if not valid() or not t.hitAttempted then return fail("chicken hit timed out or cancelled") end
        if t.development then
            d.status("Tween · moving to target egg")
            local travelled, travelReason = d.travel(t, valid)
            if not travelled or not valid() then return fail(travelReason or "target tween interrupted") end
            t.landedAt, t.phase = d.now(), "landing"
        end
        if not t.landedAt then return fail("target arrival unavailable") end
        d.status("TP · settling before target pickup")
        -- Observe recovery instead of imposing a fixed three-second floor.
        -- Carry release and native recovery must remain ready across a short
        -- replication window; any renewed reaction restarts that window.
        local readySince
        local recoverySettle = d.landingSettleWindow()
        deadline = t.landedAt + 8
        while valid() and d.now() < deadline do
            if t.failure then return fail(t.failure) end
            if not d.targetAvailable(uid) then return fail("target changed during landing") end
            local held = d.heldUid()
            if held ~= nil and not same(held, bait.Uid) then return fail("different egg carried") end
            local heldOk, holdReason = d.hold(t)
            if not heldOk then return fail(holdReason or "landing interrupted") end
            if not r.inFlight and r.carryEndedSeen
                and held == nil and d.reactionFinished(t) then
                readySince = readySince or d.now()
            else
                readySince = nil
            end
            if readySince and d.now() - readySince >= recoverySettle then
                -- A local strike callback precedes the replicated knockdown.
                -- Elapsed time alone cannot prove that pickup is available.
                local aligned, alignReason = d.alignTarget(t, function()
                    return valid() and d.now() < deadline and d.reactionFinished(t)
                end)
                if not aligned or not valid() or not d.reactionFinished(t) then
                    return fail(alignReason or "chicken recovery interrupted")
                end
                m.landing = { uid = uid, character = character, generation = t.generation, readyAt = d.now() }
                retire(t, "chicken jump settled; Glide return")
                d.release(r)
                m.completed += 1
                return true
            end
            d.wait()
        end
        return fail("chicken release or landing timed out")
    end
    return m
end

    local deps = {}
    deps.now = os.clock
    deps.sessionAlive = sessionAlive
    deps.selected = function() return true end
    deps.generation = function() return stealRuntime.respawnGeneration end
    deps.character = function()
        local root = getCharParts()
        return LocalPlayer.Character, root
    end
    deps.sameCharacter = function(t)
        local root, humanoid = getCharParts()
        return LocalPlayer.Character == t.character and root == t.root
            and stealRuntime.respawnGeneration == t.generation
            and humanoid ~= nil and humanoid.Health > 0
    end
    deps.requestCharacterAlive = function(r)
        local root, humanoid = getCharParts()
        return LocalPlayer.Character == r.character and root ~= nil
            and stealRuntime.respawnGeneration == r.generation
            and humanoid ~= nil and humanoid.Health > 0
    end
    deps.owns = function() return Arb.hold("Steal") end
    deps.wallClosed = resetWallClosed
    deps.wait = function() RunService.Heartbeat:Wait() end
    deps.position = function(root) return root.Position end
    deps.move = moveTo
    deps.brake = RuntimeStatus.brakeGlidePickup
    deps.stationary = function(root, previous, target, reach)
        local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        return humanoid ~= nil and math.abs(root.Position.Y - target.Y) <= 6
            and RuntimeStatus.glidePickupStationary(root, humanoid,
            previous, ((root.Position - target) * Vector3.new(1, 0, 1)).Magnitude, reach)
    end
    deps.pending = function() return getgenv().__CHSAE_CarryRequest end
    deps.publish = function(r)
        if getgenv().__CHSAE_CarryRequest ~= nil then return false end
        r.session = SESSION.Marker
        getgenv().__CHSAE_CarryRequest = r
        return true
    end
    deps.release = function(r)
        if getgenv().__CHSAE_CarryRequest == r and not r.inFlight then
            getgenv().__CHSAE_CarryRequest = nil
        end
    end
    deps.heldUid = function()
        for _, rec in pairs(areaEggRecords()) do
            local state = tostring(rec.State)
            if state ~= "Dropped" and state ~= "GuardCarried" and state ~= "Claimed"
                and tonumber(rec.CarrierUserId) == LocalPlayer.UserId then return rec.Uid end
        end
        return nil
    end
    deps.targetAvailable = function(uid)
        local rec = findAreaEgg(uid)
        local state = rec and tostring(rec.State)
        -- Target selection owns area policy. Its existing speed requirement is
        -- advisory; reapplying it here rejected valid selected eggs forever.
        return rec ~= nil and rec.BottomCFrame ~= nil
            and (state == "Slot" or state == "Dropped")
    end
    deps.baitSnapshot = function(uid)
        local rec = findAreaEgg(uid)
        if rec and tostring(rec.State) == "Slot" and rec.BottomCFrame then return table.clone(rec) end
        return nil
    end
    deps.pickupSettleWindow = function(attempt, firstCycle)
        return math.clamp(math.max(firstCycle and 0.6 or 0.35,
            getNetworkPingSeconds() * 2 + 0.15) + (attempt - 1) * 0.25, 0.35, 1.5)
    end
    deps.canRetryBait = function(r)
        if r.serverRejected ~= true or not r.done or r.inFlight or r.carrySeen then return false end
        local message = string.lower(tostring(r.error))
        return message:find("get closer to the egg", 1, true) ~= nil
            or message:find("enter the gameplay area first", 1, true) ~= nil
    end
    deps.pickupReady = function(t)
        local root, humanoid = getCharParts()
        if not deps.sameCharacter(t) or not humanoid or humanoid.Parent ~= t.character
            or RuntimeStatus.DevChickenTween.lease ~= nil then
            return false, "waiting for native bait rig"
        end
        if LocalPlayer:GetAttribute("__LOADED") ~= true or root.Anchored
            or (lineSide(root.Position) or -1) <= 0 then
            return false, "waiting for gameplay entry"
        end
        if (tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0) > workspace:GetServerTimeNow()
            or RuntimeStatus.glideMovementBlocked(root) then
            return false, "waiting for native movement recovery"
        end
        return true
    end
    deps.baitAvailable = function(uid)
        local rec = findAreaEgg(uid)
        return rec ~= nil and tostring(rec.State) == "Slot" and rec.BottomCFrame ~= nil
    end
    deps.retryingTarget = function(uid)
        local root = getCharParts()
        local target = findAreaEgg(uid)
        return root ~= nil and target ~= nil and target.BottomCFrame ~= nil
            and ((root.Position - target.BottomCFrame.Position) * Vector3.new(1, 0, 1)).Magnitude <= 12
            and (lineSide(root.Position) or -1) > 0
            and tostring(stealRuntime.lockedUid) == tostring(uid)
            and tostring(stealRuntime.requestFailureUid) == tostring(uid)
            and os.clock() - (tonumber(stealRuntime.requestFailureAt) or 0) <= 6
    end
    -- [[ CHICKEN BAIT SELECTOR ]] --
    local selectChickenBait = function(records, targetUid, isFirstArea, slotKey, chickenPosition)
    local best, bestDistance
    for _, rec in pairs(records) do
        if type(rec) ~= "table" or rec.Uid == nil then continue end
        local first = isFirstArea(rec.Uid)
        if tostring(rec.Uid) ~= tostring(targetUid) and first
            and tostring(rec.AreaId) == "Forest" and tostring(rec.State) == "Slot"
            and rec.BottomCFrame and slotKey(rec) ~= nil then
            local distance = chickenPosition
                and ((rec.BottomCFrame.Position-chickenPosition)*Vector3.new(1,0,1)).Magnitude or 0
            if best == nil or distance < bestDistance
                or (distance == bestDistance and tostring(rec.Uid)<tostring(best.Uid)) then
                best,bestDistance=rec,distance
            end
        end
    end
    return best
end
    -- [[ END CHICKEN BAIT SELECTOR ]] --
    deps.findBait = function(targetUid)
        return selectChickenBait(areaEggRecords(),targetUid,function(uid)
            if not AreaEggSlotIdentity or type(AreaEggSlotIdentity.IsFirstAreaUid)~="function" then return false end
            local ok,first=pcall(AreaEggSlotIdentity.IsFirstAreaUid,uid)
            return ok and first==true
        end,carrySlotKey,deps.chickenPosition())
    end
    deps.chickenCFrame = function()
        local objects = workspace:FindFirstChild("__OBJECTS")
        local areas = objects and objects:FindFirstChild("Areas")
        local guards = areas and areas:FindFirstChild("GuardAreas")
        local forest = guards and guards:FindFirstChild("Forest")
        local guard = forest and forest:FindFirstChild("Guard")
        local root = guard and (guard.PrimaryPart or guard:FindFirstChild("HumanoidRootPart", true))
        return root and root.CFrame or nil
    end
    deps.chickenPosition = function()
        local cf = deps.chickenCFrame()
        return cf and cf.Position or nil
    end
    deps.nearChicken = function(t)
        local pos = deps.chickenPosition()
        return pos ~= nil and ((t.root.Position - pos) * Vector3.new(1, 0, 1)).Magnitude <= 30
    end
    deps.ourHit = function(hit) return hit.Player == LocalPlayer end
    deps.reserve = function(valid)
        Arb.sellDuringSteal, Arb.critical = false, true
        return Arb.waitPets(valid, 4)
    end
    deps.stage = function(t, valid)
        local movement = RuntimeStatus.DevChickenTween
        t.development = movement.enabled
        local track = RuntimeStatus.getTrackStart()
        if not track or not track:IsA("BasePart") then return false, "TrackStart unavailable" end
        if not valid() or not deps.sameCharacter(t) then return false, "staging cancelled" end
        -- One preparation lease: TrackStart -> Forest bait -> native pickup.
        -- The target's TP/Tween selection is used only after the chicken hit.
        local ready, reason = movement.begin(true)
        if not ready then return false, reason end
        t.preparationLease = movement.lease
        return movement.groundMove(track.Position + Vector3.new(0, 3, 0), 0.35,
            valid, nil, t.abortFn, 500)
    end
    deps.toolFree = function() return ProgressionCtl.waitForToolFree(0.75) end
    deps.status = function(message)
        if RuntimeStatus.DevChickenTween.enabled then
            message = message:gsub("TP", "Tween")
        end
        setStealStatus(message)
    end
    deps.request = function(bait, r)
        task.spawn(function()
            local active = RuntimeStatus.ChickenTP and RuntimeStatus.ChickenTP.active
            if not sessionAlive() or not active or active.request ~= r
                or not deps.selected() or not deps.requestCharacterAlive(r)
                or not active.keepGoing() or (active.abortFn and active.abortFn())
                or resetWallClosed() then
                r.inFlight, r.done, r.accepted = false, true, false
                r.error = "chicken pickup cancelled before dispatch"
                return
            end
            local ready, issue = deps.pickupReady(active)
            if not ready then
                r.inFlight, r.done, r.completedAt = false, true, os.clock()
                r.error = issue
                return
            end
            local live = deps.baitSnapshot(r.uid)
            local root = active.root
            if not live or ((root.Position - live.BottomCFrame.Position) * Vector3.new(1, 0, 1)).Magnitude > 0.75
                or math.abs(root.Position.Y - live.BottomCFrame.Position.Y) > 6 then
                r.inFlight, r.done, r.accepted = false, true, false
                r.error = "chicken bait moved before dispatch"
                return
            end
            r.pickupDistance = (root.Position - live.BottomCFrame.Position).Magnitude
            local invoked, accepted, err = pcall(EggCmds.RequestCarryAreaEgg, r.uid, carrySlotKey(live))
            r.serverRejected = invoked and accepted == false
            r.inFlight, r.done, r.completedAt = false, true, os.clock()
            r.accepted = invoked and accepted == true
            r.error = invoked and tostring(err or "chicken carry rejected") or tostring(accepted)
            r.proofDeadline = os.clock() + 1.5
        end)
    end
    deps.drop = function(r, done)
        task.spawn(function()
            if sessionAlive() and deps.pending() == r and deps.requestCharacterAlive(r)
                and tostring(deps.heldUid()) == tostring(r.uid) then
                pcall(EggCmds.DropAreaEgg)
            end
            done()
        end)
    end
    deps.bridgeReason = function() return RuntimeStatus.movementCompatibility end
    deps.bridge = function()
        -- Both modes need the native controller. Tween must not advertise
        -- readiness before begin() can borrow and later restore this exact rig.
        local track = RuntimeStatus.getTrackStart()
        if not track or not track:IsA("BasePart") then
            RuntimeStatus.movementCompatibility = "waiting for TrackStart"
            return nil
        end
        local root, humanoid = getCharParts()
        local bridge = integrityBridge
        local state = bridge and bridge.state
        if not (root and humanoid and humanoid.Health > 0 and state
            and state.Character == LocalPlayer.Character and state.RootPart == root
            and state.Humanoid == humanoid and bridge.token
            and type(bridge.sample) == "function" and type(bridge.adopt) == "function") then
            bridge = RuntimeStatus.findMovementDispatcher(root, humanoid)
        end
        if not bridge then return nil end
        RuntimeStatus.movementCompatibility = "ready"
        if RuntimeStatus.DevChickenTween.enabled then return RuntimeStatus.DevChickenTween end
        return bridge
    end
    deps.relocate = function(t)
        local b = t.bridge
        local root, humanoid = getCharParts()
        if not deps.sameCharacter(t) or rawget(b.state, "RootPart") ~= root
            or rawget(b.state, "Humanoid") ~= humanoid
            or rawget(b.state, "Character") ~= t.character
            or rawget(b.state, "CorrectionContext") ~= nil
            or rawget(b.state, "RecoveryLocked") == true or rawget(b.state, "KickQueued") == true
            or rawget(b.state, "ThreatLevel") == "Correcting"
            or rawget(b.state, "ThreatLevel") == "Impossible" then
            return false, "chicken relocation unavailable"
        end
        if not t.hitAttempted or t.phase ~= "contact" or t.landingCFrame then
            return false, "chicken strike not observed or jump already used"
        end
        local rec = findAreaEgg(t.targetUid)
        if not rec or not rec.BottomCFrame or not deps.targetAvailable(t.targetUid) then
            return false, "target changed before jump"
        end
        -- Use the target's recorded landing height, as in the reference trace.
        -- The local strike callback occurs before replicated ragdoll arrives.
        local position = rec.BottomCFrame.Position
        local look = root.CFrame.LookVector * Vector3.new(1, 0, 1)
        if look.Magnitude < 0.01 then look = Vector3.new(0, 0, -1) end
        local landing = CFrame.lookAt(position, position + look.Unit)
        local ok, err = pcall(function()
            b.reset(b.token, b.state)
            t.character:PivotTo(landing)
            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            local sample = b.sample(b.state, os.clock(), humanoid.WalkSpeed)
            if not sample then error("native relocation sample unavailable") end
            b.adopt(b.token, b.state, sample)
        end)
        if not ok then return false, "native relocation failed: " .. tostring(err) end
        t.landingCFrame = landing
        t.recoveryPosition, t.recoveryVelocity = root.Position, root.AssemblyLinearVelocity
        t.recoveryAt = deps.now()
        return true
    end
    deps.approachBait = function(t, valid)
        if not valid() or not deps.baitAvailable(t.bait.Uid) or deps.heldUid() ~= nil then
            return false, "chicken bait unavailable"
        end
        local movement = RuntimeStatus.DevChickenTween
        local ready, reason = movement.begin(true)
        if not ready then return false, reason end
        t.preparationLease = movement.lease
        local reached, issue = movement.groundMove(t.bait.BottomCFrame.Position, 0.35,
            function() return valid() and deps.baitAvailable(t.bait.Uid) end, nil, t.abortFn, 500)
        local restored = movement.restore(issue or "bait approach complete")
        if restored then t.preparationLease = nil end
        if not restored then return false, "native bait rig restoration failed" end
        return reached, issue
    end
    deps.reportHit = function(t)
        if not sessionAlive() or not deps.sameCharacter(t) or not deps.owns()
            or not t.keepGoing() or (t.abortFn and t.abortFn()) or deps.wallClosed()
            or t.phase ~= "contact" or not t.request or t.request.carryEndedSeen
            or tostring(deps.heldUid()) ~= tostring(t.bait.Uid)
            or not deps.targetAvailable(t.targetUid) then
            return false, "bait hit report cancelled"
        end
        local packages = ReplicatedStorage:FindFirstChild("Packages")
        local networking = packages and packages:FindFirstChild("Networking")
        local remote = networking and networking:FindFirstChild("RE/GuardPatrol/ForestStrike")
        local guardCFrame = deps.chickenCFrame()
        if not remote or not remote:IsA("RemoteEvent") then return false, "Forest hit remote unavailable" end
        if not guardCFrame then return false, "Forest guard unavailable" end
        -- Captured reference payload: the current bait UID and current guard pose.
        -- Do not call the local attack handler (it would send a second report).
        remote:FireServer({ EggUid = t.bait.Uid, GuardCFrame = guardCFrame })
        return true
    end
    deps.allowChickenReaction = function()
        local stop = getgenv().__CHSAE_GuardStopActive
        if type(stop) == "function" then stop() end
    end
    deps.landingSettleWindow = function()
        return math.clamp(getNetworkPingSeconds() * 1.5 + 0.08, 0.15, 0.35)
    end
    deps.reactionFinished = function(t)
        if t.development then
            return deps.sameCharacter(t) and RuntimeStatus.DevChickenTween.lease ~= nil
                and t.developmentReadyAt ~= nil and os.clock() >= t.developmentReadyAt
                and (tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0) <= workspace:GetServerTimeNow()
        end
        if not deps.sameCharacter(t) then return false end
        local _, humanoid = getCharParts()
        local endAt = tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0
        if endAt > workspace:GetServerTimeNow() then return false end
        local state = humanoid:GetState()
        return not humanoid.PlatformStand and state ~= Enum.HumanoidStateType.Physics
            and state ~= Enum.HumanoidStateType.Ragdoll
            and state ~= Enum.HumanoidStateType.FallingDown
            and state ~= Enum.HumanoidStateType.GettingUp
            and humanoid.FloorMaterial ~= Enum.Material.Air
    end
    deps.alignTarget = function(t, valid)
        local rec = findAreaEgg(t.targetUid)
        if not rec or not rec.BottomCFrame or not deps.targetAvailable(t.targetUid) then
            return false, "target changed after chicken recovery"
        end
        if not valid() then return false, "chicken recovery interrupted" end
        local ok, reason = RuntimeStatus.stealOutboundMoveTo(
            rec.BottomCFrame.Position, 0.35, valid, nil, t.abortFn)
        if ok and valid() then
            deps.brake(t.root)
            return true
        end
        return false, reason or "chicken recovery interrupted"
    end
    deps.hold = function(t)
        if t.development then
            local development = RuntimeStatus.DevChickenTween
            if not development.lease or not development.alive(development.lease) then
                return false, "development rig interrupted"
            end
            return true
        end
        if not deps.sameCharacter(t) then return false, "character changed" end
        if RuntimeStatus.glideMovementBlocked(t.root) then return false, "correcting" end
        -- Knockback can carry this rig more than 100 studs. Compare each frame
        -- with its measured physics velocity, not a radius around the egg.
        -- Corrections and unexplained jumps still abort without writing a pose.
        local now = deps.now()
        local previous = t.recoveryPosition or t.landingCFrame.Position
        local dt = math.clamp(now - (t.recoveryAt or now), 0, 1)
        local velocity = t.root.AssemblyLinearVelocity
        local speed = math.max(velocity.Magnitude, (t.recoveryVelocity or Vector3.zero).Magnitude)
        if (t.root.Position - previous).Magnitude > math.max(12, speed * dt * 1.5 + 4) then
            return false, "relocated"
        end
        RuntimeStatus.recoverChickenLanding(t)
        t.recoveryPosition, t.recoveryVelocity, t.recoveryAt = t.root.Position, velocity, now
        -- The transaction stays alive until knockdown ends, then its existing
        -- bounded Glide alignment returns to the selected egg before pickup.
        return true
    end

    deps.travel = RuntimeStatus.DevChickenTween.launch
    deps.failed = function(t, reason)
        local movement = RuntimeStatus.DevChickenTween
        if t.development or (t.preparationLease and movement.lease == t.preparationLease) then
            movement.restore(reason or "chicken transaction failed")
        end
    end
    RuntimeStatus.ChickenTP = createChickenTP(deps)
    local nextCleanup = 0
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = RunService.Heartbeat:Connect(function()
        if not sessionAlive() or os.clock() < nextCleanup then return end
        nextCleanup = os.clock() + 0.1
        RuntimeStatus.ChickenTP.servicePending()
    end)
end
-- [[ END CHICKEN TP TRANSACTION ]] --


RuntimeStatus.moveToStealTarget = function(uid, pos, reachDist, keepGoing, onReached, abortFn)
    -- Normal and Rift targets use the selected outbound mover, including
    -- profiles restored while the event worker is already awake.
    local selectedTween = Settings.StealMovementType == "Tween"
    if RuntimeStatus.DevChickenTween.enabled ~= selectedTween then
        if not RuntimeStatus.DevChickenTween.setEnabled(selectedTween) then return false, "movement restore failed" end
    end
    if RuntimeStatus.activeDroppedRecoveryRecord(uid) then
        local development = RuntimeStatus.DevChickenTween
        if development.enabled or development.lease then
            return development.recoverDrop(pos, reachDist, keepGoing, onReached, abortFn)
        end
        -- A guard/player drop is already inside the active area. Rejoin the exact
        -- BottomCFrame directly instead of replaying the patterned outbound route.
        return moveTo(pos, reachDist, keepGoing, onReached, abortFn)
    end
    do -- Every return method shares the chicken-assisted outbound transaction.
        local ok, reached, reason = pcall(RuntimeStatus.ChickenTP.move,
            uid, pos, reachDist, keepGoing, onReached, abortFn)
        if not ok then
            RuntimeStatus.DevChickenTween.restore("chicken transaction error")
            RuntimeStatus.ChickenTP.active = nil
            RuntimeStatus.ChickenTP.servicePending()
            RuntimeStatus.ChickenTP.lastReason = "chicken transaction failed: " .. tostring(reached)
            return false, "chicken-tp"
        end
        if reached == true then return true, reason end
        -- Only a confirmed, recent landing may use a short pickup correction.
        -- Failed TP, missing bait/API and a generic retry never select another mover.
        if reached == nil and reason == "pickup-retry" then
            return RuntimeStatus.stealOutboundMoveTo(pos, reachDist, keepGoing, onReached, abortFn)
        end
        RuntimeStatus.ChickenTP.lastReason = reason or "waiting for TP"
        return false, "chicken-tp"
    end
end

-- Death ends the character, but a fatal guard catch drops the positively carried
-- egg into the field. Preserve that exact UID as a provisional recovery lease so
-- the replacement character reclaims it. A never-carried outbound target still
-- resets normally. An InvokeServer already in flight cannot be cancelled, so tag
-- it and wait without moving the replacement character.
RuntimeStatus.onAutoStealDeath = function(deadCharacter)
    if not RuntimeStatus.stealFeatureEnabled() then return end
    local now = os.clock()
    local pending = getgenv().__CHSAE_CarryRequest
    local replicatedHeld = carriedAreaEgg()
    local priorKind = tostring(stealRuntime.lastRequestKind or "")
    local pendingProvedCarry = type(pending) == "table" and pending.carrySeen == true
    local recoveringExactDrop = (priorKind == "carry-drop"
            or priorKind == "carry-loss-sync" or priorKind == "death-drop-sync")
        and (stealRuntime.lastDroppedUid ~= nil or stealRuntime.deathRecoveryUid ~= nil)
    local recoveryUid
    if replicatedHeld and replicatedHeld.Uid ~= nil then
        recoveryUid = replicatedHeld.Uid
    elseif carrying or stealRuntime.carriedUid ~= nil then
        recoveryUid = stealRuntime.carriedUid
            or (type(pending) == "table" and pending.uid or nil)
            or stealRuntime.lockedUid or stealRuntime.attemptUid
    elseif pendingProvedCarry then
        recoveryUid = pending.uid or stealRuntime.lockedUid or stealRuntime.attemptUid
    elseif recoveringExactDrop then
        recoveryUid = stealRuntime.lastDroppedUid
            or stealRuntime.deathRecoveryUid or stealRuntime.lockedUid
    else
        -- Carry=false/FieldGone can beat the deferred HealthChanged handler.
        -- Fall back only to a UID positively observed during the short death window;
        -- claims and completed recovery clear this evidence explicitly.
        recoveryUid = stealRuntime.recentPositiveCarryUid()
    end
    if recoveryUid ~= nil and RuntimeStatus.isCaptureEventUid(recoveryUid) then
        recoveryUid = nil
    end


    stealRuntime.respawnGeneration += 1
    stealRuntime.requestFailureCount = 0
    if recoveryUid ~= nil then
        if tostring(stealRuntime.persistentUid) ~= tostring(recoveryUid) then
            stealRuntime.persistentUid = nil
        end
        if tostring(stealRuntime.dropRecoveryRecordUid) ~= tostring(recoveryUid) then
            stealRuntime.dropRecoveryRecord = nil
            stealRuntime.dropRecoveryRecordUid = nil
            stealRuntime.dropRecoveryRecordAt = 0
        end
        stealRuntime.lockedUid = recoveryUid
        stealRuntime.attemptUid = recoveryUid
        stealRuntime.lastDroppedUid = recoveryUid
        if (tonumber(stealRuntime.dropDetectedAt) or 0) <= 0 then
            stealRuntime.dropDetectedAt = now
        end
        stealRuntime.deathRecoveryUid = recoveryUid
        if (tonumber(stealRuntime.deathRecoveryAt) or 0) <= 0 then
            stealRuntime.deathRecoveryAt = now
        end
        local liveRecoveryRecord = findAreaEgg(recoveryUid)
        local liveRecoveryState = liveRecoveryRecord
            and tostring(liveRecoveryRecord.State) or nil
        local liveRecoveryCarrier = liveRecoveryRecord
            and tonumber(liveRecoveryRecord.CarrierUserId) or nil
        local liveRecoveryReady = liveRecoveryRecord ~= nil
            and (((liveRecoveryState == "Slot" or liveRecoveryState == "Dropped")
                    and liveRecoveryRecord.BottomCFrame ~= nil)
                or liveRecoveryCarrier == LocalPlayer.UserId)
        if liveRecoveryReady then
            stealRuntime.deathRecoveryMissingAt = 0
            stealRuntime.deathRecoveryMissingReason = ""
        else
            -- Promotion from recent carry evidence starts a fresh full grace;
            -- this also bounds GuardCarried/unknown transitional rows.
            stealRuntime.deathRecoveryMissingAt = now
            stealRuntime.deathRecoveryMissingReason = liveRecoveryRecord
                and "death-record-transitioning" or "death-snapshot-missing"
        end
        stealRuntime.requestFailureUid = recoveryUid
        stealRuntime.requestFailureAt = now
        if priorKind ~= "carry-drop" then
            stealRuntime.lastRequestKind = "death-drop-sync"
        end
        stealRuntime.lastRequestError = "character died while carrying; awaiting exact egg"
        RuntimeStatus.pendingDroppedUid = recoveryUid
        if type(stealRuntime.webhookTarget) == "table"
            and tostring(stealRuntime.webhookTarget.uid) ~= tostring(recoveryUid) then
            stealRuntime.webhookTarget = nil
        end
    else
        stealRuntime.persistentUid = nil
        stealRuntime.lockedUid = nil
        stealRuntime.attemptUid = nil
        stealRuntime.lastDroppedUid = nil
        stealRuntime.dropDetectedAt = 0
        stealRuntime.deathRecoveryUid = nil
        stealRuntime.deathRecoveryAt = 0
        stealRuntime.deathRecoveryMissingAt = 0
        stealRuntime.deathRecoveryMissingReason = ""
        stealRuntime.dropRecoveryRecord = nil
        stealRuntime.dropRecoveryRecordUid = nil
        stealRuntime.dropRecoveryRecordAt = 0
        stealRuntime.requestFailureUid = nil
        stealRuntime.requestFailureAt = 0
        stealRuntime.lastRequestKind = ""
        stealRuntime.lastRequestError = ""
        stealRuntime.webhookTarget = nil
        RuntimeStatus.pendingDroppedUid = nil
        stealRuntime.clearPositiveCarryEvidence()
    end
    carrying = false
    stealRuntime.carriedUid = nil
    RuntimeStatus.activeGuardAreaId = nil

    if type(pending) == "table" then
        if recoveryUid ~= nil and tostring(pending.uid) == tostring(recoveryUid) then
            pending.carrySeen = true
        end
        if pending.inFlight then
            pending.cancelledByDeath = true
        else
            getgenv().__CHSAE_CarryRequest = nil
        end
    end

    ProgressionCtl.treadmillSuppressed = recoveryUid ~= nil
    local interruptedOwner = Arb.owner
    if recoveryUid ~= nil and interruptedOwner and interruptedOwner ~= "Steal" then
        Arb.release(interruptedOwner)
    end
    Arb.stealWants = recoveryUid ~= nil
    Arb.critical = false
    Arb.stealBeat = os.clock()
    Arb.release("Steal")
    RuntimeStatus.pauseStealTimer()
    RuntimeStatus.carry = recoveryUid ~= nil
        and "📦 Carry: lost on death · reclaiming" or "📦 Carry: none"
    if recoveryUid == nil then RuntimeStatus.set("target", "🎯 Target: none") end
    setStealStatus(recoveryUid ~= nil
        and "🔁 Respawning — reclaiming dropped egg" or "🟡 Respawning — rescanning")
    if wakeEggScanner then wakeEggScanner("character-death") end
end

task.spawn(function()
    -- Keep Auto-Steal self-healing. A non-movement presentation or executor
    -- exception must not leave Arb.owner="Steal" forever after one successful
    -- claim. The inner worker owns all normal state; the supervisor preserves an
    -- in-flight RemoteFunction and restarts from replicated carry state.
    while sessionAlive() do
        local workerOk, workerError = xpcall(function()
    local blacklist = {} -- [uid] = os.clock() until which we skip it
    RuntimeStatus.riftTargetBlocked = function(uid)
        return blacklist[uid] ~= nil and os.clock() <= blacklist[uid]
    end
    local seenRespawnGeneration = stealRuntime.respawnGeneration
    while sessionAlive() do
        -- A worker restart or completed transaction must never inherit an old
        -- outbound-only sale permission.
        Arb.sellDuringSteal = false
        -- Keep the persisted mirror aligned even if a config restore changes the
        -- Obsidian control without firing its OnChanged callback on this executor.
        local toggleEnabled = autoStealTgl and autoStealTgl.Value == true
        if Settings.AutoSteal ~= toggleEnabled then Settings.AutoSteal = toggleEnabled end
        if not RuntimeStatus.stealWorkerAlive() then
            setStealControlLock(false)
            ProgressionCtl.treadmillSuppressed = false
            -- stealFeatureEnabled() dips for reasons that are not "the user
            -- turned Auto-Steal off": the Rift collect flag between its
            -- own transactions, an inventory-full auto-stop, a toggle bounce. A
            -- guard drop that is still reclaimable must outlive those. The two
            -- authoritative off paths (the toggle's own OnChanged and
            -- stopAutoStealForFullInventory) already clear it, so wiping here as
            -- well only ever destroyed a live recovery — which is what sent the
            -- worker back to TrackStart empty instead of to the dropped egg.
            if not (carryLossRecoveryPending()
                and os.clock() - (tonumber(stealRuntime.dropDetectedAt) or 0)
                    <= stealRuntime.disabledRecoveryHold) then
                clearPersistentTarget()
            end
            Arb.stealWants, Arb.critical = false, false
            Arb.release("Steal") -- Auto-Steal off → pen/pet tasks are free
            RuntimeStatus.pauseStealTimer()
            RuntimeStatus.set("target", "🎯 Target: none")
            RuntimeStatus.carry = "📦 Carry: none"
            setStealStatus("🔴 Off")
            task.wait(0.5)
            continue
        end
        -- CharacterAdded is the fallback if an executor misses the dead
        -- Humanoid's final HealthChanged packet. Only reset here when transaction
        -- state actually survived onto a different character.
        local observedCharacter = LocalPlayer.Character
        if observedCharacter ~= stealRuntime.characterToken then
            stealRuntime.characterToken = observedCharacter
            if stealRuntime.lockedUid or stealRuntime.persistentUid or carrying
                or Arb.owner == "Steal"
                or stealRuntime.recentPositiveCarryUid() ~= nil then
                RuntimeStatus.onAutoStealDeath(observedCharacter)
            end
        end
        if seenRespawnGeneration ~= stealRuntime.respawnGeneration then
            seenRespawnGeneration = stealRuntime.respawnGeneration
            blacklist = {}
        end

        -- Never stage or select against a dead/not-yet-replicated character.
        local liveRoot, liveHumanoid = getCharParts()
        if not (liveRoot and liveHumanoid and liveHumanoid.Health > 0) then
            local recoveringWhileDead = carryLossRecoveryPending()
            ProgressionCtl.treadmillSuppressed = recoveringWhileDead
            Arb.stealWants = recoveringWhileDead
            Arb.critical = false
            Arb.stealBeat = os.clock()
            Arb.release("Steal")
            setStealStatus(recoveringWhileDead
                and "🔁 Respawning — exact egg recovery locked"
                or "🟡 Respawning — waiting for character")
            task.wait(0.2)
            continue
        end
        local recoveringCarryLoss = carryLossRecoveryPending()
        if RuntimeStatus.greatBloomUnlockReturnHasPriority()
            and not recoveringCarryLoss
            and not carrying and not Arb.critical
            and not RuntimeStatus.carryRequestInFlight() then
            setStealControlLock(false)
            ProgressionCtl.treadmillSuppressed = false
            Arb.sellDuringSteal = false
            Arb.stealWants, Arb.critical = false, false
            Arb.release("Steal")
            RuntimeStatus.pauseStealTimer()
            RuntimeStatus.set("target", "🎯 Target: Crane return")
            RuntimeStatus.carry = "📦 Carry: none"
            setStealStatus("🔓 Submitting hatched Crane")
            task.wait(0.1)
            continue
        end
        if RuntimeStatus.adminEventHasPriority() and not recoveringCarryLoss then
            local liveRequest = getgenv().__CHSAE_CarryRequest
            local eventOwnsRequest = type(liveRequest) == "table"
                and liveRequest.owner == "AdminEvent"
            if Arb.owner == "AdminEvent" or eventOwnsRequest
                or (not carrying and not Arb.critical
                    and not RuntimeStatus.carryRequestInFlight()) then
                setStealControlLock(false)
                ProgressionCtl.treadmillSuppressed = true
                Arb.sellDuringSteal = false
                Arb.stealWants, Arb.critical = false, false
                Arb.release("Steal")
                RuntimeStatus.pauseStealTimer()
                RuntimeStatus.set("target", RuntimeStatus.riftBossBodyPending and "🎯 Target: Rift Boss" or "🎯 Target: Rift")
                RuntimeStatus.carry = "📦 Carry: none"
                setStealStatus(RuntimeStatus.riftBossBodyPending and "⚔️ Rift Boss has priority" or "🌀 Rift has priority")
                task.wait(0.1)
                continue
            end
        end
        local inventoryFull, inventoryCount, inventoryCapacity = RuntimeStatus.eggInventoryCapacityState()
        if inventoryFull then
            if RuntimeStatus.riftCollecting == true
                or (Settings.AutoRift == true
                    and RuntimeStatus.riftActive == true
                    and RuntimeStatus.riftEggActive()) then
                RuntimeStatus.riftCollecting = false
                -- Inventory-full waiting owns no movement. Placement and actual
                -- event work retain their separate reservations below.
                ProgressionCtl.treadmillSuppressed = false
                Arb.stealWants, Arb.critical = false, false
                Arb.release("Steal")
                setStealStatus("🌀 Inventory full · place or hatch required eggs")
                local riftWake = getgenv().__CHSAE_RiftWake
                if riftWake then pcall(function() riftWake:Fire("inventory-full") end) end
                task.wait(0.1)
            elseif RuntimeStatus.greatBloomUnlockNeedsCrane() then
                ProgressionCtl.treadmillSuppressed = false
                Arb.stealWants, Arb.critical = false, false
                Arb.release("Steal")
                setStealStatus("🔓 Great Bloom · make egg inventory space")
                task.wait(0.5)
            else
                RuntimeStatus.stopAutoStealForFullInventory(inventoryCount, inventoryCapacity,
                    "Your egg inventory is full!")
                task.wait(0.05)
            end
            continue
        end
        RuntimeStatus.clearRouteObstacles()
        local guardReady = setIntegrityGuard(true)
        RuntimeStatus.defaultMoveFallback = not guardReady
        if not guardReady then
            setStealStatus("⏸️ Waiting for movement controller")
        end
        setStealControlLock(true)
        if not Settings.PersistentSteal then stealRuntime.persistentUid = nil end
        Arb.critical = carrying
            or RuntimeStatus.activeDroppedRecoveryRecord(stealRuntime.lockedUid) ~= nil
        Arb.stealBeat = os.clock()

        if RuntimeStatus.ChickenTP.servicePending() then
            Arb.critical = true
            setStealStatus("🐔 Finishing chicken bait cleanup…")
            task.wait(0.1)
            continue
        end

        -- ── Phase 1: recover a carry that survived a reload/interruption ──
        local heldRec = carriedAreaEgg()
        local heldUid = heldRec and heldRec.Uid
            or stealRuntime.carriedUid
            or stealRuntime.lastDroppedUid
            or stealRuntime.lockedUid
            or stealRuntime.attemptUid
        -- Cached carry flags and stale CarrierUserId fields are not sufficient
        -- to launch a recovery return after an authoritative drop/transfer.
        if heldUid ~= nil and stillCarrying(heldUid) then
            carrying = true
            if heldRec and heldRec.AreaId ~= nil then
                RuntimeStatus.activeGuardAreaId = tostring(heldRec.AreaId)
            end
            ProgressionCtl.treadmillSuppressed = true
            Arb.stealWants, Arb.critical = true, true
            Arb.acquireWait("Steal", 3)
            ProgressionCtl.requestTreadmillExit()
            if areaResetActive() then
                Arb.release("Steal")
                setStealStatus("⏳ Wall closed — holding egg")
                local waitTime = resetWallClosed() and 10
                    or math.max(0.25, areaResetUntil - os.clock())
                waitForScannerWake(waitTime, function()
                    return not areaResetActive()
                end)
                continue
            end
            setStealStatus("🟢 Carrying → home")
            local startArea = getStartArea()
            local home = startArea and (startArea.Position + Vector3.new(0, 3, 0))
                or getExitTarget(30)
            if not home then
                setStealStatus("🟡 No exit line")
                task.wait(0.5)
                continue
            end

            local heldCategory = heldRec and heldRec.AssetCategory
            local heldAreaId = heldRec and heldRec.AreaId ~= nil
                and tostring(heldRec.AreaId) or RuntimeStatus.activeGuardAreaId
            local recoveryClaimSequence = stealRuntime.claimSequence
            local recoveryReturned, recoveryReturnReason = false, nil
            local recoveryConfirmed = claimConfirmed(
                heldUid, heldCategory, recoveryClaimSequence)
            while sessionAlive() and not recoveryConfirmed do
                recoveryReturned, recoveryReturnReason = RuntimeStatus.centeredStealReturnTo(
                    home, stealOn, function()
                        return resetWallClosed()
                            or ProgressionCtl.detectActiveTreadmill() ~= nil
                            or (heldUid
                                and (droppedAreaEgg(heldUid)
                                    or RuntimeStatus.carryLostInField(heldUid))
                                and not claimConfirmed(
                                    heldUid, heldCategory, recoveryClaimSequence))
                            or (heldUid
                                and tostring(stealRuntime.deathRecoveryUid) == tostring(heldUid)
                                and tostring(RuntimeStatus.pendingDroppedUid) == tostring(heldUid)
                                and not claimConfirmed(
                                    heldUid, heldCategory, recoveryClaimSequence))
                    end, heldAreaId)
                recoveryConfirmed = claimConfirmed(
                    heldUid, heldCategory, recoveryClaimSequence)
                if recoveryReturned or recoveryConfirmed then break end
                if not RuntimeStatus.preserveCarriedReturn(
                    heldUid, recoveryReturnReason) then break end
                if ProgressionCtl.detectActiveTreadmill() then
                    ProgressionCtl.requestTreadmillExit()
                    setStealStatus("🟡 Treadmill blocked — exiting")
                    task.wait(0.10)
                elseif resetWallClosed() then
                    setStealStatus("⏳ Wall closed — holding carried egg")
                    waitForScannerWake(0.25, function()
                        return not resetWallClosed()
                    end)
                else
                    setStealStatus("↩️ Return interrupted · resuming safe zone")
                    task.wait(0.03)
                end
            end

            if ProgressionCtl.detectActiveTreadmill() then
                ProgressionCtl.requestTreadmillExit()
                setStealStatus("🟡 Treadmill blocked — exiting")
                continue
            end
            if resetWallClosed() then
                Arb.release("Steal")
                setStealStatus("⏳ Wall closed — holding egg")
                continue
            end

            local confirmed = recoveryConfirmed
            local confirmDeadline = os.clock() + 4
            while sessionAlive() and os.clock() < confirmDeadline do
                confirmed = claimConfirmed(heldUid, heldCategory, recoveryClaimSequence)
                if confirmed then break end
                if heldUid and droppedAreaEgg(heldUid) then break end
                if heldUid and tostring(stealRuntime.lastDroppedUid) == tostring(heldUid) then break end
                RunService.Heartbeat:Wait()
            end
            local liveHeldRec = carriedAreaEgg()
            carrying = liveHeldRec ~= nil
            RuntimeStatus.activeGuardAreaId = liveHeldRec and liveHeldRec.AreaId ~= nil
                and tostring(liveHeldRec.AreaId) or nil
            Arb.critical = carrying

            if confirmed then
                RuntimeStatus.activeGuardAreaId = nil
                if heldUid and RuntimeStatus.candidateIndex then
                    RuntimeStatus.candidateIndex:Invalidate(heldUid, "recovered delivery verified")
                end
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants, Arb.critical = true, true
                Arb.acquireWait("Steal", 0.5)
                RuntimeStatus.settleVerifiedClaim()
                RuntimeStatus.clearCarryLossRecovery(heldUid)
                stealRuntime.persistentUid = nil
                stealRuntime.lockedUid = nil
                stealRuntime.lastDroppedUid = nil
                stealRuntime.dropDetectedAt = 0
                setStealStatus("✅ Egg delivery verified")
            elseif not carrying then
                local droppedUid = heldUid or stealRuntime.lastDroppedUid
                if armDroppedEggReacquire(droppedUid, "recovered carry was dropped") then
                    setStealStatus("🥚 Guard dropped egg · reclaiming now")
                    task.wait(0.03)
                    continue
                elseif droppedUid and tostring(stealRuntime.lastDroppedUid) == tostring(droppedUid) then
                    -- CarryChanged(false) can lead FieldShifted(Dropped) by a few
                    -- frames. Hold this exact transaction instead of blacklisting
                    -- it during that provisional replication gap.
                    stealRuntime.lockedUid = droppedUid
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants, Arb.critical = true, true
                    Arb.stealBeat = os.clock()
                    if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.1) end
                    setStealStatus("🥚 Dropped egg syncing · reclaiming")
                    waitForScannerWake(0.08)
                    continue
                elseif Settings.PersistentSteal and heldUid then
                    stealRuntime.persistentUid = heldUid
                    setStealStatus("🔁 Carry lost — waiting for egg")
                else
                    if heldUid then blacklist[heldUid] = os.clock() + 3 end
                    setStealStatus("🟡 Egg dropped — rescanning")
                end
                Arb.critical = false
                continue
            else
                setStealStatus("🟢 Carrying → home")
                continue
            end

            refreshStealStatus()
            continue
        end


        -- A stalled InvokeServer must never be followed by another carry invoke.
        -- Let remote-only work/treadmill continue while we wait for the one request
        -- to finish. If it eventually grants the egg, Phase 1 above recovers it.
        local pendingCarry = getgenv().__CHSAE_CarryRequest
        if type(pendingCarry) == "table" then
            if pendingCarry.cancelledByDeath then
                local activeDeathUid = stealRuntime.deathRecoveryUid
                    or stealRuntime.lastDroppedUid
                if pendingCarry.inFlight and activeDeathUid ~= nil
                    and tostring(pendingCarry.uid) ~= tostring(activeDeathUid) then
                    -- A stale/Admin request cannot own the positively recovered
                    -- UID. Isolate its late reply and let recovery A proceed.
                    pendingCarry.supersededByRecovery = true
                    if getgenv().__CHSAE_CarryRequest == pendingCarry then
                        getgenv().__CHSAE_CarryRequest = nil
                    end
                    pendingCarry = nil
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants, Arb.critical = true, true
                    Arb.stealBeat = os.clock()
                    setStealStatus("🔁 Respawned — exact recovery superseded stale request")
                end
                if pendingCarry and pendingCarry.inFlight then
                    local liveRecoveryRecord = pendingCarry.carrySeen == true
                        and findAreaEgg(pendingCarry.uid) or nil
                    local recoveryRec = pendingCarry.carrySeen == true
                        and RuntimeStatus.activeDroppedRecoveryRecord(pendingCarry.uid) or nil
                    local liveCarrierId = liveRecoveryRecord
                        and tonumber(liveRecoveryRecord.CarrierUserId) or nil
                    local liveRecoveryState = liveRecoveryRecord
                        and tostring(liveRecoveryRecord.State) or nil
                    local takenByOther = liveRecoveryRecord ~= nil
                        and (liveRecoveryState == "Claimed"
                            or (liveCarrierId ~= nil and liveCarrierId > 0
                                and liveCarrierId ~= LocalPlayer.UserId))
                    local missingAt = tonumber(stealRuntime.deathRecoveryMissingAt) or 0
                    if carryLossRecoveryPending() and not recoveryRec and not takenByOther
                        and missingAt <= 0 then
                        missingAt = os.clock()
                        stealRuntime.deathRecoveryMissingAt = missingAt
                        stealRuntime.deathRecoveryMissingReason = liveRecoveryRecord
                            and "pending-transitioning" or "pending-missing"
                    end
                    local missingExpired = carryLossRecoveryPending()
                        and (resetWallClosed() or (missingAt > 0
                            and os.clock() - missingAt
                                >= stealRuntime.deathRecoveryMissingGrace))
                    if recoveryRec then
                        -- Death already ended this proven carry and the exact egg is
                        -- available again. Detach the uncancellable old Invoke so it
                        -- cannot park the replacement character forever; its late
                        -- result is kept request-local by supersededByRecovery.
                        pendingCarry.supersededByRecovery = true
                        if getgenv().__CHSAE_CarryRequest == pendingCarry then
                            getgenv().__CHSAE_CarryRequest = nil
                        end
                        pendingCarry = nil
                        ProgressionCtl.treadmillSuppressed = true
                        Arb.stealWants, Arb.critical = true, true
                        Arb.stealBeat = os.clock()
                        setStealStatus("🔁 Respawned — reclaiming exact egg")
                    elseif takenByOther or missingExpired then
                        -- The UID was taken by somebody else, never returned, or
                        -- the field cycle reset. Detach the dead character's invoke
                        -- and resume a fresh scan; its eventual result stays local.
                        pendingCarry.supersededByRecovery = true
                        if getgenv().__CHSAE_CarryRequest == pendingCarry then
                            getgenv().__CHSAE_CarryRequest = nil
                        end
                        RuntimeStatus.clearCarryLossRecovery(pendingCarry.uid)
                        if tostring(stealRuntime.lockedUid) == tostring(pendingCarry.uid) then
                            stealRuntime.lockedUid = nil
                        end
                        if tostring(stealRuntime.persistentUid) == tostring(pendingCarry.uid) then
                            stealRuntime.persistentUid = nil
                        end
                        pendingCarry = nil
                        ProgressionCtl.treadmillSuppressed = false
                        Arb.stealWants, Arb.critical = false, false
                        Arb.release("Steal")
                        setStealStatus(takenByOther
                            and "🟡 Recovery egg taken — rescanning"
                            or "🟡 Death recovery expired — rescanning")
                    elseif carryLossRecoveryPending() then
                        -- The old InvokeServer is uncancellable and the field row
                        -- may be absent briefly during respawn. Keep the recovery
                        -- lane reserved instead of releasing the body to TrackStart.
                        ProgressionCtl.treadmillSuppressed = true
                        Arb.stealWants, Arb.critical = true, true
                        Arb.stealBeat = os.clock()
                        if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.1) end
                        RuntimeStatus.carry = "📦 Carry: death recovery syncing"
                        setStealStatus("🔁 Respawned — waiting for exact egg")
                        task.wait(0.1)
                        continue
                    else
                        ProgressionCtl.treadmillSuppressed = false
                        Arb.stealWants, Arb.critical = false, false
                        Arb.release("Steal")
                        RuntimeStatus.carry = "📦 Carry: retiring previous request"
                        setStealStatus("🟡 Respawned — finishing previous request")
                        task.wait(0.2)
                        continue
                    end
                end
                if pendingCarry ~= nil then
                    getgenv().__CHSAE_CarryRequest = nil
                    pendingCarry = nil
                end
            elseif pendingCarry.inFlight then
                local pendingDrop = RuntimeStatus.getDroppedRecoveryRecord(pendingCarry.uid)
                if pendingDrop then
                    -- The server may publish Carry=false/Dropped before the
                    -- original InvokeServer returns. Keep its single-flight lock,
                    -- but fall through to movement so we return to that egg now.
                    armDroppedEggReacquire(pendingDrop.Uid,
                        "egg dropped while carry request was still returning")
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants, Arb.critical = true, true
                    Arb.stealBeat = os.clock()
                    if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.25) end
                    RuntimeStatus.carry = "📦 Carry: dropped · request retiring"
                    setStealStatus("🔁 Returning to dropped egg · request syncing")
                else
                -- The old path released Steal here. Treadmill/Place could then
                -- carry the character home while the one legal InvokeServer was
                -- still validating beside the egg, showing "Steal armed" with no
                -- egg. Keep the body parked until that same request completes.
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants, Arb.critical = true, true
                Arb.stealBeat = os.clock()
                if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.25) end
                local elapsed = math.max(0, os.clock() - (pendingCarry.started or os.clock()))
                RuntimeStatus.carry = ("📦 Carry: server response stalled · %.1fs"):format(elapsed)
                setStealStatus("⏳ Carry response pending — holding at egg")
                task.wait(0.2)
                continue
                end
            end

            local retryAt = pendingCarry and not pendingCarry.inFlight
                and tonumber(pendingCarry.retryAt) or 0
            local retryLeft = retryAt - os.clock()
            local proofDeadline = pendingCarry and not pendingCarry.inFlight
                and tonumber(pendingCarry.proofDeadline) or 0
            local proofLeft = proofDeadline - os.clock()
            if pendingCarry and not pendingCarry.inFlight
                and pendingCarry.accepted and proofLeft > 0 then
                -- The carry reply can reach this client before the replicated
                -- ownership snapshot.  Keep the body parked beside the egg and
                -- keep lower-priority movement suppressed during that short gap;
                -- releasing here previously let Treadmill/Place pull us away
                -- before local carry proof arrived.
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants, Arb.critical = true, true
                RuntimeStatus.carry = "📦 Carry: waiting for server sync"
                setStealStatus("⏳ Carry accepted — waiting for ownership")
                task.wait(math.min(0.12, math.max(0.02, proofLeft)))
                continue
            end

            if pendingCarry and RuntimeStatus.retainUnverifiedPickup(pendingCarry) then
                RuntimeStatus.carry = "📦 Carry: unverified · retrying beside egg"
                setStealStatus("⏳ Ownership not confirmed — retrying at egg")
            end

            -- A completed rejection cools only that UID. The previous global
            -- wait paused every valid egg because one target needed a closer
            -- server position. Persistent mode still pins and waits for its UID.
            if pendingCarry and not pendingCarry.inFlight
                and not pendingCarry.accepted and retryLeft > 0 then
                if pendingCarry.uid then
                    blacklist[pendingCarry.uid] = math.max(
                        tonumber(blacklist[pendingCarry.uid]) or 0,
                        retryAt
                    )
                end
            end
            if pendingCarry and not pendingCarry.inFlight
                and getgenv().__CHSAE_CarryRequest == pendingCarry then
                getgenv().__CHSAE_CarryRequest = nil
            end
        end

        -- ── Phase 2: pick a target egg (rarity filter + priority ranking) ──
        local selectedCount = 0
        for _, on in pairs(Settings.TargetRarities) do if on then selectedCount += 1 end end
        local selectedCategoryCount = 0
        for _, on in pairs(Settings.TargetCategories) do if on then selectedCategoryCount += 1 end end
        local selectedAreaCount = 0
        for _, on in pairs(Settings.TargetAreas) do if on then selectedAreaCount += 1 end end
        local kgFilterActive = RuntimeStatus.kgFilterActive(Settings.TargetKGMode,
            Settings.TargetKGThreshold)
        local valueFilterActive = RuntimeStatus.valueFilterActive(Settings.TargetValueThreshold)
        -- An exact carry/death recovery is already an owned transaction. Event
        -- collection may remain enabled, but it cannot replace that UID locally.
        local normalAvailable = RuntimeStatus.normalStealPending()
        local riftCollect = RuntimeStatus.riftCollecting == true
            and not carryLossRecoveryPending() and not normalAvailable
            and not RuntimeStatus.riftBossFirstActive()
        local unlockCrane = RuntimeStatus.greatBloomUnlockNeedsCrane()
            and not normalAvailable and not riftCollect
        local craneReserved = not unlockCrane
            and RuntimeStatus.greatBloomUnlockHasCraneReservation()
        local prio = Settings.TargetPriority
        if unlockCrane or riftCollect then prio = nil end

        if selectedCount == 0 and selectedCategoryCount == 0 and selectedAreaCount == 0
            and not kgFilterActive and not valueFilterActive and not prio
            and not unlockCrane and not riftCollect
            and not stealRuntime.lockedUid
            and not (Settings.PersistentSteal and stealRuntime.persistentUid) then
            ProgressionCtl.treadmillSuppressed = false
            Arb.stealWants = false
            Arb.release("Steal") -- nothing to hunt for → let the pen tasks work
            setStealStatus("🟡 Pick a target")
            task.wait(2)
            continue
        end

        -- Scan the replacement snapshot even while the wall is still closed. This
        -- lets Auto-Treadmill get off and stage before the opening instead of only
        -- discovering the target after every other player is already moving.
        local settle = 0.15 - (os.clock() - wallOpenedAt)
        if not resetWallClosed() and wallOpenedAt > 0 and settle > 0 then task.wait(settle) end

        local candidateIndex = RuntimeStatus.candidateIndex
        local records = candidateIndex and candidateIndex.records
        local indexedCandidates = candidateIndex and candidateIndex:GetEntries(prio)
        if type(records) ~= "table" or type(indexedCandidates) ~= "table" then
            ProgressionCtl.treadmillSuppressed = false
            Arb.stealWants = false
            Arb.release("Steal")
            setStealStatus("🟡 Waiting for target")
            waitForScannerWake(5)
            continue
        end

        -- Persistent mode pins the exact UID. A trapped/dropped egg is not
        -- replaced by an easier target; if another player temporarily carries it,
        -- keep every lower-priority automation paused until it drops or disappears.
        local forcedRec
        -- Rift owns its own exact nearest UID. Never let a normal
        -- Persistent/Farthest target leak into the event collection pass.
        local eventForcedUid = riftCollect and RuntimeStatus.riftTargetUid or nil
        local forcedUid = eventForcedUid
            or (Settings.PersistentSteal and stealRuntime.persistentUid)
            or stealRuntime.lockedUid
        if forcedUid then
            local forcedEntry = candidateIndex.byUid[tostring(forcedUid)]
            -- Transaction locks require the live EggState record. The candidate
            -- cache can still say Carried for one frame after FieldShifted(Dropped).
            local liveForcedRec = findAreaEgg(forcedUid)
            local recoveryKind = tostring(stealRuntime.lastRequestKind or "")
            local exactDeathRecovery = tostring(stealRuntime.deathRecoveryUid)
                    == tostring(forcedUid)
                and (recoveryKind == "death-drop-sync" or recoveryKind == "carry-drop")
            -- A cache row is suitable for ordinary target selection, but it is
            -- never proof that a death-recovery UID still exists. Only the live
            -- EggState snapshot may end the missing-record timer.
            forcedRec = liveForcedRec
                or (not exactDeathRecovery and forcedEntry and forcedEntry.rec)
            local liveForcedState = liveForcedRec and tostring(liveForcedRec.State) or nil
            local liveForcedCarrier = liveForcedRec
                and tonumber(liveForcedRec.CarrierUserId) or nil
            local liveRecoveryReady = liveForcedRec ~= nil
                and (((liveForcedState == "Slot" or liveForcedState == "Dropped")
                        and liveForcedRec.BottomCFrame ~= nil)
                    or liveForcedCarrier == LocalPlayer.UserId)
            if exactDeathRecovery and liveRecoveryReady then
                stealRuntime.deathRecoveryMissingAt = 0
                stealRuntime.deathRecoveryMissingReason = ""
            end
            if forcedRec and RuntimeStatus.isCaptureEventUid(forcedRec.Uid) then
                if tostring(stealRuntime.persistentUid) == tostring(forcedUid) then
                    stealRuntime.persistentUid = nil
                end
                if tostring(stealRuntime.lockedUid) == tostring(forcedUid) then
                    stealRuntime.lockedUid = nil
                end
                forcedRec = nil
            end
            if forcedRec and riftCollect and not RuntimeStatus.riftFieldEligible(forcedRec) then
                if tostring(RuntimeStatus.riftTargetUid) == tostring(forcedUid) then
                    RuntimeStatus.riftTargetUid = nil
                end
                stealRuntime.persistentUid = nil
                stealRuntime.lockedUid = nil
                forcedRec = nil
            end
            local liveRecoveryTerminal = liveForcedRec ~= nil
                and (liveForcedState == "Claimed"
                    or (liveForcedCarrier ~= nil and liveForcedCarrier > 0
                        and liveForcedCarrier ~= LocalPlayer.UserId))
            if exactDeathRecovery and not liveRecoveryReady and not liveRecoveryTerminal then
                local missingAt = tonumber(stealRuntime.deathRecoveryMissingAt) or 0
                if missingAt <= 0 then
                    missingAt = os.clock()
                    stealRuntime.deathRecoveryMissingAt = missingAt
                    stealRuntime.deathRecoveryMissingReason = liveForcedRec
                        and "selection-transitioning" or "selection-missing"
                end
                local missingAge = math.max(0, os.clock() - missingAt)
                if not resetWallClosed()
                    and missingAge < stealRuntime.deathRecoveryMissingGrace then
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants, Arb.critical = true, true
                    Arb.stealBeat = os.clock()
                    if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.1) end
                    setStealStatus(("🔁 Respawned · egg syncing %.1fs"):format(missingAge))
                    waitForScannerWake(0.1)
                    continue
                end
                -- A missing or non-recoverable transitional row outlived the
                -- bounded post-respawn grace. Release the exact lease so normal
                -- scanning can resume instead of waiting in this state forever.
                RuntimeStatus.clearCarryLossRecovery(forcedUid)
                if tostring(stealRuntime.lockedUid) == tostring(forcedUid) then
                    stealRuntime.lockedUid = nil
                end
                if tostring(stealRuntime.persistentUid) == tostring(forcedUid) then
                    stealRuntime.persistentUid = nil
                end
                forcedRec = nil
                exactDeathRecovery = false
                ProgressionCtl.treadmillSuppressed = false
                Arb.stealWants, Arb.critical = false, false
                Arb.release("Steal")
                setStealStatus("🟡 Death recovery expired — rescanning")
            end
            if not forcedRec or tostring(forcedRec.State) == "Claimed" then
                local preserveDeferredDeathEvidence = not forcedRec
                    and not exactDeathRecovery
                    and tostring(stealRuntime.recentPositiveCarryUid()) == tostring(forcedUid)
                    and (recoveryKind == "carry-loss-sync" or recoveryKind == "carry-drop")
                if tostring(RuntimeStatus.riftTargetUid) == tostring(forcedUid) then
                    RuntimeStatus.riftTargetUid = nil
                end
                if tostring(stealRuntime.persistentUid) == tostring(forcedUid) then
                    stealRuntime.persistentUid = nil
                end
                if tostring(stealRuntime.lockedUid) == tostring(forcedUid) then
                    stealRuntime.lockedUid = nil
                end
                if type(RuntimeStatus.clearCarryLossRecovery) == "function" then
                    RuntimeStatus.clearCarryLossRecovery(
                        forcedUid, preserveDeferredDeathEvidence)
                end
                forcedRec = nil
                -- Night/reset replaces every record with a new UID.  The old
                -- persistent target is therefore expected to disappear; clear
                -- its overlay immediately and fall through to the fresh scan.
                -- Do not read forcedRec.Uid below after this branch.
                RuntimeStatus.set("target", "🎯 Target: none")
            elseif tostring(forcedRec.State) ~= "Slot" and tostring(forcedRec.State) ~= "Dropped" then
                local exactCarryLoss = tostring(stealRuntime.lastDroppedUid) == tostring(forcedUid)
                    and (recoveryKind == "carry-loss-sync"
                        or recoveryKind == "death-drop-sync" or recoveryKind == "carry-drop")
                local carrierId = tonumber(forcedRec.CarrierUserId)
                local carriedByOther = carrierId ~= nil and carrierId > 0
                    and carrierId ~= LocalPlayer.UserId
                if exactCarryLoss and not carriedByOther then
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants, Arb.critical = true, true
                    Arb.stealBeat = os.clock()
                    if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.1) end
                    setStealStatus(recoveryKind == "death-drop-sync"
                        and "🔁 Respawned · waiting for dropped egg"
                        or "🥚 Dropped egg syncing · holding recovery")
                    waitForScannerWake(0.08)
                    continue
                end
                if Settings.PersistentSteal
                    and tostring(stealRuntime.persistentUid) == tostring(forcedUid) then
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants = true
                    Arb.stealBeat = os.clock()
                    Arb.release("Steal")
                    setStealStatus("🔁 Persistent — waiting for target to drop")
                    waitForScannerWake(0.75)
                    continue
                end
                -- Normal transaction locking covers recoverable request errors,
                -- not an egg that another player is actively carrying.
                stealRuntime.lockedUid = nil
                if exactCarryLoss and type(RuntimeStatus.clearCarryLossRecovery) == "function" then
                    RuntimeStatus.clearCarryLossRecovery(forcedUid)
                end
                forcedRec = nil
            elseif not forcedRec.BottomCFrame then
                setStealStatus("🔁 Target locked — waiting for position")
                waitForScannerWake(0.5)
                continue
            end

            if forcedRec then
                if RuntimeStatus.getDroppedRecoveryRecord(forcedRec.Uid) then
                    if armDroppedEggReacquire(forcedRec.Uid, "confirmed dropped field record") then
                        blacklist[forcedRec.Uid] = nil
                    end
                end
                local forcedRetryAt = tonumber(blacklist[forcedRec.Uid]) or 0
                if forcedRetryAt > os.clock() then
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants = true
                    Arb.stealBeat = os.clock()
                    local retryLeft = forcedRetryAt - os.clock()
                    local retryRoot, retryHumanoid = getCharParts()
                    local retryDistance = retryRoot and forcedRec.BottomCFrame
                        and ((retryRoot.Position - forcedRec.BottomCFrame.Position)
                            * Vector3.new(1, 0, 1)).Magnitude or math.huge
                    local retryKind = tostring(stealRuntime.lastRequestKind or "")
                    local retryText = string.lower(tostring(stealRuntime.lastRequestError or ""))
                    local recoverableRetry = retryKind == "movement-trust"
                        or retryKind == "position-sync"
                        or retryKind == "activity-sync"
                        or retryKind == "movement-retry"
                        or retryKind == "server"
                        or retryKind == "retry"
                        or retryKind == "carry-loss-sync"
                        or retryKind == "death-drop-sync"
                        or retryKind == "carry-drop"
                    local droppedRecovery = RuntimeStatus.activeDroppedRecoveryRecord(
                        forcedRec.Uid) ~= nil
                    local resumingSameTransaction = retryRoot and retryHumanoid
                        and retryHumanoid.Health > 0
                        and tostring(stealRuntime.requestFailureUid) == tostring(forcedRec.Uid)
                        and tostring(stealRuntime.lockedUid) == tostring(forcedRec.Uid)
                        and recoverableRetry
                        and not retryText:find("inventory is full", 1, true)
                        and not retryText:find("gameplay area", 1, true)
                        and (droppedRecovery
                            or os.clock() - (tonumber(stealRuntime.requestFailureAt) or 0) <= 6)
                        and (droppedRecovery or (lineSide(retryRoot.Position) or -1) > 0)
                    if resumingSameTransaction then
                        -- This is the same carry transaction, not a target rescan.
                        -- Retain body ownership so Treadmill cannot reclaim the
                        -- character during the short server-position retry window.
                        Arb.critical = true
                        if Arb.owner ~= "Steal" then Arb.acquireWait("Steal", 0.1) end
                        RuntimeStatus.retryResumeMode = retryDistance <= 8
                            and "beside-egg" or "current-position"
                        RuntimeStatus.retryResumeDistance = retryDistance
                        RuntimeStatus.retryResumeUid = forcedRec.Uid
                        setStealStatus(retryKind == "movement-retry"
                            and "⚡ Movement interrupted · resuming"
                            or (retryDistance <= 8
                                and "🥚 Retrying carry…"
                                or "🔁 Resuming carry target…"))
                    else
                        Arb.critical = false
                        Arb.release("Steal")
                        setStealStatus("🟡 Target retry pending")
                    end
                    task.wait(math.min(0.2, math.max(0.03, retryLeft)))
                    continue
                end
            end
        end

        local root = getCharParts()
        local best, matching, total = nil, 0, 0
        local blockedArea = 0 -- counted for the status line only; no longer a filter
        if forcedRec then
            local rar = rarityOfRecord(forcedRec) or { _id = "Target", RarityNumber = 0 }
            local muts = getMutations(forcedRec)
            best = {
                rec = forcedRec,
                rar = rar,
                muts = muts,
                dist = root and ((root.Position - forcedRec.BottomCFrame.Position)
                    * Vector3.new(1, 0, 1)).Magnitude or 0,
                score = valueScore(forcedRec),
                weight = weightKg(forcedRec) or 0,
                rarNum = tonumber(rar.RarityNumber) or 0,
            }
            matching, total = 1, #records
        else
        for _, indexed in ipairs(indexedCandidates) do
            local rec = indexed.rec
            total += 1
            if tostring(rec.State) == "Slot" and rec.BottomCFrame
                and not RuntimeStatus.isCaptureEventUid(rec.Uid)
                and (not blacklist[rec.Uid] or os.clock() > blacklist[rec.Uid]) then
                local rar  = indexed.rarity
                local muts = indexed.mutations
                -- v2.2: the speed gate no longer FILTERS anything (user's call — we're
                -- working on bypassing it). We only count it so the status can warn.
                local isCrane = tostring(rec.AssetCategory) == "Crane"
                if not areaAllowed(rec.AreaId) then blockedArea += 1 end
                -- rarity filter (skipped when no rarities are selected)
                local riftEligible = RuntimeStatus.riftFieldEligible(rec)
                local eligible = riftCollect and riftEligible
                    or not riftCollect
                    and not (craneReserved and isCrane)
                    and (unlockCrane and isCrane
                    or (rar and (selectedCount == 0 or Settings.TargetRarities[rar._id])
                        and (selectedCategoryCount == 0 or Settings.TargetCategories[tostring(rec.AssetCategory)])
                        and (selectedAreaCount == 0 or Settings.TargetAreas[tostring(rec.AreaId)])
                        and (not kgFilterActive or RuntimeStatus.kgFilterMatches(indexed.weight,
                            Settings.TargetKGMode, Settings.TargetKGThreshold, indexed.weightKnown))
                        and (not valueFilterActive or RuntimeStatus.valueFilterMatches(indexed.value,
                            Settings.TargetValueThreshold, "atLeast", indexed.valueKnown))
                        -- mutation priority doubles as a hard filter
                        and (prio ~= "Mutation" or #muts > 0)))
                if eligible then
                    matching += 1
                    local cand = {
                        rec    = rec,
                        rar    = rar,
                        muts   = muts,
                        dist   = root and ((root.Position - rec.BottomCFrame.Position) * Vector3.new(1, 0, 1)).Magnitude or 0,
                        score  = indexed.value,
                        weight = indexed.weight,
                        rarNum = indexed.rarityNumber,
                    }
                    -- Ranking is applied only after rarity/category/area filters:
                    -- Value → richest; Weight → highest KG; Rarity → rarest;
                    -- Mutation/none → nearest.
                    local better = false
                    if not best then
                        better = true
                    elseif unlockCrane then
                        better = cand.score < best.score
                            or (cand.score == best.score and cand.weight < best.weight)
                            or (cand.score == best.score and cand.weight == best.weight
                                and cand.dist < best.dist)
                    elseif prio == "Value" then
                        better = cand.score > best.score
                            or (cand.score == best.score and cand.dist < best.dist)
                    elseif prio == "Rarity" then
                        better = cand.rarNum > best.rarNum
                            or (cand.rarNum == best.rarNum and cand.score > best.score)
                            or (cand.rarNum == best.rarNum and cand.score == best.score and cand.dist < best.dist)
                    elseif prio == "Weight" then
                        better = cand.weight > best.weight
                            or (cand.weight == best.weight and cand.rarNum > best.rarNum)
                            or (cand.weight == best.weight and cand.rarNum == best.rarNum and cand.score > best.score)
                            or (cand.weight == best.weight and cand.rarNum == best.rarNum
                                and cand.score == best.score and cand.dist < best.dist)
                    elseif prio == "Farthest" then
                        better = cand.dist > best.dist
                            or (cand.dist == best.dist and cand.score > best.score)
                    else -- Rift, nil or "Mutation": nearest first
                        better = cand.dist < best.dist
                            or (cand.dist == best.dist and cand.score > best.score)
                    end
                    if better then best = cand end
                end
            end
        end
        end

        if not best then
            -- Explain an apparently idle scanner. A selected egg can still be
            -- present but temporarily in Dropped state (normal mode only takes
            -- untouched Slot eggs), or every selected Slot can be cooling down
            -- after a failed contact. Do this diagnostic pass only when no
            -- target was chosen, so the ordinary hot path stays unchanged.
            local selectedDropped, selectedCooling = 0, 0
            for _, indexed in ipairs(indexedCandidates) do
                local rec = indexed.rec
                if rec.BottomCFrame then
                    local rar = indexed.rarity
                    local muts = indexed.mutations
                    local isCrane = tostring(rec.AssetCategory) == "Crane"
                    local riftEligible = RuntimeStatus.riftFieldEligible(rec)
                    local eligible = not RuntimeStatus.isCaptureEventUid(rec.Uid)
                        and (riftCollect and riftEligible
                        or not riftCollect
                        and not (craneReserved and isCrane)
                        and (unlockCrane and isCrane
                        or (rar
                            and (selectedCount == 0 or Settings.TargetRarities[rar._id])
                            and (selectedCategoryCount == 0 or Settings.TargetCategories[tostring(rec.AssetCategory)])
                            and (selectedAreaCount == 0 or Settings.TargetAreas[tostring(rec.AreaId)])
                            and (not kgFilterActive or RuntimeStatus.kgFilterMatches(indexed.weight,
                                Settings.TargetKGMode, Settings.TargetKGThreshold, indexed.weightKnown))
                            and (not valueFilterActive or RuntimeStatus.valueFilterMatches(indexed.value,
                                Settings.TargetValueThreshold, "atLeast", indexed.valueKnown))
                            and (prio ~= "Mutation" or #muts > 0))))
                    if eligible and tostring(rec.State) == "Dropped" then
                        selectedDropped += 1
                    elseif eligible and tostring(rec.State) == "Slot"
                        and blacklist[rec.Uid] and os.clock() <= blacklist[rec.Uid]
                    then
                        selectedCooling += 1
                    end
                end
            end

            -- No egg worth stealing → hand the character to Auto-Place & co.
            ProgressionCtl.treadmillSuppressed = false
            Arb.stealWants = false
            Arb.release("Steal")
            RuntimeStatus.set("target", "🎯 Target: none")
            RuntimeStatus.carry = "📦 Carry: none"
            if riftCollect then
                setStealStatus("🌀 Waiting for a required Rift egg")
            elseif unlockCrane then
                setStealStatus("🔓 Great Bloom · waiting for Crane egg")
            elseif craneReserved then
                setStealStatus("🔓 Crane reserved · continuing unlock")
            elseif selectedDropped > 0 and not Settings.PersistentSteal then
                setStealStatus(("🟡 %d selected egg%s dropped · enable Persistent")
                    :format(selectedDropped, selectedDropped == 1 and "" or "s"))
            elseif selectedCooling > 0 then
                setStealStatus(("🟡 %d target%s cooling down")
                    :format(selectedCooling, selectedCooling == 1 and "" or "s"))
            elseif blockedArea > 0 then
                setStealStatus(("🟡 Higher Speed Power needed for %d egg%s"):format(
                    blockedArea, blockedArea == 1 and "" or "s"))
            else
                setStealStatus("🟡 Waiting for target")
            end
            waitForScannerWake(5)
            continue
        end

        -- ── Phase 3: go to it and grab it ──
        local bestRar = best.rar
        -- Keep the groupbox status short enough for its fixed one-line card.
        -- Detailed target metadata is shown by RuntimeStatus immediately below.
        setStealStatus(riftCollect and "🌀 Required Rift egg locked"
            or unlockCrane and "🔓 Crane egg locked" or "🟢 Target locked")
        RuntimeStatus.set("target", ("🎯 Target: %s %s · %.2f kg"):format(
            tostring(bestRar._id), tostring(best.rec.AssetCategory), tonumber(best.weight) or 0))
        local targetEntry = AssetsDir and AssetsDir.Directory
            and AssetsDir.Directory[tostring(best.rec.AssetCategory)]
        do
            -- Freeze the selector that authorized this transaction. Rift
            -- collection deliberately bypasses Target* filters, so its claims must
            -- not inherit ordinary Steal Alerts from the shared carry callback.
            -- A dropped/retried UID keeps its first source even if the event or
            -- internal selector changes state before the claim is acknowledged.
            local previousTarget = stealRuntime.webhookTarget
            local targetSource = riftCollect and "rift"
                or unlockCrane and "internal"
                or "steal-filter"
            if type(previousTarget) == "table"
                and tostring(previousTarget.uid) == tostring(best.rec.Uid)
                and previousTarget.source ~= nil then
                targetSource = previousTarget.source
            end
            stealRuntime.webhookTarget = {
                uid = best.rec.Uid,
                source = targetSource,
                category = tostring(best.rec.AssetCategory or "Unknown"),
                rarity = tostring(bestRar._id or "Unknown"),
                area = tostring(best.rec.AreaId or "Unknown"),
                mutations = #best.muts > 0 and table.concat(best.muts, ", ") or "None",
                scale = tonumber(best.rec.AssetScale) or 1,
                income = tonumber(best.score) or 0,
                distance = tonumber(best.dist) or 0,
                icon = targetEntry and ((targetEntry.Egg and targetEntry.Egg.Icon) or targetEntry.Icon),
            }
        end
        stealRuntime.lockedUid = best.rec.Uid
        if Settings.PersistentSteal then stealRuntime.persistentUid = best.rec.Uid end
        best = best.rec
        ProgressionCtl.treadmillSuppressed = true

        -- Own the character and quiet all other automation for the complete
        -- outbound → request → return transaction.
        Arb.stealWants = true
        if not Arb.acquireWait("Steal", 4) then
            setStealStatus("🟡 Waiting for pen…")
            task.wait(0.5)
            continue
        end
        -- Recover the exact dropped carry before opening another maintenance
        -- window. An already-running pet action still has to retire below.
        Arb.critical, Arb.sellDuringSteal = true, false
        if not Arb.waitPets(stealOn, 4) then
            task.wait(0.1)
            continue
        end

        -- Anti-treadmill: the native session anchors/presents the character. Use
        -- the game's own unequip endpoint and wait for its state event before any
        -- staging or steal movement begins.
        local exitedTreadmillForTarget = ProgressionCtl.detectActiveTreadmill() ~= nil
            or not ProgressionCtl.characterReadyToMove()
        if not ProgressionCtl.requestTreadmillExit() then
            Arb.critical, Arb.stealWants = false, false
            Arb.release("Steal")
            setStealStatus(ProgressionCtl.treadmillExitRequest.inFlight
                and "🟡 Treadmill server pending — retrying"
                or "🟡 Could not leave treadmill — retrying")
            task.wait(0.25)
            continue
        end

        -- Auto-Place, Sell, or Great Bloom may leave a Tool equipped after their
        -- worker yields. Require the tool to disappear and remain absent long
        -- enough to replicate; one Heartbeat was not a server-side handoff.
        if not ProgressionCtl.waitForToolFree(1.5) then
            Arb.critical, Arb.stealWants = false, true
            setStealStatus("🟡 Finishing previous activity — retrying")
            task.wait(0.1)
            continue
        end

        -- The event may become active while a normal target is leaving the
        -- treadmill. Abort that outbound transaction before it can carry the
        -- old Auto Steal priority into Rift collection.
        local liveRiftUid = not carryLossRecoveryPending()
            and RuntimeStatus.riftCollecting == true
            and RuntimeStatus.riftTargetUid or nil
        if liveRiftUid and tostring(best.Uid) ~= tostring(liveRiftUid) then
            if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                stealRuntime.lockedUid = nil
            end
            Arb.critical, Arb.stealWants = false, false
            Arb.release("Steal")
            setStealStatus("🌀 Event target changed · selecting nearest")
            waitForScannerWake(0.05)
            continue
        end

        -- Target selection happens before the native treadmill unequip request,
        -- which may take up to 2.5 seconds. Revalidate after that delay instead
        -- of beginning TrackStart staging with an obsolete UID.
        do
            local departureRec = findAreaEgg(best.Uid)
            local departureState = departureRec and tostring(departureRec.State) or "Missing"
            if not departureRec or (departureState ~= "Slot" and departureState ~= "Dropped") then
                local persistentWait = Settings.PersistentSteal and departureRec
                    and departureState ~= "Claimed"
                Arb.critical = false
                Arb.release("Steal")
                if persistentWait then
                    ProgressionCtl.treadmillSuppressed = true
                    Arb.stealWants = true
                    Arb.stealBeat = os.clock()
                    setStealStatus(("🔁 Persistent — target became %s"):format(departureState))
                    waitForScannerWake(0.75)
                else
                    if tostring(stealRuntime.persistentUid) == tostring(best.Uid) then
                        stealRuntime.persistentUid = nil
                    end
                    if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                        stealRuntime.lockedUid = nil
                    end
                    stealRuntime.webhookTarget = nil
                    ProgressionCtl.treadmillSuppressed = false
                    Arb.stealWants = false
                    RuntimeStatus.set("target", "🎯 Target: none")
                    if RuntimeStatus.candidateIndex then
                        RuntimeStatus.candidateIndex:Invalidate(
                            best.Uid, "target changed while leaving treadmill"
                        )
                    end
                    setStealStatus(("🟡 Target became %s — rescanning"):format(departureState))
                    waitForScannerWake(0.08)
                end
                continue
            end
            best = departureRec
        end

        -- Every fresh outbound steal begins at the canonical centered TrackStart.
        -- A recent recoverable rejection for this exact locked UID is one
        -- transaction even if server correction moved the character away from the
        -- egg. Resume from the current gameplay-side position; only fresh targets,
        -- death/reset conditions, or a correction across the entrance restage.
        do
            local retryRoot, retryHumanoid = getCharParts()
            local retrySide = retryRoot and lineSide(retryRoot.Position)
            local retryDistance = retryRoot and best.BottomCFrame
                and ((retryRoot.Position - best.BottomCFrame.Position)
                    * Vector3.new(1, 0, 1)).Magnitude or math.huge
            local failureKind = tostring(stealRuntime.lastRequestKind or "")
            local failureText = string.lower(tostring(stealRuntime.lastRequestError or ""))
            local recoverableRetry = failureKind == "movement-trust"
                or failureKind == "position-sync"
                or failureKind == "activity-sync"
                or failureKind == "movement-retry"
                or failureKind == "server"
                or failureKind == "retry"
                or failureKind == "carry-loss-sync"
                or failureKind == "death-drop-sync"
                or failureKind == "carry-drop"
            local droppedRecovery = RuntimeStatus.activeDroppedRecoveryRecord(best.Uid) ~= nil
            recoverableRetry = recoverableRetry
                and not failureText:find("inventory is full", 1, true)
                and not failureText:find("gameplay area", 1, true)
            local retryingSameUid = retryRoot and retryHumanoid and retryHumanoid.Health > 0
                and tostring(stealRuntime.requestFailureUid) == tostring(best.Uid)
                and tostring(stealRuntime.lockedUid) == tostring(best.Uid)
                and recoverableRetry
                and (droppedRecovery
                    or os.clock() - (tonumber(stealRuntime.requestFailureAt) or 0) <= 6)
                and (droppedRecovery or (retrySide ~= nil and retrySide > 0))
            if retryingSameUid then
                RuntimeStatus.retryResumeMode = retryDistance <= 8
                    and "beside-egg" or "current-position"
                RuntimeStatus.retryResumeDistance = retryDistance
                RuntimeStatus.retryResumeUid = best.Uid
                if failureKind == "movement-retry" then
                    setStealStatus("⚡ Resuming interrupted route")
                elseif retryDistance <= 8 then
                    setStealStatus(failureKind == "carry-drop"
                        and "🥚 Reclaiming dropped egg"
                        or (failureKind == "movement-trust"
                            and "🔁 Movement trust — retrying beside egg"
                            or "🔁 Carry sync — retrying beside egg"))
                else
                    setStealStatus(failureKind == "carry-drop"
                        and "🔁 Returning to dropped egg"
                        or "🔁 Carry retry — resuming from current position")
                end
            else
                RuntimeStatus.retryResumeMode = "track-start"
                RuntimeStatus.retryResumeDistance = nil
                RuntimeStatus.retryResumeUid = nil
            end

            local stagedRec = findAreaEgg(best.Uid)
            local stagedState = stagedRec and tostring(stagedRec.State)
            if not stagedRec or (stagedState ~= "Slot" and stagedState ~= "Dropped") then
                ProgressionCtl.treadmillSuppressed = false
                Arb.critical, Arb.stealWants = false, false
                Arb.release("Steal")
                if RuntimeStatus.candidateIndex then
                    RuntimeStatus.candidateIndex:Invalidate(best.Uid, "target changed before travel")
                end
                setStealStatus("🟡 Target changed — rescanning")
                waitForScannerWake(0.08)
                continue
            end
            best = stagedRec
        end

        if areaResetActive() then
            setStealStatus("⏳ Ready — waiting for wall")
            local waitTime = resetWallClosed() and 10
                or math.max(0.25, areaResetUntil - os.clock())
            waitForScannerWake(waitTime, function()
                return not areaResetActive()
            end)
            if areaResetActive() then continue end

            local openedSettle = 0.15 - (os.clock() - wallOpenedAt)
            if wallOpenedAt > 0 and openedSettle > 0 then task.wait(openedSettle) end
            local refreshed = findAreaEgg(best.Uid)
            local refreshedState = refreshed and tostring(refreshed.State)
            if not refreshed or (refreshedState ~= "Slot" and refreshedState ~= "Dropped")
                or not refreshed.BottomCFrame then
                Arb.critical, Arb.stealWants = false, false
                Arb.release("Steal")
                if RuntimeStatus.candidateIndex then
                    RuntimeStatus.candidateIndex:Invalidate(best.Uid, "target changed at wall open")
                end
                setStealStatus("🟡 Target changed — rescanning")
                waitForScannerWake(0.08)
                continue
            end
            best = refreshed
        end

        local eventTransaction = type(stealRuntime.webhookTarget) == "table"
            and stealRuntime.webhookTarget.source == "rift"

        local outStarted = os.clock()
        -- ATTEMPTS measures target transactions, not remote retries. A rejected
        -- pickup can issue RequestCarryAreaEgg again for the same locked UID, but
        -- it is still one visible steal attempt until that egg is claimed,
        -- retired, or Auto-Steal is reset.
        if tostring(stealRuntime.attemptUid) ~= tostring(best.Uid) then
            stealRuntime.attemptUid = best.Uid
            RuntimeStatus.attempts = (RuntimeStatus.attempts or 0) + 1
        end
        RuntimeStatus.beginStealTimer(best.Uid)
        -- Registered movement can land exactly on the egg because its final step
        -- is clamped to the remaining vector. Humanoid fallback keeps a practical
        -- reach radius, but the fast path mirrors the observed native transaction:
        -- stop on the egg, settle, invoke once, then wait for carry proof.
        local pickupReach = 0.35
        -- The native sell remote is UID-only after a pet Tool is held. Permit its
        -- bounded item loop while we travel toward the egg, when no carry exists.
        -- This prevents continuous Auto-Steal targets from starving Sell Full.
        Arb.sellDuringSteal = false -- bait preparation owns the inventory handoff
        local reached, reachReason = RuntimeStatus.moveToStealTarget(
            best.Uid, best.BottomCFrame.Position, pickupReach, function()
            if not stealOn() then return false end
            local eventUid = not carryLossRecoveryPending()
                and RuntimeStatus.riftCollecting == true
                and RuntimeStatus.riftTargetUid or nil
            -- An outbound Rift target is valid only while the event
            -- still owns that exact UID. Normal Steal priority removes event
            -- ownership; treating nil as permission made the old event route
            -- continue all the way to pickup.
            if eventTransaction then
                if eventUid == nil or tostring(best.Uid) ~= tostring(eventUid) then
                    return false
                end
            end
            local rec = findAreaEgg(best.Uid)
            return rec ~= nil and (tostring(rec.State) == "Slot" or tostring(rec.State) == "Dropped")
        end, nil, function()
            return resetWallClosed() or ProgressionCtl.detectActiveTreadmill() ~= nil
        end)
        Arb.sellDuringSteal = false

        local liveEventUid = not carryLossRecoveryPending()
            and RuntimeStatus.riftCollecting == true
            and RuntimeStatus.riftTargetUid or nil
        if eventTransaction and (liveEventUid == nil
            or tostring(best.Uid) ~= tostring(liveEventUid)) then
            if tostring(stealRuntime.persistentUid) == tostring(best.Uid) then
                stealRuntime.persistentUid = nil
            end
            if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                stealRuntime.lockedUid = nil
            end
            if tostring(stealRuntime.attemptUid) == tostring(best.Uid) then
                stealRuntime.attemptUid = nil
            end
            blacklist[best.Uid] = nil
            stealRuntime.webhookTarget = nil
            Arb.critical, Arb.stealWants = false, false
            Arb.release("Steal")
            RuntimeStatus.pauseStealTimer()
            setStealStatus(RuntimeStatus.riftPriorityYield == true
                and "⏸️ Normal Steal has priority"
                or "🌀 Event target changed · rescanning")
            waitForScannerWake(0.05)
            continue
        end

        if not stealOn() then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            refreshStealStatus()
            continue
        end

        if not reached then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            if not resetWallClosed() and reachReason ~= "aborted" then
                RuntimeStatus.recordSpeedResult(false, "outbound-" .. tostring(reachReason))
            end
            if ProgressionCtl.detectActiveTreadmill() then
                ProgressionCtl.requestTreadmillExit()
                setStealStatus("🟡 Treadmill blocked — exiting")
            elseif resetWallClosed() or reachReason == "aborted" then
                Arb.stealWants = false
                Arb.release("Steal")
                setStealStatus("⏳ Reset wall closed — stopped")
            elseif (reachReason == "chicken-tp" or RuntimeStatus.glideRetryClass(reachReason) or reachReason == "cancelled")
                and (function()
                        local rec = findAreaEgg(best.Uid)
                        local state = rec and tostring(rec.State) or nil
                        return rec ~= nil and (state == "Slot" or state == "Dropped")
                    end)() then
                -- A movement-only interruption is not a failed target. Preserve
                -- the exact UID and resume from the current gameplay-side
                -- position after a short bounded settle. The former generic path
                -- blacklisted it for 20 seconds, released Steal, and displayed
                -- Target retry pending / Idle in the middle of the field.
                local now = os.clock()
                local sameRetry = tostring(stealRuntime.requestFailureUid)
                        == tostring(best.Uid)
                    and stealRuntime.lastRequestKind == "movement-retry"
                    and now - (tonumber(stealRuntime.requestFailureAt) or 0) <= 6
                stealRuntime.requestFailureCount = sameRetry
                    and math.min((stealRuntime.requestFailureCount or 0) + 1, 5) or 1
                stealRuntime.requestFailureUid = best.Uid
                stealRuntime.requestFailureAt = now
                stealRuntime.lastRequestKind = "movement-retry"
                stealRuntime.lastRequestError = "outbound " .. tostring(
                    reachReason == "chicken-tp" and RuntimeStatus.ChickenTP.lastReason or reachReason)
                blacklist[best.Uid] = now + math.min(
                    0.35, 0.06 * stealRuntime.requestFailureCount)
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants = true
                Arb.stealBeat = now
                if reachReason == "chicken-tp" then
                    setStealStatus(tostring(RuntimeStatus.ChickenTP.lastReason))
                    -- Keep ownership alive but do not re-run full preparation
                    -- or emit another status on each frame of a failed attempt.
                    local retryAt=os.clock()+2
                    while sessionAlive() and stealOn() and os.clock()<retryAt do
                        if resetWallClosed() or not Arb.hold("Steal") then break end
                        task.wait(0.1)
                    end
                else
                    setStealStatus("⚡ Movement interrupted · resuming")
                    task.wait(0.05)
                end
            elseif reachReason == "bat" then
                blacklist[best.Uid] = os.clock() + 1.5
                setStealStatus("🛡️ Bat nearby — waiting")
                task.wait(0.2)
            else
                blacklist[best.Uid] = os.clock() + 20
                setStealStatus("🟡 Retrying…")
                task.wait(0.1)
            end
            continue
        end

        -- Settling is part of the grab transaction. Seal character ownership now
        -- so a pet/tool worker cannot begin during the short paid-like pause.
        Arb.critical = true
        if Arb.inventoryBlocksSteal() then
            setStealStatus("⏳ Finishing inventory handoff · securing egg")
            if not Arb.waitPets(stealOn, 4) then task.wait(0.1); continue end
            if not stealOn() then
                Arb.critical = false
                RuntimeStatus.pauseStealTimer()
                refreshStealStatus()
                continue
            end
        end
        local pickupCharacter = LocalPlayer.Character
        local pickupGeneration = stealRuntime.respawnGeneration

        -- The target can move or be replaced during the outbound trip. Settle only
        -- against a fresh record that is still available and still under our feet.
        local settleRec = findAreaEgg(best.Uid)
        local settleState = settleRec and tostring(settleRec.State) or "Missing"
        if not settleRec or (settleState ~= "Slot" and settleState ~= "Dropped")
            or not settleRec.BottomCFrame then
            Arb.critical = false
            if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                stealRuntime.lockedUid = nil
            end
            if tostring(stealRuntime.persistentUid) == tostring(best.Uid)
                and settleState == "Claimed" then
                stealRuntime.persistentUid = nil
            end
            RuntimeStatus.pauseStealTimer()
            setStealStatus(("🟡 Target became %s — rescanning"):format(settleState))
            continue
        end
        best = settleRec

        if Settings.StealMovementBackend == "Glide"
            and tostring(stealRuntime.requestFailureUid) == tostring(best.Uid)
            and stealRuntime.lastRequestKind == "position-sync"
            and (stealRuntime.requestFailureCount or 0) >= 2
            and string.lower(tostring(stealRuntime.lastRequestError or "")):find("get closer", 1, true) then
            setStealStatus("🥚 Re-approaching egg on foot…")
            local recovered = RuntimeStatus.glidePickupReapproach(best.BottomCFrame.Position, function()
                if not stealOn() or LocalPlayer.Character ~= pickupCharacter
                    or stealRuntime.respawnGeneration ~= pickupGeneration then return false end
                local rec = findAreaEgg(best.Uid)
                return rec ~= nil and (tostring(rec.State) == "Slot" or tostring(rec.State) == "Dropped")
            end, resetWallClosed)
            if not recovered then
                Arb.critical = false
                stealRuntime.requestFailureAt = os.clock()
                stealRuntime.lastRequestError = "physical pickup re-approach interrupted"
                blacklist[best.Uid] = os.clock() + 0.10
                continue
            end
        end

        local settleRoot = getCharParts()
        local settleDistance = settleRoot
            and ((settleRoot.Position - best.BottomCFrame.Position)
                * Vector3.new(1, 0, 1)).Magnitude or math.huge
        if settleDistance > pickupReach then
            Arb.critical = false
            stealRuntime.requestFailureUid = best.Uid
            stealRuntime.requestFailureAt = os.clock()
            stealRuntime.lastRequestKind = "position-sync"
            stealRuntime.lastRequestError = "target moved before pickup settle"
            blacklist[best.Uid] = os.clock() + 0.08
            RuntimeStatus.pauseStealTimer()
            setStealStatus("🟡 Closing pickup distance…")
            continue
        end

        -- Match the observed consistent transaction: after the final movement,
        -- remain continuously stationary on the egg before invoking. At the live
        -- comparison client's ~64 ms ping this is ~0.35 s; the Invoke/carry reply
        -- then makes the visible pause roughly half a second. Treadmill handoffs
        -- receive a little more margin without changing the one-request contract.
        local pingSeconds = getNetworkPingSeconds()
        local replicationSettle = math.clamp(pingSeconds + 0.29, 0.35, 0.55)
        if exitedTreadmillForTarget then
            replicationSettle = math.max(replicationSettle, 0.45)
        end
        local retryKind = tostring(stealRuntime.lastRequestKind)
        local retryingPickupSync = tostring(stealRuntime.requestFailureUid) == tostring(best.Uid)
            and (retryKind == "movement-trust" or retryKind == "position-sync")
            and os.clock() - (tonumber(stealRuntime.requestFailureAt) or 0) <= 6
        if retryingPickupSync then
            replicationSettle = math.max(replicationSettle, 0.55)
        end
        if settleState == "Slot"
            and RuntimeStatus.activeDroppedRecoveryRecord(best.Uid) == nil then
            replicationSettle = RuntimeStatus.ChickenTP.pickupDelay(best.Uid, replicationSettle)
        end
        replicationSettle = RuntimeStatus.droppedPickupSettle(best.Uid, settleState,
            replicationSettle, pingSeconds, retryingPickupSync or exitedTreadmillForTarget)
        -- Create the request table before settling; publish its lock only after all gates pass.
        local request = {
            attempts = 1, owner = "Steal", session = SESSION.Marker,
            movementBackend = Settings.StealMovementBackend,
            character = pickupCharacter, generation = pickupGeneration,
        }
        local settleHardDeadline = os.clock() + replicationSettle + 1
        local stableSince, previousSettlePosition
        local pickupSettled = false
        setStealStatus(RuntimeStatus.activeDroppedRecoveryRecord(best.Uid)
            and "🥚 Securing dropped egg…" or "🥚 Settling at egg…")
        while sessionAlive() and stealOn() and os.clock() < settleHardDeadline do
            if resetWallClosed()
                or LocalPlayer.Character ~= pickupCharacter
                or stealRuntime.respawnGeneration ~= pickupGeneration then
                break
            end

            local root, humanoid = getCharParts()
            if not (root and humanoid and humanoid.Health > 0) then break end
            local settleKind = tostring(stealRuntime.lastRequestKind or "")
            local recoveryExpected = (settleKind == "carry-drop"
                    or settleKind == "death-drop-sync" or settleKind == "carry-loss-sync")
                and tostring(stealRuntime.lockedUid) == tostring(best.Uid)
            settleRec = RuntimeStatus.activeDroppedRecoveryRecord(best.Uid)
            if recoveryExpected and not settleRec then break end
            if settleRec then
                best = settleRec
            end
            local now = os.clock()
            local planarDistance = ((root.Position - best.BottomCFrame.Position)
                * Vector3.new(1, 0, 1)).Magnitude
            local stationary = RuntimeStatus.glidePickupStationary(root, humanoid,
                previousSettlePosition, planarDistance, pickupReach)
                and RuntimeStatus.DevChickenTween.pickupHeightReady(best.BottomCFrame.Position)
            if planarDistance > pickupReach then break end

            if RuntimeStatus.activeDroppedRecoveryRecord(best.Uid)
                and planarDistance > math.max(pickupReach, 0.15) then
                -- Dropped eggs can slide for a few frames after a hit. Re-chase
                -- the new BottomCFrame immediately instead of consuming the full
                -- stationary timeout at the old position.
                break
            end

            if stationary then
                stableSince = stableSince or now
            else
                stableSince = nil
            end
            previousSettlePosition = root.Position
            RuntimeStatus.brakeGlidePickup(root)

            if stableSince and now - stableSince >= replicationSettle then
                pickupSettled = true
                break
            end
            RunService.Heartbeat:Wait()
        end

        if not stealOn() then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            refreshStealStatus()
            continue
        end
        if not pickupSettled then
            Arb.critical = false
            if resetWallClosed() then
                Arb.stealWants = false
                Arb.release("Steal")
                RuntimeStatus.pauseStealTimer()
                setStealStatus("⏳ Reset wall closed — waiting")
            elseif LocalPlayer.Character ~= pickupCharacter
                or stealRuntime.respawnGeneration ~= pickupGeneration then
                Arb.stealWants = false
                Arb.release("Steal")
                RuntimeStatus.pauseStealTimer()
                setStealStatus("🟡 Respawning — rescanning")
            elseif RuntimeStatus.activeDroppedRecoveryRecord(best.Uid) then
                stealRuntime.requestFailureUid = best.Uid
                stealRuntime.requestFailureAt = stealRuntime.dropDetectedAt
                stealRuntime.lastRequestKind = "carry-drop"
                stealRuntime.lastRequestError = "dropped egg moved during pickup settle"
                blacklist[best.Uid] = nil
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants, Arb.critical = true, true
                Arb.stealBeat = os.clock()
                setStealStatus("🥚 Dropped egg moved · catching it now")
            else
                stealRuntime.requestFailureUid = best.Uid
                stealRuntime.requestFailureAt = os.clock()
                stealRuntime.lastRequestKind = "position-sync"
                stealRuntime.lastRequestError = "pickup position did not remain stable"
                blacklist[best.Uid] = os.clock() + 0.10
                RuntimeStatus.pauseStealTimer()
                setStealStatus("🟡 Stabilizing on egg — retrying")
            end
            continue
        end
        local pickupSettledAt = os.clock()
        local actualPickupSettle = stableSince and pickupSettledAt - stableSince or 0

        if not ProgressionCtl.waitForToolFree(0.75) then
            Arb.critical = false
            stealRuntime.requestFailureUid = best.Uid
            stealRuntime.requestFailureAt = os.clock()
            stealRuntime.lastRequestKind = "activity-sync"
            stealRuntime.lastRequestError = "equipped tool still retiring"
            blacklist[best.Uid] = os.clock() + 0.15
            RuntimeStatus.pauseStealTimer()
            setStealStatus("🟡 Previous activity syncing — retrying")
            continue
        end

        local character = LocalPlayer.Character
        if character and character:GetAttribute("IsTrapped") == true then
            Arb.critical = false
            stealRuntime.requestFailureUid = best.Uid
            stealRuntime.requestFailureAt = os.clock()
            stealRuntime.lastRequestKind = "activity-sync"
            stealRuntime.lastRequestError = "character is trapped"
            blacklist[best.Uid] = os.clock() + 0.20
            RuntimeStatus.pauseStealTimer()
            setStealStatus("🟡 Trap releasing — holding target")
            continue
        end

        -- The snapshot can change while the final root position is replicating.
        -- Re-read this exact UID now so state, slot key, and BottomCFrame all
        -- belong to the record that the request is about to send.
        local pickupRec = findAreaEgg(best.Uid)
        local pickupState = pickupRec and tostring(pickupRec.State) or "Missing"
        if not pickupRec or (pickupState ~= "Slot" and pickupState ~= "Dropped")
            or not pickupRec.BottomCFrame then
            Arb.critical = false
            if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                stealRuntime.lockedUid = nil
            end
            if tostring(stealRuntime.persistentUid) == tostring(best.Uid)
                and pickupState == "Claimed" then
                stealRuntime.persistentUid = nil
            end
            RuntimeStatus.pauseStealTimer()
            setStealStatus(("🟡 Target became %s — rescanning"):format(pickupState))
            continue
        end
        best = pickupRec

        local approachRoot = getCharParts()
        -- The movement engine reaches targets in the horizontal plane because
        -- HumanoidRootPart naturally sits about three studs above an egg's
        -- BottomCFrame.  Keep this final validation planar too; using full 3D
        -- distance made the 2.25-stud gate impossible even when perfectly
        -- centered over the egg, so no carry request was ever sent.
        local away = approachRoot
            and ((approachRoot.Position - best.BottomCFrame.Position)
                * Vector3.new(1, 0, 1)).Magnitude or math.huge
        if resetWallClosed() then
            Arb.critical, Arb.stealWants = false, false
            Arb.release("Steal")
            RuntimeStatus.pauseStealTimer()
            setStealStatus("⏳ Reset wall closed — waiting")
            continue
        end
        if away > pickupReach or (approachRoot and (lineSide(approachRoot.Position) or -1) <= 0)
            or (request.movementBackend == "Glide"
                and RuntimeStatus.glideMovementBlocked(approachRoot)) then
            Arb.critical = false
            stealRuntime.requestFailureUid = best.Uid
            stealRuntime.requestFailureAt = os.clock()
            stealRuntime.lastRequestKind = "position-sync"
            stealRuntime.lastRequestError = "local pickup position drifted"
            blacklist[best.Uid] = os.clock() + 0.15
            RuntimeStatus.pauseStealTimer()
            setStealStatus("🟡 Closing pickup distance…")
            continue
        end
        if LocalPlayer.Character ~= pickupCharacter
            or stealRuntime.respawnGeneration ~= pickupGeneration then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            setStealStatus("🟡 Character changed — rescanning")
            continue
        end
        if type(getgenv().__CHSAE_CarryRequest) == "table" then
            RuntimeStatus.carry = "📦 Carry: previous request still retiring"
            setStealStatus("⏳ Previous carry request pending")
            continue
        end
        -- Exactly ONE synchronous carry invoke may exist process-wide. InvokeServer
        -- cannot be cancelled, so a timeout retreats and waits for that same call;
        -- it never spawns another request behind the stalled one.
        Arb.critical = true
        RuntimeStatus.carry = "📦 Carry: waiting for local proof"
        local slotKey = carrySlotKey(best)
        local claimSequenceAtRequest = stealRuntime.claimSequence
        request.started, request.done, request.inFlight = os.clock(), false, true
        request.accepted, request.carrySeen, request.carryActive = false, false, false
        request.carryEndedSeen, request.droppedSeen, request.claimSeen = false, false, false
        request.timedOut, request.error = false, nil
        request.uid, request.category = best.Uid, best.AssetCategory
        request.claimSequenceAtStart = claimSequenceAtRequest
        request.settledFor, request.requiredSettle = actualPickupSettle, replicationSettle
        request.pickupDistance, request.fromTreadmill = away, exitedTreadmillForTarget
        stealRuntime.lastPickupSettle = actualPickupSettle
        stealRuntime.lastPickupRequiredSettle = replicationSettle
        stealRuntime.lastPickupDistance = away
        stealRuntime.lastPickupFromTreadmill = exitedTreadmillForTarget
        getgenv().__CHSAE_CarryRequest = request
        local requestDeadline = request.started + 1.25
        task.spawn(function()
            local liveCharacter = LocalPlayer.Character
            local liveHumanoid = liveCharacter and liveCharacter:FindFirstChildOfClass("Humanoid")
            local characterReset = not sessionAlive()
                or liveCharacter ~= request.character
                or stealRuntime.respawnGeneration ~= request.generation
                or not liveHumanoid or liveHumanoid.Health <= 0
            if characterReset or resetWallClosed() then
                request.inFlight = false
                request.done = true
                request.completedAt = os.clock()
                request.accepted = false
                request.cooldownKind = characterReset and "character-reset" or "area-reset"
                request.cancelledByDeath = characterReset
                request.error = request.cooldownKind == "character-reset"
                    and "character changed before carry invoke"
                    or "gameplay area reset before carry invoke"
                request.retryAt = request.completedAt
                stealRuntime.lastRequestError = request.error
                stealRuntime.lastRequestKind = request.cooldownKind
                return
            end
            RuntimeStatus.carryRequests = (RuntimeStatus.carryRequests or 0) + 1
            local invoked, ok, err = pcall(EggCmds.RequestCarryAreaEgg, request.uid, slotKey)
            request.inFlight = false
            request.done = true
            request.completedAt = os.clock()
            request.accepted = invoked and ok == true
            request.error = invoked and tostring(err or (ok == true and "" or "server rejected"))
                or ("invoke:" .. tostring(ok))
            if request.supersededByDrop or request.supersededByRecovery then
                -- A newer exact-UID recovery owns this egg (Dropped, or restored
                -- to Slot after death). Keep the late result request-local so it
                -- cannot erase recovery state and force a TrackStart restart.
                request.cooldownKind = request.supersededByRecovery
                    and "superseded-recovery" or "superseded-drop"
                request.retryAt = request.completedAt
                return
            end
            if request.cancelledByDeath then
                request.cooldownKind = "character-reset"
                request.retryAt = request.completedAt
                return
            end
            stealRuntime.lastRequestError = request.error
            -- Keep the exact target locked, but do not manufacture a client-side
            -- cooldown around the game's carry remote. A successful Invoke waits
            -- only for the carry-state packet. Rejections receive a small per-UID
            -- retry delay so only one request can exist at a time.
            local retryDelay = 0
            if request.accepted then
                stealRuntime.requestFailureUid = nil
                stealRuntime.requestFailureCount = 0
                request.proofDeadline = request.completedAt
                    + math.clamp(pingSeconds * 4 + 0.35, 0.8, 1.5)
            else
                local errorText = string.lower(tostring(request.error or ""))
                -- Only the server's explicit final-reset verdict releases the
                -- transaction lock. Position sync, cooldown, generic rejection,
                -- and temporary replication gaps all retry this exact UID.
                if errorText:find("already claimed this reset", 1, true) then
                    request.cooldownKind = "unavailable"
                    if tostring(stealRuntime.persistentUid) == tostring(request.uid) then
                        stealRuntime.persistentUid = nil
                    end
                    if tostring(stealRuntime.lockedUid) == tostring(request.uid) then
                        stealRuntime.lockedUid = nil
                    end
                    if RuntimeStatus.candidateIndex then
                        RuntimeStatus.candidateIndex:Invalidate(request.uid, request.error)
                    end
                end
                local sameUid = tostring(stealRuntime.requestFailureUid) == tostring(request.uid)
                    and request.completedAt - (stealRuntime.requestFailureAt or 0) < 6
                stealRuntime.requestFailureUid = request.uid
                stealRuntime.requestFailureCount = sameUid
                    and math.min((stealRuntime.requestFailureCount or 0) + 1, 4) or 1
                stealRuntime.requestFailureAt = request.completedAt
                if request.cooldownKind == "unavailable" then
                    retryDelay = 0
                elseif errorText:find("movement is not currently trusted", 1, true) then
                    -- Server trust can trail the final registered movement packet,
                    -- especially after leaving a treadmill. Retain this exact UID
                    -- and retry beside it after a bounded stationary settle.
                    retryDelay = math.clamp(pingSeconds * 2 + 0.12, 0.25, 0.55)
                    request.cooldownKind = "movement-trust"
                elseif errorText:find("get closer", 1, true) then
                    retryDelay = math.clamp(pingSeconds * 0.5, 0.03, 0.10)
                    request.cooldownKind = "position-sync"
                elseif errorText:find("cooldown", 1, true) then
                    -- A real server verdict is scoped to this UID; it must not
                    -- pause candidate scanning or every other valid egg.
                    retryDelay = math.clamp(pingSeconds + 0.05, 0.12, 0.30)
                    request.cooldownKind = "server"
                else
                    retryDelay = math.clamp(pingSeconds + 0.02, 0.08, 0.22)
                    request.cooldownKind = "retry"
                end
            end
            stealRuntime.lastRequestKind = tostring(request.cooldownKind or
                (request.accepted and "accepted" or "retry"))
            request.retryAt = request.completedAt + retryDelay
        end)

        -- Stay beside the egg until the first server answer when it arrives in a
        -- normal ping window. The old fixed 0.12 s deadline often began returning
        -- while Invoke was still validating distance; that produced "Get closer"
        -- followed by a complete second trip. A rejection can leave immediately,
        -- while an accepted reply receives a second ownership-replication grace.
        setStealStatus("🥚 Requesting carry…")
        local responseWindow = math.clamp(pingSeconds * 2.5 + 0.08, 0.22, 0.45)
        local carryConfirmDeadline = request.started + responseWindow
        while sessionAlive() and stealOn() and os.clock() < carryConfirmDeadline do
            if stillCarrying(best.Uid) then
                request.carrySeen = true
                RuntimeStatus.carry = "📦 Carry: locally verified"
                break
            end
            if claimConfirmed(best.Uid, best.AssetCategory, claimSequenceAtRequest) then break end
            if request.done and not request.accepted then break end
            RunService.Heartbeat:Wait()
        end

        local confirmed = claimConfirmed(best.Uid, best.AssetCategory, claimSequenceAtRequest)
        if request.done and request.accepted and not request.carrySeen and not confirmed then
            local ownershipGrace = math.clamp(pingSeconds * 3 + 0.18, 0.4, 0.9)
            local ownershipDeadline = math.max(
                carryConfirmDeadline,
                (request.completedAt or os.clock()) + ownershipGrace,
                tonumber(request.proofDeadline) or 0
            )
            RuntimeStatus.carry = "📦 Carry: accepted · syncing"
            setStealStatus("⏳ Grab accepted — syncing")
            while sessionAlive() and stealOn() and os.clock() < ownershipDeadline do
                if stillCarrying(best.Uid) then
                    request.carrySeen = true
                    RuntimeStatus.carry = "📦 Carry: locally verified"
                    break
                end
                confirmed = claimConfirmed(best.Uid, best.AssetCategory, claimSequenceAtRequest)
                if confirmed then break end
                RunService.Heartbeat:Wait()
            end
            confirmed = claimConfirmed(best.Uid, best.AssetCategory, claimSequenceAtRequest)
        end

        if not request.carrySeen and not confirmed and request.done and not request.accepted then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            if request.cooldownKind == "position-sync"
                or request.cooldownKind == "movement-trust" then
                RuntimeStatus.recordSpeedResult(false, request.cooldownKind)
            end
            RuntimeStatus.carry = "📦 Carry: not acquired · retrying"
            local err = tostring(request.error or "carry not verified")
            local errorText = string.lower(err)
            local inventoryFull, inventoryCount, inventoryCapacity = RuntimeStatus.eggInventoryCapacityState()
            local live = findAreaEgg(best.Uid)
            local liveState = live and tostring(live.State) or nil
            if resetWallClosed() then
                setStealStatus("⏳ Reset wall closed — retrying")
            elseif not live or (liveState ~= "Slot" and liveState ~= "Dropped") then
                if tostring(stealRuntime.persistentUid) == tostring(best.Uid) then
                    stealRuntime.persistentUid = nil
                end
                if tostring(stealRuntime.lockedUid) == tostring(best.Uid) then
                    stealRuntime.lockedUid = nil
                end
                setStealStatus("🟡 Egg no longer available — rescanning")
            elseif errorText:find("gameplay area", 1, true) then
                markAreaReset(3)
                setStealStatus("⏳ Re-entering…")
            elseif inventoryFull or RuntimeStatus.isEggInventoryFullError(errorText) then
                RuntimeStatus.stopAutoStealForFullInventory(inventoryCount, inventoryCapacity, err)
            elseif request.cooldownKind == "server" then
                setStealStatus("⏳ Server rejected carry — retrying")
            elseif request.cooldownKind == "movement-trust" then
                setStealStatus("⏳ Movement trust syncing — retrying")
            elseif request.cooldownKind == "position-sync" then
                setStealStatus("⏳ Position syncing — retrying")
            elseif Settings.PersistentSteal then
                setStealStatus("🔁 Grab rejected — retrying")
                RunService.Heartbeat:Wait()
            else
                -- A failed first contact is not a completed steal.  Keep scanning
                -- immediately while this egg remains Slot/Dropped; do not hand the
                -- character to the treadmill just because we bumped another egg.
                setStealStatus(("🟡 Grab unverified · retrying: %s"):format(err:sub(1, 20)))
                RunService.Heartbeat:Wait()
            end
            continue
        end

        if not request.carrySeen and not confirmed and (request.inFlight or not request.done) then
            -- Never enter the home-return branch without positive carry/claim
            -- proof. InvokeServer may take longer than the short normal response
            -- window; the next loop retains Steal ownership beside this egg.
            Arb.critical = true
            ProgressionCtl.treadmillSuppressed = true
            RuntimeStatus.carry = "📦 Carry: response pending · holding position"
            setStealStatus("⏳ Carry response pending — holding at egg")
            task.wait(0.03)
            continue
        end

        if request.done and request.accepted and not request.carrySeen and not confirmed then
            -- Do not start the return trip on a successful server reply until
            -- this client has positive carry/claim proof.  The top-of-loop
            -- single-flight gate keeps us at the target for the remaining grace.
            Arb.critical = true
            RuntimeStatus.carry = "📦 Carry: accepted · awaiting proof"
            setStealStatus("⏳ Grab accepted — verifying")
            task.wait(0.03)
            continue
        end

        -- `carrySeen` is historical proof, not current ownership. A normal claim
        -- and a guard drop both publish Carry=false before their final packet. Do
        -- not launch an empty home trip in that gap: require this exact UID to be
        -- actively carried now, or its exact local claim feedback to be confirmed.
        local activeCarry = stillCarrying(best.Uid)
        request.carryActive = activeCarry
        if not confirmed and not activeCarry then
            Arb.critical = true
            ProgressionCtl.treadmillSuppressed = true
            Arb.stealWants = true
            Arb.stealBeat = os.clock()
            if request.droppedSeen == true
                and armDroppedEggReacquire(best.Uid,
                    "carry ended before safe-zone return") then
                setStealStatus("🔁 Egg dropped — stealing it again")
            else
                RuntimeStatus.carry = request.carrySeen
                    and "📦 Carry: ownership changed · verifying"
                    or "📦 Carry: awaiting exact ownership proof"
                setStealStatus(request.carrySeen
                    and "⏳ Carry changed — verifying at egg"
                    or "⏳ Grab proof pending — holding at egg")
            end
            task.wait(0.03)
            continue
        end

        local startArea = getStartArea()
        local home = startArea and (startArea.Position + Vector3.new(0, 3, 0))
            or getExitTarget(30)
        if not home then
            Arb.critical = false
            setStealStatus("🟡 No safe-zone target")
            task.wait(0.5)
            continue
        end

        setStealStatus(("🟢 %s → safe zone"):format(tostring(best.AssetCategory)))
        -- The accepted carry belongs to this area's guard. Set it explicitly here
        -- as well as in the replication event so a very fast return cannot race
        -- the AreaEggCarryStateChanged signal.
        local returnGuardAreaId = best.AreaId ~= nil and tostring(best.AreaId) or nil
        RuntimeStatus.activeGuardAreaId = returnGuardAreaId
        local backStarted = os.clock()
        local returned, returnReason = false, nil
        while sessionAlive() and not confirmed do
            returned, returnReason = RuntimeStatus.centeredStealReturnTo(
                home, stealOn, function()
                    local hasEgg = stillCarrying(best.Uid)
                    return resetWallClosed()
                        or ProgressionCtl.detectActiveTreadmill() ~= nil
                        or (request.done and not request.accepted)
                        or (not request.done and not request.carrySeen
                            and os.clock() >= requestDeadline + 0.25)
                        or (request.carrySeen and not hasEgg
                            and (droppedAreaEgg(best.Uid)
                                or RuntimeStatus.carryLostInField(best.Uid))
                            and not claimConfirmed(
                                best.Uid, best.AssetCategory, claimSequenceAtRequest))
                        or (request.carrySeen and not hasEgg
                            and tostring(stealRuntime.deathRecoveryUid) == tostring(best.Uid)
                            and tostring(RuntimeStatus.pendingDroppedUid) == tostring(best.Uid)
                            and not claimConfirmed(
                                best.Uid, best.AssetCategory, claimSequenceAtRequest))
                end, returnGuardAreaId)
            confirmed = claimConfirmed(
                best.Uid, best.AssetCategory, claimSequenceAtRequest)
            if returned or confirmed then break end
            if not RuntimeStatus.preserveCarriedReturn(best.Uid, returnReason) then break end
            if ProgressionCtl.detectActiveTreadmill() then
                ProgressionCtl.requestTreadmillExit()
                setStealStatus("🟡 Treadmill blocked — exiting")
                task.wait(0.10)
            elseif resetWallClosed() then
                setStealStatus("⏳ Wall closed — holding carried egg")
                waitForScannerWake(0.25, function()
                    return not resetWallClosed()
                end)
            else
                setStealStatus("↩️ Return interrupted · resuming safe zone")
                task.wait(0.03)
            end
        end

        if not returned and not confirmed then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            if not resetWallClosed() and returnReason ~= "aborted" then
                RuntimeStatus.recordSpeedResult(false, "return-" .. tostring(returnReason))
            end
            local requestError = tostring(request.error or "")
            local err = requestError ~= "" and requestError
                or tostring(returnReason or "unconfirmed")
            local inventoryFull, inventoryCount, inventoryCapacity = RuntimeStatus.eggInventoryCapacityState()
            if ProgressionCtl.detectActiveTreadmill() then
                ProgressionCtl.requestTreadmillExit()
                setStealStatus("🟡 Treadmill blocked — exiting")
            elseif resetWallClosed() then
                setStealStatus("⏳ Wall closed — holding egg")
            elseif err:find("gameplay area", 1, true) then
                markAreaReset(3)
                setStealStatus("⏳ Re-entering…")
            elseif inventoryFull or RuntimeStatus.isEggInventoryFullError(err) then
                RuntimeStatus.stopAutoStealForFullInventory(inventoryCount, inventoryCapacity, err)
            elseif request.carrySeen and droppedAreaEgg(best.Uid) then
                if armDroppedEggReacquire(best.Uid, "egg dropped during safe-zone return") then
                    setStealStatus("🔁 Egg dropped — stealing it again")
                    task.wait(0.03)
                end
            elseif request.carrySeen
                and tostring(stealRuntime.lastDroppedUid) == tostring(best.Uid) then
                -- CarryChanged can precede the Dropped snapshot by a few frames.
                -- Keep the transaction in place instead of blacklisting it and
                -- handing movement to TrackStart/Treadmill during replication.
                stealRuntime.lockedUid = best.Uid
                ProgressionCtl.treadmillSuppressed = true
                Arb.stealWants, Arb.critical = true, true
                setStealStatus("🔁 Egg drop syncing — holding recovery")
                waitForScannerWake(0.20)
            else
                if not Settings.PersistentSteal then blacklist[best.Uid] = os.clock() + 12 end
                setStealStatus(("🟡 Grab failed: %s"):format(err:sub(1, 30)))
                task.wait(0.1)
            end
            continue
        end

        local confirmDeadline = os.clock() + 4
        while sessionAlive() and stealOn() and os.clock() < confirmDeadline do
            confirmed = claimConfirmed(best.Uid, best.AssetCategory, claimSequenceAtRequest)
            if confirmed then break end
            if request.carrySeen and droppedAreaEgg(best.Uid) then break end
            if request.carrySeen
                and tostring(stealRuntime.deathRecoveryUid) == tostring(best.Uid)
                and tostring(RuntimeStatus.pendingDroppedUid) == tostring(best.Uid) then break end
            RunService.Heartbeat:Wait()
        end
        local postReturnCarry = carriedAreaEgg()
        carrying = postReturnCarry ~= nil
        RuntimeStatus.activeGuardAreaId = postReturnCarry and postReturnCarry.AreaId ~= nil
            and tostring(postReturnCarry.AreaId) or nil
        Arb.critical = carrying

        if confirmed then
            -- Current claim feedback can omit Uid. The transaction still knows
            -- the exact egg it delivered, so retire that candidate here instead
            -- of relying only on AreaEggClaimed's optional feedback field. Without
            -- this, the stale Slot is immediately selected again after success.
            if RuntimeStatus.candidateIndex then
                RuntimeStatus.candidateIndex:Invalidate(best.Uid, "transaction verified")
            end
            RuntimeStatus.activeGuardAreaId = nil
            RuntimeStatus.clearCarryLossRecovery(best.Uid)
            stealRuntime.persistentUid = nil
            stealRuntime.lockedUid = nil
            stealRuntime.lastDroppedUid = nil
            stealRuntime.dropDetectedAt = 0
            -- Close the successful transaction before touching metrics/UI. The
            -- former order left a completed request and Steal body ownership
            -- behind if a presentation callback threw, so Auto-Steal worked
            -- exactly once and then appeared frozen on "→ safe zone".
            if getgenv().__CHSAE_CarryRequest == request and request.inFlight ~= true then
                getgenv().__CHSAE_CarryRequest = nil
            end
            carrying = false
            ProgressionCtl.treadmillSuppressed = true
            Arb.stealWants, Arb.critical = true, true
            Arb.acquireWait("Steal", 0.5)
            RuntimeStatus.settleVerifiedClaim(stealOn)
            Arb.critical, Arb.stealWants = false, false
            Arb.release("Steal")
            RuntimeStatus.carry = "📦 Carry: delivery verified"
            -- Give the seller a safe opportunity between verified deliveries,
            -- before another target reserves the inventory for bait pickup.
            if Settings.AutoSell or Settings.SellPetsWhenFull or Settings.AutoSellEggs or Settings.SellEggsWhenFull then
                Arb.wakeSeller()
                task.wait(0.1)
            end
            local outTime = backStarted - outStarted
            local backTime = os.clock() - backStarted
            pcall(RuntimeStatus.finishStealTimer, outTime, backTime)
            pcall(RuntimeStatus.recordSpeedResult, true, "verified")
            pcall(setStealStatus,
                ("✅ Claim verified · %.2fs out / %.2fs back"):format(outTime, backTime))
            -- The centered TrackStart settle above is already the natural gap
            -- between transactions; begin scanning the next egg immediately.
        elseif carrying then
            RuntimeStatus.carry = "📦 Carry: locally verified"
            setStealStatus("🟢 Carrying → home")
        elseif armDroppedEggReacquire(best.Uid, "delivery return lost the egg") then
            setStealStatus("🔁 Egg dropped — stealing it again")
        elseif tostring(stealRuntime.lastDroppedUid) == tostring(best.Uid)
            and tostring(stealRuntime.lastRequestKind) == "carry-drop" then
            stealRuntime.lockedUid = best.Uid
            ProgressionCtl.treadmillSuppressed = true
            Arb.stealWants, Arb.critical = true, true
            setStealStatus("🔁 Egg drop syncing — holding recovery")
            waitForScannerWake(0.20)
        elseif Settings.PersistentSteal then
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            RuntimeStatus.carry = "📦 Carry: missing · waiting"
            setStealStatus("🔁 Carry lost — waiting for target")
        else
            Arb.critical = false
            RuntimeStatus.pauseStealTimer()
            RuntimeStatus.carry = "📦 Carry: dropped"
            blacklist[best.Uid] = os.clock() + 3
            Arb.stealWants = false
            Arb.release("Steal")
            setStealStatus("🟡 Delivery unverified — rescanning")
        end
    end
    setIntegrityGuard(false)
    setStealControlLock(false)
        end, function(err)
            local ok, trace = pcall(debug.traceback, tostring(err), 2)
            return ok and trace or tostring(err)
        end)

        if not sessionAlive() then break end
        if not workerOk then
            warn("[CloverHub-SAE][steal] worker recovered: " .. tostring(workerError))
            RuntimeStatus.movementPhase = nil
            local pending = getgenv().__CHSAE_CarryRequest
            -- Never abandon an InvokeServer that is genuinely still running.
            -- Completed requests are safe to retire; live carry replication is
            -- authoritative when the replacement worker starts Phase 1.
            if type(pending) == "table" and not pending.inFlight then
                getgenv().__CHSAE_CarryRequest = nil
            end
            local recoveredCarry = carriedAreaEgg()
            carrying = recoveredCarry ~= nil
            RuntimeStatus.activeGuardAreaId = recoveredCarry and recoveredCarry.AreaId ~= nil
                and tostring(recoveredCarry.AreaId) or nil
            Arb.sellDuringSteal = false
            Arb.critical = false
            Arb.stealWants = carrying
            Arb.stealBeat = os.clock()
            Arb.release("Steal")
            ProgressionCtl.treadmillSuppressed = carrying
            if not carrying then RuntimeStatus.pauseStealTimer() end
            pcall(setStealControlLock, false)
            pcall(setStealStatus, carrying and "🟢 Recovering carried egg" or "🟡 Recovering steal worker")
        end
        task.wait(0.25)
    end
end)

autoStealTgl:OnChanged(function(v)
    Settings.AutoSteal = v
    if wakeEggScanner then wakeEggScanner(v and "enabled" or "disabled") end
    if v then
        local full, count, capacity = RuntimeStatus.eggInventoryCapacityState()
        if full then
            Settings.AutoSteal = false
            task.defer(RuntimeStatus.stopAutoStealForFullInventory, count, capacity,
                "Your egg inventory is full!")
            return
        end
        RuntimeStatus.inventoryFullStopped = false
        setStealControlLock(true)
        setStealStatus("🟡 Waiting for target")
    else
        if RuntimeStatus.greatBloomUnlockNeedsCrane() then
            setStealStatus("🔓 Great Bloom · finding Crane egg")
            if wakeEggScanner then wakeEggScanner("great-bloom-unlock") end
            return
        end
        -- release the body right away so Auto-Place doesn't wait a whole tick
        setStealControlLock(false)
        clearPersistentTarget()
        local pendingCarry = getgenv().__CHSAE_CarryRequest
        if type(pendingCarry) == "table" and pendingCarry.inFlight ~= true then
            getgenv().__CHSAE_CarryRequest = nil
        end
        Arb.stealWants, Arb.critical = false, false
        Arb.release("Steal")
        RuntimeStatus.pauseStealTimer()
        RuntimeStatus.set("target", "🎯 Target: none")
        RuntimeStatus.carry = "📦 Carry: none"
        RuntimeStatus.activeGuardAreaId = nil
        refreshStealStatus()
        task.spawn(function()
            task.wait()
            if not sessionAlive() or Settings.AutoSteal or carrying then return end
            local trackStart = RuntimeStatus.getTrackStart()
            local root, humanoid = getCharParts()
            if not (trackStart and root and humanoid and humanoid.Health > 0) then return end
            if ((root.Position - trackStart.Position) * Vector3.new(1, 0, 1)).Magnitude <= 3 then return end
            Arb.stealWants = true
            if Arb.acquireWait("Steal", 1) then
                setStealStatus("↩️ Steal stopped · returning to TrackStart")
                RuntimeStatus.settleClaimAtTrackStart(function()
                    return sessionAlive() and not Settings.AutoSteal and not carrying
                        and Arb.hold("Steal")
                end)
                Arb.release("Steal")
            end
            Arb.stealWants = false
            refreshStealStatus()
        end)
    end
end)
-- Single current-session handle for bounded live diagnostics. This avoids getgc
