-- ════════════════════════════════════════════
-- EGGS TAB ▸ AUTO-PLACE  (place stolen eggs from inventory into the pen)
-- ════════════════════════════════════════════
-- Design: independent loop from Auto-Steal. Auto-Steal fills EggInventory;
-- Auto-Place drains it into free pen slots (so "both on" = steal→place with no
-- coupling). Optional rarity filter (empty = place ALL) + a Fill Order dropdown.
-- ✅ WORKING (live-tested): equip → place needs the character standing in the
-- pen, so the engine grounds us there first; slots come from a dynamic grid
-- sized to the live PetArea and ordered by the chosen fill direction.
local AutoPlaceBox, placeSaveMod
do
AutoPlaceBox = EggTab:AddLeftGroupbox("🥚 Auto-Place")

-- STATUS at the very top (short + emoji)
local placeStatusLbl
CHK.Merge(AutoPlaceBox, function()
    placeStatusLbl = AutoPlaceBox:AddLabel("PlaceStatusLabel", { Text = "🔴 Off", DoesWrap = true })
end)
local function setPlaceStatus(t)
    local nextStatus = "🥚 Pen: " .. tostring(t):gsub("^[^%w%s]+%s*", "")
    RuntimeStatus.set("place", nextStatus)
    RuntimeStatus.setLabel(placeStatusLbl, t)
end

local placeMutationItems, placeMutationDM = {}, {}
pcall(function()
    for name in pairs(MutationsMod.MutationNames or {}) do
        if type(name) == "string" and name ~= "None" then
            placeMutationItems[#placeMutationItems + 1] = name
        end
    end
    table.sort(placeMutationItems)
    for _, name in ipairs(placeMutationItems) do
        local hex = "#FFFFFF"
        pcall(function()
            local mutation = MutationsMod.GetMutation(name)
            if mutation and typeof(mutation.Color) == "Color3" then hex = toHex(mutation.Color) end
        end)
        placeMutationDM[name] = ('<font color="%s"><b>%s</b></font>'):format(hex, name)
    end
end)

BindDropdownOverlay(AutoPlaceBox, "PlaceCategories", "Categories", TargetCategoryData.Items, {
    configKey = "PlaceCategories",
    multi = true, store = Settings.PlaceCategories, text = "Categories",
    tooltip = "Choose categories. Empty = any.", displayMap = TargetCategoryData.Display,
    onChange = function()
        if RuntimeStatus.refreshEggOverlapStatus then RuntimeStatus.refreshEggOverlapStatus() end
    end,
})
BindDropdownOverlay(AutoPlaceBox, "PlaceRarities", "Rarities", TargetRarityItems, {
    configKey = "PlaceRarities",
    multi = true, store = Settings.PlaceRarities, text = "Rarities",
    tooltip = "Choose rarities. Empty = any.", displayMap = TargetRarityDM,
    onChange = function()
        if RuntimeStatus.refreshEggOverlapStatus then RuntimeStatus.refreshEggOverlapStatus() end
    end,
})
BindDropdownOverlay(AutoPlaceBox, "PlaceMutations", "Mutations", placeMutationItems, {
    configKey = "PlaceMutations",
    multi = true, store = Settings.PlaceMutations, text = "Mutations",
    tooltip = "Choose mutations. Empty = any.", displayMap = placeMutationDM,
    onChange = function()
        if RuntimeStatus.refreshEggOverlapStatus then RuntimeStatus.refreshEggOverlapStatus() end
    end,
})

-- Fill order (dynamic grid, built from the live pen size)
local ORDER_ITEMS = { "Back → Front", "Front → Back", "Edge → Inward", "Center → Out" }
local ORDER_DM = {
    ["Back → Front"] = '⬆️ <b>Back → Front</b> <font color="#9AA0AA">far first</font>',
    ["Front → Back"] = '⬇️ <b>Front → Back</b> <font color="#9AA0AA">near first</font>',
    ["Edge → Inward"] = '⬛ <b>Edge → Inward</b> <font color="#9AA0AA">edges first</font>',
    ["Center → Out"] = '🎯 <b>Center → Out</b> <font color="#9AA0AA">center first</font>',
}
BindDropdownOverlay(AutoPlaceBox, "PlaceOrder", "Order", ORDER_ITEMS, {
    configKey = "PlaceOrder",
    multi = false, text = "Order",
    tooltip = "Choose the fill order.",
    displayMap = ORDER_DM,
    get = function() return Settings.PlaceOrder or "Back → Front" end,
    set = function(label) Settings.PlaceOrder = label or "Back → Front" end,
})

local autoPlaceTgl = AutoPlaceBox:AddToggle("AutoPlaceToggle", {
    Text = "Auto-Place", Default = Settings.AutoPlace,
    Tooltip = "Place matching eggs automatically.",
})

local placeMoveTgl = AutoPlaceBox:AddToggle("PlaceInRangeOnlyToggle", {
    Text = "Prevent Snap",
    Default = Settings.PlaceInRangeOnly,
    Tooltip = "Wait until you are near the pen.",
})
placeMoveTgl:OnChanged(function(value)
    Settings.PlaceInRangeOnly = value
    if Settings.AutoPlace then
        setPlaceStatus(value and "🟡 Waiting for pen range" or "🟢 Auto-move enabled")
    end
end)

-- Auto-Hatch sits directly below Enable Auto-Place
local autoHatchTgl = AutoPlaceBox:AddToggle("AutoHatchToggle", {
    Text = "Auto-Hatch", Default = Settings.AutoHatch,
    Tooltip = "Hatch ready eggs automatically.",
})

-- EggState publishes placement/removal snapshots but no dedicated ready event.
-- Combine those signals with one timer for the earliest predicted ready egg.
local HatchScheduler = {
    WakeEvent = Instance.new("BindableEvent"),
    Generation = 0,
    NextCheckAt = 0,
    TimerThread = nil,
    Pending = false,
}
do
    local previous = getgenv().__CHSAE_HatchWake
    if typeof(previous) == "Instance" then
        pcall(function() previous:Fire("reload") end)
        pcall(function() previous:Destroy() end)
    end
end
getgenv().__CHSAE_HatchWake = HatchScheduler.WakeEvent
function HatchScheduler.CancelTimer()
    local timerThread = HatchScheduler.TimerThread
    HatchScheduler.TimerThread = nil
    if timerThread then pcall(task.cancel, timerThread) end
end
getgenv().__CHSAE_HatchCancel = HatchScheduler.CancelTimer
function HatchScheduler.Wake(reason)
    HatchScheduler.Pending = true
    HatchScheduler.CancelTimer()
    HatchScheduler.NextCheckAt = 0
    if sessionAlive() then
        pcall(function() HatchScheduler.WakeEvent:Fire(reason or "egg-state") end)
    end
end
RuntimeStatus.wakeRiftPen = HatchScheduler.Wake
function HatchScheduler.Wait(seconds)
    if HatchScheduler.Pending then
        HatchScheduler.Pending = false
        HatchScheduler.NextCheckAt = 0
        task.wait(0.05)
        return
    end
    HatchScheduler.Generation += 1
    local generation = HatchScheduler.Generation
    HatchScheduler.CancelTimer()
    if type(seconds) == "number" then
        HatchScheduler.TimerThread = task.delay(math.max(0.05, seconds), function()
            if generation == HatchScheduler.Generation and sessionAlive() then
                HatchScheduler.TimerThread = nil
                HatchScheduler.Wake("deadline")
            end
        end)
    end
    HatchScheduler.WakeEvent.Event:Wait()
    HatchScheduler.Pending = false
    HatchScheduler.Generation += 1
    HatchScheduler.CancelTimer()
end
if EggCmds and EggCmds.RuntimeSnapshotUpdated then
    local connection = EggCmds.RuntimeSnapshotUpdated:Connect(function()
        HatchScheduler.Wake("snapshot")
    end)
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = connection
end
if EggCmds and EggCmds.RuntimeResetCountdown then
    local connection = EggCmds.RuntimeResetCountdown:Connect(function()
        HatchScheduler.Wake("night-credit")
    end)
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = connection
end
do
    local connection = workspace:GetAttributeChangedSignal("TemporaryGrowthBoosts"):Connect(function()
        HatchScheduler.Wake("growth-boost")
    end)
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = connection
end

-- [[ AUTO-PLACE + AUTO-HATCH ENGINE (mechanics captured 2026-08-19) ]] --
-- Place: RequestEquipTool(uid) → RequestPlaceEgg(uid, CFrame.new(x,-0.5,z))
-- where x,z are CenterPoint-LOCAL (that's the frame RequestPlaceEgg wants).
-- The server ALSO requires the character to be standing in the pen, else it
-- returns "Get closer to your area to place an egg!" — so the engine grounds us
-- in the pen first and hops onto any out-of-reach slot before retrying.
-- ⚠️ DYNAMIC grid: we read the live PetArea bounds (in CenterPoint space) and
-- lay a fresh grid every pass, ordered by Settings.PlaceOrder — so it adapts to
-- ANY pen size/plot and fills in the direction the user picked. Occupied cells
-- are removed; the server rejecting a cell (false) just skips it. A whole pass
-- placing 0 = pen genuinely full.
-- Hatch: GetRuntimeSnapshot → my Records → IsLocalEggReady → RequestHatchEgg →
--        RequestCompleteHatchEgg (frees a slot for Auto-Place).
local placePlotCmds
pcall(function()
    local PlotState = require(ReplicatedStorage.Client.PlotState)
    placePlotCmds = { GetPlotData = PlotState.ResolvePlot }
end)

-- penInfo() → PetArea part + CenterPoint CFrame (the frame RequestPlaceEgg's
-- LocalCFrame is relative to). Both live-read so it tracks plot changes.
local function penInfo()
    local pd
    pcall(function() pd = placePlotCmds and placePlotCmds.GetPlotData() end)
    if not pd then return nil end
    local pa = pd.PetArea
    if not (pa and pa:IsA("BasePart")) then return nil end
    local cp, c = pa.CFrame, pd.CenterPoint
    if typeof(c) == "CFrame" then cp = c
    elseif typeof(c) == "Instance" and c:IsA("BasePart") then cp = c.CFrame end
    return pa, cp
end

local function incubatedPlaceCount()
    local count = 0
    for _ in pairs(RuntimeStatus.incubatedPlaceQueue or {}) do count += 1 end
    return count
end
local INCUBATED_INVENTORY_GRACE = 8
local function greatBloomUnlockEggUid()
    local state = RuntimeStatus.greatBloomUnlock
    if Settings.AutoUnlockGreatBloom == true and type(state) == "table"
        and state.locked == true then
        return state.reservedEggUid
    end
    return nil
end
local function greatBloomUnlockEggActive()
    return greatBloomUnlockEggUid() ~= nil
end
local function placeAutomationEnabled()
    return Settings.AutoPlace
        or (Settings.PlaceAfterIncubation and incubatedPlaceCount() > 0)
        or greatBloomUnlockEggActive()
        or RuntimeStatus.riftEggActive()
end
RuntimeStatus.getIncubatedPlaceCount = incubatedPlaceCount
local function playerInPenRange()
    local pa = penInfo()
    local root = getCharParts()
    return pa ~= nil and root ~= nil and (root.Position - pa.CFrame.Position).Magnitude <= 70
end

-- Drop the character onto the real floor above worldPos (raycast, so we don't
-- fall through the invisible PetArea into the void). Zeroes velocity so we stay
-- grounded ("Running") and in range to place.
-- [[ PLACEMENT RESERVATION ]] --
RuntimeStatus.placeHigherPriorityPending = function()
    return Arb.stealBusy() or RuntimeStatus.normalStealPending()
        or ProgressionCtl.eventPending or RuntimeStatus.greatBloomUnlockReturnPending == true
        or RuntimeStatus.bossArenaOccupied() or Arb.owner == "RiftBoss"
        or Arb.owner == "Event" or Arb.owner == "AdminEvent"
end
RuntimeStatus.updatePlaceReservation = function(hasEgg, full)
    local now = os.clock()
    local blocked = not placeAutomationEnabled() or RuntimeStatus.placeHigherPriorityPending()
        or (Settings.PlaceInRangeOnly and not greatBloomUnlockEggActive() and not RuntimeStatus.riftEggActive())
    if blocked or full then
        ProgressionCtl.placePending, ProgressionCtl.placeClearSince = false, nil
    elseif hasEgg then
        ProgressionCtl.placePending, ProgressionCtl.placeClearSince = true, nil
    elseif ProgressionCtl.placePending then
        -- Keep the batch through a brief inventory replication gap. This does
        -- not delay an event/steal handoff or a confirmed full pen.
        ProgressionCtl.placeClearSince = ProgressionCtl.placeClearSince or now
        if now - ProgressionCtl.placeClearSince >= 1 then ProgressionCtl.placePending = false end
    end
    ProgressionCtl.placeBeat = now
    if not ProgressionCtl.placePending then Arb.release("Place") end
    return ProgressionCtl.placePending
end
RuntimeStatus.placeBatchPending = function()
    return ProgressionCtl.placePending and os.clock() - ProgressionCtl.placeBeat <= ProgressionCtl.PLACE_STALE
end
-- [[ END PLACEMENT RESERVATION ]] --
local function placeCanContinue()
    if not (placeAutomationEnabled() and sessionAlive()) then return false end
    local canContinue = not RuntimeStatus.placeHigherPriorityPending()
        and Arb.hold("Place")
    if canContinue then ProgressionCtl.placeBeat = os.clock() end
    return canContinue
end

local function groundCharAt(worldPos)
    if not RuntimeStatus.progressionTweenTo then return false end
    return RuntimeStatus.progressionTweenTo("Place", worldPos, 0.35, placeCanContinue)
end

-- currently-occupied pen positions (CenterPoint-local), from the runtime snapshot
local function occupiedLocals()
    local occ = {}
    pcall(function()
        for _, e in pairs(EggCmds.GetRuntimeSnapshot() or {}) do
            if type(e) == "table" and tostring(e.OwnerUserId) == tostring(LocalPlayer.UserId) and e.Records then
                for _, rec in pairs(e.Records) do
                    local L = type(rec.Placement) == "table" and rec.Placement.LocalCFrame
                    if typeof(L) == "CFrame" then occ[#occ + 1] = { x = L.X, z = L.Z } end
                end
            end
        end
    end)
    return occ
end

-- Live pen bounds in CenterPoint-local space (PetArea's 4 corners transformed).
local PLACE_MARGIN, PLACE_STEP = 3, 5.5
local function penBounds()
    local pa, cp = penInfo()
    if not (pa and cp) then return nil end
    local sz = pa.Size
    local minx, maxx, minz, maxz = math.huge, -math.huge, math.huge, -math.huge
    for _, sx in ipairs({ -0.5, 0.5 }) do
        for _, sz2 in ipairs({ -0.5, 0.5 }) do
            local w = pa.CFrame:PointToWorldSpace(Vector3.new(sz.X * sx, 0, sz.Z * sz2))
            local l = cp:PointToObjectSpace(w)
            minx = math.min(minx, l.X); maxx = math.max(maxx, l.X)
            minz = math.min(minz, l.Z); maxz = math.max(maxz, l.Z)
        end
    end
    return { minx = minx + PLACE_MARGIN, maxx = maxx - PLACE_MARGIN,
             minz = minz + PLACE_MARGIN, maxz = maxz - PLACE_MARGIN }, cp
end

-- Order a slot list by the user's fill preference.
local function orderSlots(slots, mode, b)
    if mode == "Front → Back" then
        table.sort(slots, function(a, c) if a.z ~= c.z then return a.z < c.z end return a.x < c.x end)
    elseif mode == "Edge → Inward" then
        local function ed(s) return math.min(s.x - b.minx, b.maxx - s.x, s.z - b.minz, b.maxz - s.z) end
        table.sort(slots, function(a, c) return ed(a) < ed(c) end)
    elseif mode == "Center → Out" then
        local cx, cz = (b.minx + b.maxx) / 2, (b.minz + b.maxz) / 2
        table.sort(slots, function(a, c)
            return (a.x - cx) ^ 2 + (a.z - cz) ^ 2 < (c.x - cx) ^ 2 + (c.z - cz) ^ 2
        end)
    else -- "Back → Front" (default): far end (highest Z) first
        table.sort(slots, function(a, c) if a.z ~= c.z then return a.z > c.z end return a.x < c.x end)
    end
    return slots
end

-- Dynamic free-slot list: fresh grid from the live pen size, ordered by the
-- user's fill mode, minus anything already occupied.
local function freeSlots(occ)
    local b, cp = penBounds()
    if not b then return {}, nil end
    local slots = {}
    local z = b.minz
    while z <= b.maxz do
        local x = b.minx
        while x <= b.maxx do
            slots[#slots + 1] = { x = x, z = z }
            x = x + PLACE_STEP
        end
        z = z + PLACE_STEP
    end
    orderSlots(slots, Settings.PlaceOrder or "Back → Front", b)
    local free = {}
    for _, c in ipairs(slots) do
        local ok = true
        for _, o in ipairs(occ) do if (c.x - o.x) ^ 2 + (c.z - o.z) ^ 2 < 20 then ok = false; break end end
        if ok then free[#free + 1] = c end
    end
    return free, cp
end

pcall(function()
    local Save = require(ReplicatedStorage.Shared.Save)
    placeSaveMod = { Get = function() return Save.Get() end }
end)

-- Freshly acquired pets are quarantined briefly before any seller may touch
-- them. This is especially important after FinishHatch: that remote can return
-- before the new Inventory UID or Character Tool replicates. Tracking every new
-- UID also makes an arbitrarily late hatch result safe without freezing sales
-- of the inventory that existed before the hatch.
function RuntimeStatus.externallyHeldPetUid()
    local character = LocalPlayer.Character
    for _, tool in ipairs(character and character:GetChildren() or {}) do
        if tool:IsA("Tool") and tool:GetAttribute("ItemType") == "Asset"
            and tool ~= RuntimeStatus.sellerHeldTool then
            local uid = tostring(tool:GetAttribute("UID") or "")
            if uid ~= "" then return uid, tool end
        end
    end
    return nil, nil
end

function RuntimeStatus.reconcileNewPetUids(saveSnapshot)
    local now = os.clock()
    local observed, inventoryObserved, toolObserved = {}, {}, {}
    local inventoryReadable = false
    local save = saveSnapshot
    if save == nil then
        pcall(function() save = placeSaveMod and placeSaveMod.Get() end)
    end
    if type(save) == "table" and type(save.Inventory) == "table" then
        inventoryReadable = true
        for uid in pairs(save.Inventory) do
            uid = tostring(uid)
            observed[uid] = true
            inventoryObserved[uid] = true
        end
    end
    for _, container in pairs({ LocalPlayer.Character,
        LocalPlayer:FindFirstChildOfClass("Backpack") }) do
        for _, tool in ipairs(container and container:GetChildren() or {}) do
            if tool:IsA("Tool") and tool:GetAttribute("ItemType") == "Asset" then
                local uid = tostring(tool:GetAttribute("UID") or "")
                if uid ~= "" then
                    observed[uid] = true
                    toolObserved[uid] = true
                end
            end
        end
    end

    local known = RuntimeStatus.knownPetUids
    if type(known) ~= "table" then
        known = {}
        RuntimeStatus.knownPetUids = known
    end

    -- A readable Inventory is mandatory before the first hatch transaction.
    -- If a guard somehow exists without that baseline, treat every observation
    -- as new rather than blessing a late hatch result as old inventory.
    local baselineInitialized = false
    if RuntimeStatus.petUidBaselineReady ~= true and inventoryReadable
        and RuntimeStatus.hatchPetOutputPending ~= true
        and type(RuntimeStatus.hatchPetOutputGuard) ~= "table" then
        for uid in pairs(observed) do
            known[uid] = {
                Baseline = true,
                SeenInventory = inventoryObserved[uid] == true,
                PresentInventory = inventoryObserved[uid] == true,
                PresentTool = toolObserved[uid] == true,
                ProtectedUntil = 0,
            }
        end
        RuntimeStatus.petUidBaselineReady = true
        baselineInitialized = true
    elseif RuntimeStatus.petUidBaselineReady ~= true and inventoryReadable then
        RuntimeStatus.petUidBaselineReady = true
    end

    local newCount = 0
    if not baselineInitialized then
        local all = {}
        for uid in pairs(known) do all[uid] = true end
        for uid in pairs(observed) do all[uid] = true end
        for uid in pairs(all) do
            local state = known[uid]
            if type(state) ~= "table" then
                state = {
                    Baseline = state == true,
                    SeenInventory = false,
                    PresentInventory = false,
                    PresentTool = false,
                    ProtectedUntil = 0,
                }
                known[uid] = state
            end
            local inInventory = inventoryObserved[uid] == true
            local inTools = toolObserved[uid] == true
            local firstObservation = state.Baseline ~= true
                and state.SeenInventory ~= true and state.PresentTool ~= true
                and (inInventory or inTools)
            local inventoryTransition = inInventory
                and (state.SeenInventory ~= true or state.PresentInventory ~= true)
            local toolTransition = inTools and state.PresentTool ~= true
            if firstObservation or inventoryTransition or toolTransition then
                local protectedUntil = now
                    + (tonumber(RuntimeStatus.hatchPetProtectSeconds) or 8)
                state.ProtectedUntil = math.max(
                    tonumber(state.ProtectedUntil) or 0, protectedUntil)
                RuntimeStatus.hatchProtectedPetUids[uid] = state.ProtectedUntil
                if firstObservation then newCount += 1 end
            end
            if inInventory then
                state.SeenInventory = true
                state.LastInventoryAt = now
            end
            if inventoryReadable then state.PresentInventory = inInventory end
            state.PresentTool = inTools
        end
    end

    local guard = RuntimeStatus.hatchPetOutputGuard
    if type(guard) == "table" then
        if now >= (tonumber(guard.ExpiresAt) or 0) then
            RuntimeStatus.hatchPetOutputPending = false
            RuntimeStatus.hatchPetOutputGuard = nil
        end
    elseif RuntimeStatus.hatchPetOutputPending == true
        and now >= (tonumber(RuntimeStatus.hatchPetGuardUntil) or 0) then
        RuntimeStatus.hatchPetOutputPending = false
    end

    local externallyHeldUid = RuntimeStatus.externallyHeldPetUid()
    for uid, protectedUntil in pairs(RuntimeStatus.hatchProtectedPetUids) do
        if now >= (tonumber(protectedUntil) or 0) and uid ~= externallyHeldUid then
            RuntimeStatus.hatchProtectedPetUids[uid] = nil
        end
    end
    return newCount, inventoryReadable
end

function RuntimeStatus.ensurePetUidBaseline()
    RuntimeStatus.reconcileNewPetUids()
    return RuntimeStatus.petUidBaselineReady == true
end

function RuntimeStatus.noteHatchPetOutputAttempt()
    RuntimeStatus.reconcileNewPetUids()
    if RuntimeStatus.petUidBaselineReady ~= true then return false end
    local now = os.clock()
    local guard = RuntimeStatus.hatchPetOutputGuard
    if type(guard) ~= "table" then
        guard = { ExpiresAt = 0 }
        RuntimeStatus.hatchPetOutputGuard = guard
    end
    guard.ExpiresAt = now + (tonumber(RuntimeStatus.hatchPetResolveSeconds) or 8)
    RuntimeStatus.hatchPetOutputPending = true
    RuntimeStatus.hatchPetGuardUntil = math.max(
        tonumber(RuntimeStatus.hatchPetGuardUntil) or 0,
        guard.ExpiresAt
    )
    return true
end

function RuntimeStatus.petSellUidProtected(uid, saveSnapshot, reconciled)
    uid = tostring(uid or "")
    if uid == "" then return true end
    if RuntimeStatus.riftPetReserved(uid) then return true end
    if reconciled ~= true then RuntimeStatus.reconcileNewPetUids(saveSnapshot) end
    local protectedUntil = tonumber(RuntimeStatus.hatchProtectedPetUids[uid]) or 0
    if os.clock() < protectedUntil then return true end
    local externallyHeldUid = RuntimeStatus.externallyHeldPetUid()
    return externallyHeldUid ~= nil and externallyHeldUid == uid
end

function RuntimeStatus.hatchPetSaleGuardActive()
    return RuntimeStatus.hatchPetOutputPending == true
        or os.clock() < (tonumber(RuntimeStatus.hatchPetGuardUntil) or 0)
        or RuntimeStatus.externallyHeldPetUid() ~= nil
end

-- ReplicatedStorage.Data.Bases.GetAssetEquipCapacity is the active PET limit
-- shown by the native PetList ("N/MAX Active"), not an egg-placement limit.
-- Egg placement therefore relies on the live pen geometry and the server's
-- authoritative full response instead of incorrectly stopping at MaxAssets.
local function penCapacityState()
    local eggCount = #occupiedLocals()
    local level = nil
    pcall(function()
        local save = placeSaveMod and placeSaveMod.Get()
        if type(save) == "table" then
            level = save.BaseUpgradeLevel
        end
    end)
    return eggCount, nil, level
end

-- A server/geometric "full" rejection is latched at the current placed count.
-- the latch clears as soon as a hatch frees a slot or a pen upgrade changes level.
local penFullAtCount, penFullAtLevel
local function latchPenFull()
    local used, _, level = penCapacityState()
    penFullAtCount, penFullAtLevel = used, level
end
local function penFullState()
    local used, capacity, level = penCapacityState()
    if penFullAtCount and (level ~= penFullAtLevel or used < penFullAtCount) then
        penFullAtCount, penFullAtLevel = nil, nil
    end
    if penFullAtCount then penFullAtCount = math.max(penFullAtCount, used) end
    return used, capacity, level,
        penFullAtCount ~= nil and level == penFullAtLevel and used >= penFullAtCount
end

-- uids of eggs ALREADY placed in the pen (must NOT be re-placed — that returns
-- "Egg is already placed" and was the whole "places a few then stops" bug).
local function placedUidSet()
    local placed = {}
    pcall(function()
        for _, e in pairs(EggCmds.GetRuntimeSnapshot() or {}) do
            if type(e) == "table" and tostring(e.OwnerUserId) == tostring(LocalPlayer.UserId) and e.Records then
                -- Records holds ALL owned eggs; only those WITH a Placement are
                -- actually in the pen. (Marking all placed = 0 to place bug.)
                for uid, rec in pairs(e.Records) do
                    if type(rec.Placement) == "table" and rec.Placement.LocalCFrame ~= nil then placed[uid] = true end
                end
            end
        end
    end)
    return placed
end

local function filterHasChoice(store)
    for _, on in pairs(store or {}) do if on == true then return true end end
    return false
end

-- AND across nonempty dimensions; mutation selection is OR within Mutations.
-- Returns both the match and whether this filter set contains a real choice.
local function eggMatchesFilters(data, categories, rarities, mutations, kgMode, kgThreshold)
    if type(data) ~= "table" then return false, false end
    local byCategory = filterHasChoice(categories)
    local byRarity = filterHasChoice(rarities)
    local byMutation = filterHasChoice(mutations)
    local byKG = RuntimeStatus.kgFilterActive(kgMode, kgThreshold)
    local active = byCategory or byRarity or byMutation or byKG
    if not active then return true, false end

    local category = tostring(data.AssetCategory or data.Category or "")
    local rarityId
    pcall(function()
        local rarity = AssetsDir.Directory[category].Rarity
        rarityId = type(rarity) == "table" and rarity._id or rarity
    end)
    local mutationOk = not byMutation
    if byMutation then
        for _, mutation in pairs(data.Mutations or {}) do
            if mutations[mutation] then mutationOk = true; break end
        end
    end
    return (not byCategory or categories[category] == true)
        and (not byRarity or (rarityId and rarities[rarityId] == true))
        and mutationOk
        and (not byKG or RuntimeStatus.kgFilterMatches(data, kgMode, kgThreshold)), true
end

local function eggsToPlace()
    local list = {}
    local seen = {}
    local placed = placedUidSet()
    local save
    pcall(function() save = placeSaveMod and placeSaveMod.Get() end)
    local inv = type(save) == "table" and type(save.EggInventory) == "table"
        and save.EggInventory or {}
    local unlockUid = greatBloomUnlockEggUid()
    if unlockUid ~= nil then
        -- The unlock egg is an exclusive reservation: place it first and pause
        -- ordinary Auto-Place until it hatches or the quest state changes.
        if inv[unlockUid] ~= nil and not placed[unlockUid] then return { unlockUid } end
        return list
    end
    for uid in pairs(RuntimeStatus.riftReservedEggs) do
        if RuntimeStatus.riftEggReserved(uid) and inv[uid] and not placed[uid] then
            list[#list + 1] = uid
            seen[uid] = true
        end
    end
    table.sort(list)
    local queued = {}
    local waitingForQueuedInventory = false
    if Settings.PlaceAfterIncubation then
        local queueNow = os.clock()
        for uid, queuedAt in pairs(RuntimeStatus.incubatedPlaceQueue) do
            local queuedAtNumber = tonumber(queuedAt) or queueNow
            if placed[uid] then
                RuntimeStatus.incubatedPlaceQueue[uid] = nil
            elseif inv[uid] ~= nil then
                queued[#queued + 1] = { uid = uid, at = queuedAtNumber }
            elseif queueNow - queuedAtNumber > INCUBATED_INVENTORY_GRACE then
                -- AskMutate can return before the Save replica exposes the UID.
                -- Keep it queued during that handoff instead of losing it forever.
                RuntimeStatus.incubatedPlaceQueue[uid] = nil
            else
                waitingForQueuedInventory = true
            end
        end
        table.sort(queued, function(a, b)
            if a.at ~= b.at then return a.at < b.at end
            return tostring(a.uid) < tostring(b.uid)
        end)
        for _, item in ipairs(queued) do
            list[#list + 1] = item.uid
            seen[item.uid] = true
        end
    end

    -- Queued incubator results always go first and intentionally bypass normal
    -- Auto-Place filters. Ordinary inventory eggs are added only when the main
    -- Auto-Place toggle is enabled.
    -- Do not let ordinary Auto-Place consume the last pen slot while a freshly
    -- mutated result is still crossing from the response into EggInventory.
    if Settings.AutoPlace and not waitingForQueuedInventory then
        for uid, data in pairs(inv) do
            if not placed[uid] and not seen[uid] then -- only UN-placed eggs
            local matched, hasPlaceFilter = eggMatchesFilters(
                data, Settings.PlaceCategories, Settings.PlaceRarities, Settings.PlaceMutations)
            local keep = not hasPlaceFilter or matched


            if keep then list[#list + 1] = uid end
            end
        end
    end
    return list
end

-- Deterministic overlap rule shared with Sell Eggs: while the pen can still
-- accept eggs, every UID selected by Auto-Place is reserved from selling. Once
-- the pen has authoritatively/geometrically reported full, those remaining UIDs
-- become overflow and the egg seller may process them. Placed eggs are absent
-- from eggsToPlace() and remain protected by the seller's own placed-UID check.
RuntimeStatus.getAutoPlaceEggPolicy = function()
    local selected = {}
    if not placeAutomationEnabled() then return selected, false, false end
    for _, uid in ipairs(eggsToPlace()) do selected[tostring(uid)] = true end
    local penFull = select(4, penFullState()) == true
    return selected, not penFull, penFull
end

local function placeEggsPass()
    if not placeCanContinue() then return 0, 0, false, "interrupted" end
    local eggs = eggsToPlace()
    if #eggs == 0 then return 0, 0, false end
    local penUsed, penCapacity, penLevel, penFull = penFullState()
    if penFull then
        return 0, #eggs, true, "full"
    end
    local pa, cp = penInfo()
    -- Automatic mode moves into the pen. Manual-range mode never moves the
    -- character: it waits until the player walks close enough, then places.
    local root = getCharParts()
    if pa and root and (root.Position - pa.CFrame.Position).Magnitude > 70 then
        if Settings.PlaceInRangeOnly and not greatBloomUnlockEggActive() and not RuntimeStatus.riftEggActive() then
            return 0, #eggs, false, "range"
        end
        -- Rejoin the centered entrance before moving from gameplay to a side pen.
        local gameplaySide = lineSide(root.Position)
        if gameplaySide ~= nil and gameplaySide > 0 then
            setPlaceStatus("↩️ Returning to TrackStart")
            if not RuntimeStatus.settleClaimAtTrackStart(placeCanContinue) then
                return 0, #eggs, false, "interrupted"
            end
            if not placeCanContinue() then
                return 0, #eggs, false, "interrupted"
            end
            root = getCharParts()
            if not root then return 0, #eggs, false, "interrupted" end
        end
        setPlaceStatus("🏡 Moving to pen")
        if not groundCharAt(pa.CFrame.Position) then
            return 0, #eggs, false, "interrupted"
        end
        task.wait(0.35)
    end
    local occ = occupiedLocals()
    local cands = freeSlots(occ)
    if #cands == 0 then
        latchPenFull()
        return 0, #eggs, true, "full"
    end
    local placed, consecFails = 0, 0
    local manualRangeBlocked = false
    local ei, ci = 1, 1
    while ei <= #eggs and ci <= #cands do
        -- Arb.hold: a steal target appeared → stop placing and hand the body back
        if not placeCanContinue() then return placed, #eggs, false, "interrupted" end
        if consecFails >= 40 then break end -- many cells in a row rejected = pen full
        local uid = eggs[ei]
        local eqOk
        pcall(function() eqOk = EggCmds.RequestEquipTool(uid) end)
        if not placeCanContinue() then
            return placed, #eggs, false, "interrupted"
        end
        if eqOk ~= true then
            ei = ei + 1 -- egg unusable (already placed etc.) → next egg, keep candidate
        else
            task.wait(0.15)
            if not placeCanContinue() then
                return placed, #eggs, false, "interrupted"
            end
            local slot = cands[ci]
            local res, err
            pcall(function() res, err = EggCmds.RequestPlaceEgg(uid, CFrame.new(slot.x, -0.5, slot.z)) end)
            -- "Get closer to your area" = this slot is out of reach → hop onto it
            -- (a short in-pen ground) and retry once before giving up on it.
            if res ~= true and cp and tostring(err):find("closer") then
                if not Settings.PlaceInRangeOnly then
                    if not groundCharAt(cp:PointToWorldSpace(Vector3.new(slot.x, -0.5, slot.z))) then
                        return placed, #eggs, false, "interrupted"
                    end
                    task.wait(0.2)
                    if not placeCanContinue() then
                        return placed, #eggs, false, "interrupted"
                    end
                    pcall(function() res, err = EggCmds.RequestPlaceEgg(uid, CFrame.new(slot.x, -0.5, slot.z)) end)
                else
                    manualRangeBlocked = true
                end
            end
            if res == true then
                placed = placed + 1
                RuntimeStatus.incubatedPlaceQueue[uid] = nil
                penUsed += 1
                occ[#occ + 1] = { x = slot.x, z = slot.z }
                ei = ei + 1; ci = ci + 1 -- success → next egg, next slot
                consecFails = 0
            else
                local serverError = tostring(err or ""):lower()
                if serverError:find("full", 1, true) or serverError:find("maximum", 1, true)
                    or serverError:find("max egg", 1, true) then
                    consecFails = 40 -- authoritative full response; latch without probing more cells
                else
                    ci = ci + 1; consecFails = consecFails + 1 -- occupied/invalid → next slot, same egg
                end
            end
            humanWait(0.1, 0.18)
        end
    end
    local rejectedFull = (consecFails >= 40 or (ci > #cands and placed > 0)) and not manualRangeBlocked
    if rejectedFull then
        latchPenFull()
    elseif placed > 0 then
        penFullAtCount, penFullAtLevel = nil, nil
    end
    return placed, #eggs, rejectedFull,
        rejectedFull and "full" or (manualRangeBlocked and "range" or nil)
end

-- Public entry point (forward-declared up in the Task Arbiter). Re-entrancy
-- guard: the pen worker loop and the steal loop's "Place between steals" hook
-- both call this, and Arb's lock is keyed by task NAME — without this they could
-- run two passes into the same free slots at once.
function placeEggsNow()
    if Arb.placeBusy then return 0, 0, false end
    Arb.placeBusy = true
    local ok, placed, total, full, reason = pcall(placeEggsPass)
    Arb.placeBusy = false
    if RuntimeStatus.refreshEggOverlapStatus then
        task.defer(RuntimeStatus.refreshEggOverlapStatus)
    end
    if not ok then
        warn("[CloverHub] place pass error: " .. tostring(placed))
        return 0, 0, false, "error"
    end
    return placed, total, full, reason
end

local function hatchReadyNow()
    if not Arb.hatchOk() then return 0, nil, "busy" end
    Arb.hatchBusy = true
    local hatched = 0
    local nextReadyIn = nil
    local ok, err = pcall(function()
        local snap = EggCmds.GetRuntimeSnapshot()
        local myRec
        for _, e in pairs(snap or {}) do
            if type(e) == "table" and tostring(e.OwnerUserId) == tostring(LocalPlayer.UserId) then myRec = e break end
        end
        local unlockUid = greatBloomUnlockEggUid()
        local hatchEnabled = Settings.AutoHatch or unlockUid ~= nil or RuntimeStatus.riftEggActive()
        if myRec and myRec.Records then
            for uid, eggRecord in pairs(myRec.Records) do
                if not (hatchEnabled and sessionAlive())
                    or Arb.owner == "Place" or Arb.placeBusy or Arb.petsBusy
                    or not RuntimeStatus.ensurePetUidBaseline() then break end
                if unlockUid ~= nil and tostring(uid) ~= tostring(unlockUid) then continue end
                if not Settings.AutoHatch and unlockUid == nil and not RuntimeStatus.riftEggReserved(uid) then continue end
                local ready = false
                pcall(function() ready = EggCmds.IsLocalEggReady(uid) end)
                if ready then
                    local beganOk, began = pcall(EggCmds.RequestHatchEgg, uid)
                    local finishedOk, finished = false, false
                    if beganOk and began == true then
                        -- BeginHatch was accepted, so treat the following Finish
                        -- as possibly committed even if its response is lost.
                        -- The new pet UID is quarantined when Inventory/Tool
                        -- replication exposes it.
                        if RuntimeStatus.riftEggReserved(uid) then
                            RuntimeStatus.riftEggHandoffs[tostring(uid)] = {
                                category = eggRecord.AssetCategory or eggRecord.Category, at = os.clock(),
                            }
                        end
                        local guarded = RuntimeStatus.noteHatchPetOutputAttempt()
                        if guarded then
                            task.wait(0.15)
                            finishedOk, finished = pcall(EggCmds.RequestCompleteHatchEgg, uid)
                        end
                    end
                    if finishedOk and finished == true then
                        hatched = hatched + 1
                        if unlockUid ~= nil and tostring(uid) == tostring(unlockUid) then
                            -- FinishHatch can remove EggInventory one replication
                            -- packet before the new Crane appears in Inventory.
                            -- Reserve that bounded handoff so Steal cannot claim a
                            -- fresh target inside the gap.
                            RuntimeStatus.greatBloomUnlockHatchFinishedAt = os.clock()
                            RuntimeStatus.greatBloomUnlockHatchedEggUid = tostring(uid)
                            RuntimeStatus.greatBloomUnlockReturnPending = true
                            RuntimeStatus.greatBloomUnlockStealWanted = false
                            ProgressionCtl.refreshEventPending()
                            if wakeEggScanner then wakeEggScanner("crane-return") end
                            if type(RuntimeStatus.wakeGreatBloomUnlock) == "function" then
                                task.defer(RuntimeStatus.wakeGreatBloomUnlock, "crane-hatched")
                            end
                        end
                        if type(RuntimeStatus.sendWebhook) == "function" then
                            local category = type(eggRecord) == "table"
                                and (eggRecord.AssetCategory or eggRecord.Category) or "Egg"
                            task.spawn(RuntimeStatus.sendWebhook, "hatch", "Egg Hatched",
                                tostring(category), 0x60A5FA, false)
                        end
                    end
                    humanWait(0.2, 0.4)
                    RuntimeStatus.reconcileNewPetUids()
                elseif EggCmds.SecondsUntilReady then
                    local seconds
                    pcall(function() seconds = EggCmds.SecondsUntilReady(eggRecord) end)
                    if type(seconds) == "number" and seconds > 0 then
                        nextReadyIn = nextReadyIn and math.min(nextReadyIn, seconds) or seconds
                    end
                end
            end
        end
    end)
    RuntimeStatus.reconcileNewPetUids()
    if RuntimeStatus.hatchPetOutputPending == true then
        task.spawn(function()
            while sessionAlive() and RuntimeStatus.hatchPetOutputPending == true do
                RuntimeStatus.reconcileNewPetUids()
                task.wait(0.1)
            end
        end)
    end
    Arb.hatchBusy = false
    if not ok then warn("[CloverHub] hatch pass error: " .. tostring(err)) end
    if ok then return hatched, nextReadyIn, nil end
    return hatched, nextReadyIn, "error"
end

autoPlaceTgl:OnChanged(function(v)
    Settings.AutoPlace = v
    if not v and not placeAutomationEnabled() then ProgressionCtl.placePending = false end
    if RuntimeStatus.refreshEggOverlapStatus then
        task.defer(RuntimeStatus.refreshEggOverlapStatus)
    end
    setPlaceStatus((v or Settings.AutoHatch or Settings.PlaceAfterIncubation)
        and "🟢 Monitoring eggs" or "🔴 Off")
    HatchScheduler.Wake("auto-place-toggle")
end)
autoHatchTgl:OnChanged(function(v)
    Settings.AutoHatch = v
    setPlaceStatus((v or Settings.AutoPlace or Settings.PlaceAfterIncubation)
        and "🟢 Monitoring eggs" or "🔴 Off")
    HatchScheduler.Wake("auto-hatch-toggle")
end)

-- Combined pen worker: hatch first (frees slots), then place into free slots.
-- ARBITRATED: hatching is remote-only and may overlap body movement/training,
-- but PLACING teleports the character — it must own the body, which Auto-Steal
-- only hands over when there is no egg worth stealing (see the Task Arbiter).
task.spawn(function()
    while sessionAlive() do
        if RuntimeStatus.deferInventoryForBait() then task.wait(0.2); continue end
        local loopWait = nil
        local workerOk, workerError = xpcall(function()
        local hatched, hatchDueIn = 0, nil
        local unlockHatch = greatBloomUnlockEggActive() or RuntimeStatus.riftEggActive()
        if (Settings.AutoHatch or unlockHatch) and EggCmds then
            local hatchNow = os.clock()
            if hatchNow >= HatchScheduler.NextCheckAt then
                local nextHatchReady, hatchReason
                hatched, nextHatchReady, hatchReason = hatchReadyNow()
                hatchDueIn = hatchReason == "busy" and 0.5
                    or (hatched > 0 and 0.75)
                    or (nextHatchReady and (nextHatchReady + 0.05))
                    or nil
                HatchScheduler.NextCheckAt = hatchDueIn and (hatchNow + hatchDueIn) or math.huge
            else
                hatchDueIn = math.max(0.05, HatchScheduler.NextCheckAt - hatchNow)
            end
        end

        local placingEnabled = placeAutomationEnabled()
        if placingEnabled and EggCmds and placeSaveMod then
            ProgressionCtl.placeBeat = os.clock()
            local hasPendingEgg = #eggsToPlace() > 0
            local penUsed, penCapacity, _, penFull = penFullState()
            RuntimeStatus.updatePlaceReservation(hasPendingEgg, penFull)
            if not hasPendingEgg then
                setPlaceStatus(Settings.PlaceAfterIncubation and incubatedPlaceCount() > 0
                    and "🟡 Waiting for mutated egg" or "🟢 Active · inventory clear")
            elseif RuntimeStatus.placeHigherPriorityPending() then
                ProgressionCtl.placePending = false
                setPlaceStatus(RuntimeStatus.adminEventPending
                    and "⏸️ Rift has priority" or "⏸️ Automation has priority")
            elseif carrying then
                setPlaceStatus("⏸️ Carrying egg")      -- never place mid-carry
            elseif penFull then
                -- Do this before acquiring Place or leaving the treadmill. The
                -- hatch worker can still run remotely and the next pass rechecks.
                ProgressionCtl.placePending = false
                local fullness = penCapacity and penUsed >= penCapacity
                    and ("%d/%d"):format(penUsed, penCapacity)
                    or ("%d placed"):format(penUsed)
                setPlaceStatus("🟡 Egg slots full · " .. fullness .. " · waiting for hatch")
            elseif Settings.PlaceInRangeOnly and not unlockHatch and not playerInPenRange() then
                ProgressionCtl.placePending = false
                setPlaceStatus("🟡 Waiting for pen range")
            elseif not Arb.acquire("Place") then
                setPlaceStatus("⏸️ Steal has priority")
            else
                ProgressionCtl.placePending = true
                ProgressionCtl.placeBeat = os.clock()
                local leftTreadmill = ProgressionCtl.requestTreadmillExit()
                local ok, placed, _, full, reason
                if leftTreadmill then
                    ok, placed, _, full, reason = pcall(placeEggsNow)
                else
                    ok, reason = false, "treadmill"
                end
                -- Keep the treadmill locked out until every matching inventory
                -- egg is placed, the pen is full, or stealing preempts us.
                local remaining = #eggsToPlace()
                local fullNow = select(4, penFullState())
                RuntimeStatus.updatePlaceReservation(remaining > 0, full == true or fullNow)
                if ProgressionCtl.placePending then loopWait = 0.5 end
                if not ok and reason == "treadmill" then setPlaceStatus("🟡 Could not leave treadmill")
                elseif not ok then setPlaceStatus("🟡 Place error")
                elseif placed and placed > 0 then
                    if not ProgressionCtl.placePending then
                        ProgressionCtl.blockTreadmill(0.2)
                        ProgressionCtl.treadmillIdleSince = os.clock() - 1
                    end
                    setPlaceStatus(unlockHatch and "🔓 Crane egg placed · growing"
                        or ("🟢 Placed " .. placed))
                elseif full then setPlaceStatus("🟡 Pen full")
                elseif reason == "range" then setPlaceStatus("🟡 Waiting for pen range")
                elseif reason == "interrupted" then setPlaceStatus("⏸️ Yielding to steal")
                else setPlaceStatus("🟢 Monitoring eggs") end
            end
        elseif Settings.AutoHatch or unlockHatch then
            ProgressionCtl.placePending = false
            setPlaceStatus(hatched > 0 and ("🟢 Hatched " .. hatched)
                or (Arb.hatchOk() and "🟢 Watching hatch timers" or "⏸️ Egg transaction busy"))
        elseif Settings.PlaceAfterIncubation then
            ProgressionCtl.placePending = false
            setPlaceStatus("🟢 Waiting for mutation")
        else
            ProgressionCtl.placePending = false
        end
        if not ProgressionCtl.placePending then Arb.release("Place") end
        if placeAutomationEnabled() then
            loopWait = ProgressionCtl.placePending and 0.5 or 0.75
        elseif Settings.AutoHatch or unlockHatch then
            loopWait = hatchDueIn
        end
        end, debug.traceback)
        if workerOk then
            getgenv().__CHSAE_AutoPlaceWorkerError = nil
        else
            getgenv().__CHSAE_AutoPlaceWorkerError = tostring(workerError)
            ProgressionCtl.placePending = false
            Arb.placeBusy = false
            Arb.release("Place")
            setPlaceStatus("🟡 Retrying placement")
            warn("[CloverHub] Auto-Place worker recovered: " .. tostring(workerError))
            loopWait = 1
        end
        HatchScheduler.Wait(loopWait)
    end
end)
if getgenv().__CHSAE_Debug then
    getgenv().__CHSAE_Debug.PreviewPlaceEggs = function()
        return #eggsToPlace()
    end
end
end -- scoped AUTO-PLACE helpers; placeEggsNow is the shared exported entry point

