local function equipBestNow()
    if Settings.AutoRift == true and next(RuntimeStatus.riftReservedPets) ~= nil then
        return false, "Rift has reserved required pets"
    end
    if not (NativeEquipRemote and NativeEquipRemote:IsA("RemoteFunction")) then
        return false, "native Equip Best endpoint unavailable"
    end
    local invoked, accepted, reason = pcall(function()
        return NativeEquipRemote:InvokeServer()
    end)
    if not invoked then return false, tostring(accepted) end
    return accepted == true, tostring(reason or (accepted == true and "equipped" or "server rejected"))
end

