-- mutation list + display map (colored by each mutation's own color)
local MutItems, MutDM = {}, {}
do
    pcall(function()
        local names = {}
        -- MutationNames is a MAP: { Silver = true, ... } → the NAMES are the keys
        for name in pairs(MutationsMod.MutationNames) do
            if type(name) == "string" and name ~= "None" then names[#names + 1] = name end
        end
        table.sort(names)
        for _, name in ipairs(names) do
            MutItems[#MutItems + 1] = name
            local hex, mult = "#FFFFFF", nil
            pcall(function()
                local m = MutationsMod.GetMutation(name)
                if m then
                    if typeof(m.Color) == "Color3" then hex = toHex(m.Color)
                    elseif type(m.Color) == "string" then hex = "#" .. (m.Color:gsub("[^%x]", ""):sub(1,6)) end
                    mult = m.ValueMulti
                end
            end)
            MutDM[name] = ('<font color="%s"><b>%s</b></font>'):format(hex, name)
                .. (mult and (' <font color="#9AA0AA">×%s</font>'):format(tostring(mult)) or "")
        end
    end)
end

