-- sell plumbing (endpoints resolved live from the game's own NET_MAP)
local SellSer, SellPrice, SellNet
pcall(function()
    local AssetItems = require(ReplicatedStorage.Shared.Util.AssetItems)
    SellSer = { Deserialize = AssetItems.Decode }
    SellPrice = AssetItems.SalePrice
    SellNet = require(ReplicatedStorage.Shared.Remotes).PetSatchel
    if not SellNet.SellSelection then SellNet = nil end
end)

-- Inventory-item shape: Category / Mutations sit at the TOP level here, unlike
-- runtime records where they are nested under .ItemData.
local function invRarity(item)
    local ok, r = pcall(function() return AssetsDir.Directory[item.Category].Rarity end)
    return (ok and type(r) == "table") and r or nil
end
local function invMuts(item)
    local out = {}
    if type(item.Mutations) == "table" then
        for _, m in pairs(item.Mutations) do
            if type(m) == "string" and m ~= "None" then out[#out + 1] = m end
        end
    end
    return out
end

-- Everything the game itself would let you sell, with its sale price.
local function sellableInventory()
    local out = {}
    pcall(function()
        local sv = placeSaveMod and placeSaveMod.Get()
        if not (sv and SellSer) then return end
        RuntimeStatus.reconcileNewPetUids(sv)
        local equipped = {}
        for _, uid in ipairs(sv.EquippedAssets or {}) do equipped[tostring(uid)] = true end
        local vip = LocalPlayer:GetAttribute("VIP") and 2 or 1
        local scanned = 0
        for uid, raw in pairs(sv.Inventory or {}) do
            scanned += 1
            if scanned % 32 == 0 then task.wait(); if not sessionAlive() then return end end
            if not equipped[tostring(uid)]
                and not RuntimeStatus.petSellUidProtected(uid, sv, true) then
                local ok, item = pcall(SellSer.Deserialize, raw)
                if ok and type(item) == "table" and item.IsFavorite ~= true and not item.InFuse then
                    local price = 0
                    if SellPrice then pcall(function() price = (tonumber(SellPrice(item)) or 0) * vip end) end
                    local income, incomeKnown = valueScore(item)
                    out[#out + 1] = {
                        uid = uid,
                        item = item,
                        price = price,
                        income = income,
                        incomeKnown = incomeKnown,
                    }
                end
            end
        end
    end)
    return out
end

local function anySellFilter()
    return sellFilterHasChoice(Settings.SellPets), sellFilterHasChoice(Settings.SellRarities),
        sellFilterHasChoice(Settings.SellMutations),
        RuntimeStatus.kgFilterActive(Settings.SellPetKGMode, Settings.SellPetKGThreshold),
        RuntimeStatus.valueFilterActive(Settings.SellPetValueThreshold)
end

-- One predicate owns both the preview and the irreversible preflight. This
-- prevents the UID list from drifting when any active filter changes between a
-- status refresh and the next seller pass.
RuntimeStatus.sellPetMatchesCurrentFilters = function(item, income, incomeKnown)
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) or type(item) ~= "table" then
        return false
    end
    local cat = item.Category
    local rar = invRarity(item)
    local okPet = (not byPet) or (cat and Settings.SellPets[cat] == true)
    local okRar = (not byRar) or (rar and Settings.SellRarities[rar._id] == true)
    local okMut = not byMut
    if byMut then
        for _, mutation in ipairs(invMuts(item)) do
            if Settings.SellMutations[mutation] then okMut = true break end
        end
    end
    local okKG = not byKG or RuntimeStatus.kgFilterMatches(item,
        Settings.SellPetKGMode, Settings.SellPetKGThreshold)
    local okValue = not byValue or RuntimeStatus.valueFilterMatches(income,
        Settings.SellPetValueThreshold, "below", incomeKnown)
    local reservedForBloom = RuntimeStatus.greatBloomUnlockProtectCranePets == true
        and tostring(cat) == "Crane"
    return okPet and okRar and okMut and okKG and okValue and not reservedForBloom
end

-- which sellable pets match the current filters (AND across non-empty filters)
local function matchingSellPets()
    local out, total = {}, 0
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) then return out, 0 end -- no filter = sell NOTHING
    for _, e in ipairs(sellableInventory()) do
        if RuntimeStatus.sellPetMatchesCurrentFilters(e.item, e.income, e.incomeKnown) then
            out[#out + 1] = e
            total = total + (e.price or 0)
        end
    end
    table.sort(out, function(a, b) return tostring(a.uid) < tostring(b.uid) end)
    return out, total
end

-- Build the compact count/value summary while retaining an exact private
-- fingerprint and UID list. Inventory/filter drift still requires a second
-- confirmation even though individual items are no longer rendered.
RuntimeStatus.buildSalePreviewSnapshot = function(entries, itemKind, cap, filterSignature)
    entries = type(entries) == "table" and entries or {}
    local totalMatches = #entries
    local shown = math.min(totalMatches, tonumber(cap) or totalMatches)
    local selectedEntries, fingerprint, saleValue = {}, {}, 0
    for index = 1, shown do
        local entry = entries[index]
        selectedEntries[#selectedEntries + 1] = entry
        local item = type(entry) == "table" and entry.item or nil
        local uid = tostring(type(entry) == "table" and entry.uid or "")
        local category = tostring(type(item) == "table" and item.Category or "Unknown")
        local rarity = type(item) == "table" and invRarity(item) or nil
        local rarityId = tostring(type(rarity) == "table" and rarity._id or "Unknown rarity")
        local mutations = type(item) == "table" and invMuts(item) or {}
        table.sort(mutations)
        local weight = type(item) == "table" and weightKg(item) or nil
        local displayedWeight = type(weight) == "number"
            and tostring(math.round(math.max(weight, 0))) or "none"
        local price = type(entry) == "table" and tonumber(entry.price) or 0
        saleValue += price or 0
        fingerprint[#fingerprint + 1] = table.concat({
            uid, category, rarityId, table.concat(mutations, ","),
            displayedWeight, tostring(entry and entry.incomeKnown == true),
            tostring(entry and entry.income), tostring(price),
        }, ":")
    end
    local noun = itemKind == "egg" and "egg" or "pet"
    local summary = shown == 0 and ("0 " .. noun .. "s selected")
        or (("%d %s%s selected · $%s sale value"):format(
            shown, noun, shown == 1 and "" or "s", short(saleValue)))
    return {
        Summary = summary,
        Fingerprint = tostring(filterSignature or "") .. "|" .. tostring(totalMatches)
            .. "|" .. table.concat(fingerprint, "||"),
        Count = shown,
        TotalMatches = totalMatches,
        Entries = selectedEntries,
    }
end

-- Obsidian removes custom dialog elements before its native close tween, which
-- briefly exposes the bare title/footer shell. Hide that shell first, then let
-- Dismiss perform its normal element, registry, and overlay cleanup.
RuntimeStatus.hideAndDismissSellerDialog = function(target)
    if type(target) ~= "table" or target.Destroyed == true then return end
    pcall(function()
        local container = target.Container
        local frame = typeof(container) == "Instance"
            and container.Parent and container.Parent.Parent or nil
        if frame and frame:IsA("GuiObject") then frame.Visible = false end
    end)
    pcall(function() target:Dismiss() end)
end

-- Keep seller text stationary: remove the native dialog-only entrance scale,
-- build the cards while hidden, then reveal after automatic layout has settled.
-- The overlay may still fade; neither the card nor its labels slide or bounce.
RuntimeStatus.holdSellerDialogEntrance = function()
    local overlay
    -- Native AddDialog can yield while measuring text. Hide its fresh overlay
    -- before that first render, not only after AddDialog has returned.
    local connection = Window.MainFrame.ChildAdded:Connect(function(child)
        if not overlay and child:IsA("TextButton") and child.ZIndex == 9000 then
            overlay = child
            child.Visible = false
        end
    end)
    return function(revealOverlay)
        connection:Disconnect()
        if overlay and overlay.Parent then
            if revealOverlay then overlay.Visible = true else overlay:Destroy() end
        end
    end
end

RuntimeStatus.prepareStationarySellerDialog = function(dialog)
    local frame = dialog.Container.Parent and dialog.Container.Parent.Parent
    if not frame or not frame:IsA("GuiObject") then
        error("Seller dialog frame unavailable")
    end
    frame.Visible = false
    local entranceScale = frame:FindFirstChildOfClass("UIScale")
    if entranceScale then entranceScale:Destroy() end
    frame.Position = UDim2.fromScale(0.5, 0.5)
    return frame
end

RuntimeStatus.revealStationarySellerDialog = function(dialog, frame)
    task.spawn(function()
        local previousSize
        for _ = 1, 4 do
            RunService.Heartbeat:Wait()
            if not sessionAlive() or dialog.Destroyed == true
                or RuntimeStatus.activeSellerDialog ~= dialog or not frame.Parent then return end
            local size = frame.AbsoluteSize
            if previousSize == size and size.X > 0 and size.Y > 0 then
                frame.Visible = true
                return
            end
            previousSize = size
        end
        -- Do not show an unsettled layout. Cancel safely so a later attempt can
        -- rebuild it instead of presenting moving text or an invisible dialog.
        if RuntimeStatus.activeSellerDialog == dialog then
            RuntimeStatus.activeSellerDialog = nil
            RuntimeStatus.hideAndDismissSellerDialog(dialog)
        end
    end)
end

RuntimeStatus.openSellConfirmation = function(spec)
    spec = type(spec) == "table" and spec or {}
    if not sessionAlive() or type(spec.GetSnapshot) ~= "function"
        or type(spec.OnConfirm) ~= "function" then return false end
    local existing = RuntimeStatus.activeSellerDialog
    if type(existing) == "table" and existing.Destroyed ~= true then
        Library:Notify("Review or cancel the open sell warning first.", 4)
        return false
    end
    RuntimeStatus.activeSellerDialog = nil

    local snapshotOk, current = pcall(spec.GetSnapshot)
    if not snapshotOk or type(current) ~= "table" then return false end
    local dialog, notice, preview, releaseEntrance
    local confirming = false
    local function close(activeDialog)
        if RuntimeStatus.activeSellerDialog == dialog then
            RuntimeStatus.activeSellerDialog = nil
        end
        RuntimeStatus.hideAndDismissSellerDialog(activeDialog or dialog)
    end
    local built = pcall(function()
        releaseEntrance = RuntimeStatus.holdSellerDialogEntrance()
        dialog = Window:AddDialog(tostring(spec.Id or "SellerSafetyDialog"), {
            Title = tostring(spec.Title or "Confirm irreversible sale"),
            Description = "",
            TitleColor = Color3.fromRGB(248, 113, 113),
            AutoDismiss = false,
            OutsideClickDismiss = false,
            FooterButtons = {
                Cancel = {
                    Title = "Cancel", Variant = "Ghost", Order = 1,
                    Callback = function(activeDialog) close(activeDialog) end,
                },
                Confirm = {
                    Title = tostring(spec.ConfirmText or "Confirm Sale"),
                    Variant = "Destructive", Order = 2,
                    Callback = function(activeDialog)
                        if confirming or RuntimeStatus.activeSellerDialog ~= dialog then return end
                        if not sessionAlive() then close(activeDialog) return end
                        local freshOk, fresh = pcall(spec.GetSnapshot)
                        local valid, invalidText = freshOk and type(fresh) == "table", nil
                        if valid and type(spec.Validate) == "function" then
                            local validateOk, accepted, reason = pcall(spec.Validate, fresh)
                            valid = validateOk and accepted == true
                            invalidText = reason
                        end
                        if not valid then
                            notice.Body.Text = tostring(invalidText
                                or "The seller is no longer ready. Review the filters and Minimum Value.")
                            notice.Title.Text = "<b>SALE BLOCKED</b>"
                            return
                        end
                        if fresh.Fingerprint ~= current.Fingerprint then
                            current = fresh
                            preview:SetSnapshot(fresh)
                            notice.Title.Text = "<b>MATCHES CHANGED — REVIEW AGAIN</b>"
                            notice.Body.Text = "Inventory or filters changed while this warning was open. The selected count and value are refreshed; press the destructive button again to confirm the new selection."
                            dialog:Resize()
                            return
                        end
                        confirming = true
                        close(activeDialog)
                        local actionOk = sessionAlive() and pcall(spec.OnConfirm, fresh)
                        if not actionOk then
                            Settings.AutoSell = false
                            Settings.SellPetsWhenFull = false
                            Settings.AutoSellEggs = false
                            Settings.SellEggsWhenFull = false
                            for _, key in ipairs({ "AutoSell", "SellPetsWhenFull",
                                "AutoSellEggs", "SellEggsWhenFull" }) do
                                local controller = type(getgenv().__CHSAE_ConfigControllers) == "table"
                                    and getgenv().__CHSAE_ConfigControllers[key] or nil
                                if type(controller) == "table" and type(controller.SetValue) == "function" then
                                    pcall(controller.SetValue, controller, false)
                                end
                            end
                            Library:Notify("The confirmed action failed safely; all sellers remain off.", 5)
                        end
                    end,
                },
            },
        })
        local dialogFrame = RuntimeStatus.prepareStationarySellerDialog(dialog)
        releaseEntrance(true)
        releaseEntrance = nil
        RuntimeStatus.activeSellerDialog = dialog
        notice = CHK.Notice(dialog, tostring(spec.Id or "Seller") .. "WarningCard", {
            title = "IRREVERSIBLE SALE",
            text = tostring(spec.Warning or "This sale cannot be undone."),
            accent = Color3.fromRGB(248, 113, 113),
            titleColor = Color3.fromRGB(252, 165, 165),
            textColor = Color3.fromRGB(243, 244, 246),
            titleSize = 15,
            textSize = 13,
            height = 92,
            zIndex = 9003,
        })
        preview = CHK.SalePreview(dialog, tostring(spec.Id or "Seller") .. "Preview", {
            snapshot = current,
            accent = Color3.fromRGB(248, 113, 113),
            height = 46,
            zIndex = 9003,
        })
        dialog:Resize()
        RuntimeStatus.revealStationarySellerDialog(dialog, dialogFrame)
    end)
    if not built then
        if releaseEntrance then pcall(releaseEntrance, false) end
        if RuntimeStatus.activeSellerDialog == dialog then
            RuntimeStatus.activeSellerDialog = nil
        end
        if type(dialog) == "table" and dialog.Destroyed ~= true then
            RuntimeStatus.hideAndDismissSellerDialog(dialog)
        end
        Library:Notify("The sell warning could not open; selling remains off.", 5)
        return false
    end
    return true
end

RuntimeStatus.dismissSellConfirmation = function()
    local dialog = RuntimeStatus.activeSellerDialog
    RuntimeStatus.activeSellerDialog = nil
    if type(dialog) == "table" and dialog.Destroyed ~= true then
        RuntimeStatus.hideAndDismissSellerDialog(dialog)
    end
end

RuntimeStatus.petSalePreviewSnapshot = function(cap)
    local matches = matchingSellPets()
    local signature = table.concat({
        configSig(Settings.SellPets), configSig(Settings.SellRarities),
        configSig(Settings.SellMutations), tostring(Settings.SellPetKGMode),
        tostring(Settings.SellPetKGThreshold), tostring(Settings.SellPetValueThreshold),
    }, "|")
    return RuntimeStatus.buildSalePreviewSnapshot(matches, "pet", cap, signature)
end

RuntimeStatus.refreshSellPetStatus = function()
    if not (Settings.AutoSell or Settings.SellPetsWhenFull) then return end
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        setSellStatus("⏸️ Finish editing value")
        return
    end
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) then
        setSellStatus("🟡 Pick a filter")
        return
    end
    local matches = matchingSellPets()
    setSellStatus(("🟢 Armed · %d match"):format(#matches))
end

-- Cleanup for any legacy seller-owned Tool retained during a reload.
RuntimeStatus.stopHoldingSellerTool = function()
    local character = LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local held = character and character:FindFirstChildWhichIsA("Tool")
    local sellerOwned = RuntimeStatus.sellerHeldTool
    RuntimeStatus.sellerHeldTool = nil
    if humanoid and held and held == sellerOwned then
        pcall(function() humanoid:UnequipTools() end)
    end
end

-- Filtered batch selling (v153).
-- Revalidate the reviewed UID selection and submit one item per native selection
-- request. Never substitute a sell-all call when selection is unavailable.
local function sellPetEntries(entries, cap, autoSettingKey)
    -- Paced sale passes (v160): confirm each batch before submitting the next.
    local function sellPass(entries, cap, autoSettingKey)
    local fired, uids, seen = {}, {}, {}
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        return 0, 0, 0, 0, "value-input-mismatch"
    end
    if not sessionAlive() or carrying or not Arb.sellOk()
        or (autoSettingKey and Settings[autoSettingKey] ~= true) then
        return 0, 0, 0, 0, "seller-busy"
    end

    -- Re-read inventory and apply current protections/filters to the reviewed
    -- UIDs. Only this fresh intersection may be sent in the batch.
    local save
    pcall(function() save = placeSaveMod and placeSaveMod.Get() end)
    if not (type(save) == "table" and type(save.Inventory) == "table" and SellSer and SellNet and SellNet.SellSelection) then
        return 0, 0, 0, 0, "save-unavailable"
    end
    RuntimeStatus.reconcileNewPetUids(save)
    local equipped = {}
    for _, uid in ipairs(save.EquippedAssets or {}) do equipped[tostring(uid)] = true end
    local vip = LocalPlayer:GetAttribute("VIP") and 2 or 1
    for _, candidate in ipairs(entries) do
        if cap and #uids >= cap then break end
        local uid = tostring(candidate.uid or "")
        local raw = save.Inventory[uid]
        if uid ~= "" and not seen[uid] and raw ~= nil and not equipped[uid]
            and not RuntimeStatus.petSellUidProtected(uid, save, true) then
            local decoded, item = pcall(SellSer.Deserialize, raw)
            if decoded and type(item) == "table"
                and item.IsFavorite ~= true and not item.InFuse then
                local income, known = valueScore(item)
                if RuntimeStatus.sellPetMatchesCurrentFilters(item, income, known) then
                    local price = 0
                    if SellPrice then
                        pcall(function() price = (tonumber(SellPrice(item)) or 0) * vip end)
                    end
                    local fresh = {
                        uid = uid,
                        item = item,
                        price = price,
                        income = income,
                        incomeKnown = known,
                    }
                    seen[uid] = true
                    fired[#fired + 1] = fresh
                    uids[#uids + 1] = uid
                end
            end
        end
    end
    if #uids == 0 then return 0, 0, 0, 0, "preflight-empty" end

    -- Recheck immediately before the irreversible batch in case Steal entered a
    -- protected phase while the matching list was being assembled.
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        return 0, 0, 0, 0, "value-input-mismatch"
    end
    if not sessionAlive() or carrying or not Arb.sellOk()
        or (autoSettingKey and Settings[autoSettingKey] ~= true) then
        return 0, 0, 0, 0, "seller-busy"
    end

    local before, requested, auditRows = {}, {}, {}
    for uid in pairs(save.Inventory) do before[tostring(uid)] = true end
    for index, uid in ipairs(uids) do
        auditRows[index] = {
            UID = uid,
            Category = tostring(fired[index].item.Category or ""),
            Income = fired[index].income,
        }
    end
    RuntimeStatus.lastPetSellPreflight = {
        At = os.clock(),
        Threshold = tonumber(Settings.SellPetValueThreshold) or 0,
        Count = #uids,
        Entries = auditRows,
    }
    if type(getgenv().__CHSAE_Debug) == "table" then
        getgenv().__CHSAE_Debug.LastPetSellPreflight = RuntimeStatus.lastPetSellPreflight
    end
    if RuntimeStatus.valueFilterActive(Settings.SellPetValueThreshold) then
        setSellStatus(("🟡 Verified %d · below $%s/s"):format(#uids,
            RuntimeStatus.formatCompactValue(Settings.SellPetValueThreshold)))
    else
        setSellStatus(("🟡 Verified %d selected UID%s"):format(#uids,
            #uids == 1 and "" or "s"))
    end

    -- UI updates can yield; confirm the batch still meets every guard before
    -- sending a single native selection request. No newly matched UID is added.
    local latest
    pcall(function() latest = placeSaveMod.Get() end)
    if type(latest) ~= "table" or type(latest.Inventory) ~= "table" then
        return 0, 0, #fired, 0, "save-unavailable"
    end
    RuntimeStatus.reconcileNewPetUids(latest)
    local nowEquipped, sent, finalUids = {}, {}, {}
    for _, uid in ipairs(latest.EquippedAssets or {}) do nowEquipped[tostring(uid)] = true end
    table.clear(before)
    for uid in pairs(latest.Inventory) do before[tostring(uid)] = true end
    for _, entry in ipairs(fired) do
        local uid, raw = entry.uid, latest.Inventory[entry.uid]
        if raw ~= nil and not nowEquipped[uid] and not RuntimeStatus.petSellUidProtected(uid,latest,true) then
            local ok, item = pcall(SellSer.Deserialize,raw)
            if ok and type(item) == "table" and item.IsFavorite ~= true and not item.InFuse then
                local income,known = valueScore(item)
                if RuntimeStatus.sellPetMatchesCurrentFilters(item,income,known) then
                    entry.item,entry.income,entry.incomeKnown = item,income,known
                    if SellPrice then pcall(function() entry.price=(tonumber(SellPrice(item)) or 0)*vip end) end
                    sent[#sent+1],finalUids[#finalUids+1] = entry,uid
                end
            end
        end
    end
    if #finalUids == 0 then return 0,0,0,0,"preflight-empty" end
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        return 0,0,0,0,"value-input-mismatch"
    end
    if not sessionAlive() or carrying or not Arb.sellOk()
        or (autoSettingKey and Settings[autoSettingKey] ~= true) then return 0,0,0,0,"seller-busy" end
    local sentOk = pcall(function()
        SellNet.SellSelection:FireServer({Assets = finalUids, Eggs = {}})
    end)
    if not sentOk then return 0,0,#sent,0,"transport-error" end
    for _, uid in ipairs(finalUids) do requested[uid] = true end
    RuntimeStatus.lastPetSellPreflight.SentUIDs = finalUids

    -- FireServer has no acknowledgment. Confirm the whole submitted selection
    -- against a readable inventory snapshot and audit non-selected removals.
    local inv, inventoryReadable, requestedGone = {}, false, false
    local deadline = os.clock() + 2.5
    repeat
        task.wait(0.1)
        inv, inventoryReadable = {}, false
        pcall(function()
            local latest = placeSaveMod.Get()
            if type(latest) == "table" and type(latest.Inventory) == "table" then
                inv = latest.Inventory
                inventoryReadable = true
            end
        end)
        -- A temporarily unavailable replica is not proof that every requested
        -- pet disappeared. Keep polling until a readable snapshot arrives or
        -- the confirmation deadline expires.
        if inventoryReadable then
            local pending = false
            for _, e in ipairs(sent) do
                if inv[e.uid] ~= nil then pending = true break end
            end
            if not pending then
                requestedGone = true
                break
            end
        end
        if os.clock() >= deadline then break end
    until false
    if not inventoryReadable then
        -- Never repeat an irreversible batch when its result cannot be audited.
        Settings.AutoSell = false
        Settings.SellPetsWhenFull = false
        if type(RuntimeStatus.forceDisarmPetSeller) == "function" then
            RuntimeStatus.forceDisarmPetSeller(
                "🔴 Seller stopped · confirmation unavailable",
                "Pet selling stopped because the inventory result could not be verified.",
                true
            )
        else
            setSellStatus("🔴 Seller stopped · confirmation unavailable")
            pcall(function()
                Library:Notify("Pet selling stopped because the inventory result could not be verified.", 6)
            end)
        end
        return 0, 0, #sent, 0, "confirmation-unavailable"
    end

    -- Replication can deliver the requested removals just before another change
    -- from the same transaction. Take one settling snapshot before auditing the
    -- complete before/after UID sets.
    if requestedGone then
        task.wait(0.25)
        inv, inventoryReadable = {}, false
        pcall(function()
            local settled = placeSaveMod.Get()
            if type(settled) == "table" and type(settled.Inventory) == "table" then
                inv, inventoryReadable = settled.Inventory, true
            end
        end)
    end
    if not inventoryReadable then
        RuntimeStatus.forceDisarmPetSeller("🔴 Seller stopped · confirmation unavailable",
            "Pet selling stopped because the batch result could not be verified.", true)
        return 0,0,#sent,0,"confirmation-unavailable"
    end
    local present = {}
    for uid in pairs(inv) do present[tostring(uid)] = true end
    local sold, earned, refused = 0, 0, 0
    for _, e in ipairs(sent) do
        if not present[tostring(e.uid)] then
            sold = sold + 1
            earned = earned + (e.price or 0)
        else
            refused = refused + 1
        end
    end
    local unexpected = {}
    for uid in pairs(before) do
        if not requested[uid] and not present[uid] then unexpected[#unexpected + 1] = uid end
    end
    table.sort(unexpected)
    if type(getgenv().__CHSAE_Debug) == "table" then
        getgenv().__CHSAE_Debug.LastPetSellUnexpected = unexpected
    end
    if #unexpected > 0 then
        Settings.AutoSell = false
        Settings.SellPetsWhenFull = false
        if type(RuntimeStatus.forceDisarmPetSeller) == "function" then
            RuntimeStatus.forceDisarmPetSeller(
                "🔴 Seller stopped · unexpected inventory change",
                "Pet selling stopped because a UID outside the verified batch disappeared.",
                true
            )
        end
    end
    return sold, earned, refused, #unexpected,
        #unexpected > 0 and "unexpected-removal" or nil
end
    if #entries <= 1 then return sellPass(entries, cap, autoSettingKey) end
    local sold, earned, refused, unexpected = 0, 0, 0, 0
    local seen, cursor, attempted = {}, 1, 0
    while cursor <= #entries do
        local remaining = cap and math.max(0, cap - attempted) or 1
        if remaining <= 0 then break end
        local batch = {}
        while cursor <= #entries and #batch < math.min(1, remaining) do
            local entry = entries[cursor]
            cursor += 1
            local uid = tostring(entry.uid or "")
            if uid ~= "" and not seen[uid] then
                seen[uid] = true
                batch[#batch + 1] = entry
            end
        end
        if #batch > 0 then
            local n, money, failed, extra, reason = sellPass(batch, remaining, autoSettingKey)
            sold, earned, refused = sold + n, earned + money, refused + failed
            attempted += n + failed
            unexpected += extra
            if reason and reason ~= "preflight-empty" then return sold, earned, refused, unexpected, reason end
            -- A partially confirmed request is never repeated by this pass.
            if failed > 0 then break end
        end
        if cursor <= #entries then task.wait(0.35) end
    end
    return sold, earned, refused, unexpected
end

-- Auto-Sell pass (driven by the pets loop; sell FIRST, then Equip Best re-picks).
local function autoSellPass(autoSettingKey)
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        setSellStatus("⏸️ Finish editing value")
        return 0, false, 0
    end
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) then
        setSellStatus("🟡 Pick a filter") -- never mass-sell on an empty filter
        return 0, false, 0
    end
    local m = matchingSellPets()
    if #m == 0 then setSellStatus("🟢 Armed · 0 match") return 0, false, 0 end
    local sold, got, refused, unexpected, reason = sellPetEntries(m, nil, autoSettingKey)
    if reason == "preflight-empty" then
        setSellStatus("🟢 Armed · 0 verified")
        return 0, false, 0
    elseif reason == "value-input-mismatch" then
        setSellStatus("⏸️ Visible value does not match saved value")
        return 0, true, 0
    elseif reason == "seller-busy" then
        setSellStatus(RuntimeStatus.hatchPetSaleGuardActive()
            and "⏸️ Fresh/held hatch pet protected"
            or "⏸️ Busy · retrying")
        return 0, true, 0
    elseif reason == "save-unavailable" then
        setSellStatus("⏸️ Inventory unavailable · retrying")
        return 0, true, 0
    elseif reason == "confirmation-unavailable" then
        setSellStatus("🔴 Seller stopped · confirmation unavailable")
        return 0, false, refused
    elseif reason == "transport-error" then
        setSellStatus("🔴 Sell request failed")
        return 0, true, refused
    elseif (unexpected or 0) > 0 then
        setSellStatus("🔴 Seller stopped · unexpected inventory change")
    elseif not autoSettingKey or Settings[autoSettingKey] then
        setSellStatus(refused > 0
            and ("🟡 Sold %d · %d not sold"):format(sold, refused)
            or  ("🟢 Sold %d · $%s"):format(sold, short(got)))
    end
    return sold, true, refused
end

local autoSellTgl = SellBox:AddToggle("AutoSellToggle", {
    Text = "Auto-Sell", Default = Settings.AutoSell, Risky = true,
    Tooltip = "Warning: Sells matching pets. Favorites are safe.",
})
autoSellTgl:OnChanged(function(v)
    if RuntimeStatus.petSellerToggleWrite == true then return end
    if not v then
        Settings.AutoSell = false
        if not Settings.SellPetsWhenFull then setSellStatus("🔴 Off") end
        return
    end

    -- A visual ON state must never race the worker while approval is pending.
    Settings.AutoSell = false
    RuntimeStatus.petSellerToggleWrite = true
    pcall(function() autoSellTgl:SetValue(false) end)
    RuntimeStatus.petSellerToggleWrite = nil
    if RuntimeStatus.valueFilterLoadInProgress == true then return end
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        setSellStatus("⏸️ Finish editing value")
        Library:Notify("Finish editing Minimum Value, then enable Auto-Sell again.", 4)
        return
    end
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) then
        setSellStatus("🟡 Pick a filter")
        return
    end
    if not SellNet then
        setSellStatus("🔴 Sell unavailable")
        return
    end
    RuntimeStatus.openSellConfirmation({
        Id = "ConfirmAutoSellPets",
        Title = "Enable Pet Auto-Sell?",
        ConfirmText = "Enable Auto-Sell",
        Warning = "Turning this on repeatedly sells every current and future pet matching these filters. Sales are permanent and cannot be restored. Favorite anything you want to keep.",
        GetSnapshot = function() return RuntimeStatus.petSalePreviewSnapshot(nil) end,
        Validate = function()
            if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
                return false, "Minimum Value is still being edited; Auto-Sell remains off."
            end
            local p, r, m, k, value = anySellFilter()
            if not (p or r or m or k or value) then
                return false, "Choose at least one pet filter; Auto-Sell remains off."
            end
            return SellNet ~= nil, "Pet selling is unavailable in this client."
        end,
        OnConfirm = function(fresh)
            RuntimeStatus.petSellerToggleWrite = true
            Settings.AutoSell = true
            local wrote = pcall(function() autoSellTgl:SetValue(true) end)
            RuntimeStatus.petSellerToggleWrite = nil
            if not wrote then
                Settings.AutoSell = false
                setSellStatus("🔴 Auto-Sell stayed off")
                return
            end
            RuntimeStatus.markValueFilterChanged()
            setSellStatus(("🟢 Armed · %d match"):format(fresh.TotalMatches or 0))
        end,
    })
end)

local sellPetsWhenFullTgl = SellBox:AddToggle("SellPetsWhenFullToggle", {
    Text = "Sell Full", Default = Settings.SellPetsWhenFull, Risky = true,
    Tooltip = "Only sell once pet inventory is full.",
})
sellPetsWhenFullTgl:OnChanged(function(v)
    if RuntimeStatus.petSellerToggleWrite == true then return end
    if not v then
        Settings.SellPetsWhenFull = false
        setSellStatus(Settings.AutoSell and "🟢 Auto-Sell armed" or "🔴 Off")
        return
    end

    Settings.SellPetsWhenFull = false
    RuntimeStatus.petSellerToggleWrite = true
    pcall(function() sellPetsWhenFullTgl:SetValue(false) end)
    RuntimeStatus.petSellerToggleWrite = nil
    if RuntimeStatus.valueFilterLoadInProgress == true then return end
    if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
        setSellStatus("⏸️ Finish editing value")
        Library:Notify("Finish editing Minimum Value, then enable Sell Full again.", 4)
        return
    end
    local byPet, byRar, byMut, byKG, byValue = anySellFilter()
    if not (byPet or byRar or byMut or byKG or byValue) then
        setSellStatus("🟡 Pick a filter")
        return
    end
    if not SellNet then setSellStatus("🔴 Sell unavailable") return end
    RuntimeStatus.openSellConfirmation({
        Id = "ConfirmSellPetsWhenFull",
        Title = "Enable Pet Sell Full?",
        ConfirmText = "Enable Sell Full",
        Warning = "When pet inventory becomes full, all matching pets are submitted one at a time with a pause between confirmed sales. Each sale is permanent. The current selected count is shown below.",
        GetSnapshot = function() return RuntimeStatus.petSalePreviewSnapshot(nil) end,
        Validate = function()
            if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
                return false, "Minimum Value is still being edited; Sell Full remains off."
            end
            local p, r, m, k, value = anySellFilter()
            if not (p or r or m or k or value) then
                return false, "Choose at least one pet filter; Sell Full remains off."
            end
            return SellNet ~= nil, "Pet selling is unavailable in this client."
        end,
        OnConfirm = function()
            RuntimeStatus.petSellerToggleWrite = true
            Settings.SellPetsWhenFull = true
            local wrote = pcall(function() sellPetsWhenFullTgl:SetValue(true) end)
            RuntimeStatus.petSellerToggleWrite = nil
            if not wrote then
                Settings.SellPetsWhenFull = false
                setSellStatus("🔴 Sell Full stayed off")
                return
            end
            RuntimeStatus.markValueFilterChanged()
            local _, count, capacity = RuntimeStatus.petInventoryCapacityState()
            setSellStatus(("🟢 Watching · %d/%d"):format(count, capacity or 0))
        end,
    })
end)
if type(getgenv().__CHSAE_ConfigControllers) == "table" then
    getgenv().__CHSAE_ConfigControllers.AutoSell = autoSellTgl
    getgenv().__CHSAE_ConfigControllers.SellPetsWhenFull = sellPetsWhenFullTgl
end

RuntimeStatus.forceDisarmPetSeller = function(statusText, notificationText, notifyAlways)
    local wasEnabled = Settings.AutoSell or Settings.SellPetsWhenFull
    RuntimeStatus.dismissSellConfirmation()
    pcall(function() autoSellTgl:SetValue(false) end)
    pcall(function() sellPetsWhenFullTgl:SetValue(false) end)
    Settings.AutoSell = false
    Settings.SellPetsWhenFull = false
    if statusText then setSellStatus(statusText) end
    if notificationText and (wasEnabled or notifyAlways) then
        pcall(function()
            Library:Notify(notificationText, 6)
        end)
    end
    return wasEnabled
end

RuntimeStatus.disarmPetSellerForValueEdit = function()
    if Settings.AutoSell or Settings.SellPetsWhenFull then
        RuntimeStatus.forceDisarmPetSeller(
            "⏸️ Value changed · review and re-enable",
            "Pet selling paused. Review Minimum Value, then re-enable it.",
            false
        )
    end
end

RuntimeStatus.disarmPetSellerForFilterEdit = function()
    if Settings.AutoSell or Settings.SellPetsWhenFull then
        RuntimeStatus.forceDisarmPetSeller(
            "⏸️ Filters changed · review and re-enable",
            "Pet selling paused because its filters changed. Review the new match list, then re-enable it.",
            false
        )
    end
end

MakeButtonPanel(SellBox, "BtnSellPetsOnce", {
    { "💰 Sell Pets", function()
        if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
            setSellStatus("⏸️ Finish editing value")
            Library:Notify("Finish editing Minimum Value, then try again.", 4)
            return
        end
        local byPet, byRar, byMut, byKG, byValue = anySellFilter()
        if not (byPet or byRar or byMut or byKG or byValue) then
            setSellStatus("🟡 Pick a filter")
            return
        end
        if not SellNet then
            setSellStatus("🔴 Sell unavailable")
            Library:Notify("💰 Pet selling is unavailable in this client.", 4)
            return
        end
        local matches = matchingSellPets()
        if #matches == 0 then
            setSellStatus("🟢 0 match")
            return
        end
        RuntimeStatus.openSellConfirmation({
            Id = "ConfirmSellPetsOnce",
            Title = "Sell These Pets?",
            ConfirmText = "Sell Selected Pets",
            Warning = "All selected pets will be submitted one at a time with a pause between confirmed sales. This cannot be undone. Only pets selected at confirmation can be attempted.",
            GetSnapshot = function() return RuntimeStatus.petSalePreviewSnapshot(nil) end,
            Validate = function(fresh)
                if not RuntimeStatus.sellerValueFilterReady("SellPetValueThreshold") then
                    return false, "Minimum Value is still being edited; nothing was sold."
                end
                local p, r, m, k, value = anySellFilter()
                if not (p or r or m or k or value) then
                    return false, "Choose at least one pet filter; nothing was sold."
                end
                if not SellNet then return false, "Pet selling is unavailable in this client." end
                return (fresh.Count or 0) > 0, "No pets currently match; nothing was sold."
            end,
            OnConfirm = function(fresh)
                setSellStatus(("🟡 Selling once · %d reviewed"):format(fresh.Count or 0))
                task.spawn(function()
                    if not Arb.sellSerial(function()
                        local sold, got, refused, unexpected, reason = sellPetEntries(
                            fresh.Entries or {}, nil, nil)
                        if reason == "seller-busy" then
                            setSellStatus("⏸️ Busy · try again")
                        elseif reason == "save-unavailable" then
                            setSellStatus("⏸️ Inventory unavailable · nothing repeated")
                        elseif reason == "confirmation-unavailable" then
                            setSellStatus("🔴 Seller stopped · confirmation unavailable")
                        elseif reason == "transport-error" then
                            setSellStatus("🔴 Sell request failed")
                        elseif (unexpected or 0) > 0 then
                            setSellStatus("🔴 Seller stopped · unexpected inventory change")
                        else
                            setSellStatus(refused > 0
                                and ("🟡 Sold %d · %d not sold"):format(sold, refused)
                                or ("🟢 Sold %d · $%s"):format(sold, short(got)))
                        end
                    end, "Selling pets") then
                        setSellStatus("⏸️ Busy · try again")
                    end
                end)
            end,
        })
    end },
})

-- ── SELL ▸ Sell Eggs (category + rarity + mutation filters) ──
-- SellPrompt sends explicit EggInventory UIDs through SellSelection.Eggs.
-- Placed eggs and items reserved by Auto-Place/Rift remain protected.
EggSellBox = SellTab:AddRightGroupbox("🥚 Sell Eggs")
