local function sellEggFilterState()
    return sellFilterHasChoice(Settings.SellEggNames), sellFilterHasChoice(Settings.SellEggRarities),
        sellFilterHasChoice(Settings.SellEggMutations),
        RuntimeStatus.kgFilterActive(Settings.SellEggKGMode, Settings.SellEggKGThreshold),
        RuntimeStatus.valueFilterActive(Settings.SellEggValueThreshold)
end

local function sellableEggInventory(reviewed)
    local out = {}
    pcall(function()
        local sv = placeSaveMod and placeSaveMod.Get()
        if not (sv and EggSellUtil) then return end
        local inventory, scanned = sv.EggInventory or {}, 0
        for uid in pairs(reviewed or inventory) do
            scanned += 1
            if not reviewed and scanned % 32 == 0 then task.wait(); if not sessionAlive() then return end end
            local raw = inventory[uid]
            if type(raw) == "table" and raw.Placement == nil then
                local okEgg, egg = pcall(EggSellUtil.DeserializeSavedEgg, raw)
                if okEgg and egg then
                    local okItem, item = pcall(EggSellUtil.BuildAssetItemData, egg)
                    local price = 0
                    pcall(function() price = tonumber(EggSellUtil.GetSellPrice(egg)) or 0 end)
                    if okItem and type(item) == "table" and item.Category then
                        local income, incomeKnown = valueScore(item)
                        out[#out + 1] = {
                            uid = uid,
                            item = item,
                            raw = raw,
                            price = price,
                            income = income,
                            incomeKnown = incomeKnown,
                        }
                    end
                end
            end
        end
    end)
    return out
end

local function updateEggOverlapStatus(overlap, blocked, penFull)
    overlap, blocked = tonumber(overlap) or 0, tonumber(blocked) or 0
    local text
    if (tonumber(RuntimeStatus.riftEggBlocked) or 0) > 0 then
        text = "🔒 Required egg reserved for Rift"
    elseif overlap <= 0 then
        text = "✅ No Auto-Place overlap"
    elseif blocked > 0 then
        text = ("⚠️ Overlap: %d · Auto-Place first"):format(blocked)
    else
        text = (penFull and "🟠 Overlap: %d · pen full, can sell"
            or "🟠 Overlap: %d · eligible to sell"):format(overlap)
    end
    RuntimeStatus.eggSellOverlap = text
    RuntimeStatus.setLabel(eggSellOverlapLbl, text)
end

local function matchingSellEggs(reviewed)
    local byCategory, byRarity, byMutation, byKG, byValue = sellEggFilterState()
    local out, total, overlap, blocked, unlockBlocked = {}, 0, 0, 0, 0
    if not (byRarity or byCategory or byMutation or byKG or byValue) then
        RuntimeStatus.riftEggBlocked = 0
        updateEggOverlapStatus(0, 0, false)
        return out, 0, 0, 0
    end
    local placeSelected, protectOverlap, penFull = {}, false, false
    if type(RuntimeStatus.getAutoPlaceEggPolicy) == "function" then
        pcall(function()
            placeSelected, protectOverlap, penFull = RuntimeStatus.getAutoPlaceEggPolicy()
        end)
    end
    for _, entry in ipairs(sellableEggInventory(reviewed)) do
        local category = entry.item.Category
        local rarity = invRarity(entry.item)
        local categoryOk = not byCategory or Settings.SellEggNames[category] == true
        local rarityOk = not byRarity
            or (rarity and Settings.SellEggRarities[rarity._id] == true)
        local mutationOk = not byMutation
        local kgOk = not byKG or RuntimeStatus.kgFilterMatches(entry.item,
            Settings.SellEggKGMode, Settings.SellEggKGThreshold)
        local valueOk = not byValue or RuntimeStatus.valueFilterMatches(entry.income,
            Settings.SellEggValueThreshold, "below", entry.incomeKnown)
        if byMutation then
            for _, mutation in ipairs(invMuts(entry.item)) do
                if Settings.SellEggMutations[mutation] then mutationOk = true break end
            end
        end
        -- One filled dropdown filters by itself; filled dropdowns combine with AND.
        if categoryOk and rarityOk and mutationOk and kgOk and valueOk then
            local conflictsWithPlace = placeSelected[tostring(entry.uid)] == true
            local riftReserved = RuntimeStatus.riftEggReserved(entry.uid)
            if conflictsWithPlace or riftReserved then overlap += 1 end
            if riftReserved then
                blocked += 1
                unlockBlocked += 1
            elseif conflictsWithPlace and protectOverlap then
                blocked += 1
            else
                out[#out + 1] = entry
                total += entry.price or 0
            end
        end
    end
    if not reviewed then
        RuntimeStatus.riftEggBlocked = unlockBlocked
        updateEggOverlapStatus(overlap, blocked, penFull)
    end
    table.sort(out, function(a, b) return tostring(a.uid) < tostring(b.uid) end)
    return out, total, overlap, blocked
end
RuntimeStatus.refreshEggOverlapStatus = function() matchingSellEggs() end
task.defer(RuntimeStatus.refreshEggOverlapStatus)

RuntimeStatus.eggSalePreviewSnapshot = function(cap)
    local matches = matchingSellEggs()
    local signature = table.concat({
        configSig(Settings.SellEggNames), configSig(Settings.SellEggRarities),
        configSig(Settings.SellEggMutations), tostring(Settings.SellEggKGMode),
        tostring(Settings.SellEggKGThreshold), tostring(Settings.SellEggValueThreshold),
    }, "|")
    return RuntimeStatus.buildSalePreviewSnapshot(matches, "egg", cap, signature)
end

RuntimeStatus.eggSellUidCurrentlyEligible = function(uid)
    uid = tostring(uid or "")
    for _, entry in ipairs(matchingSellEggs()) do
        if tostring(entry.uid) == uid then return true end
    end
    return false
end

local function sellEggEntries(entries, cap, autoSettingKey)
    -- Paced sale passes (v160): confirm each batch before submitting the next.
    local function sellPass(entries, cap, autoSettingKey)
    local function ready()
        return sessionAlive() and not carrying and Arb.sellOk()
            and RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold")
            and (not autoSettingKey or Settings[autoSettingKey] == true)
    end
    if not ready() then return 0, 0, 0 end
    if not (SellNet and SellNet.SellSelection) then return 0, 0, #entries end
    local reviewed, selected, uids, requested = {}, {}, {}, {}
    for _, entry in ipairs(entries) do reviewed[tostring(entry.uid)] = true end
    -- The batch is the intersection of the reviewed UIDs and fresh matches.
    -- Newly appearing matches cannot enter a previously confirmed selection.
    for _, entry in ipairs(matchingSellEggs(reviewed)) do
        local uid = tostring(entry.uid)
        if reviewed[uid] and not requested[uid] and not RuntimeStatus.riftEggReserved(uid) then
            if cap and #uids >= cap then break end
            selected[#selected+1], uids[#uids+1], requested[uid] = entry, uid, true
        end
    end
    if #uids == 0 or not ready() then return 0, 0, 0 end
    local okBefore, beforeSave = pcall(function() return placeSaveMod.Get() end)
    if not okBefore or type(beforeSave) ~= "table" or type(beforeSave.EggInventory) ~= "table" then
        return 0, 0, #selected
    end
    local before = {}
    for uid in pairs(beforeSave.EggInventory) do before[tostring(uid)] = true end
    -- A save read can yield. Refresh eligibility once more before the one send.
    local current = {}
    for _, entry in ipairs(matchingSellEggs(reviewed)) do current[tostring(entry.uid)] = entry end
    local final, finalUids = {}, {}
    table.clear(requested)
    for _, uid in ipairs(uids) do
        if before[uid] and current[uid] and not RuntimeStatus.riftEggReserved(uid) then
            final[#final+1], finalUids[#finalUids+1], requested[uid] = current[uid], uid, true
        end
    end
    if #finalUids == 0 or not ready() then return 0, 0, 0 end
    local sent = pcall(function()
        SellNet.SellSelection:FireServer({Assets = {}, Eggs = finalUids})
    end)
    if not sent then return 0, 0, #final end
    local inventory, deadline = nil, os.clock()+2.5
    repeat
        inventory = nil
        local ok, save = pcall(function() return placeSaveMod.Get() end)
        if ok and type(save) == "table" and type(save.EggInventory) == "table" then
            inventory = save.EggInventory
            local allGone = true
            for _, uid in ipairs(finalUids) do if inventory[uid] ~= nil then allGone=false; break end end
            if allGone then break end
        end
        if os.clock() >= deadline then break end
        task.wait(0.1)
    until false
    if inventory then
        task.wait(0.25)
        local ok, save = pcall(function() return placeSaveMod.Get() end)
        inventory = ok and type(save) == "table" and type(save.EggInventory) == "table" and save.EggInventory or nil
    end
    if not inventory then
        RuntimeStatus.forceDisarmEggSeller("🔴 Seller stopped · confirmation unavailable",
            "Egg selling stopped because the batch result could not be verified.", true)
        return 0, 0, #final, "confirmation-unavailable"
    end
    local sold, earned = 0, 0
    for _, entry in ipairs(final) do
        if inventory[tostring(entry.uid)] == nil then sold+=1; earned+=entry.price or 0 end
    end
    for uid in pairs(before) do
        if not requested[uid] and inventory[uid] == nil then
            RuntimeStatus.forceDisarmEggSeller("🔴 Seller stopped · unexpected inventory change",
                "Egg selling stopped because an egg outside the filtered batch disappeared.", true)
            return sold, earned, #final-sold, "unexpected-removal"
        end
    end
    return sold, earned, #final-sold
end
    if #entries <= 1 then return sellPass(entries, cap, autoSettingKey) end
    local sold, earned, refused, unexpected = 0, 0, 0, 0
    local seen, cursor, attempted = {}, 1, 0
    while cursor <= #entries do
        local remaining = cap and math.max(0, cap - attempted) or 1
        if remaining <= 0 then break end
        local batch = {}
        while cursor <= #entries and #batch < math.min(1, remaining) do
            local entry = entries[cursor]
            cursor += 1
            local uid = tostring(entry.uid or "")
            if uid ~= "" and not seen[uid] then
                seen[uid] = true
                batch[#batch + 1] = entry
            end
        end
        if #batch > 0 then
            local n, money, failed, reason = sellPass(batch, remaining, autoSettingKey)
            sold, earned, refused = sold + n, earned + money, refused + failed
            attempted += n + failed
            if reason then return sold, earned, refused, reason end
            -- A partially confirmed request is never repeated by this pass.
            if failed > 0 then break end
        end
        if cursor <= #entries then task.wait(0.35) end
    end
    return sold, earned, refused
end

local function autoSellEggPass(autoSettingKey)
    if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
        setEggSellStatus("⏸️ Finish editing value")
        return 0, false, 0
    end
    local byCategory, byRarity, byMutation, byKG, byValue = sellEggFilterState()
    if not (byCategory or byRarity or byMutation or byKG or byValue) then
        setEggSellStatus("🟡 Pick a filter")
        return 0, false, 0
    end
    local matches = matchingSellEggs()
    if #matches == 0 then setEggSellStatus("🟢 Armed · 0 match") return 0, false, 0 end
    local sold, earned, refused, reason = sellEggEntries(matches, nil, autoSettingKey)
    if reason then return sold, false, refused end
    if not autoSettingKey or Settings[autoSettingKey] then
        setEggSellStatus(refused > 0
            and ("🟡 Sold %d · %d not sold"):format(sold, refused)
            or ("🟢 Sold %d · $%s"):format(sold, short(earned)))
    end
    return sold, true, refused
end

local autoSellEggTgl = EggSellBox:AddToggle("AutoSellEggToggle", {
    Text = "Auto-Sell Eggs", Default = Settings.AutoSellEggs, Risky = true,
    Tooltip = "Warning: Sells matching eggs. Placed eggs are safe.",
})
autoSellEggTgl:OnChanged(function(v)
    if RuntimeStatus.eggSellerToggleWrite == true then return end
    if not v then
        Settings.AutoSellEggs = false
        if RuntimeStatus.refreshEggOverlapStatus then task.defer(RuntimeStatus.refreshEggOverlapStatus) end
        if not Settings.SellEggsWhenFull then setEggSellStatus("🔴 Off") end
        return
    end

    Settings.AutoSellEggs = false
    RuntimeStatus.eggSellerToggleWrite = true
    pcall(function() autoSellEggTgl:SetValue(false) end)
    RuntimeStatus.eggSellerToggleWrite = nil
    if RuntimeStatus.valueFilterLoadInProgress == true then return end
    if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
        setEggSellStatus("⏸️ Finish editing value")
        Library:Notify("Finish editing Minimum Value, then enable Auto-Sell Eggs again.", 4)
        return
    end
    local byCategory, byRarity, byMutation, byKG, byValue = sellEggFilterState()
    if not (byCategory or byRarity or byMutation or byKG or byValue) then
        setEggSellStatus("🟡 Pick a filter")
        return
    end
    if not SellNet then setEggSellStatus("🔴 Sell unavailable") return end
    RuntimeStatus.openSellConfirmation({
        Id = "ConfirmAutoSellEggs",
        Title = "Enable Egg Auto-Sell?",
        ConfirmText = "Enable Auto-Sell Eggs",
        Warning = "Turning this on repeatedly sells every current and future egg matching these filters. Sales are permanent. Placed, Auto-Place-reserved, and Rift-reserved eggs stay excluded.",
        GetSnapshot = function() return RuntimeStatus.eggSalePreviewSnapshot(nil) end,
        Validate = function()
            if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
                return false, "Minimum Value is still being edited; Auto-Sell Eggs remains off."
            end
            local c, r, m, k, value = sellEggFilterState()
            if not (c or r or m or k or value) then
                return false, "Choose at least one egg filter; Auto-Sell Eggs remains off."
            end
            return SellNet ~= nil, "Egg selling is unavailable in this client."
        end,
        OnConfirm = function(fresh)
            RuntimeStatus.eggSellerToggleWrite = true
            Settings.AutoSellEggs = true
            local wrote = pcall(function() autoSellEggTgl:SetValue(true) end)
            RuntimeStatus.eggSellerToggleWrite = nil
            if not wrote then
                Settings.AutoSellEggs = false
                setEggSellStatus("🔴 Auto-Sell Eggs stayed off")
                return
            end
            RuntimeStatus.markValueFilterChanged()
            if RuntimeStatus.refreshEggOverlapStatus then task.defer(RuntimeStatus.refreshEggOverlapStatus) end
            setEggSellStatus(("🟢 Armed · %d match"):format(fresh.TotalMatches or 0))
        end,
    })
end)

local sellEggsWhenFullTgl = EggSellBox:AddToggle("SellEggsWhenFullToggle", {
    Text = "Sell Full", Default = Settings.SellEggsWhenFull, Risky = true,
    Tooltip = "Only sell once egg inventory is full.",
})
sellEggsWhenFullTgl:OnChanged(function(v)
    if RuntimeStatus.eggSellerToggleWrite == true then return end
    if not v then
        Settings.SellEggsWhenFull = false
        if RuntimeStatus.refreshEggOverlapStatus then task.defer(RuntimeStatus.refreshEggOverlapStatus) end
        setEggSellStatus(Settings.AutoSellEggs and "🟢 Auto-Sell eggs armed" or "🔴 Off")
        return
    end

    Settings.SellEggsWhenFull = false
    RuntimeStatus.eggSellerToggleWrite = true
    pcall(function() sellEggsWhenFullTgl:SetValue(false) end)
    RuntimeStatus.eggSellerToggleWrite = nil
    if RuntimeStatus.valueFilterLoadInProgress == true then return end
    if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
        setEggSellStatus("⏸️ Finish editing value")
        Library:Notify("Finish editing Minimum Value, then enable Egg Sell Full again.", 4)
        return
    end
    local byCategory, byRarity, byMutation, byKG, byValue = sellEggFilterState()
    if not (byCategory or byRarity or byMutation or byKG or byValue) then
        setEggSellStatus("🟡 Pick a filter")
        return
    end
    if not SellNet then setEggSellStatus("🔴 Sell unavailable") return end
    RuntimeStatus.openSellConfirmation({
        Id = "ConfirmSellEggsWhenFull",
        Title = "Enable Egg Sell Full?",
        ConfirmText = "Enable Egg Sell Full",
        Warning = "When egg inventory becomes full, all matching eggs are submitted one at a time with a pause between confirmed sales. Each sale is permanent. Reserved and placed eggs remain excluded.",
        GetSnapshot = function() return RuntimeStatus.eggSalePreviewSnapshot(nil) end,
        Validate = function()
            if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
                return false, "Minimum Value is still being edited; Egg Sell Full remains off."
            end
            local c, r, m, k, value = sellEggFilterState()
            if not (c or r or m or k or value) then
                return false, "Choose at least one egg filter; Egg Sell Full remains off."
            end
            return SellNet ~= nil, "Egg selling is unavailable in this client."
        end,
        OnConfirm = function()
            RuntimeStatus.eggSellerToggleWrite = true
            Settings.SellEggsWhenFull = true
            local wrote = pcall(function() sellEggsWhenFullTgl:SetValue(true) end)
            RuntimeStatus.eggSellerToggleWrite = nil
            if not wrote then
                Settings.SellEggsWhenFull = false
                setEggSellStatus("🔴 Egg Sell Full stayed off")
                return
            end
            RuntimeStatus.markValueFilterChanged()
            if RuntimeStatus.refreshEggOverlapStatus then task.defer(RuntimeStatus.refreshEggOverlapStatus) end
            local _, count, capacity = RuntimeStatus.eggInventoryCapacityState()
            setEggSellStatus(("🟢 Watching · %d/%d"):format(count, capacity or 0))
        end,
    })
end)
if type(getgenv().__CHSAE_ConfigControllers) == "table" then
    getgenv().__CHSAE_ConfigControllers.AutoSellEggs = autoSellEggTgl
    getgenv().__CHSAE_ConfigControllers.SellEggsWhenFull = sellEggsWhenFullTgl
end

RuntimeStatus.disarmEggSellerForValueEdit = function()
    local wasEnabled = Settings.AutoSellEggs or Settings.SellEggsWhenFull
    RuntimeStatus.dismissSellConfirmation()
    pcall(function() autoSellEggTgl:SetValue(false) end)
    pcall(function() sellEggsWhenFullTgl:SetValue(false) end)
    Settings.AutoSellEggs = false
    Settings.SellEggsWhenFull = false
    if wasEnabled then
        setEggSellStatus("⏸️ Value changed · review and re-enable")
        pcall(function()
            Library:Notify("Egg selling paused. Review Minimum Value, then re-enable it.", 5)
        end)
    end
end

RuntimeStatus.disarmEggSellerForFilterEdit = function()
    if Settings.AutoSellEggs or Settings.SellEggsWhenFull then
        RuntimeStatus.dismissSellConfirmation()
        pcall(function() autoSellEggTgl:SetValue(false) end)
        pcall(function() sellEggsWhenFullTgl:SetValue(false) end)
        Settings.AutoSellEggs = false
        Settings.SellEggsWhenFull = false
        setEggSellStatus("⏸️ Filters changed · review and re-enable")
        pcall(function()
            Library:Notify("Egg selling paused because its filters changed. Review the new match list, then re-enable it.", 5)
        end)
    end
end

MakeButtonPanel(EggSellBox, "BtnSellEggsOnce", {
    { "🥚 Sell Eggs", function()
        if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
            setEggSellStatus("⏸️ Finish editing value")
            Library:Notify("Finish editing Minimum Value, then try again.", 4)
            return
        end
        local byCategory, byRarity, byMutation, byKG, byValue = sellEggFilterState()
        if not (byCategory or byRarity or byMutation or byKG or byValue) then
            setEggSellStatus("🟡 Pick a filter")
            return
        end
        if not SellNet then
            setEggSellStatus("🔴 Sell unavailable")
            Library:Notify("🥚 Egg selling is unavailable in this client.", 4)
            return
        end
        local matches = matchingSellEggs()
        if #matches == 0 then
            setEggSellStatus("🟢 0 match")
            return
        end
        RuntimeStatus.openSellConfirmation({
            Id = "ConfirmSellEggsOnce",
            Title = "Sell These Eggs?",
            ConfirmText = "Sell Selected Eggs",
            Warning = "All selected eggs will be submitted one at a time with a pause between confirmed sales. This cannot be undone. Only eggs selected at confirmation can be attempted.",
            GetSnapshot = function() return RuntimeStatus.eggSalePreviewSnapshot(nil) end,
            Validate = function(fresh)
                if not RuntimeStatus.sellerValueFilterReady("SellEggValueThreshold") then
                    return false, "Minimum Value is still being edited; nothing was sold."
                end
                local c, r, m, k, value = sellEggFilterState()
                if not (c or r or m or k or value) then
                    return false, "Choose at least one egg filter; nothing was sold."
                end
                if not SellNet then return false, "Egg selling is unavailable in this client." end
                return (fresh.Count or 0) > 0, "No eggs currently match; nothing was sold."
            end,
            OnConfirm = function(fresh)
                setEggSellStatus(("🟡 Selling once · %d reviewed"):format(fresh.Count or 0))
                task.spawn(function()
                    if not Arb.sellSerial(function()
                        local sold, earned, refused, reason = sellEggEntries(fresh.Entries or {}, nil, nil)
                        if reason then return end
                        setEggSellStatus(refused > 0
                            and ("🟡 Sold %d · %d not sold"):format(sold, refused)
                            or ("🟢 Sold %d · $%s"):format(sold, short(earned)))
                    end, "Selling eggs") then
                        setEggSellStatus("⏸️ Busy · try again")
                    end
                end)
            end,
        })
    end },
})

-- Auto-Equip-Best loop (interval-driven).
-- ARBITRATED (v0.9): equipping is remote-only (no character movement), so it
-- doesn't need the body — but it waits out a steal's carry/grab window and any
-- in-flight pen pass, and it can never overlap the manual "Equip Best" button.
-- Auto-Sell hooks in HERE when its arg is captured: sell FIRST, then re-equip
-- (so we never equip a pet we're about to sell), both inside the same
-- Arb.petsSerial slot.
task.spawn(function()
    local lastEquip, nextPetAttempt, nextEggAttempt = 0, 0, 0
    local petWorkPending = Settings.AutoSell
    local petFullDrain, eggFullDrain = false, false
    local lastPetEnabled = Settings.AutoSell or Settings.SellPetsWhenFull
    local lastEggEnabled = Settings.AutoSellEggs or Settings.SellEggsWhenFull
    while sessionAlive() do
        if RuntimeStatus.deferInventoryForBait() then task.wait(0.2); continue end
        local petEnabled = Settings.AutoSell or Settings.SellPetsWhenFull
        local eggEnabled = Settings.AutoSellEggs or Settings.SellEggsWhenFull
        if petEnabled ~= lastPetEnabled then
            lastPetEnabled = petEnabled
            petWorkPending = Settings.AutoSell
            if not Settings.SellPetsWhenFull then petFullDrain = false end
            nextPetAttempt = 0
        end
        if eggEnabled ~= lastEggEnabled then
            lastEggEnabled = eggEnabled
            if not Settings.SellEggsWhenFull then eggFullDrain = false end
            nextEggAttempt = 0
        end
        local petFull, petCount, petCapacity = false, 0, nil
        local eggFull, eggCount, eggCapacity = false, 0, nil
        if petEnabled then petFull, petCount, petCapacity = RuntimeStatus.petInventoryCapacityState() end
        if eggEnabled then eggFull, eggCount, eggCapacity = RuntimeStatus.eggInventoryCapacityState() end
        if Settings.SellPetsWhenFull and petFull then petFullDrain = true end
        if Settings.SellEggsWhenFull and eggFull then eggFullDrain = true end
        if not Settings.SellPetsWhenFull then petFullDrain = false end
        if not Settings.SellEggsWhenFull then eggFullDrain = false end
        local petSettingKey = Settings.AutoSell and "AutoSell"
            or (petFullDrain and "SellPetsWhenFull" or nil)
        local eggSettingKey = Settings.AutoSellEggs and "AutoSellEggs"
            or (eggFullDrain and "SellEggsWhenFull" or nil)
        if not eggSettingKey and (Settings.AutoSellEggs or Settings.SellEggsWhenFull)
            and type(RuntimeStatus.refreshEggOverlapStatus) == "function" then
            pcall(RuntimeStatus.refreshEggOverlapStatus)
        end
        local immediateDrain = false
        if Arb.quietOk() then
            -- Drain one bounded pet batch and one bounded egg batch per cycle.
            -- A clean successful batch schedules its successor after only one
            -- scheduler yield; refused/no-progress work gets a cooldown so the
            -- same replicated UID can never become a hot retry loop.
            if petSettingKey and SellNet
                and os.clock() >= nextPetAttempt then
                local ran, sold, hadMatches, refused = Arb.sellSerial(function()
                    return autoSellPass(petSettingKey)
                end, "Selling pets")
                if ran then
                    petWorkPending = hadMatches == true
                    if not hadMatches then petFullDrain = false end
                    sold, refused = tonumber(sold) or 0, tonumber(refused) or 0
                    if hadMatches and sold > 0 and refused == 0 then
                        immediateDrain = true
                    elseif hadMatches then
                        nextPetAttempt = os.clock() + 3
                    end
                end
            elseif Settings.SellPetsWhenFull and not petFullDrain then
                setSellStatus(("🟢 Watching · %d/%d"):format(petCount, petCapacity or 0))
            end
            if eggSettingKey and SellNet
                and os.clock() >= nextEggAttempt then
                local ran, sold, hadMatches, refused = Arb.sellSerial(function()
                    return autoSellEggPass(eggSettingKey)
                end, "Selling eggs")
                if ran then
                    if not hadMatches then eggFullDrain = false end
                    sold, refused = tonumber(sold) or 0, tonumber(refused) or 0
                    if hadMatches and sold > 0 and refused == 0 then
                        immediateDrain = true
                    elseif hadMatches then
                        nextEggAttempt = os.clock() + 3
                    end
                end
            elseif Settings.SellEggsWhenFull and not eggFullDrain then
                setEggSellStatus(("🟢 Watching · %d/%d"):format(eggCount, eggCapacity or 0))
            end
            if Settings.AutoEquipBest and NativeEquipRemote
                and RuntimeStatus.greatBloomUnlockProtectCranePets ~= true
                -- Equip Best can make a still-filtered pet unsellable, so pet work
                -- blocks it. Egg work is independent and must not suppress pet
                -- equipment forever after a refused/missing egg Tool.
                and not (SellNet and petSettingKey and petWorkPending)
                and os.clock() - lastEquip >= math.max(5, Settings.EquipInterval or 30) then
                if Arb.petsSerial(equipBestNow, "Equipping best pets") then lastEquip = os.clock() end
            end
        end
        if immediateDrain and Arb.quietOk() then
            task.wait()
        else
            -- Remain low-cost while idle, but wake immediately when Auto-Steal
            -- opens its potentially short outbound-only selling window.
            Arb.waitSeller((petEnabled or eggEnabled or Settings.AutoEquipBest) and 1 or 5)
        end
    end
end)
end -- scoped HOME/SELL helpers (keeps Luau below its 200-local register limit)

-- ════════════════════════════════════════════
-- [[ RIFT BOSS AND SHOP CONTROLLER ]] --
function RuntimeStatus.mergeBossSnapshot(current, incoming)
    local result = table.clone(incoming)
    -- A mid-fight state update may omit health. Preserve observed health only
    -- within the exact same open cycle, never across a close or a new boss.
    if current and incoming.Open == true and current.Open == true
        and incoming.OpensAt ~= nil and incoming.ClosesAt ~= nil
        and incoming.OpensAt == current.OpensAt and incoming.ClosesAt == current.ClosesAt then
        if result.BossHealth == nil then result.BossHealth = current.BossHealth end
        if result.BossMaxHealth == nil then result.BossMaxHealth = current.BossMaxHealth end
    end
    return result
end
function RuntimeStatus.CreateRiftBossShopController(deps)
    local self = { bossStatus = "Off", shopStatus = "Off", nextSwing = 0, nextEntry = 0,
        nextPurchase = 0, swings = 0, purchases = 0, entry = deps.loadRequest("entry"),
        purchase = deps.loadRequest("purchase"), cursor = nil, nextExit = 0,
        exiting = false, exitDeadline = 0, shopStaying = false, shopIdleAt = 0 }
    local function release()
        if deps.exitIntent then deps.exitIntent(false) end
        deps.wantBody(false)
        deps.releaseBody()
    end
    function self:ObserveBoss(snapshot, serverNow)
        if not snapshot then return self.bossDefeated == true end
        local cycle = tostring(snapshot.OpensAt) .. ":" .. tostring(snapshot.ClosesAt)
        if self.bossCycle ~= cycle then
            self.bossCycle, self.bossDefeated, self.nextExit = cycle, false, 0
            self.exiting, self.exitDeadline = false, 0
            self.shopStaying, self.shopIdleAt = false, 0
        end
        local health, maximum = tonumber(snapshot.BossHealth), tonumber(snapshot.BossMaxHealth)
        if health and health <= 0 and maximum and maximum > 0
            and serverNow >= (tonumber(snapshot.BossSpawnsAt) or 0) then
            self.bossDefeated = true
        end
        return self.bossDefeated == true
    end
    function self:BossReady(snapshot, serverNow, bossLive)
        if not snapshot or snapshot.Open ~= true then return false end
        local spawnAt, health = tonumber(snapshot.BossSpawnsAt), tonumber(snapshot.BossHealth)
        -- BossSpawnsAt is an optional countdown, not a permanent boss ID.
        -- Joining mid-fight must not require having observed its spawn packet.
        if snapshot.BossSpawnsAt ~= nil and (spawnAt == nil or spawnAt ~= spawnAt
            or spawnAt <= 0 or spawnAt >= math.huge or serverNow < spawnAt) then return false end
        if snapshot.BossHealth ~= nil then
            return health ~= nil and health == health and health > 0 and health < math.huge
        end
        -- Model evidence covers health packets not received yet. An explicit
        -- zero/dead health above always wins over a lingering boss model.
        return bossLive == true
    end
    function self:StopBoss()
        release()
        self.exiting, self.shopStaying = false, false
        self.bossStatus = self.entry and self.entry.inFlight and "Entry request finishing" or "Off"
    end
    function self:ResetCharacter(character)
        release()
        self.character, self.nextSwing, self.nextEntry = character, 0, 0
        self.stealIdleSince = nil
        self.exiting, self.shopStaying = false, false
        -- An outstanding InvokeServer must finish before another entry is sent.
        if self.entry and not self.entry.inFlight then
            self.entry = nil; deps.saveRequest("entry", nil)
        end
    end
    function self:LeaveArena(info)
        self.stealIdleSince = nil
        self.shopStaying = false
        self.exiting = info.inArena == true and info.alive == true
        if deps.exitIntent then deps.exitIntent(self.exiting) end
        if not self.exiting then release(); return end
        deps.wantBody(true)
        if not deps.acquireBody() then self.bossStatus = "Waiting to use the arena exit"; return end
        if info.ragdolled then deps.stopMovement(); self.bossStatus = "Recovering before arena exit"; return end
        local portal = deps.exitPortal()
        if not portal then deps.stopMovement(); self.bossStatus = "Waiting for arena leave Hitbox"; return end
        deps.moveTo(portal.position, info.character)
        self.bossStatus = "Leaving through the boss arena portal"
    end
    function self:StepBoss(settings, snapshot, info)
        local now = deps.now()
        if self.character ~= info.character then self:ResetCharacter(info.character) end
        local wasEnabled = self.bossEnabled
        self.bossEnabled = settings.AutoRiftBoss == true
        if info.inArena and ((not settings.AutoRiftBoss and (wasEnabled or self.exiting or info.exitRequested))
            or info.exitRequested) then
            self:LeaveArena(info); return
        end
        if not info.inArena and self.exiting then
            self.exiting = false
            if deps.exitIntent then deps.exitIntent(false) end
            release()
        end
        if not settings.AutoRiftBoss then self:StopBoss(); return end
        if not info.alive then
            self.nextSwing, self.nextEntry = 0, 0
            release(); self.bossStatus = "Waiting for respawn"; return
        end
        -- Pending selection survives the gap between two carried eggs. Never
        -- treat that brief gap as permission to enter the arena again.
        if info.stealPending then
            self.stealIdleSince = nil
            if info.inArena then self:LeaveArena(info)
            else release(); self.bossStatus = "Waiting for stealing to finish" end
            return
        end
        local defeated = self:ObserveBoss(snapshot, info.serverNow)
        if defeated then
            if not info.inArena then
                self.shopStaying = false; release()
                self.bossStatus = "Boss defeated · waiting for next rift"; return
            end
            local pending = self.purchase and self.purchase.inFlight
            if self.shopWork == true or pending then
                self.shopStaying, self.exiting = true, false
                if deps.exitIntent then deps.exitIntent(true) end
                deps.wantBody(true); deps.acquireBody(); deps.stopMovement()
                self.bossStatus = "Boss defeated · finishing selected shop purchases"
                return
            end
            self:LeaveArena(info); return
        end
        if info.inArena and snapshot and snapshot.Open ~= true then self:LeaveArena(info); return end
        if self.entry then
            local q = self.entry
            if q.inFlight then
                if not settings.AutoRiftBoss or info.protected then release() end
                self.bossStatus = "Waiting for arena entry"
                if settings.AutoRiftBoss and not info.protected then deps.wantBody(true); deps.acquireBody() end
                return
            end
            if q.character ~= info.character or info.inArena or now - q.finishedAt > 3 or q.accepted == false then
                self.entry = nil; deps.saveRequest("entry", nil); self.nextEntry = now + 3
                if q.accepted ~= true and not info.inArena then self.bossStatus = "Arena entry: " .. tostring(q.message or q.accepted) end
            else self.bossStatus = "Waiting for arena replication"; return end
        end
        if info.protected then release(); self.bossStatus = "Waiting for the current egg transaction"; return end
        if not info.eligible then release(); self.bossStatus = "Rift Boss is locked"; return end
        if not snapshot then release(); self.bossStatus = "Checking Rift Boss"; return end
        if not info.inArena and snapshot.Open ~= true then
            release()
            local remaining = math.max(0, math.ceil((tonumber(snapshot.OpensAt) or info.serverNow) - info.serverNow))
            self.bossStatus = ("Next boss in %d:%02d"):format(math.floor(remaining / 60), remaining % 60)
            return
        end
        if not info.inArena and not self:BossReady(snapshot, info.serverNow, info.bossLive) then
            release()
            self.bossStatus = "Waiting for boss spawn"
            return
        end
        if not info.inArena and info.stealingEnabled then
            self.stealIdleSince = self.stealIdleSince or now
            if now - self.stealIdleSince < 1 then
                release(); self.bossStatus = "Waiting for the steal queue to stay idle"; return
            end
        end
        deps.wantBody(true)
        if info.busy or not deps.acquireBody() then self.bossStatus = "Waiting for other automation"; return end
        if not info.inArena then
            if now < self.nextEntry then return end
            local q = { inFlight = true, started = now, character = info.character }
            self.entry = q; deps.saveRequest("entry", q)
            self.bossStatus = "Entering Rift Boss arena"
            deps.spawn(function()
                q.ok, q.accepted, q.message = pcall(deps.enterArena, q.character)
                q.finishedAt, q.inFlight = deps.now(), false
            end)
            return
        end
        if snapshot.Open ~= true then release(); self.bossStatus = "Waiting for the next boss"; return end
        if info.ragdolled then deps.stopMovement(); self.bossStatus = "Recovering from a hit"; return end
        if not info.bat then deps.stopMovement(); self.bossStatus = "A bat is needed to attack"; return end
        if not info.target then deps.stopMovement(); self.bossStatus = "Waiting for a vulnerable boss target"; return end
        if not deps.equipBat(info.bat, info.character) then self.bossStatus = "Equipping bat"; return end
        if info.target.distance > info.attackRange then
            deps.moveTo(info.target.position, info.character)
            self.bossStatus = "Approaching " .. info.target.name
            return
        end
        deps.stopMovement()
        if not info.batReady or now < self.nextSwing then self.bossStatus = "Attacking " .. info.target.name; return end
        -- Tool:Activate keeps the game's own equip, ragdoll, range and cooldown checks.
        local ok = deps.swing(info.bat, info.character)
        self.nextSwing = now + (ok and 0.15 or 0.35)
        if ok then self.swings += 1 end
        self.bossStatus = ok and ("Attacking " .. info.target.name) or "Waiting for the bat"
    end
    function self:ChooseProduct(settings, products, tokens)
        if type(tokens) ~= "number" or tokens ~= tokens or tokens < 0 then return nil end
        local start = 1
        for i, product in ipairs(products) do if product.id == self.cursor then start = i % #products + 1 break end end
        for offset = 0, #products - 1 do
            local product = products[(start + offset - 1) % #products + 1]
            if settings.RiftShopItems[product.id] == true and type(product.price) == "number"
                and product.price == product.price and product.price > 0 and product.price < math.huge
                and tokens >= product.price then return product end
        end
        return nil
    end
    function self:StepShop(settings, products, tokens, ready)
        local now = deps.now()
        local pending = self.purchase
        -- An unresolved response pauses spending for good; that is not work.
        local paused = pending ~= nil and not pending.inFlight
            and (not pending.ok or (pending.accepted ~= true and pending.accepted ~= false))
        self.shopWork = settings.AutoBuyRiftShop == true and not paused
            and (pending ~= nil or (ready == true and type(settings.RiftShopItems) == "table"
                and next(settings.RiftShopItems) ~= nil
                and self:ChooseProduct(settings, products, tokens) ~= nil))
        if self.purchase then
            local q = self.purchase
            if q.inFlight then self.shopStatus = "Buying " .. q.name; return end
            if not q.ok or (q.accepted ~= true and q.accepted ~= false) then
                -- A lost response can follow a completed debit. Keep this request
                -- across reloads; never spend tokens twice on an ambiguous result.
                self.shopStatus = "Purchase response unavailable · auto-buy paused"
                return
            end
            if q.ok and q.accepted == true then
                -- The remote acknowledgment proves purchase. Wait for the balance
                -- packet before using it to authorize another automatic purchase.
                if type(tokens) ~= "number" or tokens > q.beforeTokens - q.price then
                    self.shopStatus = "Purchased " .. q.name .. " · updating tokens"; return
                end
                self.purchases += 1
                self.shopStatus = "Purchased " .. q.name
            else
                self.shopStatus = "Shop: " .. tostring(q.message or q.accepted or "response unavailable")
            end
            self.cursor = q.id
            self.purchase = nil; deps.saveRequest("purchase", nil)
            self.nextPurchase = now + (q.ok and q.accepted == true and 2 or 5)
            return
        end
        if not settings.AutoBuyRiftShop then self.shopStatus = "Off"; return end
        if not next(settings.RiftShopItems) then self.shopStatus = "Choose shop items"; return end
        if not ready then self.shopStatus = "Waiting for shop data"; return end
        if now < self.nextPurchase then return end
        local product = self:ChooseProduct(settings, products, tokens)
        if not product then self.shopStatus = "Waiting for enough Boss Tokens"; return end
        -- Re-read price, listing, selection and balance immediately before sending.
        local current, balance = deps.validatePurchase(product.id)
        if not settings.AutoBuyRiftShop or settings.RiftShopItems[product.id] ~= true
            or not current or current.id ~= product.id or type(current.price) ~= "number"
            or current.price ~= current.price or current.price <= 0 or current.price >= math.huge
            or type(balance) ~= "number" or balance ~= balance or balance < current.price then return end
        local q = { id = current.id, name = current.name, price = current.price,
            beforeTokens = balance, inFlight = true, started = now }
        self.purchase = q; deps.saveRequest("purchase", q)
        self.shopStatus = "Buying " .. q.name
        deps.spawn(function()
            q.ok, q.accepted, q.message = pcall(deps.buyProduct, q.id)
            q.finishedAt, q.inFlight = deps.now(), false
        end)
    end
    function self:Destroy() self:StopBoss() end
    return self
end
-- [[ END RIFT BOSS AND SHOP CONTROLLER ]] --

-- [[ FUSE CONTROLLER ]] --
do
    function RuntimeStatus.createFuseController(d)
        local f = { owned = {}, pending = nil, status = "Off", completed = 0 }
        local function finite(value)
            return type(value) == "number" and value == value and value >= 0 and value < math.huge
        end
        function f.eligible(uid, raw, save, loaded)
            local s = d.settings
            if type(raw) ~= "table" or s.FuseCategories[raw.Category] ~= true then return false end
            if not finite(s.FuseMinimumValue) or not finite(s.FuseKGThreshold)
                or (s.FuseKGMode ~= "Any" and s.FuseKGMode ~= "Above" and s.FuseKGMode ~= "Below") then return false end
            if raw.IsFavorite == true or (raw.InFuse == true) ~= loaded then return false end
            for _, equipped in pairs(save.EquippedAssets or {}) do
                if tostring(equipped) == tostring(uid) then return false end
            end
            if d.protected(uid, save) then return false end
            local ok, allowed = pcall(d.mayEnter, uid, raw, nil, loaded)
            if not ok or allowed ~= true then return false end
            local decoded, item = pcall(d.decode, raw)
            if not decoded or type(item) ~= "table" then return false end
            if s.FuseKGMode ~= "Any" and s.FuseKGThreshold > 0 then
                local weight = d.weight(item)
                -- Unknown protected metrics are never eligible.
                if not finite(weight) or d.kgMatches(weight, s.FuseKGMode, s.FuseKGThreshold, true) then return false end
            end
            if s.FuseMinimumValue > 0 then
                local value, known = d.value(item)
                if not known or not finite(value) or value >= s.FuseMinimumValue then return false end
            end
            return true, item
        end
        function f.plan(save)
            if type(save) ~= "table" or type(save.Inventory) ~= "table"
                or type(save.FusionSlots) ~= "table" then return nil, "Waiting for fuse data" end
            local loaded, category, seen = {}, nil, {}
            for i = 1, 3 do
                local uid = save.FusionSlots[i]
                if uid then
                    if seen[uid] or not f.owned[uid] then return nil, "Machine has manually loaded pets" end
                    seen[uid] = true
                    local raw = save.Inventory[uid]
                    if not f.eligible(uid, raw, save, true) then return nil, "Returning a protected pet", uid end
                    if category and raw.Category ~= category then return nil, "Returning mismatched pet", uid end
                    category = raw.Category
                    loaded[#loaded + 1] = uid
                end
            end
            local groups = {}
            if category then groups[category] = table.clone(loaded) end
            for uid, raw in pairs(save.Inventory) do
                if not seen[uid] and (not category or raw.Category == category)
                    and f.eligible(uid, raw, save, false) then
                    groups[raw.Category] = groups[raw.Category] or {}
                    table.insert(groups[raw.Category], uid)
                end
            end
            local categories = {}
            for name, uids in pairs(groups) do if #uids >= 3 then categories[#categories + 1] = name end end
            table.sort(categories)
            if #categories == 0 then return nil, "Waiting for 3 eligible pets of one category" end
            local uids = groups[categories[1]]
            -- Keep loaded slots first, then choose deterministic exact UIDs.
            local remaining = {}
            for _, uid in ipairs(uids) do if not seen[uid] then remaining[#remaining + 1] = uid end end
            table.sort(remaining, function(a, b) return tostring(a) < tostring(b) end)
            local result = table.clone(loaded)
            for _, uid in ipairs(remaining) do if #result == 3 then break end; result[#result + 1] = uid end
            return { uids = result, loaded = #loaded, category = categories[1] }, "Ready"
        end
        function f.tick()
            if not d.alive() then return end
            if not d.idle() then f.status = "Waiting for idle time"; return end
            if not d.ready() then f.status = "Waiting for filter edits to finish"; return end
            local save = d.save()
            if type(save) ~= "table" or type(save.FusionSlots) ~= "table" then f.status = "Waiting for fuse data"; return end
            if f.pending then
                local p = f.pending
                local consumed = p.action == "BeginFuse" and p.uids ~= nil
                if consumed then
                    for _, uid in ipairs(p.uids) do if save.Inventory[uid] then consumed = false; break end end
                end
                local observed = p.action == "LoadPet" and save.Inventory[p.uid] and save.Inventory[p.uid].InFuse == true
                    or p.action == "EjectPet" and (not save.Inventory[p.uid] or not save.Inventory[p.uid].InFuse)
                    or p.action == "BeginFuse" and (save.FusionLocked == true or type(save.FusionEggReward) == "table" or consumed)
                    or p.action == "FinishReveal" and save.FusionEggReward == false
                if not observed and d.now() - p.at < 8 then f.status = "Waiting for machine confirmation"; return end
                if not observed then
                    -- An uncertain destructive request cannot be automatically retried.
                    d.disable(); f.status = "Machine confirmation timed out; Auto Fuse stopped"
                    f.pending = nil
                    return
                end
                f.pending = nil
            end
            if save.FusionEggReward ~= false and save.FusionEggReward ~= nil then
                if not d.settings.AutoFuse then f.status = "Reward waiting in machine"; return end
                if type(save.FusionEndsAt) == "number" and save.FusionEndsAt > d.serverNow() then
                    f.status = "Fusing"; return
                end
                f.status = "Claiming fused egg"
                f.pending = { action = "FinishReveal", at = d.now() }
                local accepted, reason = d.request("FinishReveal")
                if accepted == false then f.pending = nil; f.status = tostring(reason or "Reward not ready") end
                return
            end
            if save.FusionLocked == true then f.status = "Fusing"; return end
            local slotSet = {}
            for _, uid in pairs(save.FusionSlots) do if uid then slotSet[uid] = true end end
            for uid in pairs(f.owned) do if not slotSet[uid] then f.owned[uid] = nil end end
            local plan, reason, eject = f.plan(save)
            if not d.settings.AutoFuse then
                for uid in pairs(f.owned) do eject = uid; break end
                if not eject then f.status = "Off"; return end
            end
            if eject then
                f.status = "Returning protected/unused pet"
                f.pending = { action = "EjectPet", uid = eject, at = d.now() }
                local accepted, message = d.request("EjectPet", eject)
                if accepted == false then f.pending = nil; f.status = tostring(message or "Cannot return pet") end
                return
            end
            if not plan then f.status = reason; return end
            local full, _, capacity = d.capacity()
            if full or not capacity then f.status = "Waiting for egg inventory space"; return end
            local price = d.price(save, plan.uids)
            if not finite(price) or not finite(save.Money) or save.Money < price then
                f.status = "Waiting for fuse cost"; return
            end
            if not d.alive() or not d.settings.AutoFuse or not d.idle() or not d.ready() then return end
            if plan.loaded < 3 then
                local uid = plan.uids[plan.loaded + 1]
                -- Validate a fresh save immediately before each insertion.
                local latest = d.save()
                local checked = f.plan(latest)
                if not checked or checked.uids[checked.loaded + 1] ~= uid
                    or checked.loaded ~= plan.loaded then return end
                f.owned[uid] = true
                f.pending = { action = "LoadPet", uid = uid, at = d.now() }
                f.status = "Loading " .. plan.category .. " (" .. tostring(plan.loaded + 1) .. "/3)"
                local accepted, message = d.request("LoadPet", uid)
                if accepted == false then f.pending = nil; f.owned[uid] = nil; f.status = tostring(message or "Pet rejected") end
            else
                local latest = d.save()
                local checked = f.plan(latest)
                if not checked or checked.loaded ~= 3 or latest.FusionLocked ~= false
                    or latest.FusionEggReward ~= false then return end
                for i, uid in ipairs(plan.uids) do if checked.uids[i] ~= uid then return end end
                if not d.settings.AutoFuse or not d.idle() or not d.ready() then return end
                f.status = "Fusing " .. plan.category
                f.pending = { action = "BeginFuse", at = d.now(), uids = table.clone(plan.uids) }
                local accepted, message, reward = d.request("BeginFuse")
                if accepted == false then f.pending = nil; f.status = tostring(message or "Fuse rejected")
                elseif accepted == true then
                    f.completed += 1
                end
            end
        end
        return f
    end
end
-- [[ END FUSE CONTROLLER ]] --

