;(function()
    local box = Window.__FuseTab:AddLeftGroupbox("Auto Fuse")
    Window.__FuseBox = box
    local controller, label, toggle
    CHK.Merge(box, function()
        label = box:AddLabel("FuseStatus", { Text = "Off", DoesWrap = true })
    end)
    local function changed()
