        configKey = "FuseCategories", multi = true, store = Settings.FuseCategories,
        text = "Categories", displayMap = TargetCategoryData.Display,
        tooltip = "Fuse only these categories. Empty = nothing. Each fuse consumes 3 pets of the same category.",
        onChange = changed,
    })
    RuntimeStatus.addKGFilterControls(box, "Fuse", "FuseKGMode", "FuseKGThreshold", changed, true)
    RuntimeStatus.addValueFilterInput(box, "FuseMinimumValue", "FuseMinimumValue", "Prevent Minimum Value", changed,
        "Keep pets at this income per second and above. K, M, B, T work; 0 disables.")
    toggle = box:AddToggle("AutoFuseToggle", { Text = "Auto Fuse", Default = Settings.AutoFuse,
        Tooltip = "Fuse selected pets only while other automation is idle. Each fuse consumes 3 pets and charges the game's fuse price." })
    toggle:OnChanged(function(value) Settings.AutoFuse = value == true; configSave(true) end)
    getgenv().__CHSAE_ConfigControllers.AutoFuse = {
        GetValue = function() return Settings.AutoFuse end,
        SetValue = function(_, value) toggle:SetValue(value == true) end,
    }
    local Save, AssetItems, Kernel, Remotes
    local function modules()
        if Save and AssetItems and Kernel and Remotes then return true end
        return pcall(function()
            Save = require(ReplicatedStorage.Shared.Save)
            AssetItems = require(ReplicatedStorage.Shared.Util.AssetItems)
            Kernel = require(ReplicatedStorage.Shared.Util.FuseKernel)
            Remotes = require(ReplicatedStorage.Shared.Remotes).Fusery
            assert(Remotes.LoadPet and Remotes.BeginFuse and Remotes.FinishReveal and Remotes.EjectPet)
        end)
    end
    local function idle()
        return sessionAlive() and Arb.free() and not Arb.stealBusy() and not Arb.critical
            and not carrying and carriedAreaEgg() == nil and not RuntimeStatus.carryLossRecoveryPending()
            and not Arb.placeBusy and not Arb.hatchBusy and not Arb.treadmillTraining
            and not RuntimeStatus.hatchPetOutputPending and not RuntimeStatus.adminEventPending
            and not RuntimeStatus.riftWantsBody and not RuntimeStatus.greatBloomUnlockReturnPending
    end
    local function ready()
        local identity = type(getthreadidentity) == "function" and getthreadidentity() or nil
        if type(setthreadidentity) == "function" then pcall(setthreadidentity, 8) end
        local ok, result = pcall(RuntimeStatus.sellerValueFilterReady, "FuseMinimumValue")
        if identity and type(setthreadidentity) == "function" then pcall(setthreadidentity, identity) end
        return ok and result == true
    end
    controller = RuntimeStatus.createFuseController({
        settings = Settings, now = os.clock, serverNow = function() return workspace:GetServerTimeNow() end,
        alive = sessionAlive, idle = idle, ready = ready,
        save = function()
            local save = Save.Get()
            RuntimeStatus.reconcileNewPetUids(save)
            return save
        end,
        decode = function(raw) return AssetItems.Decode(raw) end,
        mayEnter = function(...) return Kernel.MayEnterFuse(...) end,
        weight = weightKg, kgMatches = RuntimeStatus.kgFilterMatches, value = valueScore,
        protected = function(uid, save)
            return RuntimeStatus.petSellUidProtected(uid, save, true)
                or (RuntimeStatus.greatBloomUnlockProtectCranePets == true and save.Inventory[uid].Category == "Crane")
        end,
        capacity = RuntimeStatus.eggInventoryCapacityState,
        price = function(save, uids)
            local items = {}
            for _, uid in ipairs(uids) do items[#items + 1] = AssetItems.Decode(save.Inventory[uid]) end
            return Kernel.PriceFor(items)
        end,
        disable = function() Settings.AutoFuse = false; pcall(function() toggle:SetValue(false) end); configSave(true) end,
        request = function(action, uid)
            local ok, accepted, reason, reward = pcall(function()
                if uid then return Remotes[action]:InvokeServer(uid) end
                return Remotes[action]:InvokeServer()
            end)
            if not ok then return nil, tostring(accepted) end -- retain pending state on uncertain delivery
            return accepted, reason, reward
        end,
    })
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.GetFuse = function()
            return { enabled = Settings.AutoFuse, status = controller.status, completed = controller.completed,
                pending = controller.pending and controller.pending.action }
        end
        getgenv().__CHSAE_Debug.PreviewFuse = function()
            if not modules() then return { reason = "Fuse modules unavailable" } end
            local plan, reason = controller.plan(Save.Get())
            return { category = plan and plan.category, uids = plan and plan.uids, reason = reason }
        end
    end
    task.spawn(function()
        while sessionAlive() do
            local ok, err = pcall(function()
                if (Settings.AutoFuse or controller.pending) and modules() and not Arb.petsBusy and idle() then
                    Arb.petsSerial(function() controller.tick() end, "Auto Fuse")
                elseif Settings.AutoFuse then controller.status = "Waiting for idle time" end
            end)
            if not ok then controller.status = "Fuse paused: " .. tostring(err) end
            if sessionAlive() then pcall(RuntimeStatus.setLabel, label, controller.status) end
            task.wait(1)
        end
    end)
end)()
