        flowLabel = RiftBox:AddLabel("RiftFlowLabel", { Text = "🔴 Off", DoesWrap = true })
    end)
    local wake = Instance.new("BindableEvent")
    getgenv().__CHSAE_RiftWake = wake
    local function wakeWorker(reason)
