    -- [[ RIFT NORMAL TARGET CHECK ]] --
    local function normalStealTargetAvailable()
        if Settings.AutoSteal ~= true then return false end
        local index = RuntimeStatus.candidateIndex
        if not (index and type(index.entries) == "table") then return false end
        local function selected(values)
            for _, value in pairs(values) do if value then return true end end
            return false
        end
        local rf, cf, af = selected(Settings.TargetRarities), selected(Settings.TargetCategories), selected(Settings.TargetAreas)
        if not rf and not cf and not af and not Settings.TargetPriority
            and not RuntimeStatus.kgFilterActive(Settings.TargetKGMode, Settings.TargetKGThreshold)
            and not RuntimeStatus.valueFilterActive(Settings.TargetValueThreshold) then return false end
        for _, entry in ipairs(index.entries) do
            local raw, rarity = entry.rec, entry.rarity
            if raw and tostring(raw.State) == "Slot" and raw.BottomCFrame and rarity
                and not RuntimeStatus.isCaptureEventUid(raw.Uid)
                and areaAllowed(raw.AreaId)
                and not RuntimeStatus.riftTargetBlocked(raw.Uid)
                and (not rf or Settings.TargetRarities[tostring(rarity._id)] == true)
                and (not cf or Settings.TargetCategories[tostring(raw.AssetCategory)] == true)
                and (not af or Settings.TargetAreas[tostring(raw.AreaId)] == true)
                and RuntimeStatus.kgFilterMatches(entry.weight, Settings.TargetKGMode, Settings.TargetKGThreshold, entry.weightKnown)
                and RuntimeStatus.valueFilterMatches(entry.value, Settings.TargetValueThreshold, "atLeast", entry.valueKnown)
