        RuntimeStatus.adminEventActive = false
        ProgressionCtl.refreshEventPending()
    end
    local function resetIntent()
        RuntimeStatus.riftCollecting, RuntimeStatus.riftTargetUid = false, nil
        RuntimeStatus.riftPlacementWanted = false
        releaseBody()
    end
    local function petCandidates(save)
        local list, equipped = {}, {}
        for _, uid in pairs(save.EquippedAssets or {}) do equipped[tostring(uid)] = true end
        local held = RuntimeStatus.externallyHeldPetUid()
        for uid, raw in pairs(save.Inventory) do
            if not equipped[tostring(uid)] and tostring(uid) ~= tostring(held) then
                local nativeOk, allowed = pcall(FuseKernel.MayEnterRift, uid, raw)
                local decoded, item = pcall(AssetItems.Decode, raw)
                if nativeOk and allowed == true and decoded and type(item) == "table"
                    and item.IsFavorite ~= true and item.InFuse ~= true then
                    local value, known = RuntimeStatus.riftValueScore(item)
                    if Planner.ValueAllowed(value, known, Settings.RiftMinimumValue) then
                        list[#list + 1] = { uid = tostring(uid), category = item.Category, value = value,
                            waiting = os.clock() < (tonumber(RuntimeStatus.hatchProtectedPetUids[tostring(uid)]) or 0) }
                    end
                end
            end
        end
        return list
    end
    local function eggCandidates(save)
        local list, seen = {}, {}
        for uid, raw in pairs(save.EggInventory) do
            local ok, egg = pcall(EggRecords.Decode, raw)
            local decoded, item = pcall(EggRecords.ToAssetItemData, ok and egg or raw)
            local value, known = RuntimeStatus.riftValueScore(decoded and item or raw)
            if raw.IsFavorite ~= true and raw.InFuse ~= true
                and Planner.ValueAllowed(value, known, Settings.RiftMinimumValue) then
                local key = tostring(uid)
                seen[key] = true
                list[#list + 1] = { uid = key, category = decoded and item.Category or raw.AssetCategory or raw.Category,
                    value = value, placed = raw.Placement ~= nil }
