        for uid, handoff in pairs(RuntimeStatus.riftEggHandoffs) do
            if os.clock() - handoff.at > 10 then RuntimeStatus.riftEggHandoffs[uid] = nil
            elseif not seen[uid] then
                list[#list + 1] = { uid = uid, category = handoff.category, value = 0, placed = true }
            end
        end
        return list
    end
    local function updatePlan(save)
        plan = Planner.Plan(state, petCandidates(save), eggCandidates(save))
        RuntimeStatus.riftPlan = plan
        RuntimeStatus.riftReservedPets = plan and plan.pets or {}
        RuntimeStatus.riftReservedEggs = plan and plan.eggs or {}
        RuntimeStatus.riftInventoryCount = 0
        if plan then
            local lines = { "🌀 " .. tostring(state.BannerDisplayName or state.BannerId or "Rift") }
            for _, slot in ipairs(plan.slots) do
                local status = slot.petUid and (slot.waiting and "waiting for pet" or "ready")
                    or slot.eggUid and (slot.placed and "hatching" or "place egg") or "missing"
                lines[#lines + 1] = slot.category .. " · " .. status
                if slot.eggUid then RuntimeStatus.riftInventoryCount += 1 end
            end
            RuntimeStatus.setLabel(eventLabel, table.concat(lines, "\n"))
        end
    end
    local function fieldTarget()
        local best, distance, count = nil, math.huge, 0
        local root = getCharParts()
        for _, entry in ipairs(RuntimeStatus.candidateIndex and RuntimeStatus.candidateIndex.entries or {}) do
            local raw = entry.rec
            if raw and plan.missing[tostring(raw.AssetCategory)] and raw.BottomCFrame
                and tostring(raw.State) == "Slot" and areaAllowed(raw.AreaId)
                and not RuntimeStatus.isCaptureEventUid(raw.Uid)
                and not RuntimeStatus.riftTargetBlocked(raw.Uid)
                and Planner.ValueAllowed(entry.value, entry.valueKnown, Settings.RiftMinimumValue) then
                count += 1
                local d = root and (root.Position - raw.BottomCFrame.Position).Magnitude or 0
                if d < distance then best, distance = raw, d end
            end
        end
        RuntimeStatus.riftFieldCount = count
        return best
    end
    local function transaction()
        local q = getgenv().__CHSAE_RiftTransaction
        if type(q) == "table" and q.jobId ~= game.JobId then
            getgenv().__CHSAE_RiftTransaction = nil
            return nil
        end
        return type(q) == "table" and q or nil
    end
    local function reconcileRequest(save)
        local q = transaction()
        if not q then return false end
        Arb.petsBusy, Arb.remoteActivity = true, "Rift " .. tostring(q.action)
        RuntimeStatus.riftReservedPets = q.petSet or {}
        -- The request has already been dispatched. Let main Steal take the body
        -- while this worker retains the exact transaction and inventory lock.
        if Arb.owner == "AdminEvent" and not Arb.hold("AdminEvent") then releaseBody() end
        if q.inFlight then setFlow("⏳ Waiting for Rift server response"); return true end
        local fresh = state and stateAt >= (q.finishedAt or math.huge)
        local removed = true
        for uid in pairs(q.petSet or {}) do if save.Inventory[uid] then removed = false end end
        local newEgg = false
        for uid in pairs(save.EggInventory) do if not q.eggsBefore[uid] then newEgg = true break end end
        local verified = fresh and ((q.action == "trade" and removed and state.PendingReward)
            or (q.action == "claim" and not state.PendingReward and newEgg))
        local rejected = q.ok == true and q.accepted == false
        if verified or rejected then
            getgenv().__CHSAE_RiftTransaction = nil
            Arb.petsBusy, Arb.remoteActivity = false, nil
            releaseBody()
            nextActionAt = os.clock() + (rejected and 3 or 0.5)
            setFlow(verified and (q.action == "claim" and "✅ Rift egg claimed" or "✅ Pets submitted")
                or ("⏸️ Rift rejected: " .. tostring(q.message):sub(1, 110)))
            return true
        end
        setFlow("⏳ Verifying Rift " .. q.action .. " · waiting for inventory and reward state")
        return true
    end
    local function acquireBody()
        if protectedTransaction() or Arb.petsBusy or Arb.hatchBusy or Arb.placeBusy then return false end
        if Arb.owner == "AdminEvent" and not Arb.hold("AdminEvent") then
            releaseBody()
            return false
        end
        RuntimeStatus.riftWantsBody, RuntimeStatus.adminEventPending = true, true
        ProgressionCtl.refreshEventPending()
        ProgressionCtl.requestTreadmillExit()
        if ProgressionCtl.detectActiveTreadmill() ~= nil or not Arb.acquire("AdminEvent") then return false end
        RuntimeStatus.adminEventName, RuntimeStatus.adminEventActive = "Rift", true
        Arb.hold("AdminEvent")
        return true
    end
    local function beginRequest(action, save)
        if transaction() or os.clock() < nextActionAt
            or not valueReady() then return end
        -- Fresh native state and a fresh inventory are checked immediately before
        -- the sole atomic call. Refresh *before* taking the movement body: the
        -- old order reserved AdminEvent, dismounted the treadmill, then noticed
        -- this state was stale and returned. The next planner pass released the
        -- reservation, letting Auto Treadmill mount again and repeat that loop.
        if os.clock() - stateAt > 1.5 or stateRequest then
            refreshState()
            setFlow("Refreshing Rift state before submission")
            return
        end
        if not acquireBody() then return end
        save = saveNow()
        if not save or Settings.AutoRift ~= true then releaseBody(); return end
        local q = { jobId = game.JobId, action = action, inFlight = true, started = os.clock(),
            petSet = {}, uids = {}, eggsBefore = {} }
        for uid in pairs(save.EggInventory) do q.eggsBefore[uid] = true end
        if action == "trade" then
            local check = Planner.Plan(state, petCandidates(save), eggCandidates(save))
            if not check or not check.ready or check.signature ~= plan.signature or state.PendingReward then
                releaseBody(); return
            end
            for i, slot in ipairs(check.slots) do q.uids[i] = slot.petUid; q.petSet[slot.petUid] = true end
            RuntimeStatus.riftReservedPets = q.petSet
        elseif not state.PendingReward then releaseBody(); return end
        getgenv().__CHSAE_RiftTransaction = q
        Arb.petsBusy, Arb.remoteActivity = true, "Rift " .. action
        setFlow(action == "trade" and "Submitting three required pets" or "Claiming Rift egg")
        task.spawn(function()
            q.ok, q.accepted, q.message = pcall(function()
                if action == "trade" then return RiftRemotes.AskTradeIn:InvokeServer(q.uids) end
                return RiftRemotes.AskFinishReveal:InvokeServer()
            end)
            q.finishedAt, q.inFlight = os.clock(), false
            if sessionAlive() then refreshState(); wakeWorker("response") end
        end)
    end
    local function step()
        if not modules() then setFlow("Rift modules unavailable"); return end
        if os.clock() - stateAt > 3 then refreshState() end
        local save = saveNow()
        if not save then setFlow("Waiting for inventory"); return end
        if reconcileRequest(save) then
            if Arb.owner == "AdminEvent" then Arb.hold("AdminEvent") end
            return
        end
        local liveOk, live = pcall(Eligibility.IsFeatureLive)
        RuntimeStatus.riftActive = liveOk and live == true
        RuntimeStatus.adminEventStatus = RuntimeStatus.riftActive and "Rift is live" or "Rift is unavailable"
        if Settings.AutoRift ~= true then
            resetIntent()
            RuntimeStatus.riftReservedPets, RuntimeStatus.riftReservedEggs = {}, {}
            if state and Planner.Signature(state) then
                RuntimeStatus.setLabel(eventLabel, "🌀 " .. tostring(state.BannerDisplayName or state.BannerId)
                    .. "\n" .. table.concat(state.Requirements, "\n"))
            end
            setFlow("🔴 Off")
            return
        end
        if not state or os.clock() - stateAt > 10 then
            resetIntent(); setFlow(stateError and "Rift state unavailable" or "Checking Rift requirements"); return
        end
        if not RuntimeStatus.riftActive or state.Unlocked ~= true then
            resetIntent(); setFlow("Rift is closed or locked"); return
        end
        updatePlan(save)
        if not valueReady() then
            if not protectedTransaction() then resetIntent() end
            setFlow("Waiting for the protection value to finish editing")
            return
        end
        local normal = normalStealTargetAvailable()
        if not normal and RuntimeStatus.riftBossFirstActive() and not protectedTransaction() then
            resetIntent(); setFlow("Waiting for the boss event to finish"); return
        end
        -- PriorityEvent is retained for config compatibility. Eligible normal
        -- steals always win; Rift work resumes as soon as none are available.
        local action = Planner.Action(true, protectedTransaction(), normal, false, state.PendingReward, plan)
        RuntimeStatus.riftPriorityYield = action == "normal"
        if action == "transaction" then setFlow("Finishing the current steal"); return end
        resetIntent()
        if action == "normal" then setFlow("Normal steal has priority")
        elseif action == "trade" or action == "claim" then beginRequest(action, save)
        elseif action == "place" then
            RuntimeStatus.riftPlacementWanted = true
            if RuntimeStatus.wakeRiftPen then RuntimeStatus.wakeRiftPen("rift-place") end
            setFlow("Placing required eggs in your pen")
        elseif action == "collect" then
            local target = fieldTarget()
            if target then
                RuntimeStatus.riftCollecting, RuntimeStatus.riftTargetUid = true, tostring(target.Uid)
                setFlow(Settings.StealMovementType .. " · collecting " .. tostring(target.AssetCategory))
                if wakeEggScanner then wakeEggScanner("rift-collect") end
            else setFlow("Waiting for a missing required egg to spawn") end
        elseif action == "hatch" then
            if RuntimeStatus.wakeRiftPen then RuntimeStatus.wakeRiftPen("rift-hatch") end
            setFlow("Waiting for required pets to hatch")
        else setFlow("Waiting for three Rift requirements") end
    end
    RuntimeStatus.addValueFilterInput(RiftBox, "RiftMinimumValue", "RiftMinimumValue", "Protect Minimum Value", function()
        wakeWorker("protection")
    end)
    local toggle = RiftBox:AddToggle("AutoRiftToggle", {
        Text = "Auto Rift", Default = Settings.AutoRift,
        Tooltip = "Use the selected Movement Type to collect missing eggs, return using its saved Tween Speed to claim, hatch the pets, then trade and claim the Rift reward.",
    })
    toggle:OnChanged(function(value)
        Settings.AutoRift = value == true
        if not value then
            RuntimeStatus.riftCollecting = false
            RuntimeStatus.riftPlacementWanted = false
            if not transaction() then resetIntent() end
        end
        configSave(true); wakeWorker("toggle")
        if wakeEggScanner then wakeEggScanner("rift-toggle") end
    end)
    Settings.PriorityEvent = false -- retired override, accepted in old profiles
    RiftBox:AddLabel("Priority: Main Steal → Boss → Pet Submission")
    getgenv().__CHSAE_ConfigControllers.AutoRift = toggle
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.GetRift = function()
            return { State = state, Plan = plan, Flow = RuntimeStatus.adminEventFlow,
                MinimumValue = Settings.RiftMinimumValue, PriorityEvent = Settings.PriorityEvent,
                Request = transaction(), Error = stateError }
