                productDisplay[row.id] = row.name .. " · " .. tostring(row.price) .. " tokens · " .. tostring(row.quantity)
            end
            local control = getgenv().__CHSAE_ConfigControllers.RiftShopItems
            if control then uiCall(function() control:SetItems(ids, true) end) end
        end
        return ids
    end
    modules()
    local initialIds = refreshCatalog()
    BindDropdownOverlay(shopBox, "RiftShopDropdown", "Items", initialIds, {
        configKey = "RiftShopItems", multi = true, store = Settings.RiftShopItems,
        text = "Items", tooltip = "Buy the selected items with Boss Tokens. Selected items take turns when affordable.",
        displayMap = productDisplay, onChange = function() configSave(true) end,
    })
    local bossToggle = bossBox:AddToggle("AutoRiftBossToggle", {
        Text = "Auto Attack Rift Boss", Default = Settings.AutoRiftBoss,
        Tooltip = "Enter after the boss spawns, cruise 72 studs above the floor at up to 150 studs per second, keep approaching if the initial climb is blocked, and descend only within 12 horizontal studs of a vulnerable attack target, resume after respawn, and leave through the arena portal after victory once Auto Buy has nothing left to buy.",
    })
    bossToggle:OnChanged(function(value)
        Settings.AutoRiftBoss = value == true
        if value then nextSnapshot = 0 end
        if not value then controller:StopBoss(); RuntimeStatus.riftBossFirstHold = false end
        configSave(true)
        if wakeEggScanner then wakeEggScanner("rift-boss-toggle") end
    end)
    Settings.RiftBossFirst = false -- retired override, accepted in old profiles
    local shopToggle = shopBox:AddToggle("AutoBuyRiftShopToggle", {
        Text = "Auto Buy", Default = Settings.AutoBuyRiftShop,
        Tooltip = "Repeatedly buy selected items while you have enough Boss Tokens.",
    })
    shopToggle:OnChanged(function(value) Settings.AutoBuyRiftShop = value == true; configSave(true) end)
    getgenv().__CHSAE_ConfigControllers.AutoRiftBoss = bossToggle
    getgenv().__CHSAE_ConfigControllers.AutoBuyRiftShop = shopToggle
    RuntimeStatus.riftBossController = controller
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.GetRiftBossShop = function()
            return { Boss = controller.bossStatus, Shop = controller.shopStatus, Snapshot = snapshot,
                Swings = controller.swings, Purchases = controller.purchases, Products = products,
                BossLive = select(2, activeBoss()) ~= nil, SnapshotAge = os.clock() - snapshotAt,
                Entry = controller.entry, Purchase = controller.purchase, Elevating = elevation.support ~= nil,
                Exiting = controller.exiting, ExitPortal = arenaExitPortal() ~= nil,
                ShopStaying = controller.shopStaying, ShopWork = controller.shopWork,
                BossFirst = Settings.RiftBossFirst, BossFirstHold = RuntimeStatus.riftBossFirstActive(),
                ExitRequested = RuntimeStatus.bossArenaExitRequested, PortalHandoff = RuntimeStatus.bossArenaExiting,
                Flying = elevation.support ~= nil, FlightHeight = elevation.height, FlightSpeed = 150,
                FlightReason = elevation.reason, FlightDestination = flightDestination,
                TakingOff = flightRoot ~= nil and not flightLifted, CruiseHeight = bossCruiseHeight,
                Mastery = masteryClaim.status, MasteryClaims = masteryClaim.claims }
        end
    end
    task.spawn(function()
        while sessionAlive() do
            local ok, err = pcall(function()
                if not modules() then elevation:Stop(); controller.bossStatus="Boss data unavailable"; controller.shopStatus="Shop data unavailable"; return end
                if not healthBound then
                    healthBound = true
                    local function observeHealth(health, maximum)
                        if not sessionAlive() or not snapshot or snapshot.Open ~= true then return end
                        snapshot = table.clone(snapshot)
                        snapshot.BossHealth, snapshot.BossMaxHealth = health, maximum
                    snapshotAt = os.clock()
                    bossStateRevision += 1
                        if controller:ObserveBoss(snapshot, workspace:GetServerTimeNow()) then
                            stopMovement()
                        end
                    end
                    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] =
                        Remotes.BossEvent.HealthShifted.OnClientEvent:Connect(observeHealth)
                    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] =
                        Remotes.BossEvent.StateShifted.OnClientEvent:Connect(function(result)
                            if not sessionAlive() then return end
                            if not acceptBossSnapshot(result) then bossStateRevision += 1 end
                            nextSnapshot = 0
                        end)
                end
                refreshSnapshot()
                if os.clock() >= catalogAt then catalogAt=os.clock()+5; refreshCatalog() end
                local save = saveNow()
                local root, humanoid = getCharParts()
                local character = LocalPlayer.Character
                if observedCharacter ~= character then
                    controller:ResetCharacter(character)
                    observedCharacter = character
                    snapshot, snapshotAt, nextSnapshot, snapshotRequest = nil, 0, 0, nil
                    RuntimeStatus.bossArenaExiting, RuntimeStatus.bossArenaExitRequested = false, false
                    RuntimeStatus.bossArenaIdle, RuntimeStatus.riftBossFirstHold = false, false
                end
                local alive = root ~= nil and humanoid ~= nil and humanoid.Health > 0
                local inArena = insideArena(root)
                local ragdolled = character ~= nil and Ragdoll.IsRagdolled(character)
                if not inArena then
                    RuntimeStatus.bossArenaExiting, RuntimeStatus.bossArenaExitRequested = false, false
                end
                controller:ObserveBoss(snapshot, workspace:GetServerTimeNow())
                RuntimeStatus.riftBossFirstBeat = os.clock()
                RuntimeStatus.riftBossFirstHold = Settings.AutoRiftBoss == true and alive
                    and not controller.bossDefeated and save ~= nil
                    and Eligibility.IsFeatureLive() and Eligibility.IsEligible(save.SpeedPower)
                    and (inArena or (snapshot ~= nil and os.clock()-snapshotAt < 10
                        and controller:BossReady(snapshot, workspace:GetServerTimeNow(), select(2, activeBoss()) ~= nil)))
                controller:StepShop(Settings, products, save and save.BossTokens, save ~= nil)
                RuntimeStatus.bossArenaIdle = controller.bossDefeated and controller.shopWork ~= true
                local bat = alive and findBat(character) or nil
                local info = { alive = alive, character = character, inArena = inArena,
                    bossLive = select(2, activeBoss()) ~= nil,
                    protected = protectedTransaction(), busy = Arb.petsBusy or Arb.hatchBusy or Arb.placeBusy,
                    stealPending = higherPriorityPending(),
                    stealingEnabled = Settings.AutoSteal == true or Settings.AutoRift == true,
                    eligible = save ~= nil and Eligibility.IsFeatureLive() and Eligibility.IsEligible(save.SpeedPower),
                    serverNow = workspace:GetServerTimeNow(), bat = bat,
                    ragdolled = ragdolled, exitRequested = RuntimeStatus.bossArenaExitRequested == true,
                    batReady = bat ~= nil and bat:GetAttribute("CooldownActive") ~= true
                        and (tonumber(bat:GetAttribute("CooldownEndTime")) or 0) <= workspace:GetServerTimeNow()
                        and not ragdolled,
                    attackRange = math.max(1, (tonumber(BatConfig.Range) or 15) - 2),
                    target = Settings.AutoRiftBoss and alive and inArena and bossTarget(root) or nil }
                controller:StepBoss(Settings, os.clock()-snapshotAt < 10 and snapshot or nil, info)
                stepBossFlight()
                masteryClaim:Step(Settings.AutoClaimBossMastery,
                    save and Eligibility.IsFeatureLive() and Eligibility.IsEligible(save.SpeedPower) and save or nil)
                RuntimeStatus.setLabel(masteryLabel,masteryClaim.status)
                RuntimeStatus.setLabel(bossLabel, controller.bossStatus)
                RuntimeStatus.setLabel(shopLabel, controller.shopStatus)
                RuntimeStatus.setLabel(balanceLabel, "Boss Tokens: " .. tostring(save and save.BossTokens or "checking"))
            end)
            if not ok then
                controller:StopBoss(); RuntimeStatus.riftBossFirstHold = false
                controller.bossStatus="Boss paused: " .. tostring(err):sub(1,100)
                RuntimeStatus.setLabel(bossLabel, controller.bossStatus)
            end
            task.wait(Settings.AutoRiftBoss and 0.1 or 0.25)
        end
        controller:Destroy()
        RuntimeStatus.riftBossFirstHold = false
        RuntimeStatus.bossArenaExiting, RuntimeStatus.bossArenaExitRequested = false, false
    end)
end)() -- Rift Boss and Rift Shop

-- [[ SERVER BROWSER CONTROLLER ]] --
function RuntimeStatus.createServerBrowser(d)
    local c = { rows = {}, selected = nil, busy = false, revision = 0,
        status = "Enable Find Server or press Refresh", lastSuccess = nil, nextRefresh = 0 }
    local function finite(n) return type(n) == "number" and n == n and n >= 0 and n < math.huge end
    function c:Cancel()
        self.revision += 1
        self.busy = false
        self.status = "Find Server off"
        d.render(self)
    end
    function c:Select(id)
        for _, row in ipairs(self.rows) do
            if row.id == id then self.selected = id; d.render(self); return true end
        end
        return false
    end
    function c:Refresh()
        if not d.alive() or self.busy or d.now() < self.nextRefresh then return false end
        self.revision += 1
        local revision = self.revision
        self.busy = true
        self.nextRefresh = d.now() + 10
        self.status = "Finding least-populated servers..."
        d.render(self)
        local function current() return d.alive() and self.revision == revision end
        d.delay(25, function()
            if current() and self.busy then
                self.revision += 1; self.busy = false; self.lastSuccess = nil
                self.nextRefresh = d.now() + 60
                self.status = "Request timed out. Try Refresh later."
                d.render(self)
            end
        end)
        local ok, result = pcall(function()
            local found, seen, cursors, cursor = {}, {}, {}, nil
            for _ = 1, 3 do
                local page = d.fetch(cursor)
                if not current() then return nil end
                assert(type(page) == "table" and type(page.data) == "table", "Invalid server response")
                for _, row in ipairs(page.data) do
                    if type(row) == "table" and type(row.id) == "string" and row.id ~= ""
                        and row.id ~= d.jobId and not seen[row.id]
                        and finite(row.playing) and finite(row.maxPlayers)
                        and row.playing % 1 == 0 and row.maxPlayers % 1 == 0
                        and row.playing < row.maxPlayers then
                        seen[row.id] = true
                        found[#found + 1] = { id = row.id, playing = row.playing, maxPlayers = row.maxPlayers,
                            ping = finite(row.ping) and row.ping or nil, fps = finite(row.fps) and row.fps or nil }
                    end
                end
                cursor = page.nextPageCursor
                if #found >= 20 or type(cursor) ~= "string" or cursor == "" or cursors[cursor] then break end
                cursors[cursor] = true
            end
            table.sort(found, function(a, b)
                if a.playing ~= b.playing then return a.playing < b.playing end
                if a.ping ~= b.ping then return (a.ping or math.huge) < (b.ping or math.huge) end
                return a.id < b.id
            end)
            while #found > 20 do table.remove(found) end
            return found
        end)
        if not current() then return false end
        self.busy = false
        self.nextRefresh = d.now() + (ok and 10 or 60)
        if not ok then
            self.lastSuccess = nil
            self.status = "Refresh failed: " .. tostring(result):gsub("^.-:%d+: ", ""):sub(1, 150)
            d.render(self)
            return false
        end
        self.rows, self.lastSuccess = result, d.now()
        local keep = false
        for _, row in ipairs(result) do if row.id == self.selected then keep = true; break end end
        if not keep then self.selected = result[1] and result[1].id or nil end
        self.status = #result > 0 and (tostring(#result) .. " servers found · Fewest players first")
            or "No available public servers. Try Refresh later."
        d.render(self)
        return true
    end
    function c:Hop()
        if self.busy then return false, "Wait for the server refresh" end
        if not self.lastSuccess or d.now() - self.lastSuccess > 90 then return false, "Refresh the server list first" end
        for _, row in ipairs(self.rows) do
            if row.id == self.selected and row.id ~= d.jobId and row.playing < row.maxPlayers then
                return d.teleport(row.id)
            end
        end
        return false, "No available server selected"
    end
    return c
end
-- [[ END SERVER BROWSER CONTROLLER ]] --

-- [[ SERVER TAB ]] --
;(function()
    local controls = Window.__ServerTab:AddLeftGroupbox("Server Controls")
    local results = Window.__ServerTab:AddRightGroupbox("Available Servers")
    Window.__ServerControlsBox, Window.__ServerResultsBox = controls, results
    local status
    CHK.Merge(controls, function()
        status = controls:AddLabel("ServerSearchStatus", { Text = "Enable Find Server or press Refresh", DoesWrap = true })
    end)
    local toggle = controls:AddToggle("FindServerToggle", { Text = "Find Server", Default = Settings.FindServer,
        Tooltip = "Find low-player public servers now and refresh every 60 seconds." })
    local browser, render
    MakeButtonPanel(controls, "ServerBrowserButtons", {
        { "Refresh", function()
            task.spawn(function()
                if not browser:Refresh() and sessionAlive() then Library:Notify(browser.status, 4) end
            end)
        end },
        { "Server Hop", function()
            local ok, message = browser:Hop()
            if not ok then Library:Notify(message or "Unable to hop", 4) end
        end },
    })
    local list = Instance.new("ScrollingFrame")
    list.Name = "CloverServerList"
    list.BackgroundTransparency = 1
    list.BorderSizePixel = 0
    list.Size = UDim2.new(1, 0, 0, 340)
    list.CanvasSize = UDim2.fromOffset(0, 0)
    list.ScrollBarThickness = 4
    list.ScrollingDirection = Enum.ScrollingDirection.Y
    results:AddUIPassthrough("ServerListPanel", { Instance = list, Height = 340 })
    local empty = Instance.new("TextLabel")
    empty.Name = "EmptyServerList"
    empty.BackgroundTransparency = 1
    empty.Size = UDim2.new(1, -8, 0, 50)
    empty.Text = "No servers loaded"
    empty.TextColor3 = Color3.fromRGB(165, 165, 165)
    empty.Font = Enum.Font.GothamSemibold
    empty.TextSize = 12
    empty.Parent = list
    local buttons = {}
    for i = 1, 20 do
        local button = Instance.new("TextButton")
        button.Name = "ServerRow" .. i
        button.Size = UDim2.new(1, -10, 0, 50)
        button.Position = UDim2.fromOffset(1, 1 + (i - 1) * 54)
        button.BackgroundColor3 = Color3.fromRGB(32, 32, 32)
        button.BorderSizePixel = 0
        -- Match VoidHub(GAG2)'s Buy List / Wild Pet list typography.
        button.TextColor3 = Color3.fromRGB(165, 165, 165)
        button.Font = Enum.Font.GothamSemibold
        button.TextSize = 12
        button.TextWrapped = true
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Visible = false
        local padding = Instance.new("UIPadding")
        padding.PaddingLeft = UDim.new(0, 8); padding.PaddingRight = UDim.new(0, 6); padding.Parent = button
        local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(0, 6); corner.Parent = button
        local stroke = Instance.new("UIStroke")
        stroke.Color = Library.Scheme.OutlineColor
        stroke.Thickness = 1
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = button
        button.MouseButton1Click:Connect(function()
            local row = browser.rows[i]
            if row then browser:Select(row.id) end
        end)
        button.Parent = list
        buttons[i] = button
    end
    local function uiCall(fn)
        local identity = type(getthreadidentity) == "function" and getthreadidentity() or nil
        if type(setthreadidentity) == "function" then pcall(setthreadidentity, 8) end
        local ok, err = pcall(fn)
        if identity and type(setthreadidentity) == "function" then pcall(setthreadidentity, identity) end
        return ok, err
    end
    render = function(state)
        if not sessionAlive() then return end
        uiCall(function()
            -- SetText updates wrapping height when an error replaces a short status.
            status:SetText(state.status)
            empty.Visible = #state.rows == 0
            for i, button in ipairs(buttons) do
                local row = state.rows[i]
                button.Visible = row ~= nil
                if row then
                    local selected = row.id == state.selected
                    button.BackgroundColor3 = selected and Color3.fromRGB(45, 55, 45) or Color3.fromRGB(32, 32, 32)
                    local stroke = button:FindFirstChildOfClass("UIStroke")
                    if stroke then stroke.Color = selected and Color3.fromRGB(0, 180, 100) or Library.Scheme.OutlineColor end
                    button.Text = string.format("%s%d / %d players\n%s ms · %s FPS",
                        selected and "✓ " or "", row.playing, row.maxPlayers,
                        row.ping and tostring(math.floor(row.ping)) or "—",
                        row.fps and string.format("%.0f", row.fps) or "—")
                end
            end
            list.CanvasSize = UDim2.fromOffset(0, #state.rows * 54)
        end)
    end
    local function failHop(message, attempt)
        if not RuntimeStatus.serverHopPending or (attempt and RuntimeStatus.serverHopPending ~= attempt) then return end
        RuntimeStatus.serverHopPending = nil
        RuntimeStatus.intentionalDisconnectUntil = 0
        RuntimeStatus.intentionalDisconnectReason = nil
        browser.lastSuccess = nil
        browser.status = "Hop failed: " .. tostring(message) .. ". Refresh to try again."
        render(browser)
    end
    browser = RuntimeStatus.createServerBrowser({
        alive = sessionAlive, now = os.clock, delay = task.delay, jobId = game.JobId, render = render,
        fetch = function(cursor)
            local requester = (syn and syn.request) or (http and http.request) or http_request or request
            assert(type(requester) == "function", "HTTP request unavailable")
            local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId)
                .. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100"
            if cursor then url ..= "&cursor=" .. HttpService:UrlEncode(cursor) end
            local response = requester({ Url = url, Method = "GET", Timeout = 20 })
            assert(type(response) == "table", "Invalid HTTP response")
            local code = tonumber(response.StatusCode or response.status_code or response.Status)
            if code == 429 then error("Roblox rate limit. Wait 60 seconds", 0) end
            assert(code and code >= 200 and code < 300, "HTTP " .. tostring(code or "failed"))
            return HttpService:JSONDecode(response.Body or response.body or "")
        end,
        teleport = function(id)
            if RuntimeStatus.sameServerRejoinPending or RuntimeStatus.serverHopPending then
                return false, "A teleport is already pending"
            end
            local attempt = {}
            RuntimeStatus.serverHopPending = attempt
            RuntimeStatus.intentionalDisconnectUntil = os.clock() + 45
            RuntimeStatus.intentionalDisconnectReason = "Server hop"
            browser.status = "Joining selected server..."
            render(browser)
            task.spawn(function()
                local ok, err = pcall(TeleportService.TeleportToPlaceInstance, TeleportService, game.PlaceId, id, LocalPlayer)
                if not ok and sessionAlive() then failHop(err, attempt) end
            end)
            task.delay(45, function() if sessionAlive() then failHop("Teleport timed out", attempt) end end)
            return true
        end,
    })
    getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1] = TeleportService.TeleportInitFailed:Connect(
        function(player, _, message, placeId)
            if sessionAlive() and player == LocalPlayer and placeId == game.PlaceId then failHop(message) end
        end)
    local nextAuto = 0
    toggle:OnChanged(function(value)
        Settings.FindServer = value == true
        configSave(true)
        if not value then browser:Cancel() else
            nextAuto = os.clock() + 60
            task.spawn(function() browser:Refresh() end)
        end
    end)
    getgenv().__CHSAE_ConfigControllers.FindServer = toggle
    local debug = getgenv().__CHSAE_Debug
    if debug then
        debug.GetServerBrowser = function()
            local rows = {}; for i, row in ipairs(browser.rows) do rows[i] = table.clone(row) end
            return { rows = rows, selected = browser.selected, status = browser.status, busy = browser.busy,
                enabled = Settings.FindServer, lastSuccess = browser.lastSuccess }
        end
        debug.RefreshServerBrowser = function() return browser:Refresh() end
    end
    task.spawn(function()
        while sessionAlive() do
            if Settings.FindServer and os.clock() >= nextAuto and os.clock() >= browser.nextRefresh
                and not RuntimeStatus.serverHopPending then
                browser:Refresh()
                nextAuto = os.clock() + 60
            elseif not Settings.FindServer then nextAuto = 0 end
            task.wait(1)
        end
        browser.revision += 1
    end)
end)() -- Server browser
-- [[ END SERVER TAB ]] --





-- ════════════════════════════════════════════
-- WEBHOOK TAB
-- ════════════════════════════════════════════
do
    local WebhookBox = Window.__WebhookTab:AddLeftGroupbox("🔗 Webhook")
    Window.__WebhookBox = WebhookBox
    local AlertsBox = Window.__WebhookTab:AddRightGroupbox("🔔 Alerts")
    Window.__WebhookAlertsBox = AlertsBox
    local webhookStatusLbl
    CHK.Merge(WebhookBox, function()
        webhookStatusLbl = WebhookBox:AddLabel("WebhookStatusLabel", {
            Text = "🔗 Paste a webhook URL", DoesWrap = true,
        })
    end)
    local function setWebhookStatus(text)
        RuntimeStatus.setLabel(webhookStatusLbl, text)
    end

    local function normalizeWebhookURL(value)
        local url = tostring(value or ""):gsub("[%c%s]", "")
        return url:gsub("^<", ""):gsub(">$", "")
    end
    local function validWebhookURL(url)
        return tostring(url):match("^https://[%w%.%-]+/api/webhooks/%d+/%S+$") ~= nil
    end

    local webhookInput
    local function currentWebhookURL()
        local value = Settings.WebhookURL
        pcall(function()
            if webhookInput and type(webhookInput.GetValue) == "function" then
                value = webhookInput:GetValue()
            elseif webhookInput and type(webhookInput.Value) == "string" then
                value = webhookInput.Value
            end
        end)
        Settings.WebhookURL = normalizeWebhookURL(value)
        return Settings.WebhookURL
    end

    webhookInput = WebhookBox:AddInput("WebhookURLInput", {
        Text = "URL",
        Default = Settings.WebhookURL,
        Placeholder = "https://discord.com/api/webhooks/...",
        Finished = false,
        Tooltip = "Paste your Discord webhook URL.",
    })
    webhookInput:OnChanged(function(value)
        Settings.WebhookURL = normalizeWebhookURL(value)
        setWebhookStatus(validWebhookURL(Settings.WebhookURL) and "🟢 URL ready" or "🔗 Paste a webhook URL")
    end)

    AlertsBox:AddToggle("WebhookStealsToggle", {
        Text = "Steal Alerts",
        Default = Settings.WebhookSteals,
        Tooltip = "Alert only for eggs claimed through Steal Filter. Event steals stay silent.",
    }):OnChanged(function(value) Settings.WebhookSteals = value end)
    AlertsBox:AddToggle("WebhookMutationsToggle", {
        Text = "Mutation Alerts",
        Default = Settings.WebhookMutations,
        Tooltip = "Send an alert after an egg mutation.",
    }):OnChanged(function(value) Settings.WebhookMutations = value end)
    AlertsBox:AddToggle("WebhookHatchesToggle", {
        Text = "Hatch Alerts",
        Default = Settings.WebhookHatches,
        Tooltip = "Send an alert after an egg hatches.",
    }):OnChanged(function(value) Settings.WebhookHatches = value end)
    AlertsBox:AddToggle("WebhookDisconnectsToggle", {
        Text = "Disconnect Alerts",
        Default = Settings.WebhookDisconnects,
        Tooltip = "Send an alert if this client disconnects.",
    }):OnChanged(function(value) Settings.WebhookDisconnects = value end)
    AlertsBox:AddToggle("WebhookInventoryFullToggle", {
        Text = "Inventory Full Alerts",
        Default = Settings.WebhookInventoryFull,
        Tooltip = "Alert when inventory stops Auto Steal.",
    }):OnChanged(function(value) Settings.WebhookInventoryFull = value end)

    local function alertEnabled(kind)
        if kind == "steal" then return Settings.WebhookSteals end
        if kind == "mutation" then return Settings.WebhookMutations end
        if kind == "hatch" then return Settings.WebhookHatches end
        if kind == "disconnect" then return Settings.WebhookDisconnects end
        if kind == "inventory-full" then return Settings.WebhookInventoryFull end
        return false
    end

    -- Discord cannot render Roblox's rbxassetid:// values or the retired
    -- asset-thumbnail redirect reliably. Resolve each icon once to the real
    -- official *.rbxcdn.com image URL that Discord's embed fetcher can download.
    local thumbnailCache = {}
    local ROBLOX_PLACEHOLDER_HASH = "e5bef3179d5ce82a42fdc8ddc83a2ba9"
    local function resolveWebhookThumbnail(icon, requester)
        local rawIcon = tostring(icon or "")
        if rawIcon:match("^https://[%w%-]+%.rbxcdn%.com/") then return rawIcon end

        local iconId = rawIcon:match("(%d+)")
        if not iconId or type(requester) ~= "function" then return nil end
        if thumbnailCache[iconId] then return thumbnailCache[iconId] end

        local endpoint = ("https://thumbnails.roblox.com/v1/assets?assetIds=%s&size=420x420&format=Png&isCircular=false")
            :format(iconId)
        for attempt = 1, 2 do
            local ok, response = pcall(requester, {
                Url = endpoint,
                Method = "GET",
                Headers = { ["Accept"] = "application/json" },
            })
            local statusCode = ok and type(response) == "table"
                and tonumber(response.StatusCode or response.Status) or nil
            local responseBody = ok and ((type(response) == "string" and response)
                or (type(response) == "table" and (response.Body or response.body))) or nil
            if statusCode and (statusCode < 200 or statusCode >= 300) then return nil end
            if type(responseBody) ~= "string" then return nil end

            local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, responseBody)
            local item = decodedOk and type(decoded) == "table"
                and type(decoded.data) == "table" and decoded.data[1] or nil
            local imageUrl = item and item.imageUrl
            if type(imageUrl) == "string" and imageUrl:find(ROBLOX_PLACEHOLDER_HASH, 1, true) then
                return nil -- restricted/new experience image; keep this alert text-only
            end
            if type(imageUrl) == "string" and imageUrl:match("^https://[%w%-]+%.rbxcdn%.com/") then
                thumbnailCache[iconId] = imageUrl
                return imageUrl
            end
            if not item or item.state ~= "Pending" or attempt == 2 then return nil end
            task.wait(0.2)
        end
        return nil
    end

    RuntimeStatus.sendWebhook = function(kind, title, description, color, force)
        if not force and not alertEnabled(kind) then return false end
        local url = currentWebhookURL()
        if not validWebhookURL(url) then
            setWebhookStatus("🟡 Add a valid URL")
            return false
        end
        local requester = (syn and syn.request)
            or (http and http.request) or http_request or request
        if type(requester) ~= "function" then
            setWebhookStatus("🔴 Request unavailable")
            return false
        end

        setWebhookStatus("🟡 Sending")
        local details = type(description) == "table" and description or nil
        local embedTitle = tostring(title or "CloverHub")
        local descriptionText = tostring(description or "")
        local fields = {}
        local thumbnail
        if details then
            local rarity = details.rarity
            if type(rarity) == "table" then rarity = rarity._id or rarity.Id or rarity.Name end
            local category = tostring(details.category or "Unknown Egg")
            local scale = tonumber(details.scale) or 1
            embedTitle = ("🥚 %s [%s] [%.2fx]"):format(category, tostring(rarity or "Unknown"), scale)
            descriptionText = ("By User: **%s**"):format(LocalPlayer.Name)

            local eggInfo = {
                "✨ Rarity: " .. tostring(rarity or "Unknown"),
                "🗺️ Area: " .. tostring(details.area or "Unknown"),
                "🧬 Mutations: " .. tostring(details.mutations or "None"),
            }
            local claimInfo = {
                "💰 Income: $" .. short(details.income or 0) .. "/s",
                "📏 Travel: " .. ("%.0f studs"):format(tonumber(details.distance) or 0),
                "📦 Session steals: " .. tostring(RuntimeStatus.steals or 0),
            }
            fields[#fields + 1] = {
                name = "📈 Egg info",
                value = "```\n" .. table.concat(eggInfo, "\n") .. "\n```",
                inline = false,
            }
            fields[#fields + 1] = {
                name = "📦 Claim status",
                value = "```\n" .. table.concat(claimInfo, "\n") .. "\n```",
                inline = false,
            }
            local imageUrl = resolveWebhookThumbnail(details.icon, requester)
            if imageUrl then thumbnail = { url = imageUrl } end
        elseif kind == "disconnect" then
            fields = {
                { name = "Player", value = LocalPlayer.Name, inline = true },
                { name = "Place", value = tostring(game.PlaceId), inline = true },
                { name = "Server", value = tostring(game.JobId), inline = false },
            }
        elseif kind == "inventory-full" then
            fields = {
                { name = "Player", value = LocalPlayer.Name, inline = true },
                { name = "Action", value = "Auto-Steal disabled", inline = true },
            }
        else
            fields = {
                { name = "Player", value = LocalPlayer.Name, inline = true },
                { name = "Status", value = tostring(kind or "test"), inline = true },
            }
        end
        local embed = {
            title = embedTitle,
            description = descriptionText,
            color = tonumber(color) or 0x49E685,
            fields = fields,
            footer = { text = "Steal an Egg · " .. RELEASE_VERSION },
            timestamp = DateTime.now():ToIsoDate(),
        }
        if thumbnail then embed.thumbnail = thumbnail end
        local payload = {
            username = "CloverHub",
            embeds = { embed },
        }
        local payloadJson = HttpService:JSONEncode(payload)
        local ok, response = pcall(requester, {
            Url = url,
            Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = payloadJson,
        })
        local statusCode = ok and type(response) == "table"
            and tonumber(response.StatusCode or response.Status) or nil
        local accepted = ok and statusCode and statusCode >= 200 and statusCode < 300
        setWebhookStatus(accepted and "🟢 Sent" or "🔴 Send failed")
        return accepted == true
    end

    -- A full inventory can be detected during autoload before the Webhook tab is
    -- constructed. Deliver that one queued alert now that the sender exists.
    if RuntimeStatus.pendingInventoryFullAlert then
        local pending = RuntimeStatus.pendingInventoryFullAlert
        RuntimeStatus.pendingInventoryFullAlert = nil
        task.defer(function()
            RuntimeStatus.sendWebhook("inventory-full", "Egg Inventory Full",
                ("Auto-Steal was turned off. Egg inventory: **%d / %d**.")
                    :format(tonumber(pending.count) or 0, tonumber(pending.capacity) or 0),
                0xF59E0B, false)
        end)
    end

    MakeButtonPanel(WebhookBox, "WebhookButtons", {
        { "📨 Send Test", function()
            currentWebhookURL()
            task.spawn(RuntimeStatus.sendWebhook, "test", "Test Message",
                "Your CloverHub webhook is connected.", 0x49E685, true)
        end },
    })
    setWebhookStatus(validWebhookURL(Settings.WebhookURL) and "🟢 URL ready" or "🔗 Paste a webhook URL")

    -- Fire once at the earliest reliable client-side disconnect signal. Executor
    -- HTTP remains independent from Roblox replication long enough for the POST;
    -- a one-shot guard prevents GuiService and NetworkClient from double-reporting.
    do
        local disconnectSent = false
        local function reportDisconnect(reason)
            if disconnectSent or not sessionAlive() or not Settings.WebhookDisconnects then return end
            if os.clock() < (tonumber(RuntimeStatus.intentionalDisconnectUntil) or 0) then
                return
            end
            disconnectSent = true
            local message = tostring(reason or "Connection closed")
            task.spawn(RuntimeStatus.sendWebhook, "disconnect", "Client Disconnected",
                message, 0xEF4444, false)
        end

        pcall(function()
            local guiService = game:GetService("GuiService")
            getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
                = guiService.ErrorMessageChanged:Connect(function(message)
                    message = tostring(message or guiService:GetErrorMessage() or "")
                    if message ~= "" then reportDisconnect(message) end
                end)
        end)
        pcall(function()
            local networkClient = game:GetService("NetworkClient")
            getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
                = networkClient.ChildRemoved:Connect(function(child)
                    if child:IsA("ClientReplicator") then
                        local reason = "Client connection closed"
                        pcall(function()
                            local message = game:GetService("GuiService"):GetErrorMessage()
                            if type(message) == "string" and message ~= "" then reason = message end
                        end)
                        reportDisconnect(reason)
                    end
                end)
        end)
    end
end

-- ════════════════════════════════════════════
-- SETTINGS TAB
-- ════════════════════════════════════════════
local PlayerModBox, PerformanceBox, OverlayBox, DevBox
do
-- One control edits the selected movement type's saved delivery speed.
PlayerModBox = SettingsTab:AddLeftGroupbox("⚙️ Movement")
do
    local function selectMovementType(value)
        local selected = value == "Tween" and "Tween" or "TP"
        local development = RuntimeStatus.DevChickenTween
        Settings.StealMovementType = selected
        Settings.StealSpeed = RuntimeStatus.getDeliverySpeed(selected)
        if RuntimeStatus.syncSpeedSlider then RuntimeStatus.syncSpeedSlider() end
        configSave(true)
        if development.enabled == (selected == "Tween") then return end
        if not development.setEnabled(selected == "Tween") then
            Library:Notify("Character restoration needs attention: " .. development.reason, 6)
        end
    end
    local movementDropdown = BindDropdownOverlay(PlayerModBox, "StealMovementTypeDropdown",
        "Movement Type", { "TP", "Tween" }, {
        configKey = "StealMovementType", multi = false, text = "Movement Type",
        tooltip = "TP teleports outbound; Tween tweens outbound. Return follows Method: Straight, Fly, or Turbo Hybrid guard evasion.",
        get = function() return Settings.StealMovementType end,
        set = selectMovementType,
    })
    RuntimeStatus.setStealMovementType = function(value) movementDropdown:SetValue(value) end
    RuntimeStatus.setDevelopmentChickenTween = function(value)
        movementDropdown:SetValue(value == true and "Tween" or "TP")
    end
    selectMovementType(Settings.StealMovementType)
    local burstToggle = PlayerModBox:AddToggle("BurstTweenToggle", {
        Text = "Burst Tween", Default = Settings.BurstTween,
        Tooltip = "Tween outbound only. On: start at 5000 studs/s, then approach at 500. Off: use Tween Speed throughout the trip to the egg. Applies to the next departure.",
    })
    burstToggle:OnChanged(function(value)
        Settings.BurstTween = value == true
        configSave(true)
    end)
    getgenv().__CHSAE_ConfigControllers.BurstTween = burstToggle
end

local ROUTE_ITEMS = { "Straight", "Fly", "Turbo Hybrid", "Default" }
local ROUTE_DM = {
    ["Fly"] = '<font color="#A78BFA"><b>Fly</b></font> <font color="#9AA0AA">raised return</font>',
    ["Turbo Hybrid"] = '<font color="#38BDF8"><b>Turbo Hybrid</b></font> <font color="#9AA0AA">guard-aware return</font>',
    ["Straight"] = '<font color="#E6A849"><b>Straight</b></font> <font color="#9AA0AA">direct</font>',
    ["Default"] = '<font color="#60A5FA"><b>Default</b></font> <font color="#9AA0AA">game speed</font>',
}
BindDropdownOverlay(PlayerModBox, "StealRouteDropdown", "Method", ROUTE_ITEMS, {
    configKey = "StealRoute",
    multi = false,
    text = "Method",
    tooltip = "Straight returns directly to TrackStart. Fly adds the upward lift and raised return for either movement type. Turbo Hybrid follows guard-aware wall lanes using the selected Tween Speed.",
    displayMap = ROUTE_DM,
    onChange = function() configSave(true) end,
    get = function() return Settings.StealRoute end,
    set = function(label)
        if label == "Y Level" then label = "Fly" end
        Settings.StealRoute = (label == "Turbo Hybrid"
            or label == "Straight" or label == "Fly" or label == "Default") and label or "Straight"
    end,
})

do
local stealSpeedSlider = CHK.Slider(PlayerModBox, "StealSpeedSlider", {
    Text     = "Tween Speed",
    Default  = Settings.StealSpeed,
    Min      = 100,
    Max      = 1000,
    Rounding = 0,
    Suffix   = " studs/s",
    Tooltip  = "Delivery/return speed for the selected Movement Type; also Tween outbound when Burst Tween is off. TP and Tween remember separate values.",
})
local stealSpeedInput = PlayerModBox:AddInput("StealSpeedInput", {
    Text = "Exact Tween Speed",
    Default = tostring(Settings.StealSpeed),
    Numeric = true,
    Finished = true,
    Tooltip = "Enter an exact speed from 100 to 1000 studs/s.",
})
local speedControlsSyncing = false
local function normalizedStealSpeed(value)
    return math.clamp(math.floor((tonumber(value) or tonumber(Settings.StealSpeed) or 800) + 0.5), 100, 1000)
end
local function syncSpeedControls(value, updateSetting)
    local speed = normalizedStealSpeed(value)
    if updateSetting then speed = RuntimeStatus.setDeliverySpeed(speed); configSave(true) end
    speedControlsSyncing = true
    stealSpeedSlider:SetValue(speed, true)
    pcall(stealSpeedInput.SetValue, stealSpeedInput, tostring(speed))
    speedControlsSyncing = false
    return speed
end
RuntimeStatus.syncSpeedSlider = function()
    -- Auxiliary auto-calibration must not overwrite the saved delivery value
    -- shown for the currently selected mode.
    Settings.StealSpeed = RuntimeStatus.getDeliverySpeed()
    syncSpeedControls(Settings.StealSpeed, false)
end
RuntimeStatus.syncSpeedSlider()
if type(getgenv().__CHSAE_ConfigControllers) == "table" then
    getgenv().__CHSAE_ConfigControllers.StealSpeed = {
        GetValue = function() return Settings.StealSpeed end,
        SetValue = function(_, value) syncSpeedControls(value, true) end,
    }
end
stealSpeedSlider:OnChanged(function(v)
    if speedControlsSyncing then return end
    syncSpeedControls(v, true)
    RuntimeStatus.getMovementSpeed()
    if type(RuntimeStatus.syncCalibrationStatus) == "function" then
        RuntimeStatus.syncCalibrationStatus()
    end
end)
stealSpeedInput:OnChanged(function(value)
    if speedControlsSyncing or tonumber(value) == nil then return end
    syncSpeedControls(value, true)
    RuntimeStatus.getMovementSpeed()
    if type(RuntimeStatus.syncCalibrationStatus) == "function" then
        RuntimeStatus.syncCalibrationStatus()
    end
end)

local autoCalibrateTgl = PlayerModBox:AddToggle("AutoCalibrateSpeedToggle", {
    Text = "Auto Calibrate",
    Default = Settings.AutoCalibrateSpeed,
    Tooltip = "Tune auxiliary registered movement from verified steals. Delivery uses the saved Tween Speed.",
})
autoCalibrateTgl:OnChanged(function(value)
    Settings.AutoCalibrateSpeed = value == true
    RuntimeStatus.syncSpeedSlider(RuntimeStatus.getMovementSpeed())
    if type(RuntimeStatus.syncCalibrationStatus) == "function" then
        RuntimeStatus.syncCalibrationStatus()
    end
    RuntimeStatus.wakeOverlay("speed-calibration")
end)

local calibrationStatusLbl
CHK.Merge(PlayerModBox, function()
    calibrationStatusLbl = PlayerModBox:AddLabel("SpeedCalibrationStatusLabel", {
        Text = "🧭 Auto Calibrate initializing", DoesWrap = true,
    })
end)
RuntimeStatus.syncCalibrationStatus = function()
    RuntimeStatus.setLabel(calibrationStatusLbl, RuntimeStatus.getCalibrationLabel())
end
RuntimeStatus.syncCalibrationStatus()

if type(getgenv().__CHSAE_ConfigControllers) == "table" then
    getgenv().__CHSAE_ConfigControllers.AutoCalibrateSpeed = autoCalibrateTgl
end
end

-- GAG2-style Zero Texture: floor render quality, hide textures/PBR surfaces,
-- force SmoothPlastic, and disable particles/post-FX/clouds/sky. The pass is
-- spread across frames and every changed property/reference is restored on OFF.
PerformanceBox = SettingsTab:AddRightGroupbox("⚡ Performance")
do
    local originals = setmetatable({}, { __mode = "k" })
    -- Detached visual-only objects must not be kept alive just so the toggle can
    -- restore them. Weak keys/values let thousands of SurfaceAppearances be
    -- collected under memory pressure; surviving objects are restored best-effort.
    local detached = setmetatable({}, { __mode = "kv" })
    local perfConns, generation, savedQuality = {}, 0, nil
    local reduceQueue, reduceQueueHead, reduceQueueTail = {}, 1, 0
    local queuedReduce = setmetatable({}, { __mode = "k" })
    local reduceWorkerRunning = false
    local BLOOM_TREE_TAG = "SakuraBloomTree"

    local function setReduced(instance, property, value)
        local state = originals[instance]
        if not state then state = {}; originals[instance] = state end
        if state[property] == nil then
            local ok, current = pcall(function() return instance[property] end)
            if not ok then return end
            state[property] = current
        end
        pcall(function() instance[property] = value end)
    end

    local function belongsToBloomTree(instance)
        local current = instance
        while current and current ~= workspace do
            if CollectionService:HasTag(current, BLOOM_TREE_TAG) then return true end
            current = current.Parent
        end
        return false
    end

    local function restoreReducedObject(instance)
        local parent = detached[instance]
        if parent then
            if instance.Parent == nil then pcall(function() instance.Parent = parent end) end
            detached[instance] = nil
        end
        local state = originals[instance]
        if state then
            if instance.Parent then
                for property, value in pairs(state) do
                    pcall(function() instance[property] = value end)
                end
            end
            originals[instance] = nil
        end
        queuedReduce[instance] = nil
    end

    local function preserveBloomTree(tree)
        if not (tree and tree:IsA("Model")) then return end
        restoreReducedObject(tree)
        for _, instance in ipairs(tree:GetDescendants()) do restoreReducedObject(instance) end

        -- SurfaceAppearances may have been detached during the short replication
        -- window before the tree's tag arrived, so they are no longer descendants.
        for instance, parent in pairs(detached) do
            local inside = false
            if parent then
                local ok, result = pcall(function()
                    return parent == tree or parent:IsDescendantOf(tree)
                end)
                inside = ok and result
            end
            if inside then restoreReducedObject(instance) end
        end
    end

    local function reduceObject(instance)
        -- Great Bloom trees are gameplay/event objects. They can already be tagged
        -- before the initial pass, so skip them here instead of restoring them only
        -- when a later tag-added signal happens to fire.
        if belongsToBloomTree(instance) then return end
        if instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam")
            or instance:IsA("Smoke") or instance:IsA("Fire") or instance:IsA("Sparkles")
            or instance:IsA("PostEffect") then
            setReduced(instance, "Enabled", false)
        elseif instance:IsA("Decal") or instance:IsA("Texture") then
            setReduced(instance, "Transparency", 1)
        elseif instance:IsA("SurfaceAppearance") or instance:IsA("Sky") then
            if instance.Parent and detached[instance] == nil then
                detached[instance] = instance.Parent
                instance.Parent = nil
            end
        elseif instance:IsA("BasePart") then
            setReduced(instance, "Material", Enum.Material.SmoothPlastic)
            setReduced(instance, "CastShadow", false)
            setReduced(instance, "Reflectance", 0)
        elseif instance:IsA("SpecialMesh") then
            setReduced(instance, "TextureId", "")
        elseif instance:IsA("Clouds") then
            setReduced(instance, "Enabled", false)
        end
    end

    local function queueReducedObject(instance, targetGeneration)
        if not instance or queuedReduce[instance] then return end
        queuedReduce[instance] = true
        reduceQueueTail += 1
        reduceQueue[reduceQueueTail] = { instance = instance, generation = targetGeneration }
        if reduceWorkerRunning then return end
        reduceWorkerRunning = true
        task.spawn(function()
            while sessionAlive() and reduceQueueHead <= reduceQueueTail do
                local stopAt = math.min(reduceQueueTail, reduceQueueHead + 199)
                while reduceQueueHead <= stopAt do
                    local item = reduceQueue[reduceQueueHead]
                    reduceQueue[reduceQueueHead] = nil
                    reduceQueueHead += 1
                    local object = item and item.instance
                    if object then queuedReduce[object] = nil end
                    if object and item.generation == generation and Settings.ExtremeFPS then
                        reduceObject(object)
                    end
                end
                RunService.Heartbeat:Wait()
            end
            table.clear(reduceQueue)
            reduceQueueHead, reduceQueueTail = 1, 0
            reduceWorkerRunning = false
        end)
    end

    local function restorePerformance()
        generation += 1
        table.clear(reduceQueue)
        table.clear(queuedReduce)
        reduceQueueHead, reduceQueueTail = 1, 0
        for _, conn in ipairs(perfConns) do pcall(function() conn:Disconnect() end) end
        table.clear(perfConns)
        for instance, parent in pairs(detached) do
            if instance and instance.Parent == nil and parent then
                pcall(function() instance.Parent = parent end)
            end
            detached[instance] = nil
        end
        for instance, state in pairs(originals) do
            if instance and instance.Parent then
                for property, value in pairs(state) do
                    pcall(function() instance[property] = value end)
                end
            end
            originals[instance] = nil
        end
        if savedQuality then
            pcall(function() settings().Rendering.QualityLevel = savedQuality end)
            savedQuality = nil
        end
    end
    getgenv().__CHSAE_PerfRestore = restorePerformance

    local function enablePerformance()
        restorePerformance()
        generation += 1
        local myGeneration = generation
        local Lighting = game:GetService("Lighting")
        perfConns[#perfConns + 1] = CollectionService:GetInstanceAddedSignal(BLOOM_TREE_TAG):Connect(function(tree)
            if Settings.ExtremeFPS and generation == myGeneration then preserveBloomTree(tree) end
        end)
        for _, tree in ipairs(CollectionService:GetTagged(BLOOM_TREE_TAG)) do preserveBloomTree(tree) end
        pcall(function()
            savedQuality = settings().Rendering.QualityLevel
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
        end)

        -- Install streaming listeners before the initial scan. Objects that arrive
        -- during that scan are queued immediately instead of escaping reduction
        -- until the next full toggle cycle.
        perfConns[#perfConns + 1] = workspace.DescendantAdded:Connect(function(instance)
            if Settings.ExtremeFPS then queueReducedObject(instance, myGeneration) end
        end)
        perfConns[#perfConns + 1] = Lighting.ChildAdded:Connect(function(instance)
            if Settings.ExtremeFPS then queueReducedObject(instance, myGeneration) end
        end)

        task.spawn(function()
            for _, instance in ipairs(Lighting:GetChildren()) do
                if not Settings.ExtremeFPS or generation ~= myGeneration then return end
                reduceObject(instance)
            end
            -- Ask the engine only for classes this pass can modify. This avoids
            -- allocating and scanning a complete workspace descendant array on
            -- large/streaming maps; retain a compatibility fallback.
            local ok, all = pcall(function()
                return workspace:QueryDescendants(
                    "ParticleEmitter,Trail,Beam,Smoke,Fire,Sparkles,PostEffect,Decal,Texture,SurfaceAppearance,BasePart,SpecialMesh,Clouds"
                )
            end)
            if not ok or type(all) ~= "table" then all = workspace:GetDescendants() end
            for index, instance in ipairs(all) do
                if not sessionAlive() or not Settings.ExtremeFPS or generation ~= myGeneration then return end
                reduceObject(instance)
                if index % 200 == 0 then task.wait() end
            end
        end)
    end

    -- Use the game's own ActiveAssetsController instead of reparenting models.
    -- Its native hidden state is cosmetic only; income remains server-driven.
    local ActiveAssetsController
    pcall(function()
        ActiveAssetsController = require(LocalPlayer.PlayerScripts.Game.Plots.ActiveAssetsController)
    end)
    local function setPetsHidden(value)
        if ActiveAssetsController and type(ActiveAssetsController.SetAllPetsHidden) == "function" then
            local ok = pcall(ActiveAssetsController.SetAllPetsHidden, value)
            if not ok and value then Library:Notify("⚠️ Pet visuals unavailable.", 3) end
            return ok
        end
        if value then Library:Notify("⚠️ Pet visuals unavailable.", 3) end
        return false
    end
    getgenv().__CHSAE_PetsRestore = function() setPetsHidden(false) end

    local hidePetsTgl = PerformanceBox:AddToggle("HidePetsToggle", {
        Text = "Hide Pets",
        Default = Settings.HidePets,
        Tooltip = "Hide pet models locally. Income continues.",
    })
    hidePetsTgl:OnChanged(function(value)
        Settings.HidePets = value
        setPetsHidden(value)
    end)
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.SetHidePets = function(value)
            hidePetsTgl:SetValue(value == true)
            return Settings.HidePets
        end
    end

    -- Use the game's native placed-egg render folder, but do not call SetAllHidden:
    -- that API also changes a shared prompt-suppression flag used by treadmill and
    -- event logic. Reparenting this exact private folder hides only placed visuals;
    -- AreaEggSlotsClient and every stealable area egg remain untouched.
    getgenv().__CHSAE_InstallPenEggHider = function()
    local PlacedEggRenderer
    local penEggFolder
    local penEggParent
    local penEggConn
    pcall(function()
        PlacedEggRenderer = require(ReplicatedStorage.Shared.Eggs.PlacedEggRenderer)
        penEggFolder = PlacedEggRenderer.GetRenderFolder()
    end)

    local function setPenEggsHidden(hidden)
        if not penEggFolder then return false end
        if hidden then
            if penEggFolder.Parent then
                penEggParent = penEggFolder.Parent
                pcall(function() penEggFolder.Parent = nil end)
            end
        else
            if penEggFolder.Parent == nil and penEggParent then
                pcall(function() penEggFolder.Parent = penEggParent end)
            end
            penEggParent = nil
        end
        return true
    end

    local function restorePenEggs()
        if penEggConn then pcall(function() penEggConn:Disconnect() end) end
        penEggConn = nil
        setPenEggsHidden(false)
    end
    getgenv().__CHSAE_PenEggsRestore = restorePenEggs

    local function enablePenEggHider()
        if not Settings.RemovePenEggs then return end
        if not setPenEggsHidden(true) or penEggConn then return end
        -- Native events may briefly restore the folder after a cutscene. Re-hide
        -- only that exact render folder when it returns; no scans or frame loop.
        penEggConn = workspace.ChildAdded:Connect(function(child)
            if Settings.RemovePenEggs and child == penEggFolder then
                task.defer(function()
                    if Settings.RemovePenEggs then setPenEggsHidden(true) end
                end)
            end
        end)
    end

    local penEggTgl = PerformanceBox:AddToggle("RemovePenEggsToggle", {
        Text = "Remove Pen Eggs",
        Default = Settings.RemovePenEggs,
        Tooltip = "Hide eggs placed in pens. Area eggs and native prompt state stay untouched.",
    })
    penEggTgl:OnChanged(function(value)
        Settings.RemovePenEggs = value == true
        if Settings.RemovePenEggs then enablePenEggHider() else restorePenEggs() end
    end)
    if type(getgenv().__CHSAE_ConfigControllers) == "table" then
        getgenv().__CHSAE_ConfigControllers.RemovePenEggs = penEggTgl
    end
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.SetRemovePenEggs = function(value)
            penEggTgl:SetValue(value == true)
            return Settings.RemovePenEggs
        end
    end
    if Settings.RemovePenEggs then task.defer(enablePenEggHider) end
    end
    getgenv().__CHSAE_InstallPenEggHider()
    getgenv().__CHSAE_InstallPenEggHider = nil

    -- Keep the aggressive feature in its own closure. The Performance builder is
    -- already large, and Luau limits every function to 200 local registers.
    getgenv().__CHSAE_InstallExtremeFPS = function()
    -- Extreme FPS deliberately leaves gameplay/safety instances alive. Destroying
    -- the map would also remove the floor, guard bounds, TrackStart, and traps.
    -- Destroying Player characters would break bat/tool
    -- avoidance without stopping their data from replicating. Instead we detach a
    -- small allowlist of cosmetic containers and suppress remote-player rendering.
    local extremeOriginals = setmetatable({}, { __mode = "k" })
    local extremeDetached = {}
    local extremeRemoteDetached = {}
    local extremeRemoteByKey = {}
    local extremeConns = {}
    local extremeGeneration = 0
    local extremeForcedPets = false
    local ExtremePlotState
    pcall(function() ExtremePlotState = require(ReplicatedStorage.Client.PlotState) end)

    local function setExtremeProperty(instance, property, value)
        local state = extremeOriginals[instance]
        if not state then state = {}; extremeOriginals[instance] = state end
        if state[property] == nil then
            local ok, current = pcall(function() return instance[property] end)
            if not ok then return end
            state[property] = current
        end
        pcall(function() instance[property] = value end)
    end

    local function hideRemoteVisual(instance)
        if instance:IsA("BasePart") then
            setExtremeProperty(instance, "LocalTransparencyModifier", 1)
            setExtremeProperty(instance, "CastShadow", false)
        elseif instance:IsA("Decal") or instance:IsA("Texture") then
            setExtremeProperty(instance, "Transparency", 1)
        elseif instance:IsA("ParticleEmitter") or instance:IsA("Trail")
            or instance:IsA("Beam") or instance:IsA("Smoke") or instance:IsA("Fire")
            or instance:IsA("Sparkles") or instance:IsA("Highlight")
            or instance:IsA("BillboardGui") or instance:IsA("SurfaceGui") then
            setExtremeProperty(instance, "Enabled", false)
        elseif instance:IsA("PointLight") or instance:IsA("SpotLight")
            or instance:IsA("SurfaceLight") then
            setExtremeProperty(instance, "Enabled", false)
        end
    end

    local function hideRemoteCharacter(character, myGeneration)
        if not character or myGeneration ~= extremeGeneration or not Settings.ExtremeFPS then return end
        for _, instance in ipairs(character:GetDescendants()) do hideRemoteVisual(instance) end
        extremeConns[#extremeConns + 1] = character.DescendantAdded:Connect(function(instance)
            if Settings.ExtremeFPS and myGeneration == extremeGeneration then
                hideRemoteVisual(instance)
            end
        end)
    end

    local function detachCosmetic(instance)
        if instance and instance.Parent and extremeDetached[instance] == nil then
            extremeDetached[instance] = instance.Parent
            instance.Parent = nil
        end
    end

    local function forgetRemoteAsset(instance)
        local state = extremeRemoteDetached[instance]
        if not state then return end
        if state.destroyConn then pcall(function() state.destroyConn:Disconnect() end) end
        if extremeRemoteByKey[state.key] == instance then
            extremeRemoteByKey[state.key] = nil
        end
        extremeRemoteDetached[instance] = nil
    end

    local function restoreRemoteAsset(instance)
        local state = extremeRemoteDetached[instance]
        if not state then return end
        if state.destroyConn then pcall(function() state.destroyConn:Disconnect() end) end
        pcall(function()
            if instance.Parent == nil and state.parent then instance.Parent = state.parent end
        end)
        if extremeRemoteByKey[state.key] == instance then
            extremeRemoteByKey[state.key] = nil
        end
        extremeRemoteDetached[instance] = nil
    end

    local function detachRemoteAsset(instance, key, slot)
        if not (instance and instance.Parent and type(key) == "string") then return end
        local previous = extremeRemoteByKey[key]
        if previous and previous ~= instance then
            -- A streamed/upgraded replacement supersedes the old detached render.
            -- Release the stale strong reference instead of restoring duplicates.
            forgetRemoteAsset(previous)
        end
        local state = extremeRemoteDetached[instance]
        if not state then
            state = { parent = instance.Parent, key = key, slot = tostring(slot) }
            extremeRemoteDetached[instance] = state
            extremeRemoteByKey[key] = instance
            local ok, conn = pcall(function()
                return instance.Destroying:Connect(function()
                    local current = extremeRemoteDetached[instance]
                    if current then
                        if extremeRemoteByKey[current.key] == instance then
                            extremeRemoteByKey[current.key] = nil
                        end
                        extremeRemoteDetached[instance] = nil
                    end
                end)
            end)
            if ok then state.destroyConn = conn end
        end
        pcall(function() instance.Parent = nil end)
    end

    local function restoreAllRemoteAssets()
        local instance = next(extremeRemoteDetached)
        while instance do
            restoreRemoteAsset(instance)
            instance = next(extremeRemoteDetached)
        end
        table.clear(extremeRemoteByKey)
    end

    local function installRemoteSceneReduction(myGeneration)
        -- Borrow the useful part of the competing booster without deleting plot
        -- state: detach only every non-local plot's StarterPen visual and treadmill
        -- Tool. PetArea, CenterPoint, TreadmillBottom, plot roots, and
        -- every local-slot object remain live for automation and native controllers.
        local function resolveLocalSlot()
            if not (ExtremePlotState and type(ExtremePlotState.ResolveLocalSlot) == "function") then
                return nil
            end
            local ok, slot = pcall(ExtremePlotState.ResolveLocalSlot)
            return ok and slot ~= nil and tostring(slot) or nil
        end

        local function detachRemotePen(plot, localSlot)
            if myGeneration ~= extremeGeneration or not Settings.ExtremeFPS
                or not plot or not tonumber(plot.Name) or plot.Name == localSlot then return end
            local toUpdate = plot:FindFirstChild("ToUpdate")
            local pen = toUpdate and toUpdate:FindFirstChild("StarterPen")
            detachRemoteAsset(pen, "pen:" .. plot.Name, plot.Name)
        end

        local function detachRemoteTreadmill(render, localSlot)
            if myGeneration ~= extremeGeneration or not Settings.ExtremeFPS or not render then return end
            local slot = render.Name:match("^TreadmillRender_(%d+)$")
            if slot and slot ~= localSlot then
                detachRemoteAsset(render, "treadmill:" .. slot, slot)
            end
        end

        local function reconcileRemoteScene()
            if myGeneration ~= extremeGeneration or not Settings.ExtremeFPS then return end
            local localSlot = resolveLocalSlot()
            if not localSlot then return end

            -- Ownership/slot assignment can change without a rejoin. Restore any
            -- formerly remote render that now belongs to the local slot first.
            local toRestore = {}
            for instance, state in pairs(extremeRemoteDetached) do
                if state.slot == localSlot then toRestore[#toRestore + 1] = instance end
            end
            for _, instance in ipairs(toRestore) do restoreRemoteAsset(instance) end

            local plots = workspace:FindFirstChild("Plots")
            if plots then
                for _, plot in ipairs(plots:GetChildren()) do detachRemotePen(plot, localSlot) end
            end
            local renders = workspace:FindFirstChild("__ClientTreadmillRenders")
            if renders then
                for _, render in ipairs(renders:GetChildren()) do
                    detachRemoteTreadmill(render, localSlot)
                end
            end
        end

        task.defer(reconcileRemoteScene)
        extremeConns[#extremeConns + 1] = workspace.DescendantAdded:Connect(function(instance)
            if myGeneration ~= extremeGeneration or not Settings.ExtremeFPS then return end
            if instance.Name == "StarterPen" then
                local toUpdate = instance.Parent
                local plot = toUpdate and toUpdate.Name == "ToUpdate" and toUpdate.Parent or nil
                if plot then
                    task.defer(function()
                        local localSlot = resolveLocalSlot()
                        if localSlot then detachRemotePen(plot, localSlot) end
                    end)
                end
            elseif instance.Name:match("^TreadmillRender_%d+$") then
                local parent = instance.Parent
                if parent and parent.Name == "__ClientTreadmillRenders" then
                    task.defer(function()
                        local localSlot = resolveLocalSlot()
                        if localSlot then detachRemoteTreadmill(instance, localSlot) end
                    end)
                end
            end
        end)
        if ExtremePlotState and ExtremePlotState.PlotChanged then
            local ok, conn = pcall(function()
                return ExtremePlotState.PlotChanged:Connect(function()
                    task.defer(reconcileRemoteScene)
                end)
            end)
            if ok and conn then extremeConns[#extremeConns + 1] = conn end
        end
    end

    local function restoreExtremeFPS()
        extremeGeneration += 1
        for _, conn in ipairs(extremeConns) do pcall(function() conn:Disconnect() end) end
        table.clear(extremeConns)
        restoreAllRemoteAssets()
        for instance, parent in pairs(extremeDetached) do
            if instance and instance.Parent == nil and parent then
                pcall(function() instance.Parent = parent end)
            end
            extremeDetached[instance] = nil
        end
        for instance, state in pairs(extremeOriginals) do
            if instance and instance.Parent then
                for property, value in pairs(state) do
                    pcall(function() instance[property] = value end)
                end
            end
            extremeOriginals[instance] = nil
        end
    end
    getgenv().__CHSAE_ExtremeRestore = restoreExtremeFPS

    local function enableExtremeFPS()
        restoreExtremeFPS()
        extremeGeneration += 1
        local myGeneration = extremeGeneration

        -- Apply the texture/effect reducer as part of this single combined mode.
        enablePerformance()
        extremeForcedPets = not hidePetsTgl.Value
        if extremeForcedPets then hidePetsTgl:SetValue(true) end

        local objects = workspace:FindFirstChild("__OBJECTS")
        local build = objects and objects:FindFirstChild("Build")
        detachCosmetic(build and build:FindFirstChild("Props"))
        if build then
            for _, zone in ipairs(build:GetChildren()) do
                if zone:IsA("Folder") or zone:IsA("Model") then
                    detachCosmetic(zone:FindFirstChild("Props"))
                end
            end
        end
        detachCosmetic(objects and objects:FindFirstChild("Leaderboards"))
        detachCosmetic(objects and objects:FindFirstChild("ExclamationPoints"))
        detachCosmetic(objects and objects:FindFirstChild("Highlights"))
        detachCosmetic(objects and objects:FindFirstChild("GroupRewards"))
        -- Native treadmill entry/detection raycasts against this gameplay render.
        -- Reducing remote visuals is safe; detaching the container is not.
        installRemoteSceneReduction(myGeneration)

        local function watchPlayer(player)
            if player == LocalPlayer then return end
            if player.Character then hideRemoteCharacter(player.Character, myGeneration) end
            extremeConns[#extremeConns + 1] = player.CharacterAdded:Connect(function(character)
                task.defer(hideRemoteCharacter, character, myGeneration)
            end)
        end
        for _, player in ipairs(Players:GetPlayers()) do watchPlayer(player) end
        extremeConns[#extremeConns + 1] = Players.PlayerAdded:Connect(watchPlayer)
    end

    local function disableExtremeFPS()
        restoreExtremeFPS()
        restorePerformance()
        if extremeForcedPets and hidePetsTgl.Value then hidePetsTgl:SetValue(false) end
        extremeForcedPets = false
    end

    local extremeTgl = PerformanceBox:AddToggle("ExtremeFPSToggle", {
        Text = "Delete Unnecessary Models",
        Default = Settings.ExtremeFPS,
        Tooltip = "Reduce effects and hide remote pens, treadmills, pets, and players locally.",
    })
    extremeTgl:OnChanged(function(value)
        Settings.ExtremeFPS = value == true
        if Settings.ExtremeFPS then enableExtremeFPS() else disableExtremeFPS() end
    end)
    if getgenv().__CHSAE_Debug then
        getgenv().__CHSAE_Debug.SetExtremeFPS = function(value)
            extremeTgl:SetValue(value == true)
        end
    end
    if Settings.ExtremeFPS then task.defer(enableExtremeFPS) end
    end
    getgenv().__CHSAE_InstallExtremeFPS()
    getgenv().__CHSAE_InstallExtremeFPS = nil

    local blackFrame = Instance.new("Frame")
    blackFrame.Name = "CHSAE_BlackScreen"
    -- Overscan past Roblox's top inset so the 3D view and native top bar area
    -- are both covered while the CloverHub window remains available above it.
    blackFrame.Size = UDim2.new(1, 0, 1, 200)
    blackFrame.Position = UDim2.new(0, 0, 0, -100)
    blackFrame.BackgroundColor3 = Color3.new(0, 0, 0)
    blackFrame.BackgroundTransparency = 0
    blackFrame.BorderSizePixel = 0
    blackFrame.ZIndex = 0
    blackFrame.Active = false
    blackFrame.Visible = false
    blackFrame.Parent = Library.ScreenGui

    -- Black Screen keeps the client light while still showing the information an
    -- unattended CloverHub session actually needs. This is deliberately a compact
    -- CloverHub dashboard, not a copy of another hub's unsupported stat list.
    local blackMonitor = (function()
        local palette = {
            panel = Color3.fromRGB(11, 15, 18),
            card = Color3.fromRGB(18, 24, 29),
            cardSoft = Color3.fromRGB(15, 20, 24),
            outline = Color3.fromRGB(39, 52, 61),
            text = Color3.fromRGB(235, 242, 245),
            muted = Color3.fromRGB(139, 153, 163),
            green = Color3.fromRGB(74, 222, 128),
            cyan = Color3.fromRGB(56, 189, 248),
            blue = Color3.fromRGB(96, 165, 250),
            gold = Color3.fromRGB(251, 191, 36),
            pink = Color3.fromRGB(244, 114, 182),
            orange = Color3.fromRGB(251, 146, 60),
            violet = Color3.fromRGB(167, 139, 250),
        }

        -- A semibold face makes the monitor easier to read without the heavy,
        -- poster-like weight of wrapping every line in RichText <b> tags.
        local monitorFont = Library.Scheme.Font
        pcall(function()
            monitorFont = Font.new(monitorFont.Family, Enum.FontWeight.SemiBold, monitorFont.Style)
        end)

        local root = Instance.new("Frame")
        root.Name = "CHSAE_BlackScreenMonitor"
        root.AnchorPoint = Vector2.new(0.5, 0.5)
        root.Position = UDim2.fromScale(0.5, 0.5)
        root.Size = UDim2.new(0.92, 0, 0, 386)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.ZIndex = 1
        root.Parent = blackFrame

        local bounds = Instance.new("UISizeConstraint")
        bounds.MinSize = Vector2.new(300, 386)
        bounds.MaxSize = Vector2.new(620, 386)
        bounds.Parent = root

        -- Very short mobile viewports can be only a few pixels taller than this
        -- dashboard. Scale the complete composition together so the Discord and
        -- version footer remain inside the visible screen instead of clipping.
        local responsiveScale = Instance.new("UIScale")
        responsiveScale.Name = "ShortViewportScale"
        responsiveScale.Scale = 1
        responsiveScale.Parent = root
        local function refreshResponsiveScale()
            local viewportHeight = 600
            pcall(function()
                local camera = workspace.CurrentCamera
                if camera then viewportHeight = camera.ViewportSize.Y end
            end)
            responsiveScale.Scale = math.clamp((viewportHeight - 16) / 386, 0.7, 1)
        end

        local function addCorner(parent, radius)
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, radius)
            corner.Parent = parent
        end

        local function addLabel(parent, name, position, size, text, textSize, color, alignment, zindex)
            local label = Instance.new("TextLabel")
            label.Name = name
            label.BackgroundTransparency = 1
            label.BorderSizePixel = 0
            label.Position = position
            label.Size = size
            label.FontFace = monitorFont
            label.Text = text or ""
            label.TextSize = textSize or 12
            label.TextColor3 = color or palette.text
            label.TextXAlignment = alignment or Enum.TextXAlignment.Left
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.TextTruncate = Enum.TextTruncate.AtEnd
            label.ZIndex = zindex or 3
            label.Parent = parent
            return label
        end

        local panel = Instance.new("Frame")
