        local userLine = addLabel(panel, "User", UDim2.fromOffset(62, 35), UDim2.new(1, -180, 0, 17),
            "@" .. tostring(LocalPlayer.Name), 13, palette.muted, Enum.TextXAlignment.Left, 3)

        local liveBadge = Instance.new("Frame")
