        liveBadge.Size = UDim2.fromOffset(94, 26)
        liveBadge.BackgroundColor3 = Color3.fromRGB(18, 52, 36)
        liveBadge.BorderSizePixel = 0
        liveBadge.ZIndex = 2
        liveBadge.Parent = panel
        addCorner(liveBadge, 13)
        local liveText = addLabel(liveBadge, "Text", UDim2.fromScale(0, 0), UDim2.fromScale(1, 1),
            "●  LIVE · 1P", 12, palette.green, Enum.TextXAlignment.Center, 3)

        local divider = Instance.new("Frame")
