        local activityValue = addLabel(activityCard, "Value", UDim2.fromOffset(11, 18), UDim2.new(1, -22, 0, 23),
            "Starting CloverHub…", 19, palette.green, Enum.TextXAlignment.Left, 3)

        local metricGrid = Instance.new("Frame")
