        metricGrid.Position = UDim2.new(0, 14, 0, 120)
        metricGrid.Size = UDim2.new(1, -28, 0, 168)
        metricGrid.BackgroundTransparency = 1
        metricGrid.BorderSizePixel = 0
        metricGrid.ZIndex = 2
        metricGrid.Parent = panel
        local gridLayout = Instance.new("UIGridLayout")
        gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
        gridLayout.CellPadding = UDim2.fromOffset(7, 7)
        gridLayout.CellSize = UDim2.new(1 / 3, -5, 0, 51)
        gridLayout.Parent = metricGrid

