        addLabel(root, "Version", UDim2.new(0, 0, 0, 370), UDim2.new(1, 0, 0, 14),
            "CloverHub " .. RELEASE_VERSION .. "  •  3D RENDERING PAUSED", 10,
            Color3.fromRGB(91, 105, 113), Enum.TextXAlignment.Center, 2)

        local monitor = { Root = root }
        function monitor.Refresh()
            refreshResponsiveScale()
            local activity = "Idle"
            pcall(function() activity = tostring(Arb.status()) end)
            activityValue.Text = activity

            moneyValue.Text = tostring(StatsMetrics:Get("money"))
            incomeValue.Text = tostring(StatsMetrics:Get("income"))
            petValue.Text = tostring(StatsMetrics:Get("petValue"))
            eggsValue.Text = tostring(StatsMetrics:Get("eggs"))
            stealsValue.Text = tostring(tonumber(RuntimeStatus.steals) or 0)
            attemptsValue.Text = tostring(tonumber(RuntimeStatus.attempts) or 0)
            fpsValue.Text = tostring(fps)
            pingValue.Text = tostring(SessionMetrics:Get("ping"))
            sessionValue.Text = fmtClock(os.clock() - startClock)

            local eventStatus = tostring(RuntimeStatus.adminEventStatus or "Waiting for event data")
            eventValue.Text = eventStatus
            eventDot.BackgroundColor3 = RuntimeStatus.riftActive and palette.pink or palette.cyan

            local playerCount = 1
            pcall(function() playerCount = #Players:GetPlayers() end)
            liveText.Text = ("●  LIVE · %dP"):format(playerCount)
        end
        function monitor.GetState()
            return {
                Visible = blackFrame.Visible == true,
                Activity = activityValue.Text,
                Money = moneyValue.Text,
                Income = incomeValue.Text,
                PetValue = petValue.Text,
                Eggs = eggsValue.Text,
                Steals = stealsValue.Text,
                Attempts = attemptsValue.Text,
                FPS = fpsValue.Text,
                Ping = pingValue.Text,
                Session = sessionValue.Text,
                Event = eventValue.Text,
                Discord = "discord.gg/CloverOnTop",
            }
        end

        task.spawn(function()
            while sessionAlive() do
                if not Settings.BlackScreen then
                    SESSION.IdleWorkerWake.Event:Wait()
                    continue
                end
                pcall(monitor.Refresh)
                task.wait(1)
            end
        end)
        monitor.Refresh()
        return monitor
    end)()

    local function setBlackScreenEnabled(value)
        value = value == true
        blackFrame.Visible = value
        if value then pcall(blackMonitor.Refresh) end
        -- A black Frame alone does not stop Roblox from rendering the world
        -- behind it. Disable only the 3D renderer when the client exposes the
        -- native switch; simulation, Heartbeat, remotes, and movement continue.
        pcall(function() RunService:Set3dRenderingEnabled(not value) end)
    end
    getgenv().__CHSAE_RenderRestore = function()
        pcall(function() RunService:Set3dRenderingEnabled(true) end)
    end

    -- Heartbeat rate is what the movement engine actually steps on: every CFrame
    -- step, arrival check, guard-proximity test and abort check runs once per
    -- Heartbeat. Measured on void26v1 with 3D rendering off, the client sat at
    -- exactly the 60 cap (60.0 Hz) while raising the cap reached 87.4 Hz — the
    -- client is cap-bound, not GPU-bound, once rendering is disabled. With
    -- rendering ON the same change gave 55.2 Hz, i.e. nothing, because the
    -- renderer becomes the limit again. So the boost is deliberately tied to
    -- Black Screen and dropped the moment 3D rendering comes back.
    local savedFpsCap = nil

    local function applyTickRate()
        if type(setfpscap) ~= "function" then return end
        local wanted = Settings.BoostTickRate == true and Settings.BlackScreen == true
        if wanted then
            if savedFpsCap == nil then
                local ok, current = pcall(function()
                    return type(getfpscap) == "function" and getfpscap() or nil
                end)
                savedFpsCap = (ok and tonumber(current)) or 60
            end
            pcall(setfpscap, 240)
        elseif savedFpsCap ~= nil then
            pcall(setfpscap, savedFpsCap)
            savedFpsCap = nil
        end
    end

    -- Restored on unload alongside the other performance overrides.
    do
        local previousPerfRestore = getgenv().__CHSAE_PerfRestore
        getgenv().__CHSAE_PerfRestore = function()
            if savedFpsCap ~= nil and type(setfpscap) == "function" then
                pcall(setfpscap, savedFpsCap)
                savedFpsCap = nil
            end
            if type(previousPerfRestore) == "function" then pcall(previousPerfRestore) end
        end
    end

    local blackTgl = PerformanceBox:AddToggle("BlackScreenToggle", {
        Text = "Black Screen",
        Default = Settings.BlackScreen,
        Tooltip = "Stop 3D rendering behind a black screen.",
    })
    blackTgl:OnChanged(function(value)
        Settings.BlackScreen = value
        setBlackScreenEnabled(value)
        SESSION.WakeIdleWorkers("black-screen-toggle")
        applyTickRate()
        local statusOverlay = getgenv().__CHSAE_StatusGui
        if statusOverlay then
            local refresh = getgenv().__CHSAE_StatusRefresh
            if type(refresh) == "function" then
                pcall(refresh)
            else
                pcall(function() statusOverlay:SetVisible(Settings.ShowStatusOverlay and not value) end)
            end
        end
    end)
    setBlackScreenEnabled(Settings.BlackScreen)

    local boostTgl = PerformanceBox:AddToggle("BoostTickRateToggle", {
        Text = "Boost Tick Rate",
        Default = Settings.BoostTickRate,
        Tooltip = "Smoother automation. Needs Black Screen on.",
    })
    boostTgl:OnChanged(function(value)
        Settings.BoostTickRate = value == true
        applyTickRate()
    end)
    if type(getgenv().__CHSAE_ConfigControllers) == "table" then
        getgenv().__CHSAE_ConfigControllers.BoostTickRate = boostTgl
    end
    applyTickRate()

    if type(getgenv().__CHSAE_Debug) == "table" then
        getgenv().__CHSAE_Debug.SetBlackScreen = function(value)
            blackTgl:SetValue(value == true)
            return blackMonitor.GetState()
        end
        getgenv().__CHSAE_Debug.GetBlackScreenMonitorState = blackMonitor.GetState
        getgenv().__CHSAE_Debug.GetTickRateState = function()
            local current
            pcall(function()
                current = type(getfpscap) == "function" and getfpscap() or nil
            end)
            return {
                BoostTickRate = Settings.BoostTickRate == true,
                BlackScreen = Settings.BlackScreen == true,
                Applied = savedFpsCap ~= nil,
                SavedCap = savedFpsCap,
                CurrentCap = current,
            }
        end
    end

    if Settings.HidePets then task.defer(setPetsHidden, true) end
end

