-- Native Obsidian draggable status overlay, separate from the main window.
OverlayBox = SettingsTab:AddRightGroupbox("📡 Status")
local overlayLabel
local robloxMenuOpen = false
local function statusOverlayDefaultPosition()
    local screenGui = Library.ScreenGui
    local height = screenGui and screenGui.AbsoluteSize.Y or 0
    if height <= 0 then
        local camera = workspace.CurrentCamera
        height = camera and camera.ViewportSize.Y or 1080
    end
    return UDim2.fromOffset(48, math.floor(height * 0.66 + 0.5))
end
local function refreshOverlayVisibility()
    if overlayLabel then
        local visible = Settings.ShowStatusOverlay
            and not Settings.BlackScreen and not robloxMenuOpen
        overlayLabel:SetVisible(visible)
        if visible then RuntimeStatus.wakeOverlay("overlay-visible") end
    end
end
do
    local old = getgenv().__CHSAE_StatusGui
    if old then pcall(function() old:Destroy() end) end

    overlayLabel = Library:AddDraggableLabel("[Activity] Idle")
    local nativeLabel = overlayLabel.Label
    nativeLabel.Name = "CHSAE_StatusOverlay"
    -- Obsidian parents draggable labels under its Floats root (ZIndex 10). In
    -- Sibling mode a child cannot render below the Main sibling (ZIndex 1), even
    -- when the child itself is ZIndex 0. Reparent only this label so it remains
    -- above the 3D game via ScreenGui.DisplayOrder but below the automation UI.
    nativeLabel.Parent = Library.ScreenGui
    nativeLabel.ZIndex = 0
    nativeLabel.AnchorPoint = Vector2.new(0, 0.5)
    -- Preserve the established 66%-down location as a screen-space offset. It
    -- remains stable after reparenting and the player can still drag it.
    nativeLabel.Position = statusOverlayDefaultPosition()
    task.defer(function()
        if sessionAlive() and nativeLabel.Parent then
            nativeLabel.Position = statusOverlayDefaultPosition()
        end
    end)
    nativeLabel.TextXAlignment = Enum.TextXAlignment.Left
    nativeLabel.TextYAlignment = Enum.TextYAlignment.Top
    nativeLabel.TextWrapped = false
    nativeLabel.RichText = true
    nativeLabel.BackgroundTransparency = 1
    nativeLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    nativeLabel.TextStrokeTransparency = 0.35
    -- Keep Obsidian's padded drag target, but make the card/border invisible so
    -- the result stays text-only like the supplied reference.
    for _, child in ipairs(nativeLabel:GetChildren()) do
        if child:IsA("UIStroke") then child.Transparency = 1 end
    end

    getgenv().__CHSAE_StatusGui = overlayLabel
    getgenv().__CHSAE_StatusRefresh = refreshOverlayVisibility

    -- Core Roblox menus must always own the screen. Obsidian overlays are under
    -- CoreGui, so ZIndex alone cannot reliably place them behind the menu blur.
    -- Hide the text while Escape/Roblox Settings is open, then restore it.
    pcall(function()
        local guiService = game:GetService("GuiService")
        getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
            = guiService.MenuOpened:Connect(function()
                robloxMenuOpen = true
                refreshOverlayVisibility()
            end)
        getgenv().__CHSAE_RuntimeConns[#getgenv().__CHSAE_RuntimeConns + 1]
            = guiService.MenuClosed:Connect(function()
                robloxMenuOpen = false
                refreshOverlayVisibility()
            end)
    end)
end

local overlayToggle = OverlayBox:AddToggle("ShowStatusOverlayToggle", {
    Text = "Show Status",
    Default = Settings.ShowStatusOverlay,
    Tooltip = "Show automation status on screen.",
})
overlayToggle:OnChanged(function(value)
    Settings.ShowStatusOverlay = value
    refreshOverlayVisibility()
end)
refreshOverlayVisibility()

-- Reference idle-callback suppression (v152).
-- Addcantsleep enumerates all Idled listeners and prefers Disable to Disconnect.
-- Rescanning handles new listeners; callback state does not prove an idle reset.
do
    (function()
        local env = getgenv()
        local registry = env.__CHSAE_AFKCallbackRecords
        if type(registry) ~= "table" or registry.JobId ~= game.JobId then
            registry = { JobId = game.JobId, Records = {}, Disconnected = 0, Rejoin = false }
            env.__CHSAE_AFKCallbackRecords = registry
        end
        local afk = { Enabled = false, Generation = 0, Count = 0, Verified = 0, Unknown = 0 }
        registry.Owner = afk
        local function read(object, key)
            local ok, value = pcall(function() return object[key] end)
            if ok then return value end
        end
        local function method(object, name)
            local fn = read(object, name)
            if type(fn) ~= "function" then fn = read(object, string.lower(name)) end
            return type(fn) == "function" and fn or nil
        end
        local function current(generation)
            return afk.Enabled and afk.Generation == generation and sessionAlive()
                and registry.JobId == game.JobId and registry.Owner == afk
        end
        local function pending()
            local count = 0
            for _ in pairs(registry.Records) do count += 1 end
            return count
        end
        local function restore(record)
            local target = record.Object
            if record.Kind == "Disconnect" and read(target, "Connected") ~= true then
                registry.Rejoin = true
                return true
            end
            if read(target, "Connected") == false or read(target, "Enabled") == true then return true end
            if record.WasEnabled ~= true or not record.Enable then
                -- Never enable an opaque callback that might already have been
                -- disabled by another script before we saw it.
                registry.Rejoin = true
                return true
            end
            local ok = pcall(record.Enable, target)
            return ok and (read(target, "Enabled") == true or read(target, "Connected") == false)
        end
        local function restoreOwned()
            for target, record in pairs(registry.Records) do
                if record.Owner == afk or registry.Owner == afk then
                    if restore(record) then registry.Records[target] = nil end
                end
            end
            return pending() == 0
        end
        local function publish()
            env.__CHSAE_AFKStartupError = afk.Error and {
                Message = afk.Error, Method = "Idle callback suppression",
            } or nil
        end
        local function stop()
            afk.Enabled = false
            afk.Generation += 1
            afk.Count, afk.Verified, afk.Unknown = 0, 0, 0
            local restored = restoreOwned()
            afk.Error = nil
            if not restored then afk.Error = "Restore incomplete; switch off again to retry" end
            publish()
            return restored and not registry.Rejoin
        end
        local function snapshot()
            local scopes = { env, getfenv(0), _G }
            local tried, lastError = {}, "Unsupported: idle callback API unavailable"
            for _, name in ipairs({ "getconnections", "get_connections", "get_signal_cons",
                "getsignalcons", "getsignalconnections" }) do
                for _, scope in ipairs(scopes) do
                    local fn = type(scope) == "table" and rawget(scope, name)
                    if type(fn) == "function" and not tried[fn] then
                        tried[fn] = true
                        local ok, result = pcall(function() return fn(LocalPlayer.Idled) end)
                        if ok and type(result) == "table" then return result end
                        lastError = "Idle callback inspection failed: " .. tostring(ok and "invalid result" or result)
                    end
                end
            end
            return nil, lastError
        end
        local function suppress(target, generation)
            if not current(generation) then return false, "Idle callback update superseded" end
            if read(target, "Connected") == false then return true, nil, "gone" end
            local enabled = read(target, "Enabled")
            if enabled == false then return true, nil, "verified" end
            local off, kind = method(target, "Disable"), "Disable"
            if not off then off, kind = method(target, "Disconnect"), "Disconnect" end
            if not off then return false, "Unsupported: callback cannot be disabled" end
            local record = registry.Records[target]
            if not record then
                if pending() >= 512 then return false, "Idle callback tracking limit reached" end
                record = { Object = target, Owner = afk, WasEnabled = enabled,
                    Enable = method(target, "Enable"), Kind = kind }
                registry.Records[target] = record
            end
            record.Owner = afk
            local ok, err = pcall(off, target)
            local after, connected = read(target, "Enabled"), read(target, "Connected")
            local noEffect = (kind == "Disable" and after == true)
                or (kind == "Disconnect" and connected == true)
            if kind == "Disconnect" and not noEffect then
                if not record.Counted then registry.Disconnected += 1; record.Counted = true end
                registry.Rejoin = true
            elseif kind == "Disable" and not noEffect and (enabled == nil or not record.Enable) then
                registry.Rejoin = true
            end
            if not current(generation) then
                if restore(record) then registry.Records[target] = nil end
                return false, "Idle callback update superseded"
            end
            if not ok then return false, "Idle callback disable failed: " .. tostring(err) end
            if noEffect then
                return false, "Idle callback disable had no effect"
            end
            return true, nil, (after == false or read(target, "Connected") == false) and "verified" or "unknown"
        end
        local function scan(generation)
            if not current(generation) then return false, "Anti-AFK is not active" end
            if registry.Busy then
                afk.Error = "Waiting for the previous idle callback update"
                publish()
                return false, afk.Error
            end
            local token = {}
            registry.Busy = token
            for target in pairs(registry.Records) do
                if read(target, "Connected") == false then registry.Records[target] = nil end
            end
            local callbacks, issue = snapshot()
            local count, verified, unknown = 0, 0, 0
            if callbacks and current(generation) then
                local visited, seen = 0, {}
                for _, target in pairs(callbacks) do
                    if not current(generation) then break end
                    visited += 1
                    if visited > 512 then issue = "Idle callback snapshot exceeds limit"; break end
                    if not seen[target] then
                        seen[target] = true
                        local ok, err, state = suppress(target, generation)
                        if state ~= "gone" then count += 1 end
                        if ok and state == "verified" then verified += 1
                        elseif ok and state == "unknown" then unknown += 1 end
                        if not ok then issue = issue or err end
                    end
                end
            end
            if registry.Busy == token then registry.Busy = nil end
            if not current(generation) then publish(); return false, "Idle callback update superseded" end
            afk.Count, afk.Verified, afk.Unknown = count, verified, unknown
            afk.Error, afk.LastScan = issue, os.clock()
            publish()
            return issue == nil, issue
        end
        local function start()
            if current(afk.Generation) then return scan(afk.Generation) end
            -- Retry restoration left by a previous instance before taking over.
            if not registry.Busy and not restoreOwned() then
                afk.Error = "Restore incomplete; switch off again to retry"; publish()
                return false, afk.Error
            end
            afk.Enabled = true
            afk.Generation += 1
            local generation = afk.Generation
            local ok, err = scan(generation)
            task.spawn(function()
                while current(generation) do
                    task.wait(10)
                    if current(generation) then scan(generation) end
                end
                if afk.Enabled and afk.Generation == generation then stop() end
            end)
            return ok, err
        end
        env.__CHSAE_AFKGuardRestore = stop
        local toggle = OverlayBox:AddToggle("AntiAFKToggle", {
            Text = "Anti-AFK", Default = Settings.AntiAFK,
            Tooltip = "Block idle callbacks and watch for new ones. Callbacks that can only be disconnected need a rejoin to restore.",
        })
        toggle:OnChanged(function(value)
            Settings.AntiAFK = value
            if value then start() else stop() end
        end)
        local controls = env.__CHSAE_ConfigControllers
        if type(controls) == "table" then controls.AntiAFK, controls.AntiAFKMethod = toggle, nil end
        local debug = env.__CHSAE_Debug
        if debug then
            debug.TestAntiAFK, debug.GetAntiAFKPulses = nil, nil
            debug.RefreshAntiAFKGuard = function()
                if not Settings.AntiAFK then return false, "Enable Anti-AFK first" end
                return start()
            end
            debug.GetAntiAFKStatus = function()
                local active = current(afk.Generation) and not afk.Error
                local state = "DISABLED"
                if afk.Enabled then
                    if afk.Error then state = "CALLBACK_ERROR"
                    elseif afk.Count == 0 then state = "WATCHING"
                    elseif afk.Unknown > 0 then state = "BEST_EFFORT"
                    else state = "CALLBACKS_BLOCKED" end
                end
                return { Method = "Idle callback suppression", Enabled = afk.Enabled,
                    SettingEnabled = Settings.AntiAFK, RuntimeActive = active,
                    ProtectionState = state, Error = afk.Error, LastScanAt = afk.LastScan,
                    CallbackCount = afk.Count, VerifiedCallbackCount = afk.Verified,
                    UnverifiedCallbackCount = afk.Unknown, RestorePending = pending(),
                    DisconnectedCount = registry.Disconnected, RejoinRequired = registry.Rejoin,
                    EnduranceVerified = false, NativeVerified = false,
                    ControllerTouched = false, SimulatedInput = false, Pulses = 0,
                    SyntheticInput = false, InputFailures = 0, JobId = game.JobId }
            end
        end
        if Settings.AntiAFK then start() else stop() end
    end)()
end


task.spawn(function()
    local lastStatus
    local function valueOf(text)
        return tostring(text):match(":%s*(.*)$") or tostring(text)
    end
    local function row(name, value, color)
        return ('<font color="#E4E4E7"><b>[%s]</b></font> <font color="%s">%s</font>')
            :format(name, color or "#D4D4D8", tostring(value))
    end
    local function debugSummary()
        local owner = Arb.owner or (Arb.treadmillTraining and "Treadmill") or "Idle"
        local pending = getgenv().__CHSAE_CarryRequest
        local dropped = type(RuntimeStatus.getDroppedRecoveryRecord) == "function"
            and RuntimeStatus.getDroppedRecoveryRecord() or nil
        if dropped then
            local root = getCharParts()
            local distance = root and ((root.Position - dropped.BottomCFrame.Position)
                * Vector3.new(1, 0, 1)).Magnitude or nil
            local requestState = type(pending) == "table" and pending.inFlight
                and " · request pending" or ""
            return ("%s · drop %s · %s%s"):format(owner,
                tostring(dropped.Uid):sub(1, 6),
                distance and (("%.0f studs"):format(distance)) or "position syncing",
                requestState), "#FDE68A"
        end
        if type(pending) == "table" and pending.inFlight then
            return ("%s · carry request pending %.1fs"):format(owner,
                math.max(0, os.clock() - (tonumber(pending.started) or os.clock()))), "#FDE68A"
        end
        if carrying then return owner .. " · carry verified", "#86EFAC" end
        local failureAge = math.max(0,
            os.clock() - (tonumber(stealRuntime.requestFailureAt) or os.clock()))
        if stealRuntime.lockedUid and failureAge <= 8
            and tostring(stealRuntime.lastRequestKind or "") ~= "" then
            local detail = tostring(stealRuntime.lastRequestKind)
            if detail == "movement-retry" and tostring(stealRuntime.lastRequestError or "") ~= "" then
                detail = tostring(stealRuntime.lastRequestError):gsub("[<>&\r\n]", " "):sub(1, 100)
            end
            return ("%s · retry %s · %.1fs"):format(owner,
                detail, failureAge), "#FDE68A"
        end
        local index = RuntimeStatus.candidateIndex
        return ("%s · targets %d · scan %d"):format(owner,
            index and #index.entries or 0, index and index.version or 0), "#A1A1AA"
    end
    while sessionAlive() do
        if not (Settings.ShowStatusOverlay and not Settings.BlackScreen and not robloxMenuOpen) then
            RuntimeStatus.statusWake.Event:Wait()
            continue
        end
        local safety, safetyFlags = RuntimeStatus.getSafetySummary()
        local activity = Arb.status()
        local steal = valueOf(RuntimeStatus.steal)
        local target = valueOf(RuntimeStatus.target)
        local pen = valueOf(RuntimeStatus.place)
        local stealTime = valueOf(RuntimeStatus.stealTime)
        local activityColor = activity:find("Idle", 1, true) and "#A1A1AA"
            or activity:find("Waiting", 1, true) and "#FDE68A" or "#86EFAC"
        local stealColor = (steal == "Off" or steal:find("Waiting for target", 1, true))
            and "#A1A1AA" or "#FDE68A"
        local targetColor = target == "none" and "#A1A1AA" or "#FDE68A"
        local penColor = pen:find("full", 1, true) and "#FDBA74"
            or pen:find("Placed", 1, true) and "#86EFAC"
            or "#D4D4D8"
        local safetyColor = (tonumber(safetyFlags) or 0) > 0 and "#FCA5A5" or "#86EFAC"
        local lines = { row("Activity", activity, activityColor) }
        local eventSource = RuntimeStatus.adminEventStatus
        local event = tostring(eventSource or "Rift status unavailable")
            :gsub("^🌀%s*", ""):gsub("^🕒%s*", "")
            :gsub("^👑%s*", ""):gsub("^👾%s*", "")
        lines[#lines + 1] = row("Event", event,
            (event:find("Rift live", 1, true) or event:find("is live", 1, true))
                and "#F9A8D4" or "#7DD3FC")
        local stealWorking = Arb.owner == "Steal" or Arb.stealBusy()
        if stealWorking and steal ~= "Off" and not steal:find("Waiting for target", 1, true) then
            lines[#lines + 1] = row("Steal", steal, stealColor)
        end
        if target ~= "none" then
            lines[#lines + 1] = row("Target", target, targetColor)
        end
        if RuntimeStatus.stealTimer.active then
            lines[#lines + 1] = row("Time", stealTime, "#7DD3FC")
        end
        if Settings.AutoPlace or Settings.AutoHatch or Arb.owner == "Place"
            or (Settings.PlaceAfterIncubation and type(RuntimeStatus.getIncubatedPlaceCount) == "function"
                and RuntimeStatus.getIncubatedPlaceCount() > 0) then
            lines[#lines + 1] = row("Pen", pen, penColor)
        end
        lines[#lines + 1] = row("Safety", valueOf(safety), safetyColor)
        local debug, debugColor = debugSummary()
        lines[#lines + 1] = row("Debug", debug, debugColor)
        local status = table.concat(lines, "\n")
        if status ~= lastStatus then
            lastStatus = status
            pcall(function()
                overlayLabel:SetText(status)
            end)
        end
        RuntimeStatus.statusWake.Event:Wait()
    end
end)

-- Key metadata and logout remain loader-owned. The licensed loader may expose
-- only this sanitized capability contract to the payload:
--   accessInfo -> { tier, remainingSeconds, canLogout }
--   logout     -> true only after server-confirmed unbind + local-token removal
-- The standalone Maintenance copy has no capability, so it fails closed without
-- reading remembered credentials or presenting a runtime/session timer as key time.
Window.__BuildAccountTab = function(alive)
    Window.__KeyStatusBox = Window.__AccountTab:AddRightGroupbox("🔑 Key Status")
    Window.__LogoutBox = Window.__AccountTab:AddLeftGroupbox("🚪 Account")
    local statusLabel = Window.__KeyStatusBox:AddLabel("KeyRemainingStatus", {
        Text = "Checking...",
        DoesWrap = true,
    })
    Window.__LogoutBox:AddLabel("KeyLogoutNotice", {
        Text = "Logout this device",
        DoesWrap = true,
    })

    local logoutBusy = false
    local logoutDialog
    local logoutButton

    local function capability()
        return type(SESSION) == "table" and type(SESSION.RuntimeCapability) == "function"
            and SESSION.RuntimeCapability or nil
    end

    local function readAccessInfo()
        local runtimeCapability = capability()
        if not runtimeCapability then return nil, "loader capability unavailable" end
        local ok, info = pcall(runtimeCapability, "accessInfo")
        if not ok or type(info) ~= "table" then
            return nil, "loader capability unavailable"
        end
        local remaining = tonumber(info.remainingSeconds)
        if not remaining or remaining < 0 or remaining ~= remaining
            or remaining == math.huge then
            return nil, "invalid key-time response"
        end
        return {
            tier = tostring(info.tier or info.accessTier or "licensed"),
            remainingSeconds = remaining,
            canLogout = info.canLogout == true,
        }
    end

    local function formatRemaining(seconds)
        seconds = math.max(0, math.floor(tonumber(seconds) or 0))
        local days = math.floor(seconds / 86400)
        local hours = math.floor((seconds % 86400) / 3600)
        local minutes = math.floor((seconds % 3600) / 60)
        local secs = seconds % 60
        if days > 0 then
            return ("%dd %02dh %02dm %02ds"):format(days, hours, minutes, secs)
        end
        return ("%02dh %02dm %02ds"):format(hours, minutes, secs)
    end

    local panel = MakeButtonPanel(Window.__LogoutBox, "KeyLogoutButtons", {
        { "Log Out", function()
            if logoutBusy then return end
            local info = readAccessInfo()
            if not info or not info.canLogout then
                Library:Notify("Logout is unavailable until the licensed loader exposes secure key controls.", 5)
                return
            end
            if logoutDialog and logoutDialog.Destroyed ~= true then return end

            local dialog
            local function dismiss(activeDialog)
                local target = activeDialog or dialog
                logoutDialog = nil
                if target then pcall(function() target:Dismiss() end) end
            end
            local built = pcall(function()
                dialog = Window:AddDialog("ConfirmKeyLogout", {
                    Title = "Log out and unbind this key?",
                    Description = "This ends the current session, removes this device binding, and kicks you from the game. The same key can be entered again after it is unbound.",
                    TitleColor = Color3.fromRGB(248, 113, 113),
                    AutoDismiss = false,
                    OutsideClickDismiss = false,
                    FooterButtons = {
                        Cancel = {
                            Title = "Cancel", Variant = "Ghost", Order = 1,
                            Callback = function(activeDialog) dismiss(activeDialog) end,
                        },
                        Confirm = {
                            Title = "Log Out & Unbind", Variant = "Destructive", Order = 2,
                            Callback = function(activeDialog)
                                if logoutBusy then return end
                                dismiss(activeDialog)
                                logoutBusy = true
                                if logoutButton then
                                    logoutButton.Active = false
                                    logoutButton.Text = "Logging out..."
                                end
                                task.spawn(function()
                                    local runtimeCapability = capability()
                                    local ok, confirmed, safeMessage = false, false, nil
                                    if runtimeCapability then
                                        ok, confirmed, safeMessage = pcall(runtimeCapability, "logout")
                                    end
                                    if ok and confirmed == true then
                                        pcall(function()
                                            Library:Notify("Key unbound. Closing this session.", 3)
                                        end)
                                        task.wait(0.15)
                                        pcall(function()
                                            LocalPlayer:Kick("Logged out of CloverHub. Your key is unbound and can be entered again.")
                                        end)
                                        return
                                    end

                                    logoutBusy = false
                                    if logoutButton then
                                        logoutButton.Active = true
                                        logoutButton.Text = "Log Out"
                                    end
                                    local detail = type(safeMessage) == "string" and safeMessage or "server confirmation was not received"
                                    Library:Notify("Logout was not confirmed: " .. detail .. ". You were not kicked.", 6)
                                end)
                            end,
                        },
                    },
                })
                logoutDialog = dialog
            end)
            if not built then
                logoutDialog = nil
                Library:Notify("Could not open the logout confirmation.", 4)
            end
        end },
    })
    logoutButton = panel and panel:FindFirstChildWhichIsA("TextButton") or nil

    -- These boxes do not exist during the startup styling/collapse passes.
    for _, box in ipairs({ Window.__KeyStatusBox, Window.__LogoutBox }) do
        StyleGroupboxPanel(box)
        if CHK.CardifyBox then CHK.CardifyBox(box) end
        MakeCollapsible(box, true)
    end
    Window.__ApplyMobileScrollFix(Window.__AccountTab)
    if not alive() then return end

    task.spawn(function()
        local lastText
        while alive() do
            local info = readAccessInfo()
            local text
            if info then
                text = ("Access: %s\nKey remaining: %s"):format(
                    info.tier, formatRemaining(info.remainingSeconds))
            else
                text = "Unavailable"
            end
            if text ~= lastText then
                local written = pcall(function() statusLabel:SetText(text) end)
                if written then lastText = text end
            end
            task.wait(1)
        end
    end)
end

Window.__CleanupAccountTab = function()
    for _, key in ipairs({ "__KeyStatusBox", "__LogoutBox" }) do
        local box = Window[key]
        if box then pcall(function() box:Destroy() end) end
        Window[key] = nil
    end
end

DevBox = SettingsTab:AddLeftGroupbox("🛡️ Protected Release")
DevBox:AddLabel("ProtectedReleaseNotice", {
    Text = "External Lua tool loaders are disabled in release builds.",
    DoesWrap = true,
})

-- Official Obsidian SaveManager with a CloverHub snapshot bridge. SaveManager
-- owns the named-config workflow and confirmation dialogs; the snapshot keeps
-- custom overlay dropdowns and CHK controls lossless alongside native controls.
task.defer(function()
    -- Named configs are non-critical for first paint. Load the optional addon
    -- after the main hub has been created so it cannot delay startup.
    local managerOk, loadedManager = pcall(function()
        return loadstring(game:HttpGet(repo .. "addons/SaveManager.lua"))()
    end)
    if managerOk and type(loadedManager) == "table" then
        Library.__SaveManager = loadedManager
    end
    local manager = Library.__SaveManager
    if type(manager) == "table" then
        local configured, configBox = pcall(function()
            manager:SetLibrary(Library)
            manager:IgnoreThemeSettings()
            manager:SetFolder("CloverHub")
            manager:SetSubFolder("StealAnEgg")
            manager:SetIgnoreIndexes({
                "EggTargetRarities", "EggTargetCategories", "EggTargetAreas", "EggTargetPriority",
                "EggTargetKGMode", "EggTargetKGThreshold", "EggTargetValueThreshold",
                "TrailShopDropdown", "PlaceCategories", "PlaceRarities", "PlaceMutations", "PlaceOrder",
                "SellPets", "SellRarities", "SellMutations", "SellPetKGMode", "SellPetKGThreshold",
                "SellPetValueThreshold",
                "SellEggNames", "SellEggRarities", "SellEggMutations",
                "SellEggKGMode", "SellEggKGThreshold", "SellEggValueThreshold",
                "FindServerToggle",
                "FuseCategories", "FuseKGMode", "FuseKGThreshold", "FuseMinimumValue", "AutoFuseToggle",
                "RiftMinimumValue", "PriorityEventToggle", "AutoRiftToggle", "StealRouteDropdown",
                "AutoRiftBossToggle", "RiftBossFirstToggle", "AutoClaimBossMasteryToggle", "AutoBuyRiftShopToggle", "RiftShopDropdown",
                "StealMovementTypeDropdown", "BurstTweenToggle", "StealSpeedSlider", "StealSpeedInput",
                "SidewaysGlideToggle", "GuardProtectionToggle", "EggESPAreas",
                "CloverConfigName", "CloverConfigList", "CloverConfigJSON", "WebhookURLInput",
                -- The complete Clover snapshot below owns automated seller state.
                "AutoSellToggle", "AutoSellEggToggle",
                "SellPetsWhenFullToggle", "SellEggsWhenFullToggle",
            })

            local rawSaveJSON = manager.SaveJSON
            local rawLoadJSON = manager.LoadJSON
            local function applySnapshot(snapshot)
                if type(snapshot) ~= "table" then
                    Settings.AutoFuse = false
                    Settings.AutoRift, Settings.PriorityEvent, Settings.RiftMinimumValue = false, false, 0
                    Settings.SellPetValueThreshold = 0
                    Settings.SellEggValueThreshold = 0
                    Settings.AutoSell = false
                    Settings.SellPetsWhenFull = false
                    Settings.AutoSellEggs = false
                    Settings.SellEggsWhenFull = false
                    return true, true
                end
                local snapshotRevision = tonumber(snapshot.ConfigRevision) or 0
                local function validSnapshotFloor(key)
                    local value = snapshot[key]
                    return type(value) == "number" and value == value
                        and value >= 0 and value < math.huge
                end
                -- Pause during restore; resume only a complete, valid Fuse profile.
                Settings.AutoFuse = false
                local fuseValid = validSnapshotFloor("FuseMinimumValue")
                    and validSnapshotFloor("FuseKGThreshold") and type(snapshot.FuseCategories) == "table"
                    and (snapshot.FuseKGMode == "Any" or snapshot.FuseKGMode == "Above" or snapshot.FuseKGMode == "Below")
                local legacySellerSemantics = snapshotRevision < 11
                local invalidPetThreshold = legacySellerSemantics
                    or not validSnapshotFloor("SellPetValueThreshold")
                local invalidEggThreshold = legacySellerSemantics
                    or not validSnapshotFloor("SellEggValueThreshold")
                if invalidPetThreshold then Settings.SellPetValueThreshold = 0 end
                if invalidEggThreshold then Settings.SellEggValueThreshold = 0 end
                for key, default in pairs(Settings) do
                    local value = snapshot[key]
                    if key ~= "WebhookURL" and value ~= nil then
                        if type(default) == "table" and type(value) == "table" then
                            for oldKey in pairs(default) do default[oldKey] = nil end
                            for newKey, enabled in pairs(value) do
                                if enabled == true then default[newKey] = true end
                            end
                        elseif type(default) == type(value) then
                            if key == "TargetValueThreshold" or key == "SellPetValueThreshold"
                                or key == "SellEggValueThreshold" or key == "RiftMinimumValue" then
                                local valid = value == value and value >= 0 and value < math.huge
                                if valid then
                                    Settings[key] = value
                                elseif key == "SellPetValueThreshold" then
                                    invalidPetThreshold = true
                                elseif key == "SellEggValueThreshold" then
                                    invalidEggThreshold = true
                                end
                            else
                                Settings[key] = value
                            end
                        end
                    end
                end
                if not fuseValid then Settings.AutoFuse = false end
                if invalidPetThreshold then
                    Settings.AutoSell = false
                    Settings.SellPetsWhenFull = false
                end
                if invalidEggThreshold then
                    Settings.AutoSellEggs = false
                    Settings.SellEggsWhenFull = false
                end
                if invalidPetThreshold or invalidEggThreshold then
                    pcall(function()
                        Library:Notify("Invalid seller Minimum Value was rejected; selling stays off.", 5)
                    end)
                end
                -- Loading a named/shared config must not bypass the destructive
                -- confirmation merely because its snapshot stored an ON flag.
                Settings.AutoSell = false
                Settings.SellPetsWhenFull = false
                Settings.AutoSellEggs = false
                Settings.SellEggsWhenFull = false
                if snapshotRevision < 15 or not validSnapshotFloor("RiftMinimumValue") then
                    Settings.AutoRift, Settings.PriorityEvent, Settings.RiftMinimumValue = false, false, 0
                end
                if snapshotRevision < 16 then Settings.AutoRift = false end
                if Settings.StealRoute == "Chicken TP" then Settings.StealRoute = "Straight" end
                Settings.ConfigRevision = 17
                if Settings.StealRoute == "Wall to Wall" then Settings.StealRoute = "Turbo Hybrid" end
                if Settings.StealRoute == "Y Level" then Settings.StealRoute = "Fly" end
                if Settings.StealRoute ~= "Straight" and Settings.StealRoute ~= "Turbo Hybrid"
                    and Settings.StealRoute ~= "Default" and Settings.StealRoute ~= "Fly" then Settings.StealRoute = "Straight" end
                Settings.StealWallSpacing = "Wide Wall"
                Settings.StealMovementBackend = "Glide"
                Settings.StealMovementType = Settings.StealMovementType == "Tween" and "Tween" or "TP"
                Settings.HoverRunSpeed = nil -- discard the retired saved setting
                ConfigMeta.normalizeDeliverySpeeds(snapshot)
                return invalidPetThreshold, invalidEggThreshold
            end
            local function syncCustomControls()
                for key, controller in pairs(getgenv().__CHSAE_ConfigControllers or {}) do
                    local value = Settings[key]
                    if value ~= nil and type(controller) == "table" and type(controller.SetValue) == "function" then
                        if type(value) == "table" then
                            local copy = {}
                            for item, enabled in pairs(value) do if enabled then copy[item] = true end end
                            pcall(controller.SetValue, controller, copy)
                        else
                            pcall(controller.SetValue, controller, value)
                        end
                    end
                end
            end

            manager.SaveJSON = function(self, name)
                local encoded, success, err = rawSaveJSON(self, name)
                if not success then return encoded, success, err end
                local ok, payload = pcall(HttpService.JSONDecode, HttpService, encoded)
                if not (ok and type(payload) == "table") then
                    return "", false, "Failed to attach CloverHub settings"
                end
                -- Defense in depth: IgnoreIndexes should already omit this
                -- native input, but scrub the generated object list as well so
                -- a future SaveManager change cannot leak the private token.
                if type(payload.objects) == "table" then
                    local safeObjects = {}
                    for _, object in ipairs(payload.objects) do
                        if type(object) ~= "table" or object.idx ~= "WebhookURLInput" then
                            safeObjects[#safeObjects + 1] = object
                        end
                    end
                    payload.objects = safeObjects
                end
                -- Webhook URLs contain a secret token. Never place that token in
                -- exported JSON, named profiles, clipboard output, or autoload
                -- files. Loading a profile without it preserves the local URL.
                local exportSettings = configSnapshot(false)
                local exportSchema = {}
                for key in pairs(exportSettings) do exportSchema[#exportSchema + 1] = key end
                table.sort(exportSchema)
                payload.cloverSettings = exportSettings
                payload.cloverSettingsSchema = exportSchema
                payload.cloverSettingsRevision = Settings.ConfigRevision
                local encodeOk, bridged = pcall(HttpService.JSONEncode, HttpService, payload)
                if not encodeOk then return "", false, "Failed to encode CloverHub settings" end
                return bridged, true
            end
            manager.LoadJSON = function(self, content)
                RuntimeStatus.valueFilterLoadInProgress = true
                RuntimeStatus.markValueFilterChanged()
                local decodeOk, payload = pcall(HttpService.JSONDecode, HttpService, content)
                local safeContent = content
                local invalidPetThreshold, invalidEggThreshold = false, false
                if decodeOk and type(payload) == "table" then
                    invalidPetThreshold, invalidEggThreshold = applySnapshot(payload.cloverSettings)
                    if type(payload.objects) == "table" then
                        local safeObjects = {}
                        local cloverOwned = {
                            AntiAFKMethodDropdown = true, -- retired v149 selector
                            -- Retired UI tombstone: strip old named-config objects
                            -- so SaveManager never tries to restore a removed control.
                            FastTPCycleToggle = true,
                            AutoHungryMonsterToggle = true,
                            HungryMonsterPriority = true,
                            HungryMonsterProtectedCategories = true,
                            HungryMonsterProtectedRarities = true,
                            AutoOpenChestToggle = true,
                            AutoSkipChestToggle = true,
                            FindServerToggle = true,
                            FuseCategories = true, FuseKGMode = true, FuseKGThreshold = true,
                            FuseMinimumValue = true, AutoFuseToggle = true,
                            AutoRiftToggle = true,
                            AutoRiftBossToggle = true,
                            RiftBossFirstToggle = true,
                            AutoClaimBossMasteryToggle = true,
                            AutoBuyRiftShopToggle = true,
                            RiftShopDropdown = true,
                            PriorityEventToggle = true,
                            RiftMinimumValue = true,
                            StealMovementBackendDropdown = true,
                            StealMovementTypeDropdown = true,
                            StealRouteDropdown = true,
                            BurstTweenToggle = true,
                            StealSpeedSlider = true, StealSpeedInput = true,
                            StealWallSpacingDropdown = true, -- removed fixed spacing control
                            DevChickenTweenToggle = true, -- replaced by Movement Type
                            InstantStealToggle = true, -- retired pickup shortcut
                            AutoSellToggle = true,
                            AutoSellEggToggle = true,
                            SellPetsWhenFullToggle = true,
                            SellEggsWhenFullToggle = true,
                        }
                        for _, object in ipairs(payload.objects) do
                            if type(object) ~= "table" or (object.idx ~= "WebhookURLInput"
                                and cloverOwned[object.idx] ~= true) then
                                safeObjects[#safeObjects + 1] = object
                            end
                        end
                        payload.objects = safeObjects
                    end
                    payload.cloverSettings = configSnapshot(false)
                    payload.cloverSettingsSchema = nil
                    local encodeOk, encoded = pcall(HttpService.JSONEncode, HttpService, payload)
                    if encodeOk then safeContent = encoded end
                end
                local loadOk, success, err = pcall(rawLoadJSON, self, safeContent)
                local loadSucceeded = loadOk and success == true
                -- A malicious/old native object entry must not re-arm a seller
                -- after its invalid floor was rejected by the Clover snapshot.
                if invalidPetThreshold then
                    Settings.AutoSell = false
                    Settings.SellPetsWhenFull = false
                end
                if invalidEggThreshold then
                    Settings.AutoSellEggs = false
                    Settings.SellEggsWhenFull = false
                end
                if not loadSucceeded then
                    -- The Clover snapshot is applied before the native objects.
                    -- If native loading fails, never leave irreversible seller
                    -- flags armed from a config which the UI reports as failed.
                    Settings.AutoSell = false
                    Settings.SellPetsWhenFull = false
                    Settings.AutoSellEggs = false
                    Settings.SellEggsWhenFull = false
                end
                task.defer(function()
                    task.wait()
                    pcall(syncCustomControls)
                    pcall(configSave, true)
                    RuntimeStatus.valueFilterLoadInProgress = false
                    RuntimeStatus.markValueFilterChanged()
                end)
                if not loadOk then return false, success end
                return success, err
            end

            -- Keep SaveManager as the storage/serialization engine, but build the
            -- surface with CloverHub controls. The addon's stock BuildConfigSection
            -- uses flat AddButton elements which do not match the rest of this UI.
            local box = SettingsTab:AddGroupbox({ Side = "Left", Name = "💾 Config" })
            local configNameInput = box:AddInput("CloverConfigName", {
                Text = "Name", Placeholder = "My config", Finished = false,
                Tooltip = "Name a new config.",
            })

            local selectedConfig
            local configList
            local autoloadLabel
            local function setAutoloadLabel()
                local name = manager:GetAutoloadConfig()
                pcall(function() autoloadLabel:SetText("⭐ Autoload: " .. tostring(name or "none")) end)
            end
            local function refreshList(preserve)
                local values = manager:RefreshConfigList()
                table.sort(values, function(a, b)
                    return string.lower(tostring(a)) < string.lower(tostring(b))
                end)
                if configList then configList:SetItems(values, preserve == true) end
                setAutoloadLabel()
                return values
            end
            configList = BindDropdownOverlay(box, "CloverConfigList", "Configs",
                manager:RefreshConfigList(), {
                    multi = false, text = "Configs", tooltip = "Choose a saved config.",
                    get = function() return selectedConfig end,
                    set = function(value) selectedConfig = value end,
                    onOpen = function() refreshList(true) end,
                })

            local function chosen()
                if type(selectedConfig) ~= "string" or selectedConfig == "" then
                    Library:Notify("Choose a config first.", 3)
                    return nil
                end
                return selectedConfig
            end
            local function configName()
                local value = tostring(configNameInput.Value or ""):match("^%s*(.-)%s*$")
                if value == "" or string.lower(value) == "autoload" then
                    Library:Notify("Enter a valid config name.", 3)
                    return nil
                end
                return value
            end
            local function report(action, name, success, err)
                if success then
                    Library:Notify(("✅ %s: %s"):format(action, tostring(name or "config")), 3)
                else
                    Library:Notify(("❌ %s: %s"):format(action, tostring(err or "failed")), 4)
                end
            end
            local function confirm(index, title, description, actionText, destructive, callback)
                Window:AddDialog(index, {
                    Title = title, Description = description, AutoDismiss = false,
                    FooterButtons = {
                        Cancel = {
                            Title = "Cancel", Variant = "Ghost", Order = 1,
                            Callback = function(dialog) dialog:Dismiss() end,
                        },
                        Confirm = {
                            Title = actionText,
                            Variant = destructive and "Destructive" or "Primary",
                            Order = 2,
                            Callback = function(dialog)
                                dialog:Dismiss()
                                callback()
                            end,
                        },
                    },
                })
            end
            local function saveNamed(name, label)
                local success, err = manager:Save(name)
                report(label or "Saved", name, success, err)
                if success then
                    selectedConfig = name
                    refreshList(false)
                    configList:SetValue(name)
                end
            end

            MakeButtonPanel(box, "CloverConfigCreateButtons", {
                { "+ Create Config", function()
                    local name = configName()
                    if not name then return end
                    local exists = table.find(manager:RefreshConfigList(), name) ~= nil
                    if exists then
                        confirm("CloverConfigCreateDialog", "Config exists",
                            ("Overwrite %q with your current settings?"):format(name),
                            "Overwrite", true, function() saveNamed(name, "Overwritten") end)
                    else
                        saveNamed(name, "Created")
                    end
                end },
            })

            MakeButtonPanel(box, "CloverConfigManageButtons", {
                { "📂 Load Config", function()
                    local name = chosen(); if not name then return end
                    confirm("CloverConfigLoadDialog", "Load config",
                        ("Load %q and replace the current settings?"):format(name),
                        "Load", false, function()
                            local success, err = manager:Load(name)
                            report("Loaded", name, success, err)
                        end)
                end },
                { "💾 Overwrite Config", function()
                    local name = chosen(); if not name then return end
                    confirm("CloverConfigOverwriteDialog", "Overwrite config",
                        ("Replace %q with the current settings?"):format(name),
                        "Overwrite", true, function() saveNamed(name, "Overwritten") end)
                end },
                { "🗑 Delete Config", function()
                    local name = chosen(); if not name then return end
                    confirm("CloverConfigDeleteDialog", "Delete config",
                        ("Delete %q? This cannot be undone."):format(name),
                        "Delete", true, function()
                            local success, err = manager:Delete(name)
                            report("Deleted", name, success, err)
                            if success then selectedConfig = nil; refreshList(false) end
                        end)
                end },
                { "🔄 Refresh Configs", function() refreshList(true) end },
            })

            MakeButtonPanel(box, "CloverConfigAutoloadButtons", {
                { "⭐ Set Autoload", function()
                    local name = chosen(); if not name then return end
                    local success, err = manager:SaveAutoloadConfig(name)
                    report("Autoload", name, success, err)
                    setAutoloadLabel()
                end },
                { "🗑 Clear Autoload", function()
                    confirm("CloverConfigClearAutoloadDialog", "Clear autoload",
                        "Stop loading a named config on startup?", "Clear", true, function()
                            local success, err = manager:DeleteAutoLoadConfig()
                            if not success and tostring(err):find("not set", 1, true) then success = true end
                            report("Autoload cleared", nil, success, err)
                            setAutoloadLabel()
                        end)
                end },
            })
            autoloadLabel = box:AddLabel("CloverConfigAutoload", {
                Text = "⭐ Autoload: none", DoesWrap = true,
            })

            local configJSONInput = box:AddInput("CloverConfigJSON", {
                Text = "Config JSON", Placeholder = "Exported JSON appears here",
                Finished = false, Tooltip = "Paste JSON to import or export.",
            })
            MakeButtonPanel(box, "CloverConfigJSONButtons", {
                { "📥 Import JSON", function()
                    local content = tostring(configJSONInput.Value or "")
                    if content:match("^%s*$") then Library:Notify("Paste config JSON first.", 3); return end
                    confirm("CloverConfigImportDialog", "Import config",
                        "Apply the JSON and replace the current settings?", "Import", false, function()
                            local success, err = manager:LoadJSON(content)
                            report("Imported", "JSON", success, err)
                        end)
                end },
                { "📤 Export JSON", function()
                    local encoded, success, err = manager:SaveJSON()
                    if not success then report("Export", nil, false, err); return end
                    configJSONInput:SetValue(encoded)
                    Library:Notify("✅ Config JSON is ready.", 3)
                end },
                { "📋 Copy JSON", function()
                    local content = tostring(configJSONInput.Value or "")
                    if content:match("^%s*$") then Library:Notify("Export JSON first.", 3); return end
                    if type(setclipboard) ~= "function" then
                        Library:Notify("Clipboard is unavailable.", 3)
                        return
                    end
                    local success = pcall(setclipboard, content)
                    Library:Notify(success and "✅ Config JSON copied." or "❌ Copy failed.", 3)
                end },
            })

            refreshList(false)
            task.defer(function()
                if sessionAlive() then manager:LoadAutoloadConfig() end
            end)
            return box
        end)
        if configured then Window.__ConfigBox = configBox end
    end
    if not Window.__ConfigBox then
        Window.__ConfigBox = SettingsTab:AddGroupbox({ Side = "Left", Name = "💾 Config" })
        Window.__ConfigBox:AddLabel("ConfigUnavailableLabel", {
            Text = "Named configs are unavailable.\nSafe autosave is still active.", DoesWrap = true,
        })
    end
    pcall(StyleGroupboxPanel, Window.__ConfigBox)
    task.spawn(MakeCollapsible, Window.__ConfigBox, true)
end)
-- Remote Spy button removed (v1.1): every spy we tried is blind in this game —
-- the client talks through `Library.Client.Network` wrappers, so the baked-in
-- capture hook (which wraps Network.Invoke AND Network.Fire) is the tool that
-- actually works here.
end -- scoped SETTINGS helpers

